module FSM (
  input clk,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the original FSM

reg [2:0] state; // original FSM state register

// Define the original FSM transitions
always @(posedge clk) begin
  case(state)
    3'b000: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b001: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b010: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b011: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
    3'b100: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b101: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b110: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b111: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
  endcase
end

// Define the merged FSM transitions
always @(posedge clk) begin
  case(state)
    3'b000: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b001: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b010: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b011: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
    3'b100: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b101: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b110: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b111: if(in == 4'b0000) state <= 3'b010; else state <= 3'b111;
  endcase
end

// Define the output signals as a function of the state and input signals
always @(state or in) begin
  case(state)
    3'b000: out <= {m{1'b0}};
    3'b001: out <= {m{in[0]}};
    3'b010: out <= {m{in[1]}};
    3'b011: out <= {m{in[0] ^ in[1]}};
    3'b100: out <= {m{in[2]}};
    3'b101: out <= {m{in[0] ^ in[2]}};
    3'b110: out <= {m{in[1] ^ in[2]}};
    3'b111: out <= {m{in[0] ^ in[1] ^ in[2]}};
  endcase
end

endmodule

module check_10us (
  input start,
  input stop,
  output reg [31:0] elapsed_time
);

  reg [31:0] counter = 0;
  reg counting = 0;

  always @(posedge clk) begin
    if (start) begin
      counter <= 0;
      counting <= 1;
    end else if (stop) begin
      counting <= 0;
      elapsed_time <= counter;
    end else if (counting) begin
      counter <= counter + 1;
    end
  end

endmodule

module buffer
  #(parameter BUF_SIZE = 9)
  (
   // Control Interface
   input clk,
   input rst,
   input [31:0] ctrl_word,
   input go,
   output reg done,
   output reg error,
   output reg idle,

   // Buffer Interface
   output reg en_o,
   output reg we_o,
   output reg [BUF_SIZE-1:0] addr_o,
   output reg [31:0] dat_to_buf,
   input [31:0] dat_from_buf,

   // Write FIFO Interface
   input [31:0] wr_data_i,
   input [3:0] wr_flags_i,
   input wr_ready_i,
   output reg wr_ready_o,

   // Read FIFO Interface
   output reg [31:0] rd_data_o,
   output reg [3:0] rd_flags_o,
   output reg rd_ready_o,
   input rd_ready_i
  );

   reg [31:0] ctrl_reg;
   reg go_reg;

   always @(posedge clk)
     go_reg <= go;

   always @(posedge clk)
     if(rst)
       ctrl_reg <= 0;
     else
       if(go & (ctrl_word[31:28] == 0))
	 ctrl_reg <= ctrl_word;

   wire [BUF_SIZE-1:0] firstline = ctrl_reg[BUF_SIZE-1:0];
   wire [BUF_SIZE-1:0] lastline = ctrl_reg[2*BUF_SIZE-1:BUF_SIZE];

   wire       read = ctrl_reg[22];
   wire       write = ctrl_reg[23];
   wire       clear = ctrl_reg[24];

   localparam IDLE = 3'd0;
   localparam PRE_READ = 3'd1;
   localparam READING = 3'd2;
   localparam WRITING = 3'd3;
   localparam ERROR = 3'd4;
   localparam DONE = 3'd5;

   reg [2:0]  state;
   reg 	      rd_sop, rd_eop;
   wire       wr_sop, wr_eop, wr_error;
   reg [1:0]  rd_occ;
   wire [1:0] wr_occ;

   always @(posedge clk)
     if(rst)
       begin
	  state <= IDLE;
	  rd_sop <= 0;
	  rd_eop <= 0;
	  rd_occ <= 0;
       end
     else
       if(clear)
	 begin
	    state <= IDLE;
	    rd_sop <= 0;
	    rd_eop <= 0;
	    rd_occ <= 0;
	 end
       else 
	 case(state)
	   IDLE :
	     if(go_reg & read)
	       begin
		  addr_o <= firstline;
		  state <= PRE_READ;
	       end
	     else if(go_reg & write)
	       begin
		  addr_o <= firstline;
		  state <= WRITING;
	       end

	   PRE_READ :
	     begin
		state <= READING;
		addr_o <= addr_o + 1;
		rd_occ <= 2'b00;
		rd_sop <= 1;
		rd_eop <= 0;
	     end

	   READING :
	     if(rd_ready_i)
	       begin
		  rd_sop <= 0;
		  addr_o <= addr_o + 1;
		  if(addr_o == lastline)
		    begin
		       rd_eop <= 1;
		       rd_occ <= 0;
		    end
		  else
		    rd_eop <= 0;
		  if(rd_eop)
		    state <= DONE;
	       end

	   WRITING :
	     begin
		if(wr_ready_i)
		  begin
		     addr_o <= addr_o + 1;
		     if(wr_error)
		       begin
			  state <= ERROR;
		       end
		     else if((addr_o == lastline)||wr_eop)
		       state <= DONE;
		  end
	     end // case: WRITING

	 endcase // case(state)

   assign     dat_to_buf = wr_data_i;
   assign     rd_data_o = dat_from_buf;

   assign     rd_flags_o = { rd_occ[1:0], rd_eop, rd_sop };
   assign     rd_ready_o = (state == READING);

   assign     wr_sop = wr_flags_i[0];
   assign     wr_eop = wr_flags_i[1];
   assign     wr_occ = wr_flags_i[3:2];
   assign     wr_error = wr_sop & wr_eop;
   assign     wr_ready_o = (state == WRITING);

   assign     we_o = (state == WRITING);

   assign     en_o = ~((state==READING)& ~rd_ready_i);

   always @(posedge clk)
     begin
	if(state == DONE)
	  begin
	     done <= 1;
	     rd_occ <= rd_occ + wr_occ;
	     if(rd_occ > 2'b11)
	       begin
		  error <= 1;
		  rd_occ <= 2'b11;
	       end
	     idle <= 1;
	  end
	else
	  begin
	     done <= 0;
	     error <= 0;
	     idle <= 0;
	  end
     end

endmodule

module spi_bus (
    input SBCLKI,
    input SBRWI,
    input SBSTBI,
    input [7:0] SBADRI,
    input [7:0] SBDATI,
    input MI,
    input SI,
    input SCKI,
    input SCSNI,
    output reg [7:0] SBDATO,
    output reg SBACKO,
    output reg SPIIRQ,
    output reg SPIWKUP,
    output reg SO,
    output reg SOE,
    output reg MO,
    output reg MOE,
    output reg SCKO,
    output reg SCKOE,
    output reg [3:0] MCSNO,
    output reg [3:0] MCSNOE
);

parameter BUS_ADDR74 = "0b0000";

reg [7:0] shift_reg;
reg [7:0] data_reg;
reg [7:0] addr_reg;
reg [3:0] cs_reg;
reg [1:0] rw_reg;
reg [2:0] state_reg;

localparam IDLE = 3'b000;
localparam ADDR = 3'b001;
localparam READ = 3'b010;
localparam WRITE = 3'b011;
localparam ACK = 3'b100;

always @(posedge SBCLKI) begin
    // Shift in data
    shift_reg <= {shift_reg[6:0], SBDATI[7]};

    // Update state
    case(state_reg)
        IDLE: begin
            // Check for chip select
            if(SCSNI == 0) begin
                // Update address register
                addr_reg <= SBADRI;

                // Update read/write register
                rw_reg <= SBRWI[0:1];

                // Update chip select register
                cs_reg <= {cs_reg[2:0], 1};

                // Move to address state
                state_reg <= ADDR;
            end
        end

        ADDR: begin
            // Shift in address
            data_reg <= {data_reg[6:0], addr_reg[7]};

            // Check for last bit of address
            if(addr_reg[0] == 1) begin
                // Move to read or write state
                if(rw_reg == 2'b00) begin
                    // Move to read state
                    state_reg <= READ;
                end else begin
                    // Move to write state
                    state_reg <= WRITE;
                end
            end

            // Shift address register
            addr_reg <= {addr_reg[6:0], 0};
        end

        READ: begin
            // Shift in data
            data_reg <= {data_reg[6:0], SI};

            // Check for last bit of data
            if(shift_reg[0] == 1) begin
                // Update data output
                SBDATO <= data_reg;

                // Update acknowledge output
                SBACKO <= 1;

                // Move to idle state
                state_reg <= ACK;
            end
        end

        WRITE: begin
            // Shift out data
            SO <= data_reg[7];

            // Check for last bit of data
            if(shift_reg[0] == 1) begin
                // Move to idle state
                state_reg <= IDLE;
            end

            // Shift data register
            data_reg <= {data_reg[6:0], shift_reg[7]};
        end

        ACK: begin
            // Check for chip select
            if(SCSNI == 1) begin
                // Update chip select register
                cs_reg <= {cs_reg[2:0], 0};

                // Move to idle state
                state_reg <= IDLE;
            end
        end
    endcase
end

always @(negedge SCKI) begin
    // Update multi-chip select outputs
    MCSNO <= cs_reg;

    // Update multi-chip select output enables
    MCSNOE <= {cs_reg[2:0], 1'b1};

    // Update interrupt request output
    SPIIRQ <= 0;

    // Update wakeup output
    SPIWKUP <= 0;

    // Update master output
    MO <= 0;

    // Update master output enable
    MOE <= 0;

    // Update serial clock output
    SCKO <= SCKI;

    // Update serial clock output enable
    SCKOE <= 1;

    // Update serial output enable
    SOE <= 1;

    // Update acknowledge output
    SBACKO <= 0;

    // Update state
    state_reg <= IDLE;
end

endmodule

module my_axi_gpio_module
   (s_axi_aclk,
    s_axi_aresetn,
    s_axi_awaddr,
    s_axi_awvalid,
    s_axi_awready,
    s_axi_wdata,
    s_axi_wstrb,
    s_axi_wvalid,
    s_axi_wready,
    s_axi_bresp,
    s_axi_bvalid,
    s_axi_bready,
    s_axi_araddr,
    s_axi_arvalid,
    s_axi_arready,
    s_axi_rdata,
    s_axi_rresp,
    s_axi_rvalid,
    s_axi_rready);

  input s_axi_aclk;
  input s_axi_aresetn;
  input [8:0] s_axi_awaddr;
  input s_axi_awvalid;
  output s_axi_awready;
  input [31:0] s_axi_wdata;
  input [3:0] s_axi_wstrb;
  input s_axi_wvalid;
  output s_axi_wready;
  output [1:0] s_axi_bresp;
  output s_axi_bvalid;
  input s_axi_bready;
  input [8:0] s_axi_araddr;
  input s_axi_arvalid;
  output s_axi_arready;
  output [31:0] s_axi_rdata;
  output [1:0] s_axi_rresp;
  output s_axi_rvalid;
  input s_axi_rready;

  input [15:0] gpio_io_i;
  output [15:0] gpio_io_o;
  inout [15:0] gpio_io_t;
  output ip2intc_irpt;

  reg [31:0] gpio_o_reg;
  reg [31:0] gpio_t_reg;
  reg [1:0] bresp_reg;
  reg bvalid_reg;
  reg [31:0] rdata_reg;
  reg [1:0] rresp_reg;
  reg rvalid_reg;
  reg [1:0] arready_reg;
  reg [1:0] awready_reg;
  reg [31:0] wdata_reg;
  reg [3:0] wstrb_reg;
  reg wvalid_reg;

  assign s_axi_awready = awready_reg[1];
  assign s_axi_wready = wvalid_reg & awready_reg[1];
  assign gpio_io_o = gpio_o_reg[15:0];
  assign gpio_io_t = gpio_t_reg[15:0];
  assign s_axi_bresp = bresp_reg[1:0];
  assign s_axi_bvalid = bvalid_reg;
  assign s_axi_arready = arready_reg[1];
  assign s_axi_rdata = rdata_reg;
  assign s_axi_rresp = rresp_reg[1:0];
  assign s_axi_rvalid = rvalid_reg;

  always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
      gpio_o_reg <= 0;
      gpio_t_reg <= 0;
      bresp_reg <= 0;
      bvalid_reg <= 0;
      rdata_reg <= 0;
      rresp_reg <= 0;
      rvalid_reg <= 0;
      arready_reg <= 2'b0;
      awready_reg <= 2'b0;
      wdata_reg <= 0;
      wstrb_reg <= 0;
      wvalid_reg <= 0;
    end else begin
      if (s_axi_awvalid & !awready_reg[0] & !awready_reg[1]) begin
        awready_reg <= 2'b11;
      end else if (awready_reg[1] & !s_axi_wvalid & !wvalid_reg) begin
        awready_reg <= 2'b00;
      end else if (awready_reg[1] & s_axi_wvalid & !wvalid_reg) begin
        wdata_reg <= s_axi_wdata;
        wstrb_reg <= s_axi_wstrb;
        wvalid_reg <= 1;
        awready_reg <= 2'b00;
      end else if (wvalid_reg & !s_axi_bvalid & s_axi_bready) begin
        bresp_reg <= 2'b00;
        bvalid_reg <= 1;
        wvalid_reg <= 0;
      end else if (s_axi_arvalid & !arready_reg[0] & !arready_reg[1]) begin
        arready_reg <= 2'b11;
      end else if (arready_reg[1] & !rvalid_reg & !s_axi_rvalid) begin
        rdata_reg <= gpio_io_i;
        rresp_reg <= 2'b00;
        rvalid_reg <= 1;
        arready_reg <= 2'b00;
      end else if (rvalid_reg & s_axi_rready) begin
        rvalid_reg <= 0;
        rresp_reg <= 2'b00;
      end else if (wvalid_reg & !s_axi_wvalid & !awready_reg[1]) begin
        wvalid_reg <= 0;
        awready_reg <= 2'b00;
        bresp_reg <= 2'b10;
        bvalid_reg <= 1;
      end else if (s_axi_awvalid & (awready_reg == 2'b00)) begin
        awready_reg <= 2'b01;
      end else if (s_axi_arvalid & (arready_reg == 2'b00)) begin
        arready_reg <= 2'b01;
      end else begin
        awready_reg <= awready_reg;
        arready_reg <= arready_reg;
      end
    end
  end

endmodule

