module testbench_simulation(
  input logic reset,
  output logic host_clk,
  output logic configuration_busy,
  input logic monitor_finished_1g,
  input logic monitor_finished_100m,
  input logic monitor_finished_10m,
  input logic monitor_error
);

  // Drive HOSTCLK at one third the frequency of GTX_CLK
  initial begin
    host_clk <= 1'b0;
    #2000;
    forever begin
      host_clk <= ~host_clk;
      #12000;
    end
  end

  // Reset the core
  initial begin
    reset <= 1'b1;
    #4000000;
    reset <= 1'b0;
    #200000;
  end

  // Set configuration_busy to 1 for a period of time, then set it to 0.
  initial begin
    configuration_busy <= 0;
    #200000;
    configuration_busy <= 1;
    #100000;
    configuration_busy <= 0;
  end

  // Wait for the monitor_finished_1g signal to go high.
  initial begin
    @(monitor_finished_1g);
  end

  // Check the monitor_error signal and print a message indicating whether the simulation was successful or not.
  initial begin
    if (monitor_error == 1'b1) begin
      $display("*************************");
      $display("ERROR: Simulation Failed.");
      $display("*************************");
    end
    else begin
      $display("****************************");
      $display("PASS: Simulation Successful.");
      $display("****************************");
    end
    $stop;
  end

endmodule

module decade_counter (
    input clk,
    input pause,
    input reset,
    output reg [3:0] q
);

reg [3:0] johnson;
reg [3:0] johnson_next;
reg flip_flop;

always @ (posedge clk) begin
    if (reset) begin
        johnson <= 4'b0001;
        flip_flop <= 1'b0;
        q <= 4'b0000;
    end else if (pause) begin
        johnson_next <= johnson;
    end else begin
        johnson_next[0] <= johnson[3];
        johnson_next[1] <= johnson[0];
        johnson_next[2] <= johnson[1];
        johnson_next[3] <= johnson[2] ^ johnson[3];
        johnson <= johnson_next;

        if (johnson == 4'b1001) begin
            flip_flop <= ~flip_flop;
        end

        if (flip_flop) begin
            q <= 4'b0000;
        end else begin
            q <= johnson;
        end
    end
end

endmodule

