   always @(posedge clock, posedge reset) begin
      if (reset) begin
         rr_counter <= 2'b0;
         rr_next_counter <= 2'b0;
         rr_next_addr <= rri_addr_0;
         rr_next_tag <= rri_tag_0;
         rro_valid_reg <= 1'b0;
      end else begin
         if (rro_ready && rro_valid_reg) begin
            rr_counter <= rr_next_counter;
            rr_next_counter <= (rr_counter == 2'b11) ? 2'b00 : rr_counter + 1;
            rr_next_addr <= rri_addr_0;
            rr_next_tag <= rri_tag_0;
            rro_valid_reg <= 1'b0;
         end else begin
            rr_next_addr <= (rr_counter == 2'b00) ? rri_addr_0 :
                            (rr_counter == 2'b01) ? rri_addr_1 :
                            (rr_counter == 2'b10) ? rri_addr_2 :
                                                   rri_addr_3;
            rr_next_tag <= (rr_counter == 2'b00) ? rri_tag_0 :
                           (rr_counter == 2'b01) ? rri_tag_1 :
                           (rr_counter == 2'b10) ? rri_tag_2 :
                                                  rri_tag_3;
            rro_valid_reg <= rri_valid[rr_counter];
         end
      end
   end

   // Assign output ports
   assign rro_valid = rro_valid_reg;
   assign rro_addr = rr_next_addr;
   assign rro_tag = {3'b0, rr_next_tag};

endmodule

module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  input [254:0] in, // 255-bit input vector for priority encoder
  input [2:0] stage,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  output reg [31:0] regfile [7:0],
  output [7:0] out // 8-bit output from priority encoder
);

  // Priority Encoder
  priority_encoder pe(
    .in(in),
    .out(out)
  );

  // Control Logic
  control_logic cl(
    .instruction(instruction),
    .stage(stage),
    .rs1(rs1),
    .rs2(rs2),
    .rd(rd),
    .add(add),
    .sub(sub),
    .and(and),
    .nand(nand),
    .write(write)
  );

  // Instruction Decode
  reg [7:0] instruction_reg;
  always @(posedge clk) begin
    if (reset) begin
      instruction_reg <= 8'b0;
    end else begin
      instruction_reg <= instruction;
    end
  end

  // Instruction Execution
  reg [31:0] data1_reg;
  reg [31:0] data2_reg;
  reg [31:0] result_reg;
  always @(posedge clk) begin
    if (reset) begin
      data1_reg <= 32'b0;
      data2_reg <= 32'b0;
      result_reg <= 32'b0;
    end else begin
      case (stage)
        0: begin // Instruction Decode
          data1_reg <= regfile[rs1];
          data2_reg <= regfile[rs2];
        end
        1: begin // Instruction Execution
          case (instruction_reg)
            8'h00: result_reg <= data1_reg + data2_reg; // ADD
            8'h01: result_reg <= data1_reg - data2_reg; // SUB
            8'h02: result_reg <= data1_reg & data2_reg; // AND
            8'h03: result_reg <= ~(data1_reg & data2_reg); // NAND
            default: result_reg <= 32'b0;
          endcase
        end
        2: begin // Write-Back
          if (write) begin
            regfile[rd] <= result_reg;
          end
        end
      endcase
    end
  end

endmodule

