module ripple_decoder_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout,
    output reg [15:0] O
);

    wire [3:0] adder_sum;
    wire adder_cout;
    wire [15:0] decoder_input;

    ripple_carry_adder adder(
        .A(A),
        .B(B),
        .Cin(Cin),
        .Sum(adder_sum),
        .Cout(adder_cout)
    );

    assign decoder_input = {adder_sum, adder_cout};

    decoder_4to16 decoder(
        .A(decoder_input),
        .O(O)
    );

    assign Sum = adder_sum;
    assign Cout = adder_cout;

    always @(*) begin
        case (O)
            16'b0000000000000001: Sum = 4'b0000;
            16'b0000000000000010: Sum = 4'b0001;
            16'b0000000000000100: Sum = 4'b0010;
            16'b0000000000001000: Sum = 4'b0011;
            16'b0000000000010000: Sum = 4'b0100;
            16'b0000000000100000: Sum = 4'b0101;
            16'b0000000001000000: Sum = 4'b0110;
            16'b0000000010000000: Sum = 4'b0111;
            16'b0000000100000000: Sum = 4'b1000;
            16'b0000001000000000: Sum = 4'b1001;
            16'b0000010000000000: Sum = 4'b1010;
            16'b0000100000000000: Sum = 4'b1011;
            16'b0001000000000000: Sum = 4'b1100;
            16'b0010000000000000: Sum = 4'b1101;
            16'b0100000000000000: Sum = 4'b1110;
            16'b1000000000000000: Sum = 4'b1111;
            default: Sum = 4'b0000;
        endcase
    end

