module comparator_decoder (
    input [15:0] a,
    input [15:0] b,
    input [3:0] sel,
    input mode,
    output reg [15:0] out
);

    wire eq;
    wire gt;
    wire lt;

    comparator_16bit cmp (
        .a(a),
        .b(b),
        .eq(eq),
        .gt(gt),
        .lt(lt)
    );

    wire [15:0] decoder_out;
    assign decoder_out = {3'b000, eq, gt, lt};

    wire [15:0] reg_in;
    assign reg_in = (mode == 0) ? a : b;

    reg [15:0] reg_out;
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 16'b0;
        end else if (decoder_out[sel] == 1'b0) begin
            reg_out <= reg_in;
        end
    end

    assign out = (decoder_out[sel] == 1'b0) ? reg_out : cmp.out;

endmodule

