module top_module (
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output reg [1:0] pos,
    output [7:0] final_output
);

    wire [3:0] in_not = ~in;
    wire [3:0] in_and = &in;
    wire [3:0] in_or = |in;
    wire [3:0] in_xor = ^in;

    assign out_and = in_and;
    assign out_or = in_or;
    assign out_xor = in_xor;

    wire [3:0] and_not = ~in_and;
    wire [3:0] or_not = ~in_or;
    wire [3:0] xor_not = ~in_xor;

    wire [2:0] and_not_pos = and_not[2:0] == 0 ? 3 : and_not[1:0] == 0 ? 2 : and_not[0] == 0 ? 1 : 0;
    wire [2:0] or_not_pos = or_not[2:0] == 0 ? 3 : or_not[1:0] == 0 ? 2 : or_not[0] == 0 ? 1 : 0;
    wire [2:0] xor_not_pos = xor_not[2:0] == 0 ? 3 : xor_not[1:0] == 0 ? 2 : xor_not[0] == 0 ? 1 : 0;

    wire [7:0] and_not_product = and_not_pos == 0 ? 0 : and_not_pos == 1 ? in[0] : and_not_pos == 2 ? in[1:0] : in[2:0];
    wire [7:0] or_not_product = or_not_pos == 0 ? 0 : or_not_pos == 1 ? in[0] : or_not_pos == 2 ? in[1:0] : in[2:0];
    wire [7:0] xor_not_product = xor_not_pos == 0 ? 0 : xor_not_pos == 1 ? in[0] : xor_not_pos == 2 ? in[1:0] : in[2:0];

    assign final_output = {and_not_product, or_not_product, xor_not_product};

    always @(*) begin
        if (in[0] == 1) pos = 0;
        else if (in[1] == 1) pos = 1;
        else if (in[2] == 1) pos = 2;
        else if (in[3] == 1) pos = 3;
        else pos = 0;
    end

endmodule

module delay_fifo_module
	#(
	parameter 
	REQ_RANDOM_RANGE=8,
	RESP_RANDOM_RANGE=8,
	RESP_FIFO_POW=4
	)
(
	input [0:0] clk_i,
	input [0:0] rst_i,

	input 		[0:0] 	host_req,
	output reg 	[0:0] 	host_ack,
	input 		[0:0] 	host_we,
	input 		[31:0] 	host_addr,
	input 		[31:0] 	host_wdata,
	input 		[3:0] 	host_be,
	output reg 	[0:0] 	host_resp,
	output reg 	[31:0] 	host_rdata,

	output reg 	[0:0] 	target_req,
	input 		[0:0] 	target_ack,
	output reg 	[0:0] 	target_we,
	output reg 	[31:0] 	target_addr,
	output reg 	[31:0] 	target_wdata,
	output reg 	[3:0] 	target_be,
	input 		[0:0] 	target_resp,
	input 		[31:0] 	target_rdata
);

// req delaying //
integer req_random_var;
always @(posedge clk_i)
	begin
	req_random_var <= $urandom_range(0,REQ_RANDOM_RANGE-1);
	end

always @*
	begin
	if (req_random_var == 0)
		begin
		target_req 		= host_req;
		target_we 		= host_we;
		target_addr 	= host_addr;
		target_wdata 	= host_wdata;
		target_be 		= host_be;
		host_ack 		= target_ack;
		end
	else 
		begin
		target_req 		= 1'b0;
		target_we 		= 1'b0;
		target_addr 	= 32'h0;
		target_wdata 	= 32'h0;
		target_be 		= 4'h0;
		host_ack 		= 1'b0;
		end
	end

// resp delaying //
integer resp_random_var;
always @(posedge clk_i)
	begin
	resp_random_var <= $urandom_range(0,RESP_RANDOM_RANGE-1);
	end

reg resp_fifo_rd;
wire resp_fifo_empty, resp_fifo_full;
wire [31:0] resp_fifo_rdata;

always @*
	begin
	resp_fifo_rd = 1'b0;
	host_resp = 1'b0;
	host_rdata = 32'h0;
	if ((resp_fifo_full) || ( (!resp_fifo_empty) && (resp_random_var == 0) ))
		begin
		resp_fifo_rd = 1'b1;
		host_resp = 1'b1;
		host_rdata = resp_fifo_rdata;
		end
	end

fifo
#(
	.B(32),
	.W(RESP_FIFO_POW)
) resp_fifo (
	.clk(clk_i),
	.reset(rst_i),
	.rd(resp_fifo_rd),
	.wr(target_resp),
	.w_data(target_rdata),
	.empty(resp_fifo_empty),
	.full(resp_fifo_full),
	.r_data(resp_fifo_rdata)
);

endmodule

