module memory_controller (
    input clk_i,
    input rst_i,
    input enable_i,
    input write_i,
    input [31:0] addr_i,
    output reg ack_o,
    input [255:0] data_i,
    output [255:0] data_o
);

// Memory module instantiation
Data_Memory memory_inst (
    .clk_i(clk_i),
    .rst_i(rst_i),
    .addr_i(addr_i),
    .data_i(data_i),
    .enable_i(enable_i),
    .write_i(write_i),
    .ack_o(ack_o),
    .data_o(data_o)
);

// Controller module logic
reg [1:0] state;
reg [3:0] count;
reg ok;
reg [255:0] data;

parameter STATE_IDLE = 2'b00;
parameter STATE_WAIT = 2'b01;
parameter STATE_ACK = 2'b10;
parameter STATE_FINISH = 2'b11;

always @(posedge clk_i or negedge rst_i) begin
    if (~rst_i) begin
        state <= STATE_IDLE;
        count <= 4'b0;
        ok <= 1'b0;
        ack_o <= 1'b0;
    end
    else begin
        case (state)
            STATE_IDLE: begin
                if (enable_i) begin
                    count <= count + 4'b1;
                    state <= STATE_WAIT;
                end else begin
                    state <= STATE_IDLE;
                end
            end
            STATE_WAIT: begin
                if (count == 4'd6) begin
                    ok <= 1'b1;
                    state <= STATE_ACK;
                end else begin
                    count <= count + 4'b1;
                    state <= STATE_WAIT;
                end
            end
            STATE_ACK: begin
                ack_o <= 1'b1;
                state <= STATE_FINISH;
            end
            STATE_FINISH: begin
                ack_o <= 1'b0;
                ok <= 1'b0;
                state <= STATE_IDLE;
            end
        endcase
    end
end

always @(posedge clk_i) begin
    if (ok && !write_i) begin
        data <= data_o;
    end
end

always @(posedge clk_i) begin
    if (ok && write_i) begin
        data <= data_i;
    end
end

endmodule

