module Viterbi_decoder (
  input clk,
  input reset,
  input [N-1:0] data_in,
  output [N-1:0] data_out
);

parameter N = 8; // number of bits in convolutional code
parameter K = 3; // constraint length
parameter L = 8; // traceback depth

// define state transitions and trellis diagram here

reg [N-1:0] state_reg;
reg [N-1:0] state_next;
reg [N-1:0] path_metric_reg;
reg [N-1:0] path_metric_next;
reg [N-1:0] data_out_reg;
reg [N-1:0] data_out_next;
reg [K-1:0] input_reg;
reg [K-1:0] input_next;
reg [K-1:0] input_history_reg [L-1:0];
reg [N-1:0] path_metric_history_reg [L-1:0];

integer i, j, k;
integer min_index;
integer hamming_distance;

// initialize state and path metric registers
initial begin
  state_reg = 0;
  path_metric_reg = 0;
  data_out_reg = 0;
  input_reg = 0;
  for (i = 0; i < L; i = i + 1) begin
    input_history_reg[i] = 0;
    path_metric_history_reg[i] = 0;
  end
end

// state transition and path metric calculation
always @(posedge clk) begin
  if (reset) begin
    state_reg <= 0;
    path_metric_reg <= 0;
    data_out_reg <= 0;
    input_reg <= 0;
    for (i = 0; i < L; i = i + 1) begin
      input_history_reg[i] <= 0;
      path_metric_history_reg[i] <= 0;
    end
  end else begin
    state_reg <= state_next;
    path_metric_reg <= path_metric_next;
    data_out_reg <= data_out_next;
    input_reg <= input_next;
    for (i = 0; i < L-1; i = i + 1) begin
      input_history_reg[i] <= input_history_reg[i+1];
      path_metric_history_reg[i] <= path_metric_history_reg[i+1];
    end
    input_history_reg[L-1] <= input_reg;
    path_metric_history_reg[L-1] <= path_metric_reg;
  end

  // calculate state transitions and path metrics
  for (i = 0; i < N; i = i + 1) begin
    for (j = 0; j < 2; j = j + 1) begin
      k = (i << 1) | j;
      if (k < (1 << K)) begin
        if (j == 0) begin
          state_next[i] = state_reg[i] >> 1;
        end else begin
          state_next[i] = (state_reg[i] >> 1) | (1 << (K-1));
        end
        input_next = {input_reg[K-2:0], j};
        hamming_distance = $countones(state_next[i] ^ input_next);
        path_metric_next[i] = path_metric_reg[i] + hamming_distance;
        if (i == 0) begin
          data_out_next = {data_out_reg[N-2:0], j};
        end
        if (path_metric_next[i] < path_metric_history_reg[0]) begin
          path_metric_history_reg[0] = path_metric_next[i];
          data_out_history_reg[0] = data_out_next;
        end
      end
    end
  end

  // determine most likely sequence of transmitted bits
  min_index = 0;
  for (i = 1; i < L; i = i + 1) begin
    if (path_metric_history_reg[i] < path_metric_history_reg[min_index]) begin
      min_index = i;
    end
  end
  data_out_next = data_out_history_reg[min_index];
end

assign data_out = data_out_reg;

endmodule

