module calculator(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output [7:0] result,
    output overflow
);

reg [15:0] temp_result;

always @(*) begin
    case(op)
        2'b00: temp_result = a + b;
        2'b01: temp_result = a - b;
        2'b10: temp_result = a * b;
        2'b11: temp_result = a / b;
    endcase
end

assign result = temp_result[7:0];
assign overflow = (op[1] == 0) ? (temp_result > 8'hFF) : (temp_result > 16'hFFFF);

endmodule

module top_module (
    input clk,
    input reset,  // Synchronous active-high reset
    input [7:0] d,  // 8-bit input for the register
    input select,  // Select input to choose between register and counter
    output [7:0] q  // 8-bit output from the addition operation
);

    // Instantiate the register module
    reg_module reg_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(reg_out)
    );

    // Instantiate the counter module
    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .q(counter_out)
    );

    // Instantiate the adder module
    adder_module adder_inst (
        .a(select ? reg_out : counter_out),
        .b(select ? counter_out : reg_out),
        .sum(q)
    );

    // Declare internal wires
    wire [7:0] reg_out;
    wire [3:0] counter_out;

endmodule

// 8-bit register with active high synchronous reset
module reg_module (
    input clk,
    input reset,  // Synchronous active-high reset
    input [7:0] d,  // 8-bit input
    output reg [7:0] q  // 8-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 8'h34;
        end else begin
            q <= d;
        end
    end

endmodule

// 4-bit binary counter that counts from 0 through 15, with synchronous reset to 0
module counter_module (
    input clk,
    input reset,  // Synchronous active-high reset
    output reg [3:0] q  // 4-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

// Functional module that adds two 8-bit inputs
module adder_module (
    input [7:0] a,  // 8-bit input a
    input [7:0] b,  // 8-bit input b
    output reg [7:0] sum  // 8-bit output sum
);

    always @(*) begin
        sum = a + b;
    end

endmodule

module wb_semaphore 
  #(parameter count=8, DBUS_WIDTH=32)
    (input wb_clk_i,
     input wb_rst_i,
     input [DBUS_WIDTH-1:0] wb_dat_i,
     input [2:0] wb_adr_i,
     input wb_cyc_i,
     input wb_stb_i,
     input wb_we_i,
     output wb_ack_o,
     output [DBUS_WIDTH-1:0] wb_dat_o);

   reg [count-1:0] locked;

   always @(posedge wb_clk_i)
     if(wb_rst_i)
       locked <= {count{1'b0}};
     else if(wb_stb_i)
       if(wb_we_i)
	 locked[wb_adr_i] <= 1'b0;
       else
	 locked[wb_adr_i] <= 1'b1;

   assign 	   wb_dat_o[DBUS_WIDTH-1:1] = {(DBUS_WIDTH-1){1'b0}};
   assign 	   wb_dat_o[0] = locked[wb_adr_i];
   assign 	   wb_ack_o = wb_stb_i && !wb_we_i && (locked[wb_adr_i] || !wb_cyc_i);

endmodule

module fifo_full_block (
   // Outputs
   wr_fifo_full, wr_fifo_almost_full, wr_addr, wr_gray_pointer,
   // Inputs
   reset, wr_clk, wr_rd_gray_pointer, wr_write
   );

   parameter AW   = 2; // Number of bits to access all the entries 

   //##########
   //# INPUTS
   //##########
   input           reset;
   input           wr_clk;

   input [AW:0]    wr_rd_gray_pointer;//synced from read domain
   input           wr_write;

   //###########
   //# OUTPUTS
   //###########
   output           wr_fifo_full;
   output           wr_fifo_almost_full;

   output [AW-1:0]  wr_addr;
   output [AW:0]    wr_gray_pointer;//for read domain

   //#########
   //# REGS
   //#########
   reg [AW:0]      wr_gray_pointer;
   reg [AW:0]      wr_binary_pointer;
   reg             wr_fifo_full;

   //##########
   //# WIRES
   //##########
   wire            wr_fifo_full_next;
   wire [AW:0]     wr_gray_next;
   wire [AW:0]     wr_binary_next;

   wire 	   wr_fifo_almost_full_next;
   reg 		   wr_fifo_almost_full;

   //Counter States
   always @(posedge wr_clk or posedge reset)
     if(reset)
       begin
	  wr_binary_pointer[AW:0]     <= {(AW+1){1'b0}};
	  wr_gray_pointer[AW:0]       <= {(AW+1){1'b0}};
       end
     else if(wr_write)
       begin
	  wr_binary_pointer[AW:0]     <= wr_binary_next[AW:0];	  
	  wr_gray_pointer[AW:0]       <= wr_gray_next[AW:0];	  
       end

   //Write Address
   assign wr_addr[AW-1:0]       = wr_binary_pointer[AW-1:0];

   //Updating binary pointer
   assign wr_binary_next[AW:0]  = wr_binary_pointer[AW:0] + 
				  {{(AW){1'b0}},wr_write};

   //Gray Pointer Conversion (for more reliable synchronization)!
   assign wr_gray_next[AW:0]    = {1'b0,wr_binary_next[AW:1]} ^ 
				  wr_binary_next[AW:0];

   //FIFO full indication
   assign wr_fifo_full_next =
			 (wr_gray_next[AW-2:0] == wr_rd_gray_pointer[AW-2:0]) &
			 (wr_gray_next[AW]     ^  wr_rd_gray_pointer[AW])     &
			 (wr_gray_next[AW-1]   ^  wr_rd_gray_pointer[AW-1]);


   always @ (posedge wr_clk or posedge reset)
     if(reset)
       wr_fifo_full <= 1'b0;
     else
       wr_fifo_full <=wr_fifo_full_next;


   //FIFO almost full
   assign wr_fifo_almost_full_next =
			 (wr_gray_next[AW-3:0] == wr_rd_gray_pointer[AW-3:0]) &
			 (wr_gray_next[AW]     ^  wr_rd_gray_pointer[AW])     &
			 (wr_gray_next[AW-1]   ^  wr_rd_gray_pointer[AW-1])   &
			 (wr_gray_next[AW-2]   ^  wr_rd_gray_pointer[AW-2]);

   always @ (posedge wr_clk or posedge reset)
     if(reset)
       wr_fifo_almost_full <= 1'b0;
     else
       wr_fifo_almost_full <=wr_fifo_almost_full_next;

endmodule

