    wire equal, greater_than, less_than;

    alu_module alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .Y(Y)
    );

    comparator_module comp_inst (
        .A(A),
        .B(B),
        .equal(equal),
        .greater_than(greater_than),
        .less_than(less_than)
    );

    always @(*) begin
        case ({equal, greater_than, less_than})
            3'b000: result = 2'b00;
            3'b001: result = 2'b01;
            3'b010: result = 2'b10;
            3'b100: result = 2'b10;
            3'b011: result = 2'b00;
            3'b101: result = 2'b00;
            3'b110: result = 2'b00;
            3'b111: result = 2'b11;
        endcase
    end

endmodule

module freq_divider (
  input clk,
  input rst,
  input [3:0] div_factor,
  output reg clk_out
);

// The module has a 4-bit control input, which allows for division factors of up to 16.
// The default division factor is 2.
parameter DEFAULT_DIV_FACTOR = 2;
parameter MAX_DIV_FACTOR = 16;

initial begin
  clk_out <= 0;
end

reg [3:0] count;

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    clk_out <= 0;
    count <= 0;
  end
  else begin
    if (count >= div_factor - 1) begin
      count <= 0;
      clk_out <= ~clk_out;
    end
    else begin
      count <= count + 1;
    end
  end
end

endmodule

