  always @(posedge clk, posedge reset) begin
    if (reset) begin
      y <= 4'b0000;
      match <= 1'b0;
    end else begin
      case (y)
        4'b0000: begin
          if (data == 4'b0001) begin
            y <= 4'b0001;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b0001: begin
          if (data == 4'b0010) begin
