            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b0110: begin
          if (data == 4'b0111) begin
            y <= 4'b0111;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b0111: begin
          if (data == 4'b1000) begin
            y <= 4'b1000;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b1000: begin
          if (data == 4'b1001) begin
            y <= 4'b1001;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b1001: begin
          if (data == 4'b1010) begin
            y <= 4'b1010;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b1010: begin
          if (data == 4'b1011) begin
            y <= 4'b1011;
