          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b1101: begin
          if (data == 4'b1110) begin
            y <= 4'b1110;
            match <= 1'b0;
          end else begin
            y <= 4'b0000;
            match <= 1'b0;
          end
        end
        4'b1110: begin
          if (data == 4'b1111) begin
            y <= 4'b1111;
            match <= 1'b1;
          end else begin
            y <= 4'b0001;
            match <= 1'b0;
          end
        end
        4'b1111: begin
