module Booth_Multiplier(
    input signed [3:0] multiplicand,
    input signed [3:0] multiplier,
    input clock,
    input start,
    output signed [7:0] product,
    output busy
);

reg signed [7:0] product_reg;
reg [2:0] state;
reg busy_reg;

always @(posedge clock) begin
    case(state)
        3'b000: begin
            product_reg <= 8'b00000000;
            state <= 3'b001;
        end
        3'b001: begin
            if(start) begin
                busy_reg <= 1;
                state <= 3'b010;
            end
        end
        3'b010: begin
            if(multiplier[0] == 1) begin
                product_reg <= product_reg - multiplicand;
            end else if(multiplier[0] == 0) begin
                product_reg <= product_reg + multiplicand;
            end
            multiplier <= {multiplier[2:0], multiplier[3]};
            state <= 3'b011;
        end
        3'b011: begin
            multiplier <= {multiplier[2:0], multiplier[3]};
            state <= 3'b100;
        end
        3'b100: begin
            multiplier <= {multiplier[2:0], multiplier[3]};
            state <= 3'b010;
        end
    endcase
end

assign product = product_reg;
assign busy = busy_reg;

always @(posedge clock) begin
    if(state == 3'b010 && multiplier == 4'b0000) begin
        busy_reg <= 0;
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input ld,
    input data_in,
    input [3:0] d,
    output reg [3:0] q
);

reg [3:0] shift_reg;
reg [3:0] up_counter;

// Shift Register with Parallel Load and Asynchronous Reset
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        shift_reg <= 4'b0000;
    end else begin
        if (ld) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[2:0], d[0]};
        end
    end
end

// Up Counter with Synchronous Reset and Load Inputs
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        up_counter <= 4'b0000;
    end else begin
        if (ld) begin
            up_counter <= data_in;
        end else begin
            up_counter <= up_counter + 1;
        end
    end
end

// Functional Module that performs bitwise AND operation
always @(posedge clk) begin
    q <= shift_reg & up_counter;
end

endmodule

