module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input select,
    output [7:0] out
);

    wire [15:0] sum;
    wire threshold_exceeded;
    wire edge_detected;
    wire [7:0] active_output;
    wire [7:0] and_result;

    // Instantiate the first given module
    sum_module sum_inst (
        .in(in),
        .sum(sum),
        .threshold_exceeded(threshold_exceeded)
    );

    // Instantiate the second given module
    edge_detection_module edge_inst (
        .in(in[7]),
        .edge_detected(edge_detected)
    );

    // Control logic for selecting active module
    assign active_output = select ? edge_detected : threshold_exceeded;

    // Instantiate the functional module for bitwise AND operation
    and_module and_inst (
        .in1(active_output),
        .in2(sum[15:8]),
        .and_result(and_result)
    );

    // Output assignment
    assign out = threshold_exceeded ? edge_detected ? and_result : edge_detected : and_result;

endmodule

// First given module
module sum_module (
    input [31:0] in,
    output [15:0] sum,
    output threshold_exceeded
);

    assign sum = in[31:16] + in[15:0];
    assign threshold_exceeded = (sum > 16'h8000);

endmodule

