module four_bit_adder(A, B, C, Y, OVF);
input [3:0] A, B;
input C;
output [3:0] Y;
output OVF;

reg [3:0] sum;
reg [3:0] diff;

// Calculate the sum and difference
always @ (A, B, C)
begin
    if (C == 0) // Add
    begin
        sum = A + B;
        diff = 4'b0;
    end
    else // Subtract
    begin
        sum = 4'b0;
        diff = A - B;
    end
end

// Calculate the output and overflow
always @ (sum, diff)
begin
    if (sum > 4'b1111) // Overflow
    begin
        Y = 4'b1111;
        OVF = 1;
    end
    else if (diff < 4'b0000) // Underflow
    begin
        Y = 4'b0000;
        OVF = 1;
    end
    else // Normal output
    begin
        Y = (C == 0) ? sum : diff;
        OVF = 0;
    end
end

endmodule

module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output [31:0] and_result
);

    wire [15:0] carry;
    wire [15:0] g;
    wire [15:0] p;
    wire [15:0] c;

    wire [31:0] and_result_temp;

    assign and_result_temp = a & b;

    assign and_result = reset ? 32'b0 : and_result_temp;

    assign {carry[16], g[16], p[16]} = {1'b0, a[16] & b[16], a[16] ^ b[16]};
    assign {carry[15], g[15], p[15]} = {carry[16], a[15] & b[15], a[15] ^ b[15]};
    assign {carry[14], g[14], p[14]} = {carry[15], a[14] & b[14], a[14] ^ b[14]};
    assign {carry[13], g[13], p[13]} = {carry[14], a[13] & b[13], a[13] ^ b[13]};
    assign {carry[12], g[12], p[12]} = {carry[13], a[12] & b[12], a[12] ^ b[12]};
    assign {carry[11], g[11], p[11]} = {carry[12], a[11] & b[11], a[11] ^ b[11]};
    assign {carry[10], g[10], p[10]} = {carry[11], a[10] & b[10], a[10] ^ b[10]};
    assign {carry[9], g[9], p[9]} = {carry[10], a[9] & b[9], a[9] ^ b[9]};
    assign {carry[8], g[8], p[8]} = {carry[9], a[8] & b[8], a[8] ^ b[8]};
    assign {carry[7], g[7], p[7]} = {carry[8], a[7] & b[7], a[7] ^ b[7]};
    assign {carry[6], g[6], p[6]} = {carry[7], a[6] & b[6], a[6] ^ b[6]};
    assign {carry[5], g[5], p[5]} = {carry[6], a[5] & b[5], a[5] ^ b[5]};
    assign {carry[4], g[4], p[4]} = {carry[5], a[4] & b[4], a[4] ^ b[4]};
    assign {carry[3], g[3], p[3]} = {carry[4], a[3] & b[3], a[3] ^ b[3]};
    assign {carry[2], g[2], p[2]} = {carry[3], a[2] & b[2], a[2] ^ b[2]};
    assign {carry[1], g[1], p[1]} = {carry[2], a[1] & b[1], a[1] ^ b[1]};
    assign {carry[0], g[0], p[0]} = {carry[1], a[0] & b[0], a[0] ^ b[0]};

    assign c[16] = g[16] | (p[16] & carry[16]);
    assign c[15] = g[15] | (p[15] & carry[15]);
    assign c[14] = g[14] | (p[14] & carry[14]);
