parameter m = 2; // number of output signals
parameter V1 = 3.3; // input voltage level
parameter V2 = 5; // output voltage level

// Define logical operations to shift voltage levels
// In this case, we will use a simple voltage divider circuit
// to shift from V1 to V2

// Calculate the resistance values for the voltage divider
// R1 = R2 * (V1 / (V2 - V1))
parameter R2 = 1000; // choose a value for R2
parameter R1 = R2 * (V1 / (V2 - V1));

// Define the voltage divider circuit
// Vout = Vin * (R2 / (R1 + R2))
// We will use this equation to shift the voltage levels
// from V1 to V2
assign out = in * (R2 / (R1 + R2));

