module spi_master (
  input clk,
  input rst,
  input mosi,
  input sclk,
  input ss,
  output reg miso
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] bit_count;
  reg [2:0] tx_bit_count;
  reg [2:0] rx_bit_count;
  reg tx_done;
  reg rx_done;

  always @(posedge clk) begin
    if (rst) begin
      miso <= 1'b0;
      bit_count <= 3'd0;
      tx_bit_count <= 3'd0;
      rx_bit_count <= 3'd0;
      tx_done <= 1'b0;
      rx_done <= 1'b0;
    end
    else begin
      if (ss == 1'b0) begin
        if (bit_count == 3'd0) begin
          tx_data <= mosi;
          tx_bit_count <= 3'd0;
          rx_bit_count <= 3'd0;
          tx_done <= 1'b0;
          rx_done <= 1'b0;
        end
        else begin
          if (tx_bit_count < 3'd8) begin
            miso <= tx_data[7 - tx_bit_count];
            tx_bit_count <= tx_bit_count + 1;
          end
          else begin
            if (rx_bit_count < 3'd8) begin
              rx_data[7 - rx_bit_count] <= miso;
              rx_bit_count <= rx_bit_count + 1;
            end
            else begin
              tx_done <= 1'b1;
              rx_done <= 1'b1;
            end
          end
        end
        bit_count <= bit_count + 1;
      end
      else begin
        miso <= 1'b0;
        bit_count <= 3'd0;
        tx_bit_count <= 3'd0;
        rx_bit_count <= 3'd0;
        tx_done <= 1'b0;
        rx_done <= 1'b0;
      end
    end
  end

endmodule

