module nios_system_switches (
                              // inputs:
                               address,
                               clk,
                               in_port,
                               reset_n,

                              // outputs:
                               readdata
                            )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  9: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  9: 0] data_in;
  wire    [  9: 0] read_mux_out;
  reg     [ 31: 0] readdata;
  reg     [  9: 0] reg1;
  reg     [  9: 0] reg2;
  assign clk_en = 1;

  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          begin
            readdata <= 0;
            reg1 <= 0;
            reg2 <= 0;
          end
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end

  assign data_in = (address == 2'b00) ? in_port :
                   (address == 2'b01) ? reg1 :
                   (address == 2'b10) ? reg2 :
                   (address == 2'b11) ? in_port & reg1 : 10'b0;

  assign read_mux_out = (address == 2'b00) ? data_in :
                        (address == 2'b01) ? reg1 :
                        (address == 2'b10) ? reg2 :
                        (address == 2'b11) ? in_port & reg1 : 10'b0;

  always @(posedge clk)
    begin
      if (reset_n == 0)
          begin
            reg1 <= 0;
            reg2 <= 0;
          end
      else
          begin
            case (address)
              2'b01: reg1 <= in_port;
              2'b10: reg2 <= in_port;
              2'b11: reg1 <= in_port;
            endcase
          end
    end

endmodule

module UART (
    input rx_clk,
    input rx_data,
    input tx_clk,
    output reg tx_data,
    output reg rx_interrupt,
    output reg tx_interrupt,
    output reg tx,
    output reg tx_en,
    output reg rts_n,
    input reset,
    input cts_n,
    input clock,
    input rx
);

    parameter Address1 = 0;
    parameter Address2 = 0;
    parameter EnIntRXInterrupt = 0;
    parameter EnIntTXInterrupt = 0;
    parameter FlowControl = 0;
    parameter HalfDuplexEn = 0;
    parameter HwTXEnSignal = 1;
    parameter NumDataBits = 8;
    parameter NumStopBits = 1;
    parameter ParityType = 0;
    parameter RXEnable = 1;
    parameter TXEnable = 0;

    reg [NumDataBits-1:0] data_reg;
    reg [3:0] state_reg;
    reg [2:0] bit_count_reg;
    reg [1:0] stop_bit_count_reg;
    reg parity_reg;
    reg tx_busy_reg;

    always @(posedge rx_clk) begin
        if (reset) begin
            state_reg <= 4'b0000;
            bit_count_reg <= 3'b000;
            stop_bit_count_reg <= 2'b00;
            parity_reg <= 1'b0;
            rx_interrupt <= 1'b0;
        end else begin
            case (state_reg)
                4'b0000: begin // idle state
                    if (!rx) begin
                        state_reg <= 4'b0001;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                        parity_reg <= 1'b0;
                    end
                end
                4'b0001: begin // start bit received
                    data_reg[0] <= rx_data;
                    state_reg <= 4'b0010;
                end
                4'b0010: begin // data bits received
                    data_reg[bit_count_reg] <= rx_data;
                    bit_count_reg <= bit_count_reg + 1;
                    parity_reg <= parity_reg ^ rx_data;
                    if (bit_count_reg == NumDataBits-1) begin
                        state_reg <= 4'b0011;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0011: begin // parity bit received
                    if (ParityType == 1) begin
                        if (rx_data != parity_reg) begin
                            state_reg <= 4'b0000;
                            rx_interrupt <= 1'b1;
                        end else begin
                            state_reg <= 4'b0100;
                            stop_bit_count_reg <= 2'b00;
                        end
                    end else begin
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0100: begin // stop bits received
                    stop_bit_count_reg <= stop_bit_count_reg + 1;
                    if (stop_bit_count_reg == NumStopBits) begin
                        state_reg <= 4'b0000;
                        rx_interrupt <= 1'b1;
                    end
                end
            endcase
        end
    end

    always @(posedge tx_clk) begin
        if (reset) begin
            state_reg <= 4'b0000;
            bit_count_reg <= 3'b000;
            stop_bit_count_reg <= 2'b00;
            tx_busy_reg <= 1'b0;
            tx_interrupt <= 1'b0;
        end else begin
            case (state_reg)
                4'b0000: begin // idle state
                    if (TXEnable && tx_en && !tx_busy_reg) begin
                        state_reg <= 4'b0001;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                        tx_data <= 1'b0;
                        tx_busy_reg <= 1'b1;
                    end
                end
                4'b0001: begin // start bit transmitted
                    tx_data <= 1'b0;
                    state_reg <= 4'b0010;
                end
                4'b0010: begin // data bits transmitted
                    tx_data <= data_reg[bit_count_reg];
                    bit_count_reg <= bit_count_reg + 1;
                    if (bit_count_reg == NumDataBits-1) begin
                        state_reg <= 4'b0011;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0011: begin // parity bit transmitted
                    if (ParityType == 1) begin
                        tx_data <= parity_reg;
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end else begin
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0100: begin // stop bits transmitted
                    tx_data <= 1'b1;
                    stop_bit_count_reg <= stop_bit_count_reg + 1;
                    if (stop_bit_count_reg == NumStopBits) begin
                        state_reg <= 4'b0000;
                        tx_busy_reg <= 1'b0;
                        tx_interrupt <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign rx_clk = clock;
    assign tx_clk = clock;
    assign tx = tx_busy_reg;
    assign rts_n = 1'b1;

endmodule

Instruction:
Please act as a professional verilog designer. Create a module to implement the given 4-variable Boolean function f, as shown in the Karnaugh map below. The function takes 4 input bits (x1, x2, x3, x4) and produces a single output bit (y). Use Verilog to describe the logic gate implementation of this function. You may use basic logic gates (AND, OR, NOT) and any combination of them to achieve the desired output.

Karnaugh map:
// x[1]x[2] // x[3]x[4]
00 01 11 10
// 00 | 1 | 0 | 0 | 1 |
// 01 | 0 | 0 | 0 | 0 |
// 11 | 1 | 1 | 1 | 0 |
// 10 | 1 | 1 | 0 | 1 |

Response:
module karnaugh_map (
  input x1,
  input x2,
  input x3,
  input x4,
  output y
);

  wire w1, w2, w3, w4, w5, w6, w7, w8;

  assign w1 = x1 & x4;
  assign w2 = x1 & x2 & x3;
  assign w3 = x1 & x2 & x4;
  assign w4 = x1 & x3 & x4;
  assign w5 = x2 & x3 & x4;
  assign w6 = x2 & x4;
  assign w7 = x3 & x4;
