module shift_register (
    input CLK,
    input shift,
    input [3:0] D,
    output reg Q3,
    output [3:0] Q
);

reg [3:0] Q_reg;

always @(posedge CLK) begin
    if (shift) begin
        Q_reg <= {Q_reg[2:0], D[0]};
        Q3 <= Q_reg[3];
    end
    else begin
        Q_reg <= {D, Q_reg[3]};
        Q3 <= Q_reg[3];
    end
end

assign Q = Q_reg;

endmodule

