module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry_outs;
  wire [3:0] sums;

  // First full adder
  full_adder FA0(
    .a(A[0]),
    .b(B[0]),
    .c(carry_in),
    .sum(sums[0]),
    .carry_out(carry_outs[0])
  );

  // Second full adder
  full_adder FA1(
    .a(A[1]),
    .b(B[1]),
    .c(carry_outs[0]),
    .sum(sums[1]),
    .carry_out(carry_outs[1])
  );

  // Third full adder
  full_adder FA2(
    .a(A[2]),
    .b(B[2]),
    .c(carry_outs[1]),
    .sum(sums[2]),
    .carry_out(carry_outs[2])
  );

  // Fourth full adder
  full_adder FA3(
    .a(A[3]),
    .b(B[3]),
    .c(carry_outs[2]),
    .sum(sums[3]),
    .carry_out(carry_out)
  );

  assign sum = sums;

endmodule

module edge_detect_adder_display (
