reg [7:0] prev_in;
reg [7:0] edge_detected;
wire [7:0] sum;

always @(negedge clk) begin
    if (reset) begin
        reg_value <= 8'h34;
    end else begin
        reg_value <= sum;
    end
end

always @(posedge clk) begin
    edge_detected <= (in ^ prev_in);
    prev_in <= in;
end

assign sum = reg_value + edge_detected;

reg [6:0] seg_temp;
always @(*) begin
    case (sum)
        4'h0: seg_temp = 7'b1000000;
