module BinarySearch (
  input clk,
  input reset,
  input [31:0] arr [0:1023],
  input [9:0] n,
  input [31:0] target,
  output reg [9:0] index
);

  reg [9:0] low = 0;
  reg [9:0] high = n - 1;
  reg [9:0] mid;

  always @(posedge clk) begin
    if (reset) begin
      index <= -1;
      low <= 0;
      high <= n - 1;
    end else begin
      if (low > high) begin
        index <= -1;
      end else begin
        mid = (low + high) / 2;
        if (arr[mid] == target) begin
          index <= mid;
        end else if (arr[mid] > target) begin
          high <= mid - 1;
        end else begin
          low <= mid + 1;
        end
      end
    end
  end

endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] stage1, stage2, stage3, stage4;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            stage1 <= 4'b0000;
            stage2 <= 4'b0000;
            stage3 <= 4'b0000;
            stage4 <= 4'b0000;
            q <= 4'b0000;
        end else if (load) begin
            stage1 <= data[0];
            stage2 <= data[1];
            stage3 <= data[2];
            stage4 <= data[3];
            q <= data;
        end else if (ena) begin
            stage1 <= q[0];
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
            q <= {stage4, q[3:1]};
        end
    end

endmodule

