module CoProcessor0RF(clk, din, wEn, regNum, sel, dout, npc_out, expiaddr, ins);
	input				clk;
	input		[1:0]	wEn;
	input 		[4:0]	regNum;
	input		[2:0]	sel;
	input		[31:0]	din;
	input 		[31:0] 	ins;
	input 		[31:0] 	npc_out;
	output		[31:0]	dout;
	output reg 	[31:0] 	expiaddr;

	reg	[31:0]	coprf	[0:31];

	wire [5:0] op;
	wire [5:0] func;
	wire [4:0] mf_tc0_eret;

	assign op			= ins[31:26];
	assign mf_tc0_eret	= ins[25:21];
	assign func			= ins[5:0];

	// op
	parameter 	R 				= 6'b000000,
				MTC0_MFC0_ERET	= 6'b010000;
	// Function code.
	parameter 	SYSCALL	= 6'b001100;
	// MTC0_MFC0_ERET
	parameter 	MTC0 	= 5'b00100,
				MFC0 	= 5'b00000,
				ERET 	= 5'b10000;

	initial begin
		coprf[12]	= 32'h0000_0000;// Status
		coprf[13]	= 32'h0000_0000;// Cause
		coprf[14]	= 32'h0000_3000;// EPC
	end

	assign dout = coprf[regNum];

	always @ (posedge clk) begin
		if (wEn) begin
			if ((op == R) && (func == SYSCALL)) begin// SYSCALL
				coprf[14] <= npc_out - 3'b100;
				coprf[13][6:2] <= 5'b01000;
				coprf[12][1] <= 1'b1;
				expiaddr <= 32'h0000_3000;
			end else if ((op == MTC0_MFC0_ERET) && (mf_tc0_eret == ERET)) begin// ERET
				coprf[12][1] <= 1'b0;
				expiaddr <= coprf[14][31:0];
			end else begin// MTC0
				coprf[regNum] <= din;
			end
		end
	end

endmodule

module parity_mux (
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [8:0] out
);

    // 8-bit odd parity checker
    wire [7:0] in_xor = in0 ^ in1;
    wire odd_parity = ^in_xor;

    // 2-to-1 multiplexer
    always @(*) begin
        if (sel == 1'b0) begin
            out[8:1] = in0;
        end else begin
            out[8:1] = in1;
        end
    end

    // Parity bit computation
    always @(*) begin
        if (odd_parity == 1'b1) begin
            out[0] = 1'b1;
        end else begin
            out[0] = 1'b0;
        end
    end

endmodule

module Counter(
  input Reset_n_i,
  input Clk_i,
  input ResetSig_i,
  input Preset_i,
  input Enable_i,
  input Direction_i,
  input [15:0] PresetVal_i,
  output reg [15:0] D_o,
  output reg Overflow_o,
  output reg Zero_o
);

  reg [15:0] count;

  always @(posedge Clk_i) begin
    if (!Reset_n_i) begin
      count <= 16'd0;
      Overflow_o <= 1'b0;
      Zero_o <= 1'b1;
    end
    else if (ResetSig_i) begin
      count <= 16'd0;
      Overflow_o <= 1'b0;
      Zero_o <= 1'b1;
    end
    else if (Preset_i) begin
      count <= PresetVal_i;
      Overflow_o <= (Direction_i && (PresetVal_i == 16'hFFFF)) || (!Direction_i && (PresetVal_i == 16'h0000));
      Zero_o <= (PresetVal_i == 16'h0000);
    end
    else if (Enable_i) begin
      if (Direction_i) begin
        if (count == 16'hFFFF) begin
          count <= 16'h0000;
          Overflow_o <= 1'b1;
          Zero_o <= 1'b0;
        end
        else begin
          count <= count + 1;
          Overflow_o <= 1'b0;
          Zero_o <= (count == 16'h0000);
        end
      end
      else begin
        if (count == 16'h0000) begin
          count <= 16'hFFFF;
          Overflow_o <= 1'b0;
          Zero_o <= 1'b1;
        end
        else begin
          count <= count - 1;
          Overflow_o <= (count == 16'hFFFF);
          Zero_o <= 1'b0;
        end
      end
    end
    D_o <= count;
  end

endmodule

module clock_period_checker(clk, rst, max_period, clk_period);

parameter MAX_TIME = max_period * 2; // maximum time between rising edges of the clock
input clk, rst;
input [31:0] max_period;
output reg [31:0] clk_period;

reg [31:0] last_edge_time; // stores the time of the last rising edge of the clock
reg [31:0] current_time; // stores the time of the current rising edge of the clock

always @(posedge clk) begin
    if (rst == 0) begin
        clk_period <= 0;
        last_edge_time <= 0;
        current_time <= 0;
    end else begin
        // calculate the time since the last rising edge of the clock
        current_time <= $time;
        clk_period <= current_time - last_edge_time;

        if (clk_period > MAX_TIME) begin
            $display("Warning: Input clock period of %1.3f ns exceeds allowed value of %1.3f ns at time %1.3f ns.", clk_period/1000.0, max_period/1000.0, $time/1000.0);
        end

        // update the last_edge_time register
        last_edge_time <= current_time;
    end
end

endmodule

