module add_sub_control(
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] out
);

    // Instantiate the adder and subtractor modules
    eight_bit_adder adder(.a(a), .b(b), .sum(sum_adder));
    four_bit_subtractor subtractor(.a(a), .b(b), .diff(diff_subtractor));

    // Control logic to select adder or subtractor based on select signal
    always @ (posedge clk) begin
        if (reset) begin
            out <= 8'b0;
        end else begin
            if (select) begin
                out <= sum_adder;
            end else begin
                out <= diff_subtractor;
            end
        end
    end

