module top_module( 
    input [99:0] in,
    input select, // Select input to choose between AND, OR, and XOR outputs
    output out_and,
    output out_or,
    output out_xor 
);

// Define intermediate wires for BDD
wire [99:0] and_wire;
wire [99:0] or_wire;
wire [99:0] xor_wire;

// AND operation using BDD
assign and_wire = &in;

// OR operation using BDD
assign or_wire = |in;

// XOR operation using BDD
assign xor_wire = ^in;

// Control logic for selecting output
always @(*) begin
    case (select)
        1'b0: begin // AND selected
            out_and = and_wire;
            out_or = 1'b0;
            out_xor = 1'b0;
        end
        1'b1: begin // OR selected
            out_and = 1'b0;
            out_or = or_wire;
            out_xor = 1'b0;
        end
        default: begin // XOR selected
            out_and = 1'b0;
            out_or = 1'b0;
            out_xor = xor_wire;
        end
    endcase
end

endmodule

