module axi_tap (
    input clk,
    input rst,
    input [DATA_WIDTH-1:0] tap_axis_tdata,
    input [KEEP_WIDTH-1:0] tap_axis_tkeep,
    input tap_axis_tvalid,
    output tap_axis_tready,
    input tap_axis_tlast,
    input [ID_WIDTH-1:0] tap_axis_tid,
    input [DEST_WIDTH-1:0] tap_axis_tdest,
    input [USER_WIDTH-1:0] tap_axis_tuser,
    output reg [DATA_WIDTH-1:0] m_axis_tdata,
    output reg [KEEP_WIDTH-1:0] m_axis_tkeep,
    output reg m_axis_tvalid,
    input m_axis_tready,
    output reg m_axis_tlast,
    output reg [ID_WIDTH-1:0] m_axis_tid,
    output reg [DEST_WIDTH-1:0] m_axis_tdest,
    output reg [USER_WIDTH-1:0] m_axis_tuser
);

// Parameters
parameter DATA_WIDTH = 8;
parameter KEEP_ENABLE = (DATA_WIDTH>8);
parameter KEEP_WIDTH = (DATA_WIDTH/8);
parameter ID_ENABLE = 1;
parameter ID_WIDTH = 8;
parameter DEST_ENABLE = 1;
parameter DEST_WIDTH = 8;
parameter USER_ENABLE = 1;
parameter USER_WIDTH = 1;
parameter USER_BAD_FRAME_VALUE = 1'b1;
parameter USER_BAD_FRAME_MASK = 1'b1;

// Internal signals
reg [DATA_WIDTH-1:0] tap_data_reg;
reg [KEEP_WIDTH-1:0] tap_keep_reg;
reg tap_valid_reg;
reg tap_last_reg;
reg [ID_WIDTH-1:0] tap_id_reg;
reg [DEST_WIDTH-1:0] tap_dest_reg;
reg [USER_WIDTH-1:0] tap_user_reg;

// Bad frame detection
reg bad_frame;
always @(posedge clk) begin
    if (rst) begin
        bad_frame <= 0;
    end else if (tap_valid_reg && !tap_last_reg && !m_axis_tready) begin
        bad_frame <= 1;
    end else if (tap_valid_reg && tap_last_reg && !m_axis_tvalid) begin
        bad_frame <= 1;
    end else if (tap_valid_reg && tap_last_reg && m_axis_tvalid && (tap_user_reg & USER_BAD_FRAME_MASK) == USER_BAD_FRAME_VALUE) begin
        bad_frame <= 1;
    end else begin
        bad_frame <= 0;
    end
end

// AXI tap
axis_tap #(
    .DATA_WIDTH(DATA_WIDTH),
    .KEEP_ENABLE(KEEP_ENABLE),
    .KEEP_WIDTH(KEEP_WIDTH),
    .ID_ENABLE(ID_ENABLE),
    .ID_WIDTH(ID_WIDTH),
    .DEST_ENABLE(DEST_ENABLE),
    .DEST_WIDTH(DEST_WIDTH),
    .USER_ENABLE(USER_ENABLE),
    .USER_WIDTH(USER_WIDTH),
    .USER_BAD_FRAME_VALUE(USER_BAD_FRAME_VALUE),
    .USER_BAD_FRAME_MASK(USER_BAD_FRAME_MASK)
)
UUT (
    .clk(clk),
    .rst(rst),
    // AXI tap
    .tap_axis_tdata(tap_data_reg),
    .tap_axis_tkeep(tap_keep_reg),
    .tap_axis_tvalid(tap_valid_reg),
    .tap_axis_tready(tap_axis_tready),
    .tap_axis_tlast(tap_last_reg),
    .tap_axis_tid(tap_id_reg),
    .tap_axis_tdest(tap_dest_reg),
    .tap_axis_tuser(tap_user_reg),
    // AXI output
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tkeep(m_axis_tkeep),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .m_axis_tlast(m_axis_tlast),
    .m_axis_tid(m_axis_tid),
    .m_axis_tdest(m_axis_tdest),
    .m_axis_tuser(m_axis_tuser)
);

// Tap into input signals and modify user value
always @(posedge clk) begin
    if (rst) begin
        tap_data_reg <= 0;
        tap_keep_reg <= 0;
        tap_valid_reg <= 0;
        tap_last_reg <= 0;
        tap_id_reg <= 0;
        tap_dest_reg <= 0;
        tap_user_reg <= 0;
    end else begin
        if (current_test == 0) begin
            // Send valid frame with user value of 0
            tap_data_reg <= 8'hFF;
            tap_keep_reg <= {KEEP_WIDTH{1'b1}};
            tap_valid_reg <= 1;
            tap_last_reg <= 0;
            tap_id_reg <= 8'hAA;
            tap_dest_reg <= 8'hBB;
            tap_user_reg <= 1'b0;
        end else if (current_test == 1) begin
            // Tap into input signals and modify user value
            tap_data_reg <= tap_axis_tdata;
            tap_keep_reg <= tap_axis_tkeep;
            tap_valid_reg <= tap_axis_tvalid;
            tap_last_reg <= tap_axis_tlast;
            tap_id_reg <= tap_axis_tid;
            tap_dest_reg <= tap_axis_tdest;
            tap_user_reg <= 1'b1;
        end else if (current_test == 2) begin
            // Send valid frame with user value of 0
            tap_data_reg <= 8'hFF;
            tap_keep_reg <= {KEEP_WIDTH{1'b1}};
            tap_valid_reg <= 1;
            tap_last_reg <= 1;
            tap_id_reg <= 8'hAA;
            tap_dest_reg <= 8'hBB;
            tap_user_reg <= 1'b0;
        end
    end
end

// Output signals match input signals, except for modified user value
always @(posedge clk) begin
    if (rst) begin
        m_axis_tdata <= 0;
        m_axis_tkeep <= 0;
        m_axis_tvalid <= 0;
        m_axis_tlast <= 0;
        m_axis_tid <= 0;
        m_axis_tdest <= 0;
        m_axis_tuser <= 0;
    end else begin
        if (tap_axis_tvalid && m_axis_tready) begin
            m_axis_tdata <= tap_axis_tdata;
            m_axis_tkeep <= tap_axis_tkeep;
            m_axis_tvalid <= tap_axis_tvalid;
            m_axis_tlast <= tap_axis_tlast;
            m_axis_tid <= tap_axis_tid;
            m_axis_tdest <= tap_axis_tdest;
            m_axis_tuser <= bad_frame ? USER_BAD_FRAME_VALUE : tap_axis_tuser;
        end
    end
end

endmodule

module up_down_counter (
    input clk,
    input rst,
    input up_down,
    output reg [2:0] count
);

reg [2:0] count_reg1;
reg [2:0] count_reg2;

always @(posedge clk) begin
    if (rst) begin
        count_reg1 <= 3'b0;
        count_reg2 <= 3'b0;
    end
    else begin
        count_reg1 <= up_down ? count : count_reg2;
        count_reg2 <= count_reg1;
    end
end

assign count = count_reg2 + (up_down ? 1 : -1);

endmodule

module traffic_light_controller (
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);

  // Define the states
  parameter STATE_1 = 2'b00;
  parameter STATE_2 = 2'b01;
  parameter STATE_3 = 2'b10;
  parameter STATE_4 = 2'b11;

  // Define the state register and initialize to STATE_1
  reg [1:0] state_reg = STATE_1;

  // Define the state transition logic
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state_reg <= STATE_1;
    end else begin
      case (state_reg)
        STATE_1: state_reg <= STATE_2;
        STATE_2: state_reg <= STATE_3;
        STATE_3: state_reg <= STATE_4;
        STATE_4: state_reg <= STATE_1;
      endcase
    end
  end

  // Define the output logic based on the current state
  always @(*) begin
    case (state_reg)
      STATE_1: begin
        red <= 0;
        yellow <= 0;
        green <= 1;
      end
      STATE_2: begin
        red <= 0;
        yellow <= 1;
        green <= 0;
      end
      STATE_3: begin
        red <= 1;
        yellow <= 0;
        green <= 0;
      end
      STATE_4: begin
        red <= 1;
        yellow <= 1;
        green <= 0;
      end
    endcase
  end

endmodule

