module sirv_gnrl_pipe_stage # (
  parameter CUT_READY = 0,
  parameter DP = 1,
  parameter DW = 32
) (
  input           i_vld, 
  output          i_rdy, 
  input  [DW-1:0] i_dat,
  output          o_vld, 
  input           o_rdy, 
  output [DW-1:0] o_dat,

  input           clk,
  input           rst_n
);

  genvar i;
  generate
  if(DP == 0) begin: dp_eq_0
      assign o_vld = i_vld;
      assign i_rdy = o_rdy;
      assign o_dat = i_dat;
  end
  else begin: dp_gt_0
      wire vld_set;
      wire vld_clr;
      wire vld_ena;
      wire vld_r;
      wire vld_nxt;

      assign vld_set = i_vld & i_rdy;
      assign vld_clr = o_vld & o_rdy;

      assign vld_ena = vld_set | vld_clr;
      assign vld_nxt = vld_set | (~vld_clr);

      sirv_gnrl_dfflr #(1) vld_dfflr (vld_ena, vld_nxt, vld_r, clk, rst_n);

      assign o_vld = vld_r;

      sirv_gnrl_dffl #(DW) dat_dfflr (vld_set, i_dat, o_dat, clk);

      if(CUT_READY == 1) begin:cut_ready
          assign i_rdy = (~vld_r);
      end
      else begin:no_cut_ready
          assign i_rdy = (~vld_r) | vld_clr;
      end
  end
  endgenerate

endmodule

module FP16RMulS0Of2(
 input 	       clk,
 input 	       rst,
 input [15:0]  arg_0,
 input [15:0]  arg_1,
 output        ret_0,
 output [4:0]  ret_1,
 output [4:0]  ret_2,
 output [11:0] ret_3);

   wire        s0;
   wire        s1;
   wire [4:0]  e0;
   wire [4:0]  e1;
   wire [9:0]  f0;
   wire [9:0]  f1;
   wire [10:0] ff0;
   wire [10:0] ff1;
   wire [21:0] z;
   wire [11:0] zz;

   assign s0 = arg_0[15:15];
   assign s1 = arg_1[15:15];
   assign e0 = arg_0[14:10];
   assign e1 = arg_1[14:10];
   assign f0 = arg_0[9:0];
   assign f1 = arg_1[9:0];

   // sign
   assign ret_0 = s0 ^ s1;
   // exponent
   assign ret_1 = e0;
   assign ret_2 = e1;

   assign ff0 = {(e0 == 0 ? 1'b0 : 1'b1), f0};
   assign ff1 = {(e1 == 0 ? 1'b0 : 1'b1), f1};

   assign z = ff0 * ff1;
   assign zz = z[21:10];

   // fraction
   assign ret_3 = zz;

   // normalize fraction
   assign {zz, ret_1} = (zz[10] == 1'b1) ? {zz[9:0], ret_1 + 1} : {zz[8:0], ret_1};

endmodule

module matrix_multiplier (
    input signed [7:0] A [3:0][3:0],
    input signed [7:0] B [3:0][3:0],
    output signed [7:0] C [3:0][3:0]
);
    integer i, j, k;
    reg signed [15:0] temp;

    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                temp = 0;
                for (k = 0; k < 4; k = k + 1) begin
                    temp = temp + A[i][k] * B[k][j];
                end
                C[i][j] = temp;
            end
        end
    end

endmodule

