module calculator (
  input clk,
  input rst_n,
  input op,
  input signed [7:0] a,
  input signed [7:0] b,
  output reg signed [7:0] result,
  output reg overflow
);

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      result <= 0;
      overflow <= 0;
    end else begin
      if (op == 0) begin // addition
        result <= a + b;
        if (((a > 0) && (b > 0) && (result < 0)) || ((a < 0) && (b < 0) && (result > 0))) begin
          overflow <= 1;
        end else begin
          overflow <= 0;
        end
      end else begin // subtraction
        result <= a - b;
        if (((a > 0) && (b < 0) && (result < 0)) || ((a < 0) && (b > 0) && (result > 0))) begin
          overflow <= 1;
        end else begin
          overflow <= 0;
        end
      end
    end
  end

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  input [1:0] state_in,
  output reg [1:0] state_out,
  output reg red_led,
  output reg green_led
);

  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  reg [3:0] counter;
  reg [1:0] current_state;

  always @(posedge clk) begin
    if (reset) begin
      counter <= 0;
      current_state <= GREEN;
    end
    else begin
      case (current_state)
        GREEN: begin
          green_led <= 1;
          red_led <= 0;
          if (counter == 20000000) begin
            current_state <= YELLOW;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
        YELLOW: begin
          green_led <= 0;
          red_led <= 1;
          if (counter == 4000000) begin
            current_state <= RED;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
        RED: begin
          green_led <= 0;
          red_led <= 1;
          if (counter == 20000000) begin
            current_state <= GREEN;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    state_out <= current_state;
  end

endmodule

