module fifo_module (
    input aclr,       // Asynchronous clear input
    input clock,      // Clock input
    output empty,     // Output indicating if FIFO is empty
    output full,      // Output indicating if FIFO is full
    input rreq,       // Read request input
    input sclr,       // Synchronous clear input
    output [2:0] usedw_out, // Output indicating number of words stored
    input wreq        // Write request input
);

    // Parameter to define the depth of the FIFO
    parameter depth = 8;

    // Parameter to define the width of each word in the FIFO
    parameter width = 8;

    // Internal wires and registers
    wire [2:0] usedw;
    wire valid_rreq;
    wire valid_wreq;
    wire is_almost_empty;
    wire is_almost_full;
    reg [depth-1:0] fifo_data;
    reg full_reg;
    reg non_empty_reg;

    // Instantiate the small FIFO counter module
    small_fifo_cntr count_usedw (
        .aclr(aclr),
        .clock(clock),
        .cnt_en(valid_wreq ^ valid_rreq),
        .q(usedw),
        .sclr(sclr),
        .updown(valid_wreq)
    );

    // Logic to handle read and write requests
    always @ (posedge clock or posedge aclr) begin
        if (aclr) begin
            fifo_data <= {depth{1'b0}};
            full_reg <= 1'b0;
            non_empty_reg <= 1'b0;
        end else begin
            // Handle read request
            if (rreq && valid_rreq) begin
                non_empty_reg <= (usedw > 0);
                fifo_data <= {fifo_data[depth-width-1:0], {width{1'b0}}};
            end
            // Handle write request
            if (wreq && valid_wreq) begin
                fifo_data <= {fifo_data[depth-width-1:0], wreq};
                full_reg <= (usedw == depth-1);
                non_empty_reg <= 1'b1;
            end
        end
    end

    // Logic to handle clear requests
    always @ (posedge clock or posedge aclr) begin
        if (aclr) begin
            full_reg <= 1'b0;
            non_empty_reg <= 1'b0;
        end else begin
            if (sclr) begin
                fifo_data <= {depth{1'b0}};
                full_reg <= 1'b0;
                non_empty_reg <= 1'b0;
            end
        end
    end

    // Output signals
    assign empty = ~non_empty_reg;
    assign full = full_reg;
    assign usedw_out = usedw;
    assign valid_rreq = rreq & non_empty_reg;
    assign valid_wreq = wreq & ~full_reg;

endmodule

