    input reset,
    input [3:0] DATA_IN_A,
    input [2:0] DATA_IN_B,
    output reg [6:0] PRODUCT_OUT
);

    reg [4:0] A;
    reg [3:0] S;
    reg [2:0] P;
    reg [1:0] count;
    reg [3:0] temp;

    always @(posedge clk) begin
        if (reset) begin
            A <= 0;
            S <= 0;
            P <= 0;
            count <= 0;
        end else begin
            temp <= {DATA_IN_A, 2'b0};
            if (count == 0) begin
                S <= DATA_IN_B;
                P <= 0;
            end else begin
                if (S[1:0] == 2'b01) begin
                    P <= P + temp;
                end else if (S[1:0] == 2'b10) begin
                    P <= P - temp;
                end
                S <= {S[1], S[0], S[2]};
            end
            count <= count + 1;
        end
    end

    assign PRODUCT_OUT = P[6:0];

endmodule

