   input [dw-1:0] di_b,
   output reg [dw-1:0] do_a
   );

   //
   // Default address and data buses width
   //
   parameter aw = 5;
   parameter dw = 32;

   //
   // Internal wires and registers
   //
   reg [dw-1:0] mem [(1<<aw)-1:0];	// RAM content
   reg [aw-1:0] addr_a_reg;		// RAM address registered

   // Function to access GPRs
   function [31:0] get_gpr;
      input [aw-1:0] gpr_no;
      begin
         get_gpr = mem[gpr_no];
      end
   endfunction // get_gpr

   function [31:0] set_gpr;
      input [aw-1:0] gpr_no;
      input [dw-1:0] value;
      begin
         mem[gpr_no] = value;
         set_gpr = 0;
      end
   endfunction // get_gpr

   //
   // Data output drivers
   //
   always @(posedge clk_a)
     if (ce_a)
       do_a <= mem[addr_a_reg];
     else
       do_a <= 0;

   //
   // RAM read
   //
   always @(posedge clk_a)
     if (ce_a)
       addr_a_reg <=  addr_a;

   //
   // RAM write
   //
   always @(posedge clk_b)
     if (ce_b & we_b)
       mem[addr_b] <=  di_b;

   //
   // Initialize RAM to all zeros
   //
   integer k;
   initial begin 
      for(k = 0; k < (1 << aw); k = k + 1) begin
         mem[k] = 0;
      end
   end

