module flt_mult
	(
	input			clk,
	input			rstn,
	input	    [31:0]	afl,
	input	    [31:0]	bfl,
	output	reg [31:0]	fl
	);

reg	[47:0]	mfl_0;		// Mantisa of the Float
reg		sfl_0;		// Sign of the Float
reg	[7:0]	efl_0;		// Exponent of the Float
reg		zero_out_0;
reg		sfl_1;		// Sign of the Float
reg	[7:0]	efl_1;		// Exponent of the Float
reg		zero_out_1;
reg		mfl47_1;	// Mantisa of the Float
reg	[24:0]	nmfl_1;		// Normalized Mantisa of the Float
reg 		not_mfl_47;

always @* not_mfl_47 = (~mfl47_1 & ~nmfl_1[24]);

always @(posedge clk, negedge rstn) begin
	if(!rstn) begin
		mfl_0 	   <= 48'h0;
		sfl_0 	   <= 1'b0;
		efl_0 	   <= 8'h0;
		zero_out_0 <= 1'b0;
		efl_1 	   <= 8'h0;
		sfl_1 	   <= 1'b0;
		zero_out_1 <= 1'b0;
		mfl47_1    <= 1'b0;
		nmfl_1     <= 25'h0;
		fl 	   <= 32'h0;
	end
	else begin
		// Pipe 0.
		// Multiply the mantisa.
		mfl_0 <= {1'b1,afl[22:0]} * {1'b1,bfl[22:0]};
		// Calulate the Sign.
		sfl_0 <= afl[31] ^ bfl[31];
		efl_0 <= afl[30:23] + bfl[30:23] - 8'h7E;
		// If a or b equals zero, return zero.
		if((afl[30:0] == 0) || (bfl[30:0] == 0))zero_out_0 <= 1'b1;
		else zero_out_0 <= 1'b0;
		// Pipe 1.
		efl_1 <= efl_0;	
		sfl_1 <= sfl_0;	
		zero_out_1 <= zero_out_0;
		mfl47_1  <= mfl_0[47];
		if(mfl_0[47]) nmfl_1 <= mfl_0[47:24] + mfl_0[23];
		else 	      nmfl_1 <= mfl_0[47:23] + mfl_0[22];
		// Pipe 2.
		if(zero_out_1) fl <= 32'h0;
		else 	       fl <= {sfl_1,(efl_1 - not_mfl_47),nmfl_1[22:0]};
	end
end

endmodule

module axi_to_b2s_converter(
    input aclk,
    input areset,
    input [31:0] m_axi_araddr,
    input m_axi_arready,
    input m_axi_rvalid,
    input [31:0] m_axi_rdata,
    input [1:0] m_axi_rresp,
    output s_axi_arready,
    output s_axi_rvalid,
    output [31:0] s_axi_rdata,
    output [1:0] s_axi_rresp
);

    // Registers to store the current state of the converter
    reg [31:0] addr_reg;
    reg [1:0] resp_reg;
    reg [31:0] data_reg;
    reg [1:0] state;

    // Constants to define the state machine
    localparam IDLE = 2'b00;
    localparam READ_AXI = 2'b01;
    localparam OUTPUT_B2S = 2'b10;

    // Set initial state
    always @(posedge aclk, negedge areset) begin
        if (~areset) begin
            state <= IDLE;
            addr_reg <= 0;
            resp_reg <= 0;
            data_reg <= 0;
        end else begin
            state <= IDLE;
        end
    end

    // State machine to control the converter
    always @(posedge aclk) begin
        case (state)
            IDLE: begin
                if (m_axi_arready && s_axi_arready) begin
                    state <= READ_AXI;
                    addr_reg <= m_axi_araddr;
                end
            end
            READ_AXI: begin
                if (m_axi_rvalid) begin
                    state <= OUTPUT_B2S;
                    data_reg <= m_axi_rdata;
                    resp_reg <= m_axi_rresp;
                end
            end
            OUTPUT_B2S: begin
                state <= IDLE;
            end
        endcase
    end

    // Output signals
    assign s_axi_arready = state == IDLE;
    assign s_axi_rvalid = state == OUTPUT_B2S;
    assign s_axi_rdata = data_reg;
    assign s_axi_rresp = resp_reg;

endmodule

module clock_generator(
    input CLK_24M,
    input RESETP,
    output CLK_24MB,
    output LSPC_12M,
    output LSPC_8M,
    output LSPC_6M,
    output LSPC_4M,
    output LSPC_3M,
    output LSPC_1_5M,
    output Q53_CO
);

    assign CLK_24MB = ~CLK_24M;

    // D flip-flop with asynchronous active-low reset
    reg R262_Q, R262_nQ, R268_Q;
    always @(posedge CLK_24M or negedge RESETP) begin
        if (!RESETP) begin
            R262_Q <= 0;
            R262_nQ <= 1;
            R268_Q <= 0;
        end else begin
            R262_Q <= R268_Q;
            R262_nQ <= ~R268_Q;
            R268_Q <= R262_nQ;
        end
    end

    // D flip-flop with asynchronous active-high reset
    reg S219A_nQ;
    always @(posedge LSPC_8M or negedge RESETP) begin
        if (!RESETP) begin
            S219A_nQ <= 1;
        end else begin
            S219A_nQ <= ~S219A_nQ;
        end
    end

    // XOR gate
    assign Q53_CO = R262_Q ^ R262_nQ;

    // Inverter
    assign LSPC_1_5M = ~R262_Q;

    // 2-bit counter with asynchronous active-low reset
    reg [1:0] counter;
    always @(posedge LSPC_3M or negedge RESETP) begin
        if (!RESETP) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Mux
    assign LSPC_6M = (counter == 2'b00) ? 1 : 0;
    assign LSPC_4M = (counter == 2'b01) ? 1 : 0;
    assign LSPC_12M = (counter == 2'b10) ? 1 : 0;

    // AND gate
    assign LSPC_8M = ~(R262_Q & R262_nQ);

endmodule

