    // XOR the input with its right-shifted value
    assign xor_out = bin_in ^ {bin_in[2:0], 1'b0};
    // XOR the XOR output with its right-shifted value
    assign xor_out_shifted = xor_out ^ {xor_out[2:0], 1'b0};

    // Implement the first bit of the Gray code output
    sky130_fd_sc_hs__udp_dlatch$PR_pp$PG$N g1(
        .Q(gray_out[0]),
        .D(xor_out_shifted[0]),
        .GATE(1'b1),
        .RESET(1'b0),
        .NOTIFIER(1'b0),
        .VPWR(1'b1),
        .VGND(1'b0)
    );

    // Implement the remaining bits of the Gray code output
    assign gray_out[3:1] = xor_out_shifted[3:1] ^ gray_out[2:0];

