        .RST(RST),
        .EN(EN_REG1),
        .D(FIXED),
        .Q(fixed)
    );

    // Calculate the two's complement of the fixed-point number
    Complement COMPLEMENTO2 (
        .a_i(fixed),
        .twos_comp(complemento)
    );

    // Determine the sign of the number and store it in a MUX
    Mux_2x1_32Bits MUX2x1_0_I (
        .MS(fixed[31]),
        .D_0(fixed),
        .D_1(complemento),
        .D_out(MUXSIGN)
    );

    // Truncate the number to 30 bits
    FF_D #(.P(P)) REG_FLOAT_mult (
        .CLK(CLK),
        .RST(RST),
        .EN(EN_REGmult),
        .D(MUXSIGN),
        .Q(mult)
    );

    // Determine the position of the first 1 in the binary sequence
    Priority_Encoder OUTONE (
        .d_in(mult),
        .d_out(Encoder)
    );

    // Normalize the number and calculate the exponent
    S_SUBT #(.P(W),.W(W)) SUBT_EXP_1_I (
        .A(Encoder),
        .B(8'b00011010), // 26 in binary
        .Y(Bandcomp)
    );

    // If the exponent is greater than 26, set the Bandcomp signal to 1 and subtract 26 from the exponent
    S_SUBT #(.P(W),.W(W)) SUBT_EXP_2_I (
        .A(8'b00011010), // 26 in binary
        .B(Encoder),
        .Y(P_RESULT[7:0])
    );

    Mux_2x1_8Bits MUX2x1_1_I (
        .MS(Bandcomp),
        .D_0(P_RESULT[7:0]),
        .D_1(Encoder),
        .D_out(P_RESULT[7:0])
    );

    ADDT_8Bits #(.P(W),.W(W)) ADDT_EXPONENTE_I (
        .A(Encoder),
        .B(8'b01100101), // 101 in binary
        .Y(FLOATOUT[30:23])
    );

    // Shift the mantissa left or right depending on the value of Bandcomp
    Barrel_Shifter #(.SWR(32),.EWR(8)) S_REG_I (
        .clk(CLK),
        .rst(RST),
        .load_i(LOAD),
        .Shift_Value_i(MS_1),
        .Shift_Data_i(mult),
        .Left_Right_i(~Bandcomp),
        .Bit_Shift_i(1'b0),
        .N_mant_o(P_RESULT)
    );

    // Combine the sign, exponent, and mantissa to form the floating-point number
    assign FLOATOUT[31] = fixed[31];
    assign FLOATOUT[22:0] = P_RESULT[25:3];

    // Store the floating-point number in a register
    FF_D #(.P(P)) REG_FLOAT (
        .CLK(CLK),
        .RST(RST),
        .EN(EN_REG2),
        .D(FLOATOUT),
        .Q(FLOATOUT)
    );

    // Output the value of the first 1 in the binary sequence
    assign Encd = Encoder[7:0];

endmodule

module rising_edge_detector (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

reg [31:0] stage1_out;
reg [31:0] stage2_out;
reg [31:0] stage3_out;

always @(posedge clk) begin
    if (reset) begin
        stage1_out <= 0;
        stage2_out <= 0;
        stage3_out <= 0;
    end else begin
        stage1_out <= in;
        stage2_out <= stage1_out ^ {stage1_out[0], stage1_out[31:1]};
        stage3_out <= stage2_out & {~stage2_out[0], stage2_out[31:1]};
    end
end

assign out = stage3_out;

endmodule

module freq_divider(
  input clk,
  input rst,
  output reg clk_out
);

parameter div = 2;
reg [31:0] count;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    clk_out <= 1'b0;
    count <= 0;
  end
  else begin
    if (count == div - 1) begin
      clk_out <= ~clk_out;
      count <= 0;
    end
    else begin
      count <= count + 1;
    end
  end
end

endmodule

module twos_complement_display (
    input [3:0] data_in,
    input [3:0] en,
    output reg [6:0] seg_a,
    output reg [6:0] seg_b,
    output reg [6:0] seg_c,
    output reg [6:0] seg_d
);

    reg [3:0] twos_comp;
    reg [6:0] hex_val;
    reg [1:0] digit_sel = 2'b00;

    always @(*) begin
        twos_comp = ~data_in + 1;
        case (twos_comp)
            4'b0000: hex_val = 7'b100_0000;
            4'b0001: hex_val = 7'b111_1001;
            4'b0010: hex_val = 7'b010_0100;
            4'b0011: hex_val = 7'b011_0000;
            4'b0100: hex_val = 7'b001_1001;
            4'b0101: hex_val = 7'b001_0010;
            4'b0110: hex_val = 7'b000_0010;
            4'b0111: hex_val = 7'b111_1000;
            4'b1000: hex_val = 7'b000_0000;
            4'b1001: hex_val = 7'b001_1000;
            4'b1010: hex_val = 7'b000_0100;
            4'b1011: hex_val = 7'b000_0001;
            4'b1100: hex_val = 7'b000_0110;
            4'b1101: hex_val = 7'b000_1110;
            4'b1110: hex_val = 7'b000_1100;
            4'b1111: hex_val = 7'b000_0111;
            default: hex_val = 7'b111_1111;
        endcase
    end

    always @(posedge clk) begin
        if (en[0]) begin
            digit_sel <= 2'b00;
            seg_a <= hex_val;
