module delay_block (
  input clk,
  input in,
  output out
);

parameter delay = 10; // delay time in nanoseconds

reg [31:0] count = 0; // 32-bit counter to count up to the specified delay time
reg delayed_in = 0; // delayed input signal

always @(posedge clk) begin
  if (in != delayed_in) begin // reset the counter whenever the input signal changes
    count <= 0;
    delayed_in <= in;
  end else if (count < delay) begin // increment the counter until it reaches the delay time
    count <= count + 1;
  end else begin // output the delayed input signal
    out <= in;
  end
end

endmodule

module file_reader(
    input clk,
    input rst,
    input file_in,
    input read_enable,
    output reg [31:0] data_out,
    output reg pass
);

  reg [31:0] in_32;
  integer res, fd;

  always @(posedge clk) begin
    if (rst) begin
      data_out <= 0;
      pass <= 0;
    end else if (read_enable) begin
      // read data from file
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);

      // check for missing bytes
      if (res !== -1) begin
        $display("FAILED: $fscanf() returned %d (%b)", res, in_32);
        pass <= 0;
      end

      // assign output data
      data_out <= in_32;

      // check suppression of data reads
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%*u", in_32);
      $fclose(fd);
      if (res !== -1) begin
        $display("FAILED: $fscanf() suppression returned %d (%b)", res, in_32);
        pass <= 0;
      end

      // check that data was read correctly
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);
      if (res !== 1) begin
        $display("FAILED: $fscanf() read returned %d (%b)", res, in_32);
        pass <= 0;
      end else if (in_32 !== data_out) begin
        $display("FAILED: Data mismatch (%b != %b)", in_32, data_out);
        pass <= 0;
      end

      // check that there is no more data to read
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);
      if (res !== -1) begin
        $display("FAILED: EOF not reached (%d bytes remaining)", res);
        pass <= 0;
      end

      // if all checks passed, set pass signal
      if (pass) pass <= 1;
    end
  end
endmodule

