module counter (clk, reset, modulus, cout);

    // INPUT PORTS
    input clk;
    input reset;
    input [31:0] modulus;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES
    reg [31:0] count;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;

    // INITIALIZE VARIABLES
    initial begin
        count = 1;
        first_rising_edge = 1;
        clk_last_value = 0;
    end

    // COUNTER LOGIC
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 1;
            tmp_cout <= 0;
            first_rising_edge <= 1;
        end else begin
            if (first_rising_edge && (clk == 1'b1) && (clk_last_value == 1'b0)) begin
                first_rising_edge <= 0;
                tmp_cout <= clk;
            end else begin
                if (count < modulus) begin
                    count <= count + 1;
                end else begin
                    count <= 1;
                    tmp_cout <= ~tmp_cout;
                end
            end
        end
        clk_last_value <= clk;
    end

    // OUTPUT ASSIGNMENT
    assign cout = tmp_cout;

endmodule

