module ALU_1bit_overflow
(
// Input
		input								a_in,
		input								b_in,
		input								carry_in,
		input								b_invert,
		input								less,
		input     		[1:0]     	op,

// Output
		output	wire					result,
		output	wire					carry_out,
		output	wire					set,
		output	wire					overflow
    );

// Internal Variables
reg					b_invert_out;
reg					mux_out;
reg					check;

wire					fa_01_out;
wire					and_out;
wire					or_out;

//assign
assign 				set = fa_01_out;
assign				overflow = check;
assign				result   =  mux_out;

//submodule
full_adder fa_01 (
	.x_in				( a_in				),
	.y_in				( b_invert_out 	),
	.c_in				( carry_in 			),
	.s_out			( fa_01_out 		),
	.c_out			( carry_out 		)
); // Full_Adder


// b_Inverter
always @ ( b_invert or b_in )
begin : Binvert
			if ( !b_invert )
				b_invert_out	=   	b_in;				// 	b
			else
				b_invert_out	=		~ b_in;			//		b'
end

// Logical_operation
assign		and_out	=	a_in & b_invert_out;
assign		or_out	=	a_in | b_invert_out;

// op_Selection
always @ ( op or and_out or or_out or less or fa_01_out )
begin : Operation
		if ( op == 0 )
			mux_out	= 	and_out;
			else if ( op == 1)
				mux_out	= 	or_out;
			else if ( op == 2)
				mux_out	= 	fa_01_out;
			else 
				mux_out	= 	less;		
end

//Overflow_detection
always @ ( op or a_in or b_invert_out or fa_01_out or carry_in)
begin : Checker
		if ( op == 0 || op == 1 )
			check = 1'b0;
			else if ( op == 2 && carry_in == 1'b1 && fa_01_out == 1'b1 )
			check = 1'b1;
			else if ( op == 2 && carry_in == 1'b0 && fa_01_out == 1'b0 )
			check = 1'b1;
			else if ( op == 3 && less == 1'b1 && a_in == 1'b0 && b_invert_out == 1'b1 )
			check = 1'b1;
			else if ( op == 3 && less == 1'b0 && a_in == 1'b1 && b_invert_out == 1'b0 )
			check = 1'b1;
			else
			check = 1'b0;
end 

endmodule

