  FDCE #(
    .INIT(1'b0)) 
    FDCE_1 
       (.C(m_aclk),
        .CE(1'b1),
        .CLR(rd_rst_reg_reg),
        .D(D[1]),
        .Q(Q_reg[1]));
  FDCE #(
