module sirv_expl_apb_slv #(
    parameter AW = 32,
    parameter DW = 32 
)(
  input  [AW-1:0] apb_paddr,
  input           apb_pwrite,
  input           apb_pselx,
  input           apb_penable,
  input  [DW-1:0] apb_pwdata,
  output [DW-1:0] apb_prdata,

  input  clk,  
  input  rst_n
);

  reg [DW-1:0] data_mem [(1<<AW)/DW-1:0]; // data memory
  reg [DW-1:0] byte_order; // byte order register
  reg [2:0] access_type; // access type register
  reg [1:0] byte_select; // byte select register
  reg [AW-1:0] addr_reg; // address register
  reg [DW-1:0] read_data; // read data register
  reg [DW-1:0] write_data; // write data register
  reg [1:0] byte_shift; // byte shift register

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      byte_order <= 2'b0;
      access_type <= 3'b0;
      byte_select <= 2'b0;
      addr_reg <= 0;
      read_data <= 0;
      write_data <= 0;
      byte_shift <= 0;
    end else begin
      if (apb_pselx && apb_penable) begin
        // determine byte order
        if (apb_paddr[1] == 1'b1 && access_type == 3'b0) begin
          byte_order <= apb_pwdata[7:6];
        end
        // determine access type
        if (apb_paddr[0] == 1'b1) begin
          access_type <= apb_pwdata[1:0];
        end
        // determine byte select
        if (access_type == 3'b0) begin
          byte_select <= apb_paddr[1:0];
        end else if (access_type == 3'b1) begin
          byte_select <= apb_paddr[2:1];
        end else if (access_type == 3'b10) begin
          byte_select <= apb_paddr[1];
        end else if (access_type == 3'b11) begin
          byte_select <= 2'b0;
        end
        // determine address
        addr_reg <= apb_paddr[AW-1:2];
        if (access_type == 3'b0) begin
          addr_reg <= addr_reg + byte_select;
        end else if (access_type == 3'b1) begin
          addr_reg <= addr_reg + (byte_select << 2);
        end else if (access_type == 3'b10) begin
          addr_reg <= addr_reg + (byte_select << 1);
        end
        // read data
        if (!apb_pwrite) begin
          read_data <= data_mem[addr_reg];
        end
        // write data
        if (apb_pwrite) begin
          write_data <= apb_pwdata;
          if (access_type == 3'b0) begin
            case (byte_select)
              2'b00: data_mem[addr_reg][7:0] <= write_data;
              2'b01: data_mem[addr_reg][15:8] <= write_data;
              2'b10: data_mem[addr_reg][23:16] <= write_data;
              2'b11: data_mem[addr_reg][31:24] <= write_data;
            endcase
          end else if (access_type == 3'b1) begin
            case (byte_select)
              2'b00: data_mem[addr_reg][31:0] <= write_data;
              2'b01: data_mem[addr_reg][31:8] <= {data_mem[addr_reg][23:0], write_data};
              2'b10: data_mem[addr_reg][31:16] <= {data_mem[addr_reg][15:0], write_data};
              2'b11: data_mem[addr_reg][31:24] <= {data_mem[addr_reg][7:0], write_data};
            endcase
          end else if (access_type == 3'b10) begin
            case (byte_shift)
              2'b00: data_mem[addr_reg][15:0] <= write_data;
              2'b01: data_mem[addr_reg][31:16] <= write_data;
            endcase
            byte_shift <= ~byte_shift;
          end else if (access_type == 3'b11) begin
            data_mem[addr_reg] <= write_data;
          end
        end
      end
      // byte order conversion
      if (byte_order == 2'b10) begin
        read_data <= {read_data[7:0], read_data[15:8], read_data[23:16], read_data[31:24]};
      end
    end
  end

  assign apb_prdata = read_data;

endmodule

module PRNG (
  input reset,
  input clock,
  input [n-1:0] seed,
  output reg [n-1:0] rand
);

parameter n = 8; // number of bits in the pseudo-random number
parameter a = 3; // constant used to generate the pseudo-random number
parameter c = 5; // constant used to generate the pseudo-random number

reg [n-1:0] shift_reg;

always @(posedge clock) begin
  if (reset) begin
    shift_reg <= seed;
  end else begin
    shift_reg <= {shift_reg[n-2:0], shift_reg[n-a-1] ^ shift_reg[n-1]};
  end
  rand <= shift_reg;
end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between counter and multiplexer
    input [1023:0] in_mux, // 256 4-bit inputs packed into a single 1024-bit input vector
    output [3:0] q); // 4-bit output from the active module

    // Counter module
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else if (count == 4'b1111) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

    // Multiplexer module
    wire [3:0] mux_out;
    reg [7:0] select_reg;
    always @(posedge clk) begin
        if (reset) begin
            select_reg <= 8'b0;
        end else begin
            select_reg <= select_reg + 1;
        end
    end

    // Binary tree architecture for the multiplexer
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : mux_tree
            if (i == 0) begin
                assign mux_out = in_mux[select_reg[7:6]*16 + select_reg[5:2]*4 + select_reg[1:0]];
            end else begin
                wire [3:0] mux_left, mux_right;
                assign mux_left = mux_tree[i-1].mux_out;
                assign mux_right = mux_tree[i-1].mux_out;
                assign mux_out = (select_reg[7-i] == 1'b0) ? mux_left : mux_right;
            end
        end
    endgenerate

    // Control logic module to enable either the counter or the multiplexer
    always @(*) begin
        if (select == 1'b0) begin
            q = count | 4'b0000;
        end else begin
            q = mux_out | count;
        end
    end

endmodule

