module dataflow_graph_node (
    input clock,
    input resetn,
    input valid_in,
    output valid_out,
    input stall_in,
    output stall_out
);

reg valid_out_reg;
reg stall_out_reg;

always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        valid_out_reg <= 1'b0;
        stall_out_reg <= 1'b0;
    end else begin
        if (valid_in && ~stall_in) begin
            valid_out_reg <= 1'b1;
            stall_out_reg <= 1'b0;
        end else begin
            valid_out_reg <= 1'b0;
            stall_out_reg <= 1'b1;
        end
    end
end

assign valid_out = valid_out_reg;
assign stall_out = stall_out_reg;

endmodule

module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

  // Define states
  parameter INIT_STATE = 2'b00;
  parameter SECOND_STATE = 2'b01;
  parameter FINAL_STATE = 2'b10;

  // Define state register and next state logic
  reg [1:0] state_reg, state_next;

  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      state_reg <= INIT_STATE;
    end else begin
      state_reg <= state_next;
    end
  end

  // Define output register and matching logic
  reg match_reg;

  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      match_reg <= 1'b0;
    end else begin
      match_reg <= match;
    end
  end

  // Define state transition and matching logic
  always @(*) begin
    state_next = state_reg;
    match = match_reg;

    case (state_reg)
      INIT_STATE: begin
        if (data[3] == 1'b1) begin
          state_next = SECOND_STATE;
        end
      end

      SECOND_STATE: begin
        if (data[2:1] == 2'b01) begin
          state_next = FINAL_STATE;
        end else if (data[3] == 1'b0) begin
          state_next = INIT_STATE;
        end
      end

      FINAL_STATE: begin
        if (data[0] == 1'b0) begin
          match = 1'b1;
          state_next = INIT_STATE;
        end else begin
          state_next = INIT_STATE;
        end
      end
    endcase
  end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum,
    output cout
);

    wire [3:0] carry;
    full_adder fa0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], cout);

endmodule

module fifo (
  input clk, // clock signal
  input rst, // reset signal
  input [7:0] data_in, // input data
  input wr_en, // write enable signal
  output [7:0] data_out, // output data
  input rd_en, // read enable signal
  output full, // FIFO full signal
  output empty // FIFO empty signal
);

  parameter DEPTH = 8; // FIFO depth
  reg [7:0] mem [0:DEPTH-1]; // internal memory array
  reg [2:0] wr_ptr = 0; // write pointer
  reg [2:0] rd_ptr = 0; // read pointer
  reg [2:0] count = 0; // number of elements in the FIFO

  // combinational logic for full and empty signals
  assign full = (count == DEPTH);
  assign empty = (count == 0);

  // synchronous write operation
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      mem <= 0;
    end else if (wr_en && !full) begin
      mem[wr_ptr] <= data_in;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
    end
  end

  // synchronous read operation
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      mem <= 0;
    end else if (rd_en && !empty) begin
      data_out <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
    end
  end

endmodule

module uart_tx(
               input               clk_i,
               input [7:0]         rx_i,
               input               rx_i_v,
               output              tx_o,
               output              tx_o_v
               );

    localparam ST_IDLE   = 3'd0;
    localparam ST_START  = 3'd1;
    localparam ST_DATA   = 3'd2;
    localparam ST_STOP   = 3'd3;

    reg [2:0]                   state = ST_IDLE;
    reg [2:0]                   tx_ctr = 0;

    reg [7:0]                   s_rx = 0;
    reg                         s_tx = 1;


    always @ (posedge clk_i)
    begin
        case (state)

            ST_IDLE :
                if (rx_i_v)
                    state <= ST_START;

            ST_START :
                state <= ST_DATA;

            ST_DATA :
                if (tx_ctr == 7)
                    state <= ST_STOP;

            ST_STOP :
                state <= ST_IDLE;

        endcase
    end // always @ (posedge clk_i)

    always @ (posedge clk_i)
    begin
        if (state == ST_DATA)
        begin
            tx_ctr <= tx_ctr + 1;
        end
        else
        begin
            tx_ctr <= 0;
        end
    end // always @ (posedge state)

    always @ (posedge clk_i)
    begin
        if (state == ST_START)
        begin
            s_rx <= rx_i;
        end
        else if (state == ST_DATA)
        begin
            s_rx <= s_rx >> 1;
        end
    end

    assign tx_o_v = (state == ST_IDLE) ? 0 : 1;

    always @ *
    begin
        if (state == ST_START)
        begin
            s_tx = 0;
        end
        else if (state == ST_DATA)
        begin
            s_tx = s_rx[0];
        end
        else if (state == ST_STOP)
        begin
            s_tx = 1;
        end
    end // always @ *

    assign tx_o = s_tx;


endmodule

