module NIOS_SYSTEMV3_JTAG_UART_scfifo_r (
    // inputs:
    clk,
    fifo_clear,
    fifo_rd,
    rst_n,
    t_dat,
    wr_rfifo,

    // outputs:
    fifo_EF,
    fifo_rdata,
    rfifo_full,
    rfifo_used
);

    output fifo_EF;
    output [7:0] fifo_rdata;
    output rfifo_full;
    output [5:0] rfifo_used;
    input clk;
    input fifo_clear;
    input fifo_rd;
    input rst_n;
    input [7:0] t_dat;
    input wr_rfifo;

    reg [7:0] fifo_mem [63:0];
    reg [5:0] fifo_used;
    reg [5:0] fifo_head;
    reg [5:0] fifo_tail;
    wire fifo_empty = (fifo_used == 0);
    wire fifo_full = (fifo_used == 64);

    assign fifo_EF = fifo_empty || fifo_full;
    assign fifo_rdata = fifo_mem[fifo_tail];
    assign rfifo_full = fifo_full;
    assign rfifo_used = fifo_used;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fifo_head <= 6'd0;
            fifo_tail <= 6'd0;
            fifo_used <= 6'd0;
        end else begin
            if (fifo_clear) begin
                fifo_head <= 6'd0;
                fifo_tail <= 6'd0;
                fifo_used <= 6'd0;
            end else begin
                if (wr_rfifo && !fifo_full) begin
                    fifo_mem[fifo_head] <= t_dat;
                    fifo_head <= fifo_head + 1;
                    fifo_used <= fifo_used + 1;
                end
                if (fifo_rd && !fifo_empty) begin
                    fifo_tail <= fifo_tail + 1;
                    fifo_used <= fifo_used - 1;
                end
            end
        end
    end

endmodule

module cycloneive_scale_cntr   ( clk,
                                reset,
                                cout,
                                high,
                                low,
                                initial_value,
                                mode,
                                ph_tap);

    // INPUT PORTS
    input clk;
    input reset;
    input [31:0] high;
    input [31:0] low;
    input [31:0] initial_value;
    input [8*6:1] mode;
    input [31:0] ph_tap;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES AND NETS
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg init;
    integer count;
    integer output_shift_count;
    reg cout_tmp;

    initial
    begin
        count = 1;
        first_rising_edge = 0;
        tmp_cout = 0;
        output_shift_count = 1;
    end

    always @(clk or reset)
    begin
        if (init !== 1'b1)
        begin
            clk_last_value = 0;
            init = 1'b1;
        end
        if (reset)
        begin
            count = 1;
            output_shift_count = 1;
            tmp_cout = 0;
            first_rising_edge = 0;
        end
        else if (clk_last_value !== clk)
        begin
            if (mode == "   off")
                tmp_cout = 0;
            else if (mode == "bypass")
            begin
                tmp_cout = clk;
                first_rising_edge = 1;
            end
            else if (first_rising_edge == 0)
            begin
                if (clk == 1)
                begin
                    if (output_shift_count == initial_value)
                    begin
                        tmp_cout = clk;
                        first_rising_edge = 1;
                    end
                    else
                        output_shift_count = output_shift_count + 1;
                end
            end
            else if (output_shift_count < initial_value)
            begin
                if (clk == 1)
                    output_shift_count = output_shift_count + 1;
            end
            else
            begin
                count = count + 1;
                if (mode == "  even" && (count == (high*2) + 1))
                    tmp_cout = 0;
                else if (mode == "   odd" && (count == (high*2)))
                    tmp_cout = 0;
                else if (count == (high + low)*2 + 1)
                begin
                    tmp_cout = 1;
                    count = 1;        // reset count
                end
            end
        end
        clk_last_value = clk;
        cout_tmp <= tmp_cout;
    end

    and (cout, cout_tmp, 1'b1);

endmodule

module axis_data_fifo (
  input wire s_axis_aresetn,
  input wire s_axis_aclk,
  input wire s_axis_tvalid,
  input wire [39:0] s_axis_tdata,
  output wire s_axis_tready,
  output wire m_axis_tvalid,
  output wire [39:0] m_axis_tdata,
  output wire [31:0] axis_data_count,
  output wire [31:0] axis_wr_data_count,
  output wire [31:0] axis_rd_data_count
);

  // Parameter definitions
  parameter DATA_WIDTH = 40;
  parameter ADDR_WIDTH = 10;
  parameter DEPTH = 1024;

  // Internal signals
  reg [DATA_WIDTH-1:0] fifo [DEPTH-1:0];
  reg [ADDR_WIDTH-1:0] wr_ptr = 0;
  reg [ADDR_WIDTH-1:0] rd_ptr = 0;
  reg [31:0] data_count = 0;
  reg [31:0] wr_data_count = 0;
  reg [31:0] rd_data_count = 0;
  wire full = (data_count == DEPTH);
  wire empty = (data_count == 0);

  // Read/Write pointers
  always @(posedge s_axis_aclk) begin
    if (!s_axis_aresetn) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
    end else begin
      if (s_axis_tvalid && s_axis_tready) begin
        fifo[wr_ptr] <= s_axis_tdata;
        wr_ptr <= (wr_ptr == DEPTH-1) ? 0 : wr_ptr + 1;
        data_count <= data_count + 1;
        wr_data_count <= wr_data_count + 1;
      end
      if (m_axis_tvalid && m_axis_tready) begin
        rd_ptr <= (rd_ptr == DEPTH-1) ? 0 : rd_ptr + 1;
        data_count <= data_count - 1;
        rd_data_count <= rd_data_count + 1;
      end
    end
  end

  // Data output
  assign m_axis_tdata = fifo[rd_ptr];
  assign m_axis_tvalid = (data_count > 0);
  assign s_axis_tready = (!full);

  // Output signals
  assign axis_data_count = data_count;
  assign axis_wr_data_count = wr_data_count;
  assign axis_rd_data_count = rd_data_count;

endmodule

module top_module (
    input CLK,
    input UP_DOWN,
    input RESET,
    input [3:0] gray,
    output reg [3:0] OUT
);

reg [3:0] binary;
reg [3:0] counter;
reg [3:0] sum;

gray_to_binary gray_to_binary_inst (
    .gray(gray),
    .binary(binary)
);

up_down_counter up_down_counter_inst (
    .CLK(CLK),
    .UP_DOWN(UP_DOWN),
    .RESET(RESET),
    .OUT(counter)
);

functional_module functional_module_inst (
    .binary(binary),
    .counter(counter),
    .sum(sum)
);

always @ (posedge CLK) begin
    if (RESET) begin
        binary <= 4'b0000;
        counter <= 4'b0000;
        sum <= 4'b0000;
    end else begin
        if (UP_DOWN) begin
            counter <= counter + 4'b0001;
        end else begin
            counter <= counter - 4'b0001;
        end
    end
end

always @ (posedge CLK) begin
    sum <= binary + counter;
    OUT <= sum;
end

endmodule

module zet_next_or_not (
    input [1:0] prefix,
    input [7:1] opcode,
    input cx_zero,
    input zf,
    input ext_int,
    output next_in_opco,
    output next_in_exec,
    output use_eintp
  );

  // Net declarations
  wire exit_z, cmp_sca, exit_rep, valid_ops;

  // Assignments
  assign cmp_sca = opcode[7] & opcode[2] & opcode[1];
  assign exit_z = prefix[0] ? /* repz */ (cmp_sca ? ~zf : 1'b0 )
                            : /* repnz */ (cmp_sca ? zf : 1'b0 );
  assign exit_rep = cx_zero | exit_z;
  assign valid_ops = (opcode[7:1]==7'b1010_010   // movs
                   || opcode[7:1]==7'b1010_011   // cmps
                   || opcode[7:1]==7'b1010_101   // stos
                   || opcode[7:1]==7'b0110_110   // ins
                   || opcode[7:1]==7'b0110_111   // outs
                   || opcode[7:1]==7'b1010_110   // lods
                   || opcode[7:1]==7'b1010_111); // scas
  assign next_in_exec = prefix[1] && valid_ops && !exit_rep && !ext_int;
  assign next_in_opco = prefix[1] && valid_ops && cx_zero;
  assign use_eintp    = prefix[1] && valid_ops && !exit_z;

endmodule

module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [3:0] i_data0;
  output  [15:0] o_data0;

  //Multipliers:

  wire [15:0]
    w1,
    w256,
    w257,
    w8224,
    w8225,
    w16,
    w241,
    w964,
    w7261;

  assign w1 = {i_data0, 4'b0};
  assign w16 = w1 << 4;
  assign w257 = w1 + (w1 << 8);
  assign w241 = w257 - w16;
  assign w8224 = w257 << 5;
  assign w8225 = w1 + w8224;
  assign w964 = w241 << 2;
  assign w7261 = w8225 - w964;
  assign o_data0 = w7261;

  //multiplier_block area estimate = 7338.03834891177;
endmodule

