module contact_discovery_db_mem_V_m_axi_buffer
#(
    parameter MEM_STYLE = "block",
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 5,
    parameter DEPTH = 32
)
(
    input wire clk,
    input wire reset,
    input wire sclk_en,

    output wire if_full_n,
    input wire if_write_ce,
    input wire if_write,
    input wire [DATA_WIDTH-1:0] if_din,

    output wire if_empty_n,
    input wire if_read_ce,
    input wire if_read,
    output wire [DATA_WIDTH-1:0] if_dout
);

    // Memory
    (* ram_style = MEM_STYLE *) reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Write address and next address
    reg [ADDR_WIDTH-1:0] waddr = 0;
    wire [ADDR_WIDTH-1:0] wnext = (waddr == DEPTH-1) ? 0 : waddr + 1;

    // Read address and next address
    reg [ADDR_WIDTH-1:0] raddr = 0;
    wire [ADDR_WIDTH-1:0] rnext = (raddr == DEPTH-1) ? 0 : raddr + 1;

    // Flags
    reg [ADDR_WIDTH-1:0] usedw = 0;
    reg full_n = 1;
    reg empty_n = 0;
    reg [DATA_WIDTH-1:0] q_buf = 0;
    reg [DATA_WIDTH-1:0] q_tmp = 0;
    reg show_ahead = 0;
    reg [DATA_WIDTH-1:0] dout_buf = 0;
    reg dout_valid = 0;

    // Push and pop signals
    wire push = if_write_ce & if_write & full_n;
    wire pop = if_read_ce & if_read & empty_n;

    // Write data to memory
    always @(posedge clk) begin
        if (reset) begin
            waddr <= 0;
        end else if (sclk_en) begin
            if (push) begin
                mem[waddr] <= if_din;
                waddr <= wnext;
            end
        end
    end

    // Read data from memory
    always @(posedge clk) begin
        if (reset) begin
            raddr <= 0;
        end else if (sclk_en) begin
            if (pop) begin
                q_buf <= mem[rnext];
                raddr <= rnext;
            end
        end
    end

    // Update usedw
    always @(posedge clk) begin
        if (reset) begin
            usedw <= 0;
        end else if (sclk_en) begin
            if (push & ~pop) begin
                usedw <= usedw + 1;
            end else if (~push & pop) begin
                usedw <= usedw - 1;
            end
        end
    end

    // Update full_n
    always @(posedge clk) begin
        if (reset) begin
            full_n <= 1;
        end else if (sclk_en) begin
            if (push & ~pop) begin
                full_n <= (usedw != DEPTH-1);
            end else if (~push & pop) begin
                full_n <= 1;
            end
        end
    end

    // Update empty_n
    always @(posedge clk) begin
        if (reset) begin
            empty_n <= 0;
        end else if (sclk_en) begin
            if (push & ~pop) begin
                empty_n <= 1;
            end else if (~push & pop) begin
                empty_n <= (usedw != 1);
            end
        end
    end

    // Update q_tmp
    always @(posedge clk) begin
        if (reset) begin
            q_tmp <= 0;
        end else if (sclk_en) begin
            if (push) begin
                q_tmp <= if_din;
            end
        end
    end

    // Update show_ahead
    always @(posedge clk) begin
        if (reset) begin
            show_ahead <= 0;
        end else if (sclk_en) begin
            if (push && usedw == pop) begin
                show_ahead <= 1;
            end else begin
                show_ahead <= 0;
            end
        end
    end

    // Update dout_buf
    always @(posedge clk) begin
        if (reset) begin
            dout_buf <= 0;
        end else if (sclk_en) begin
            if (pop) begin
                dout_buf <= show_ahead ? q_tmp : q_buf;
            end
        end
    end

    // Update dout_valid
    always @(posedge clk) begin
        if (reset) begin
            dout_valid <= 0;
        end else if (sclk_en) begin
            if (pop) begin
                dout_valid <= 1;
            end else if (if_read_ce & if_read) begin
                dout_valid <= 0;
            end
        end
    end

    // Output signals
    assign if_full_n = full_n;
    assign if_empty_n = dout_valid;
    assign if_dout = dout_buf;

endmodule

module adder_4bit (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

