            clk_out1 <= ~clk_out1;
            if (invert_phase) begin
                clk_out2 <= ~master_in;
            end else begin
                clk_out2 <= master_in;
            end
        end else begin
            clk_out1 <= ~clk_out1;
            if (invert_phase) begin
                clk_out2 <= ~clk_out2;
            end else begin
                clk_out2 <= clk_out2;
            end
        end
    end

    initial begin
        if (power_up == "low") begin
            clk_out1 <= 1'b0;
            clk_out2 <= 1'b0;
