    input reset,
    input signed [15:0] a,
    input signed [15:0] b,
    output reg signed [15:0] sum,
    output reg greater_than
);

reg signed [15:0] a_sync;
reg signed [15:0] b_sync;

reg [15:0] carry;

// D flip-flops for input synchronization
always @(posedge clk) begin
    if (reset) begin
        a_sync <= 0;
        b_sync <= 0;
    end
    else begin
        a_sync <= a;
        b_sync <= b;
    end
end

// Full adder instantiation
genvar i;
generate
    for (i = 0; i < 16; i = i + 1) begin : adder_loop
        full_adder fa(
            .A(a_sync[i]),
            .B(b_sync[i]),
            .C_in(carry[i]),
            .Sum(sum[i]),
            .C_out(carry[i+1])
        );
    end
endgenerate

// Comparator
always @(*) begin
    if (sum == a_sync) begin
        greater_than <= 0;
    end
    else if (sum > a_sync) begin
        greater_than <= 1;
    end
    else begin
        greater_than <= 0;
    end
end

endmodule

