        .iterations(iterations),
        .sqrt_out(sqrt_consecutive_zeros)
    );

    always @(posedge clk) begin
        if (reset) begin
            valid <= 0;
            result <= 0;
        end else if (consecutive_zeros != 0) begin
            valid <= 1;
            result <= sqrt_consecutive_zeros;
        end else begin
            valid <= 0;
            result <= 0;
        end
    end

endmodule

