  input reset,
  output reg [3:0] out
);

  // Combinational always block
  always @ (posedge clk) begin
    if (!reset) begin
      out <= 4'b0000;
    end else begin
      out <= out + 1;
    end
  end

  // Sequential always block with reset signal
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      out <= 4'b0000;
    end else begin
      out <= out + 1;
    end
  end

