module digital_clock (
  input                clk,        // Clock input
  input                reset,      // Synchronous active-high reset
  input       [7:0]    d,          // 8-bit input for the accumulator
  input                select,     // Select input to choose between accumulator and counter
  input                valid_a,    // Valid signal for the accumulator
  input                ready_b,    // Ready signal for the additional functional module
  output               ready_a,    // Ready signal for the upstream module
  output  reg          valid_b,    // Valid signal for the downstream module
  output  reg [23:0]   time        // Output of the digital clock, in hours, minutes, and seconds
);

reg [7:0] accumulator = 8'b0;      // 8-bit accumulator
reg [3:0] counter_sec = 4'b0;      // 4-bit binary counter for seconds
reg [3:0] counter_min = 4'b0;      // 4-bit binary counter for minutes
reg [4:0] counter_hr = 5'b0;       // 5-bit binary counter for hours

always @(posedge clk) begin
  if (reset) begin
    accumulator <= 8'b0;
    counter_sec <= 4'b0;
    counter_min <= 4'b0;
    counter_hr <= 5'b0;
    time <= 24'b0;
    valid_b <= 1'b0;
  end else begin
    if (valid_a && select) begin
      // Accumulate input data using modified Booth algorithm
      accumulator <= accumulator + {accumulator[7], accumulator} - ({d[7], d} << 1);
      if (accumulator[8]) begin
        accumulator <= accumulator - 256;
      end
      // Output accumulation result every 8 input data
      if (counter_sec == 4'b1111) begin
        valid_b <= 1'b1;
        time <= {counter_hr, counter_min, counter_sec};
      end
    end
    // Increment seconds counter every clock cycle
    counter_sec <= counter_sec + 1;
    if (counter_sec == 4'b1111) begin
      // Increment minutes counter every 60 seconds
      counter_min <= counter_min + 1;
      if (counter_min == 4'b1111) begin
        // Increment hours counter every 60 minutes
        counter_hr <= counter_hr + 1;
        if (counter_hr == 5'b10111) begin
          counter_hr <= 5'b0;
        end
      end
    end
  end
  // Set ready signal for upstream module
  ready_a <= ~valid_b;
end

// Two-way handshake mechanism for downstream module
always @(posedge clk) begin
  if (valid_b && ready_b) begin
    valid_b <= 1'b0;
  end
end

endmodule

module nonrestore_div #(
	parameter	NUMERATOR_WIDTH		= 64,
	parameter	DENOMINATOR_WIDTH	= 64
)(
	input										clk,
	input										clr,
	input		[NUMERATOR_WIDTH	- 1	: 0]	numer_in,
	input		[DENOMINATOR_WIDTH	- 1	: 0]	denom_in,
	output	reg	[NUMERATOR_WIDTH	- 1	: 0]	quot_out,
	output	reg	[DENOMINATOR_WIDTH	- 1	: 0]	rem_out,
	output	reg									rdy_out
);

// Define the states of the state machine
localparam	s0 = 4'b0001;
localparam	s1 = 4'b0010;
localparam	s2 = 4'b0100;
localparam	s3 = 4'b1000;

// Define the width of temporary variables
localparam	TMPVAR_WIDTH		= NUMERATOR_WIDTH + DENOMINATOR_WIDTH;
localparam	REM_ITER_MSB		= DENOMINATOR_WIDTH;
localparam	QUOT_MSB			= NUMERATOR_WIDTH - 1;

// Define the state variables
reg			[3						: 0]	state;
reg			[NUMERATOR_WIDTH	- 1	: 0]	numer;
reg			[DENOMINATOR_WIDTH	- 1	: 0]	denom;
reg			[DENOMINATOR_WIDTH		: 0]	denom_neg;
reg			[NUMERATOR_WIDTH	- 1	: 0]	quot;
reg			[DENOMINATOR_WIDTH	- 1 : 0]	rem;
reg			[DENOMINATOR_WIDTH		: 0]	rem_iter;
reg			[7						: 0]	count;

// Define the wires
wire		[DENOMINATOR_WIDTH		: 0]	rem_iter_shift;
wire		[NUMERATOR_WIDTH	- 1 : 0]	quot_shift;
wire		[DENOMINATOR_WIDTH		: 0]	rem_iter_sum;

// Define the combinational logic
assign		{rem_iter_shift, quot_shift} = {rem_iter, quot} << 1;
assign		rem_iter_sum = rem_iter_shift + (rem_iter[REM_ITER_MSB]) ? denom : denom_neg;

// Define the state machine
always @ (posedge clk or posedge clr)
begin
	if (clr) begin
		state		<= s0;
		rdy_out		<= 1'b0;
		numer		<= 0;
		denom		<= 0;
		denom_neg	<= 0;
		quot		<= 0;
		rem_iter	<= 0;
		rem			<= 0;
		count		<= 0;
	end
	else begin
		case (state)
			s0	: begin
				numer		<= numer_in;
				denom		<= denom_in;
				denom_neg	<= {1'b1,~denom_in} + 1;
				quot		<= numer_in;
				rem_iter	<= 0;
				count		<= 0;
				state		<= s1;
			end
			s1	: begin
				count		<= count + 1;
				quot[QUOT_MSB : 1]	<= quot_shift[QUOT_MSB : 1];
				rem_iter	<= rem_iter_sum;
				if (rem_iter_sum[REM_ITER_MSB]) begin
					quot[0] <= 0;
				end
				else begin
					quot[0] <= 1;
				end
				if (count == NUMERATOR_WIDTH - 1) begin
					state	<= s2;
				end
			end
			s2	: begin
				if (rem_iter[REM_ITER_MSB]) begin	// rem < 0
					rem 	<= rem_iter + denom;
				end
				else begin
					rem 	<= rem_iter;
				end
				state 		<= s3;
			end
			s3	: begin
				quot_out	<= quot;
				rem_out		<= rem;
				rdy_out		<= 1'b1;
			end
			default : begin
				state 		<= s0;
			end
		endcase
	end
end

endmodule

module adder_subtractor_overflow (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input CIN,
    output reg [3:0] sum,
    output reg overflow
);

    reg [3:0] temp_sum;
    reg temp_overflow;

    always @(*) begin
        if (SUB) begin
            temp_sum = A - B - (~CIN);
            temp_overflow = (A < B + (~CIN));
        end else begin
            temp_sum = A + B + CIN;
            temp_overflow = (temp_sum < A) && (temp_sum < B);
        end
    end

    assign sum = temp_sum;
    assign overflow = temp_overflow;

endmodule

module MacOverflow #(
    parameter D_BITS = 8,
    parameter W_BITS = 8,
    parameter A_BITS = 16
) (
    input clock,
    input reset,

    input set_w,
    input stall,
    input [A_BITS-1:0] a_in,
    input [D_BITS-1:0] d_in,
    input [A_BITS-1:0] shift,

    output reg [A_BITS-1:0] a_out,
    output reg [D_BITS-1:0] d_out,
    output reg overflow
);
    reg [W_BITS-1:0] w;
    reg signed [2*A_BITS-1:0] mac_result;
    always @(posedge clock) begin
        if (reset) begin
            a_out <= {A_BITS{1'b0}};
            d_out <= {D_BITS{1'b0}};
            overflow <= 1'b0;
        end else if (!stall) begin
            if (set_w) begin
                w     <= a_in;
                a_out <= a_in;
            end else begin
                mac_result <= d_in * w + a_in;
                if (shift > A_BITS) begin
                    overflow <= 1'b1;
                    a_out <= {A_BITS{mac_result[2*A_BITS-1]}};
                end else begin
                    overflow <= 1'b0;
                    a_out <= mac_result[A_BITS+shift-1:shift];
                end
                d_out <= d_in;
            end
        end
    end
endmodule

