module DDC (
  input clk,
  input rst,
  input [15:0] in,
  output [15:0] out
);

parameter M = 4; // decimation factor
parameter N = 8; // number of filter taps

// Declare internal signals
reg [15:0] filter_taps [0:N-1];
reg [15:0] buffer [0:M-1];
integer i;

// DDC logic
always @(posedge clk or posedge rst) begin
  if (rst) begin
    for (i = 0; i < M; i = i + 1) begin
      buffer[i] <= 16'h0;
    end
  end else begin
    for (i = 0; i < M-1; i = i + 1) begin
      buffer[i] <= buffer[i+1];
    end
    buffer[M-1] <= in;
  end
end

// FIR filter
always @(posedge clk or posedge rst) begin
  if (rst) begin
    out <= 16'h0;
  end else begin
    out <= 0;
    for (i = 0; i < N; i = i + 1) begin
      out <= out + buffer[i*M/N] * filter_taps[i];
    end
  end
end

endmodule

