module vga_controller(
input wire pixel_clk,
input wire reset_n,
output reg h_sync,
output reg v_sync,
output reg disp_ena,
output reg [31:0] column,
output reg [31:0] row,
output wire n_blank,
output wire n_sync
);
parameter [31:0] h_pulse=208;
parameter [31:0] h_bp=336;
parameter [31:0] h_pixels=1920;
parameter [31:0] h_fp=128;
parameter h_pol=1'b0;
parameter [31:0] v_pulse=3;
parameter [31:0] v_bp=38;
parameter [31:0] v_pixels=1200;
parameter [31:0] v_fp=1;
parameter v_pol=1'b1;
//vertical sync pulse polarity (1 = positive, 0 = negative)
//pixel clock at frequency of VGA mode being used
//active low asycnchronous reset
//horiztonal sync pulse
//vertical sync pulse
//display enable ('1' = display time, '0' = blanking time)
//horizontal pixel coordinate
//vertical pixel coordinate
//direct blacking output to DAC
//sync-on-green output to DAC
parameter h_period = h_pulse + h_bp + h_pixels + h_fp;  //total number of pixel clocks in a row
parameter v_period = v_pulse + v_bp + v_pixels + v_fp;  //total number of rows in column
  assign n_blank = 1'b1;
  //no direct blanking
  assign n_sync = 1'b0;
  //no sync on green
  always @(posedge pixel_clk, posedge reset_n) begin : P1
    reg [31:0] h_count = 0;
  //horizontal counter (counts the columns)
    reg [31:0] v_count = 0;
  //vertical counter (counts the rows)
    if((reset_n == 1'b0)) begin
      //reset asserted
      h_count = 0;
      //reset horizontal counter
      v_count = 0;
      //reset vertical counter
      h_sync <=  ~h_pol;
      //deassert horizontal sync
      v_sync <=  ~v_pol;
      //deassert vertical sync
      disp_ena <= 1'b0;
      //disable display
      column <= 0;
      //reset column pixel coordinate
      row <= 0;
      //reset row pixel coordinate
    end else begin
      //counters
      if((h_count < (h_period - 1))) begin
        //horizontal counter (pixels)
        h_count = h_count + 1;
      end
      else begin
        h_count = 0;
        if((v_count < (v_period - 1))) begin
          //veritcal counter (rows)
          v_count = v_count + 1;
        end
        else begin
          v_count = 0;
        end
      end
      //horizontal sync signal
      if((h_count < (h_pixels + h_fp) || h_count > (h_pixels + h_fp + h_pulse))) begin
        h_sync <=  ~h_pol;
        //deassert horiztonal sync pulse
      end
      else begin
        h_sync <= h_pol;
        //assert horiztonal sync pulse
      end
      //vertical sync signal
      if((v_count < (v_pixels + v_fp) || v_count > (v_pixels + v_fp + v_pulse))) begin
        v_sync <=  ~v_pol;
        //deassert vertical sync pulse
      end
      else begin
        v_sync <= v_pol;
        //assert vertical sync pulse
      end
      //set pixel coordinates
      if((h_count < h_pixels)) begin
        //horiztonal display time
        column <= h_count;
        //set horiztonal pixel coordinate
      end
      if((v_count < v_pixels)) begin
        //vertical display time
        row <= v_count;
        //set vertical pixel coordinate
      end
      //set display enable output
      if((h_count < h_pixels && v_count < v_pixels)) begin
        //display time
        disp_ena <= 1'b1;
        //enable display
      end
      else begin
        //blanking time
        disp_ena <= 1'b0;
        //disable display
      end
    end
  end
endmodule

