module ALU(
input wire [31:0] a1,
input wire [31:0] a2,
input wire [3:0] alu_control,
output wire [31:0] alu_result,
output wire zero
);
reg [31:0] resultX;
  always @(a1, a2, alu_control) begin
    case(alu_control)
        // Bitwise and
    4'b0000 : begin
      resultX <= a1 & a2;
      // Bitwise or
    end
    4'b0001 : begin
      resultX <= a1 | a2;
      // addition
    end
    4'b0010 : begin
      resultX <= (a1) + (a2);
      // subtract
    end
    4'b0110 : begin
      resultX <= (a1) - (a2);
      // set les than
    end
    4'b0111 : begin
      if(((a1) < (a2))) begin
        resultX <= 32'h00000001;
      end
      else begin
        resultX <= 32'h00000000;
      end
      // Bitwise nor
    end
    4'b1100 : begin
      resultX <=  ~(a1 | a2);
      // Nop
    end
    default : begin
      resultX <= 32'h00000000;
    end
    endcase
  end
  // concurent code
  assign alu_result = resultX;
  assign zero = resultX == 32'h00000000 ? 1'b1 : 1'b0;
endmodule

