  //    PORT map(
  //      i => CLKB_IN,
  //      o => clkb_in_i
  //    );
  assign clkb_in_i = CLKB_IN;
  assign CLKB = clkb_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
