  BMG_DATA_CHECKER_INST(
      .CLK(clkb_in_i),
    .RST(RSTB),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTB),
    .STATUS(ISSUE_FLAG[0]));
