module read_instruction_stage(
input wire clk,
input wire reset_n,
input wire stall,
input wire cbranch,
input wire [31:0] cbranch_address,
input wire ubranch,
input wire [31:0] ubranch_address,
output reg [31:0] next_pc,
output wire [31:0] r_addr_inst
);
//outputs
//memory
reg [31:0] pc;
  assign r_addr_inst = pc;
  always @(posedge clk, posedge reset_n) begin
    if((reset_n == 1'b0)) begin
      pc <= 32'b00000000000000000000000000000000;
      next_pc <= 32'b00000000000000000000000000000011;
    end else begin
      if((stall == 1'b0)) begin
        if((cbranch == 1'b1)) begin
          pc <= cbranch_address;
          next_pc <= (cbranch_address) + (3);
        end
        else if((ubranch == 1'b1)) begin
          pc <= ubranch_address;
          next_pc <= (ubranch_address) + (3);
        end
        else begin
          pc <= (pc) + (3);
          next_pc <= (pc) + (6);
        end
      end
      else begin
        //hold previous value on stall (automatic)
      end
    end
  end
endmodule

module arbiter(
input wire [31:0] I_addr,
input wire I_busy0,
input wire I_busy1,
input wire I_busy2,
input wire I_busy3,
input wire [31:0] I_data0,
input wire [31:0] I_data1,
input wire [31:0] I_data2,
input wire [31:0] I_data3,
input wire I_en,
output reg O_busy,
output reg [31:0] O_data,
output reg O_en0,
output reg O_en1,
output reg O_en2,
output reg O_en3
);
  always @(I_addr, I_en, I_data0, I_data1, I_data2, I_data3, I_busy0, I_busy1, I_busy2, I_busy3) begin
    if(I_en == 1'b1) begin
      O_en0 <= 1'b0;
      O_en1 <= 1'b0;
      O_en2 <= 1'b0;
      O_en3 <= 1'b0;
      // most significant nibble selects device - room for 16 devices
      case(I_addr[29:28])
      2'b00 : begin
        O_en0 <= 1'b1;
        O_data <= I_data0;
        O_busy <= I_busy0;
      end
      2'b01 : begin
        O_en1 <= 1'b1;
        O_data <= I_data1;
        O_busy <= I_busy1;
      end
      2'b10 : begin
        O_en2 <= 1'b1;
        O_data <= I_data2;
        O_busy <= I_busy2;
      end
      default : begin
        // "11" presumably
        O_en3 <= 1'b1;
        O_data <= I_data3;
        O_busy <= I_busy3;
      end
      endcase
    end
    else begin
      O_en0 <= 1'b0;
      O_en1 <= 1'b0;
      O_en2 <= 1'b0;
      O_en3 <= 1'b0;
      O_data <= 32'h00000000;
      O_busy <= 1'b0;
    end
  end
endmodule

