module dspba_delay(
input wire clk,
input wire aclr,
input wire ena,
input wire [width - 1:0] xin,
output wire [width - 1:0] xout
);
parameter [31:0] width;
parameter [31:0] depth;
parameter reset_high=1'b1;
reg [width - 1:0] delay_signals[depth:0];
  assign delay_signals[depth] = xin;
  genvar i;
  generate for (i=depth - 1; i >= 0; i = i - 1) begin: delay_loop
    always @(posedge clk, posedge aclr) begin
      if(aclr == reset_high) begin
        delay_signals[i] <= {1{1'b0}};
      end else begin
        if(ena == 1'b1) begin
          delay_signals[i] <= delay_signals[i + 1];
        end
      end
    end
  end
  endgenerate
  assign xout = delay_signals[0];
endmodule

module sipo(
input wire clk,
input wire [1:0] se,
input wire [3:0] D,
input wire Dl,
input wire Dr,
output wire [3:0] Q
);
reg [3:0] Qt = 4'b0000;
  always @(posedge clk, posedge se) begin
    if(se[0] == 1'b0) begin
      Qt <= {Dl,Qt[3:1]};
    end
    else if(se[1] == 1'b1) begin
      Qt <= {Qt[2:0],Dr};
    end
    else begin
      Qt <= D;
    end
  end
  assign Q = Qt;
endmodule

