output wire spiData_out,
input wire spiData_in,
output wire [NUM_DEVS - 1:0] spiCS_out
);
parameter [31:0] NUM_DEVS=1;
// FX2LP interface ---------------------------------------------------------------------------
// 48MHz clock from FX2LP
// select FIFO: "00" for EP2OUT, "10" for EP6IN
// 8-bit data to/from FX2LP
// When EP2OUT selected:
// asserted (active-low) when reading from FX2LP
// asserted (active-low) to tell FX2LP to drive bus
// asserted (active-high) when FX2LP has data for us
// When EP6IN selected:
// asserted (active-low) when writing to FX2LP
// asserted (active-high) when FX2LP has room for more data from us
// asserted (active-low) when a host read needs to be committed early
// Peripheral interface ----------------------------------------------------------------------
// Channel read/write interface -----------------------------------------------------------------
wire [6:0] chanAddr;  // the selected channel (0-127)
// Host >> FPGA pipe:
wire [7:0] h2fData;  // data lines used when the host writes to a channel
wire h2fValid;  // '1' means "on the next clock rising edge, please accept the data on h2fData"
wire h2fReady;  // channel logic can drive this low to say "I'm not ready for more data yet"
// Host << FPGA pipe:
wire [7:0] f2hData;  // data lines used when the host reads from a channel
wire f2hValid;  // channel logic can drive this low to say "I don't have data ready for you"
wire f2hReady;  // '1' means "on the next clock rising edge, put your next byte of data on f2hData"
// ----------------------------------------------------------------------------------------------
// Needed so that the comm_fpga_fx2 module can drive both fx2Read_out and fx2OE_out
wire fx2Read;  // Reset signal so host can delay startup
wire fx2Reset;
  // CommFPGA module
  assign fx2Read_out = fx2Read;
  assign fx2OE_out = fx2Read;
  assign fx2Addr_out[0] = fx2Reset == 1'b0 ? 1'b0 : 1'bZ;
  comm_fpga_fx2 comm_fpga_fx2(
      .clk_in(fx2Clk_in),
    .reset_in(1'b0),
    .reset_out(fx2Reset),
    // FX2LP interface
    .fx2FifoSel_out(fx2Addr_out[1]),
    .fx2Data_io(fx2Data_io),
    .fx2Read_out(fx2Read),
    .fx2GotData_in(fx2GotData_in),
    .fx2Write_out(fx2Write_out),
    .fx2GotRoom_in(fx2GotRoom_in),
    .fx2PktEnd_out(fx2PktEnd_out),
    // DVR interface -> Connects to application module
    .chanAddr_out(chanAddr),
    .h2fData_out(h2fData),
    .h2fValid_out(h2fValid),
    .h2fReady_in(h2fReady),
    .f2hData_in(f2hData),
    .f2hValid_in(f2hValid),
    .f2hReady_out(f2hReady));
  // Switches & LEDs application
  spi_talk #(
      .NUM_DEVS(NUM_DEVS))
  spi_talk_app(
      .clk_in(fx2Clk_in),
    // DVR interface -> Connects to comm_fpga module
    .chanAddr_in(chanAddr),
    .h2fData_in(h2fData),
    .h2fValid_in(h2fValid),
    .h2fReady_out(h2fReady),
    .f2hData_out(f2hData),
    .f2hValid_out(f2hValid),
    .f2hReady_in(f2hReady),
    // Peripheral interface
    .spiClk_out(spiClk_out),
    .spiData_out(spiData_out),
    .spiData_in(spiData_in),
    .spiCS_out(spiCS_out));
endmodule

