module int_to_ascii(
input wire [7:0] int_in,
output reg [7:0] ascii_out
);
  always @(int_in) begin
    if((int_in >= 8'h00 && int_in <= 8'h09)) begin
      ascii_out <= int_in + 8'h30;
    end
    else if((int_in >= 8'h0a && int_in <= 8'h0f)) begin
      ascii_out <= int_in + 8'h41 - 8'h0a;
    end
    else begin
      ascii_out <= int_in;
    end
  end
endmodule

