      4'b0010 : s_decOut_n <= 7'b0100100;
  //2
      4'b0011 : s_decOut_n <= 7'b0110000;
  //3
      4'b0100 : s_decOut_n <= 7'b0011001;
  //4
      4'b0101 : s_decOut_n <= 7'b0010010;
  //5
      4'b0110 : s_decOut_n <= 7'b0000010;
  //6
      4'b0111 : s_decOut_n <= 7'b1111000;
  //7
      4'b1000 : s_decOut_n <= 7'b0000000;
  //8
      4'b1001 : s_decOut_n <= 7'b0010000;
  //9
      4'b1010 : s_decOut_n <= 7'b0001000;
  //A
      4'b1011 : s_decOut_n <= 7'b0000011;
  //b
      4'b1100 : s_decOut_n <= 7'b1000110;
  //C
      4'b1101 : s_decOut_n <= 7'b0100001;
  //d
      4'b1110 : s_decOut_n <= 7'b0000110;
  //E
      4'b1111 : s_decOut_n <= 7'b0001110;
  //F
      default : s_decOut_n <= 7'b1000000;
