module shift_register_serial_in(
input wire TCK,
input wire reset,
input wire SE,
input wire UE,
input wire SI,
output wire SO,
output reg [REG_WIDTH - 1:0] data_out_parallel
);
parameter [31:0] REG_WIDTH=32;
// shift enable 
// update enable
// serial Input
// serial output
reg [REG_WIDTH - 1:0] shift_register_mem_out;
reg output_strobe;
  always @(posedge TCK, posedge reset) begin
    if(reset == 1'b0) begin
      shift_register_mem_out <= {((REG_WIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if(SE == 1'b1) begin
        shift_register_mem_out <= {shift_register_mem_out[REG_WIDTH - 2:0],SI};
      end
    end
  end
  always @(negedge TCK) begin
    output_strobe <= UE;
  end
  always @(output_strobe, shift_register_mem_out) begin
    if(output_strobe == 1'b1) begin
      data_out_parallel <= shift_register_mem_out;
    end
    else begin
      data_out_parallel <= {((REG_WIDTH - 1)-(0)+1){1'b0}};
    end
  end
  assign SO = shift_register_mem_out[REG_WIDTH - 1];
endmodule

module cipher_cu(
input wire clk,
input wire reset,
input wire x_start,
input wire x_comp,
output reg [1:0] y_1_2,
output reg [1:0] y_3_4,
output reg y_end
);
// start encryption
// '1' if last round is reached
// controlling values for cipher
// controlling values for counter	
// encryption finished
parameter [2:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3,
  S4 = 4,
  S5 = 5;
reg [2:0] S; reg [2:0] S_next;
  always @(S, x_start, x_comp) begin
    case(S)
    S0 : begin
      y_1_2 <= 2'b--;
      y_3_4 <= 2'b00;
      // initialize counter
      y_end <= 1'b0;
      if(x_start == 1'b1) begin
        S_next <= S1;
      end
      else begin
        S_next <= S0;
      end
    end
    S1 : begin
      y_1_2 <= 2'b--;
      // round key 0 not yet available (due to synchonous read)
      y_3_4 <= 2'b01;
      // increment counter
      y_end <= 1'b0;
      S_next <= S2;
    end
    S2 : begin
      y_1_2 <= 2'b00;
      // load in plaintext (round key 0 now available) 
      y_3_4 <= 2'b01;
      // increment counter
      y_end <= 1'b0;
      S_next <= S3;
    end
    S3 : begin
      y_1_2 <= 2'b01;
      // include mix columns stage
      y_3_4 <= 2'b01;
      y_end <= 1'b0;
      if(x_comp == 1'b1) begin
        S_next <= S4;
        // last round starts after the next cycle
      end
      else begin
        S_next <= S3;
      end
    end
    S4 : begin
      y_1_2 <= 2'b10;
      // leave out mix columns stage
      y_3_4 <= 2'b--;
      y_end <= 1'b0;
      S_next <= S5;
    end
    S5 : begin
      y_1_2 <= 2'b--;
      y_3_4 <= 2'b--;
      y_end <= 1'b1;
      // finished (output valid for one cycle)
      S_next <= S0;
    end
    endcase
  end
  always @(posedge clk, posedge reset, posedge S_next) begin
    if(reset == 1'b1) begin
      S <= S0;
    end else begin
      S <= S_next;
    end
  end
endmodule

