module EPROC_OUT2(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
input wire ENA,
input wire swap_outbits,
output wire getDataTrig,
input wire [3:0] ENCODING,
output reg [1:0] EDATA_OUT,
input wire [1:0] TTCin,
input wire [9:0] DATA_IN,
input wire DATA_RDY
);
parameter do_generate=true;
// @ bitCLKx4
parameter zeros2bit = 1'b0;
wire [1:0] EdataOUT_ENC8b10b_case; wire [1:0] EdataOUT_direct_case; wire [1:0] EdataOUT_HDLC_case; reg [1:0] EdataOUT_TTC0_case;
wire rst_s; wire rst_case000; wire rst_case001; wire rst_case010; wire rst_case011;
wire getDataTrig_ENC8b10b_case; wire getDataTrig_direct_case; wire getDataTrig_HDLC_case; wire getDataTrig_TTC_case;
wire [1:0] edata_out_s;
  generate if (do_generate == true) begin: gen_enabled
      assign rst_s = rst | ( ~ENA);
    //-----------------------------------------------------------------------------------------
    // case 0: direct data, no delimeter...
    //-----------------------------------------------------------------------------------------
    assign rst_case000 = ((rst_s == 1'b0) && (ENCODING[2:0] == 3'b000)) ? 1'b0 : 1'b1;
    //
    EPROC_OUT2_direct direct_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case000),
      .getDataTrig(getDataTrig_direct_case),
      .edataIN(DATA_IN),
      .edataINrdy(DATA_RDY),
      .EdataOUT(EdataOUT_direct_case));
    //
    //-----------------------------------------------------------------------------------------
    // case 1: DEC8b10b
    //-----------------------------------------------------------------------------------------
    assign rst_case001 = ((rst_s == 1'b0) && (ENCODING[2:0] == 3'b001)) ? 1'b0 : 1'b1;
    //
    EPROC_OUT2_ENC8b10b ENC8b10b_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case001),
      .getDataTrig(getDataTrig_ENC8b10b_case),
      .edataIN(DATA_IN),
      .edataINrdy(DATA_RDY),
      .EdataOUT(EdataOUT_ENC8b10b_case));
    //
    //-----------------------------------------------------------------------------------------
    // case 2: HDLC
    //-----------------------------------------------------------------------------------------
    assign rst_case010 = ((rst_s == 1'b0) && (ENCODING[2:0] == 3'b010)) ? 1'b0 : 1'b1;
    //
    EPROC_OUT2_HDLC HDLC_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case010),
      .getDataTrig(getDataTrig_HDLC_case),
      // output, data request
      .edataIN(DATA_IN),
      .edataINrdy(DATA_RDY),
      .EdataOUT(EdataOUT_HDLC_case));
    //
    //-----------------------------------------------------------------------------------------
    // case 3: TTC-0 
    //-----------------------------------------------------------------------------------------
    assign rst_case011 = ((rst_s == 1'b0) && (ENCODING[2:0] == 3'b011)) ? 1'b0 : 1'b1;
    //
    assign getDataTrig_TTC_case = 1'b0;
    //'1' when (ENCODING(2 downto 0) = "011") else '0';
    //
    always @(posedge bitCLK) begin
      if(rst_case011 == 1'b1) begin
        EdataOUT_TTC0_case <= zeros2bit;
      end
      else begin
        EdataOUT_TTC0_case <= TTCin;
      end
    end
    //
    //-----------------------------------------------------------------------------------------
    // output data and busy according to the encoding settings
    //-----------------------------------------------------------------------------------------
    MUX4_Nbit #(
          .N(2))
    dataOUTmux(
          .data0(EdataOUT_direct_case),
      .data1(EdataOUT_ENC8b10b_case),
      .data2(EdataOUT_HDLC_case),
      .data3(EdataOUT_TTC0_case),
      .sel(ENCODING[1:0]),
      .data_out(edata_out_s));
    //
    assign getDataTrig = ENA & (getDataTrig_TTC_case | getDataTrig_HDLC_case | getDataTrig_ENC8b10b_case | getDataTrig_direct_case);
        //
  end
  endgenerate
  //
  //
  generate if (do_generate == false) begin: gen_disabled
      assign edata_out_s = {2{1'b0}};
    assign getDataTrig = 1'b0;
  end
  endgenerate
  //
  always @(swap_outbits, edata_out_s) begin
    if(swap_outbits == 1'b1) begin
      EDATA_OUT <= {edata_out_s[0],edata_out_s[1]};
    end
    else begin
      EDATA_OUT <= edata_out_s;
    end
  end
    //
endmodule

