module suma(
input wire cin,
input wire [3:0] x,
input wire [3:0] y,
output wire [3:0] s,
output wire cout
);
wire [0:4] c;
  assign c[0] = cin;
  //i = 0
  assign s[0] = c[0] ^ x[0] ^ y[0];
  assign c[1] = (x[0] & y[0]) | (c[0] & (x[0] ^ y[0]));
  //i = 1
  assign s[1] = c[1] ^ x[1] ^ y[1];
  assign c[2] = (x[1] & y[1]) | (c[1] & (x[1] ^ y[1]));
  //i = 2
  assign s[2] = c[2] ^ x[2] ^ y[2];
  assign c[3] = (x[2] & y[2]) | (c[2] & (x[2] ^ y[2]));
  //i = 3
  assign s[3] = c[3] ^ x[3] ^ y[3];
  assign c[4] = (x[3] & y[3]) | (c[3] & (x[3] ^ y[3]));
  assign cout = c[4];
endmodule

