module freq_counter(
input wire clk,
input wire rst,
input wire pulse,
output reg err,
output reg [15:0] data_out
);
reg [15:0] count; reg [15:0] prev_count;
  // simple counter process
  // max frequency is clk
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      count <= {16{1'b0}};
    end else begin
      count <= count + 1;
    end
  end
  always @(posedge pulse, posedge rst) begin
    if((rst == 1'b1)) begin
      prev_count <= {16{1'b0}};
      data_out <= {16{1'b0}};
    end else begin
      if((prev_count < count)) begin
        data_out <= count - prev_count;
        err <= 1'b0;
      end
      else if((prev_count > count)) begin
        data_out <= prev_count + count;
        err <= 1'b0;
      end
      else begin
        data_out <= {16{1'b0}};
        err <= 1'b1;
      end
      prev_count <= count;
    end
  end
endmodule

module single_debouncer(
input wire nrst,
input wire clk,
input wire input,
output wire output
);
parameter [31:0] n=5000;
reg [31:0] counter = 0;
reg output2 = 1'b0;
  assign output = output2;
  always @(posedge clk, posedge nrst) begin
    if(nrst == 1'b0) begin
      counter <= 0;
      output2 <= 1'b0;
    end else begin
      if(counter >= n) begin
        if(output2 != input) begin
          output2 <= input;
          counter <= 0;
        end
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

