input wire reset,
input wire clk,
output wire [47:0] source_MAC,
output wire [7:0] test
);
reg [10:0] address_counter = 1'b0;
reg [47:0] temp;
  assign source_MAC = temp;
  assign test = temp[47:40];
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      address_counter <= {11{1'b0}};
    end
    else if(enable == 1'b1) begin
      address_counter <= address_counter + 1;
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      temp <= {48{1'b0}};
    end
    else if(address_counter == 7) begin
      temp[47:40] <= data_in;
    end
    else if(address_counter == 8) begin
      temp[39:32] <= data_in;
    end
    else if(address_counter == 9) begin
      temp[31:24] <= data_in;
    end
    else if(address_counter == 10) begin
      temp[23:16] <= data_in;
    end
    else if(address_counter == 11) begin
      temp[15:8] <= data_in;
    end
    else if(address_counter == 12) begin
      temp[7:0] <= data_in;
    end
  end
endmodule

