module m8bitRegister(
input wire [7:0] I,
output reg [7:0] O,
input wire clr,
input wire load_en,
input wire clk
);
//declared signal
wire [7:0] S = 8'b00000000;
  always @(posedge clk, posedge clr, posedge I, posedge load_en) begin
      // this is to make the events synchronous
    if(clr == 1'b1) begin
      S = 8'b00000000;
      O <= S;
    end
    else begin
      if(load_en == 1'b1) begin
        S = I;
      end
      else begin
        O <= S;
      end
    end
  end
