module spimaster(
input wire clk,
input wire reset,
input wire [2:0] cpu_address,
output wire cpu_wait,
input wire [7:0] data_in,
output reg [7:0] data_out,
input wire enable,
input wire req_read,
input wire req_write,
output wire slave_cs,
output wire slave_clk,
output wire slave_mosi,
input wire slave_miso
);
// registers:
// base+0   -- chip select control; bit 0 is slave_cs
// base+1   -- status register; bit 0 indicates "transmitter busy"
// base+2   -- transmitter: write a byte here, starts SPI bus transaction
// base+3   -- receiver: last byte received (updated on each transation)
// base+4   -- clock divider: clk counts from 0 to whatever is in this register before proceeding
//
// Note that if an SPI transfer is underway already the CPU will be
// forced to wait until it completes before any register can be
// read or written. This is very convenient as it means you can
// just read or write bytes without checking the status register.
// start up in idle state
reg slave_cs_register = 1'b1;
reg slave_clk_register = 1'b1;
reg slave_mosi_register = 1'b0;
reg [7:0] data_out_sr = 1'b0;  // shifted left ie MSB <- LSB
reg [7:0] data_in_sr = 1'b0;  // shifted left ie MSB <- LSB
reg [7:0] busy_sr = 1'b0;  // shifted left ie MSB <- LSB
reg [7:0] clk_divide_target = 1'b0;
reg [7:0] clk_divide_value = 1'b0;
reg cpu_was_idle = 1'b1;  // cpu visible registers
wire [7:0] chip_select_out;
wire [7:0] status_data_out;
wire data_out_enable;
  assign chip_select_out = {7'b0000000,slave_cs_register};
  assign status_data_out = {7'b0000000,busy_sr[7]};
  assign cpu_wait = busy_sr[7];
  //TH: Added logic to expose data to bus only when it is really needed
  // I think it wastes energy when uneccesary signal value changes are avoided
  assign data_out_enable = req_read &  ~busy_sr[7];
  always @(*) begin
    case(cpu_address,data_out_enable)
      4'b0001 : data_out <= chip_select_out;
      4'b0011 : data_out <= status_data_out;
      4'b0101 : data_out <= data_out_sr;
      4'b0111 : data_out <= data_in_sr;
      4'b1001 : data_out <= clk_divide_target;
      default : data_out <= {8{1'b0}};
    endcase
  end
  assign slave_cs = slave_cs_register;
  assign slave_clk = slave_clk_register;
  assign slave_mosi = slave_mosi_register;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      slave_cs_register <= 1'b1;
      slave_clk_register <= 1'b1;
      slave_mosi_register <= 1'b0;
      data_out_sr <= {8{1'b0}};
      data_in_sr <= {8{1'b0}};
      busy_sr <= {8{1'b0}};
      clk_divide_target <= {8{1'b0}};
      clk_divide_value <= {8{1'b0}};
      cpu_was_idle <= 1'b1;
    end
    else begin
      // divide down input clk to get 2 * spi clk
      clk_divide_value <= clk_divide_value + 1;
      if(clk_divide_value == clk_divide_target) begin
        clk_divide_value <= 0;
      end
      if(busy_sr[7] == 1'b1) begin
        if(clk_divide_value == clk_divide_target) begin
          // we're in the midst of a transaction! whoo!
          if(slave_clk_register == 1'b1) begin
            // clk is high; next cycle will be falling edge of clk
            slave_clk_register <= 1'b0;
            slave_mosi_register <= data_out_sr[7];
            // shift data out
            data_out_sr <= {data_out_sr[6:0],1'b0};
          end
          else begin
            // clk is low; next cycle will be rising edge of clk
            slave_clk_register <= 1'b1;
            // shift busy
            busy_sr <= {busy_sr[6:0],1'b0};
            // latch data in
            data_in_sr <= {data_in_sr[6:0],slave_miso};
          end
        end
      end
      if(enable == 1'b1 && req_write == 1'b1) begin
        if(busy_sr[7] == 1'b0 && cpu_was_idle == 1'b1) begin
          cpu_was_idle <= 1'b0;
          case(cpu_address)
          3'b000 : begin
            slave_cs_register <= data_in[0];
          end
          3'b010 : begin
            // only allow writes when transmitter is idle
            data_out_sr <= data_in;
            busy_sr <= {8{1'b1}};
          end
          3'b100 : begin
            clk_divide_target <= data_in;
          end
          default : begin
            // no change
          end
          endcase
        end
        else begin
          cpu_was_idle <= cpu_was_idle;
        end
      end
      else begin
        cpu_was_idle <= 1'b1;
      end
    end
  end
endmodule

module xorshift16(
input wire clk,
input wire rst_n,
input wire kick_n,
output reg d_en_n,
output reg [3:0] data
);
reg [15:0] y = 16'h8ca2;
reg [3:0] state = 4'b0000;
  always @(posedge clk) begin
    if(rst_n == 1'b0) begin
      d_en_n <= 1'b1;
      state <= 4'b0000;
    end
    else begin
      case(state)
      4'b0000 : begin
        if(kick_n == 1'b0) begin
          y <= y ^ ({y[15 - 2:0],2'b00});
          state <= 4'b0001;
        end
      end
      4'b0001 : begin
        y <= y ^ ({5'b00000,y[15:5]});
        state <= 4'b0011;
      end
      4'b0011 : begin
        y <= y ^ ({y[15 - 8:0],8'b00000000});
        state <= 4'b0010;
      end
      4'b0010 : begin
        state <= 4'b0110;
        d_en_n <= 1'b0;
        data <= y[3:0];
      end
      4'b0110 : begin
        state <= 4'b0111;
        data <= y[7:4];
      end
      4'b0111 : begin
        state <= 4'b0101;
        data <= y[11:8];
      end
      4'b0101 : begin
        state <= 4'b0100;
        data <= y[15:12];
      end
      4'b0100 : begin
        d_en_n <= 1'b1;
        state <= 4'b0000;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

module CU(
input wire RST,
input wire CLK,
input wire HALT_REQ,
input wire [15:0] INMEM,
input wire [15:0] FRIN,
output reg [1:0] sM1,
output wire [1:0] sM2,
output wire [3:0] sM3,
output wire [3:0] sM4,
output wire sM5,
output wire sM6,
output wire [6:0] ULAOP,
output reg LoadFR,
output reg LoadMAR,
output reg [2:0] LIDPC,
output reg [2:0] LIDSP,
output reg LoadMBR,
output reg [7:0] LoadREG,
output reg HALT_ACK,
output reg DRAW,
output reg RW
);
parameter HALT = 6'b001111;
parameter [1:0]
  fetch = 0,
  decode = 1,
  exec = 2,
  halted = 3;
reg [15:0] IR;
reg [1:0] STATE;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      STATE <= fetch;
      DRAW <= 1'b0;
      RW <= 1'b0;
      IR <= 16'h0000;
      LoadFR <= 1'b0;
      LoadMAR <= 1'b0;
      LIDPC <= 3'b000;
      LIDSP <= 3'b100;
      LoadMBR <= 1'b0;
      LoadREG <= 8'h00;
      HALT_ACK <= 1'b0;
    end else begin
      case(STATE)
      fetch : begin
        DRAW <= 1'b0;
        RW <= 1'b0;
        LoadFR <= 1'b0;
        LIDSP <= 3'b000;
        LoadREG <= 8'h00;
        HALT_ACK <= 1'b0;
        sM1 <= 2'b10;
        LoadMBR <= 1'b1;
        IR <= INMEM;
        LIDPC <= 3'b010;
        STATE <= decode;
      end
      decode : begin
        case(IR[15:10])
        HALT : begin
          STATE <= halted;
        end
        default : begin
        end
        endcase
      end
      exec : begin
      end
      halted : begin
        HALT_ACK <= 1'b1;
      end
      endcase
    end
  end
endmodule

