reg [31:0] ram_s[0:524287] = 32'h00000000;
  //process modelling writing:
  always @(posedge clk) begin
    if((write1 == 1'b1)) begin
      ram_s[address] <= wdata;
    end
  end
  //asynchronous reading:
  assign rdata = ram_s[address];
endmodule

module csi_rx_video_output(
