//Number of pixels per clock to output; 1, 2 or 4
//Output pixel clock
//CSI byte clock
//system enable input
//synchronous active high reset input
//Unpacked 10 bit data
//goes high when valid frames are being received
//Pixel data output
//like hsync but asserted for one clock period only and only for visible lines
//LSB of y-coordinate for a downstream debayering block
//LSW is leftmost pixel
//last line's data at this point, for a debayering block to use
reg csi_in_line_last = 1'b0; reg csi_in_frame_last = 1'b0; reg csi_odd_line = 1'b0; reg csi_frame_started = 1'b0;
reg video_fsync_pre = 1'b0; reg video_fsync = 1'b0;
reg [31:0] csi_x_pos;
parameter output_width = video_h_visible / pixels_per_clock;
parameter output_tmg_hlength = video_hlength / pixels_per_clock;
parameter output_hvis_begin = (video_hsync_len + video_hbp_len) / pixels_per_clock;
wire [31:0] output_timing_h;
wire [31:0] output_pixel_y;
wire [31:0] linebuf_write_address;
wire [31:0] linebuf_read_address;
wire even_linebuf_wren = 1'b0; wire odd_linebuf_wren = 1'b0;
wire [(10 * pixels_per_clock) - 1:0] even_linebuf_q; wire [(10 * pixels_per_clock) - 1:0] odd_linebuf_q;
wire output_hsync; wire output_vsync; wire output_den; wire output_line_start; wire output_odd_line;
wire [(10 * pixels_per_clock) - 1:0] output_data; wire [(10 * pixels_per_clock) - 1:0] output_prev_line_data;
  always @(posedge csi_byte_clock) begin
    if(reset == 1'b1) begin
      csi_in_line_last <= 1'b0;
      csi_in_frame_last <= 1'b0;
      csi_frame_started <= 1'b0;
      csi_odd_line <= 1'b1;
    end
    else if(enable == 1'b1) begin
      csi_in_frame_last <= csi_in_frame;
      csi_in_line_last <= csi_in_line;
      if(csi_in_frame_last == 1'b0 && csi_in_frame == 1'b1) begin
        //Start of frame
        csi_x_pos <= 0;
        csi_odd_line <= 1'b1;
        csi_frame_started <= 1'b0;
      end
      else if(csi_in_line_last == 1'b0 && csi_in_line == 1'b1) begin
        //Start of line
        csi_x_pos <= 0;
        csi_odd_line <=  ~csi_odd_line;
        csi_frame_started <= 1'b1;
      end
      else if(pixel_data_valid == 1'b1) begin
        csi_x_pos <= csi_x_pos + 4;
      end
    end
  end
  assign linebuf_write_address = csi_x_pos / 4;
  assign even_linebuf_wren = csi_odd_line == 1'b0 ? pixel_data_valid : 1'b0;
  assign odd_linebuf_wren = csi_odd_line == 1'b1 ? pixel_data_valid : 1'b0;
  always @(posedge output_clock) begin
    if(reset == 1'b1) begin
      video_fsync_pre <= 1'b0;
      video_fsync <= 1'b0;
    end
    else if(enable == 1'b1) begin
      video_fsync_pre <= csi_frame_started;
      video_fsync <= video_fsync_pre;
      //Register video output
      video_hsync <= output_hsync;
      video_vsync <= output_vsync;
      video_den <= output_den;
      video_line_start <= output_line_start;
      video_odd_line <= output_odd_line;
      video_data <= output_data;
      video_prev_line_data <= output_prev_line_data;
    end
  end
  assign output_odd_line = (output_pixel_y % 2) == 1 ? 1'b1 : 1'b0;
  assign output_data = output_odd_line == 1'b1 ? odd_linebuf_q : even_linebuf_q;
  assign output_prev_line_data = output_odd_line == 1'b1 ? even_linebuf_q : odd_linebuf_q;
  assign linebuf_read_address = output_timing_h - (output_hvis_begin - 1);
  // the -1 accounts for the RAM read latency
  video_timing_ctrl #(
      .video_hlength(output_tmg_hlength),
    .video_vlength(video_vlength),
    .video_hsync_pol(video_hsync_pol),
    .video_hsync_len(video_hsync_len / pixels_per_clock),
    .video_hbp_len(video_hbp_len / pixels_per_clock),
    .video_h_visible(video_h_visible / pixels_per_clock),
    .video_vsync_pol(video_vsync_pol),
    .video_vsync_len(video_vsync_len),
    .video_vbp_len(video_vbp_len),
    .video_v_visible(video_v_visible),
    .sync_v_pos(video_vbp_len + video_vsync_len - 1),
    //keep output 1 line behind input
    .sync_h_pos(output_tmg_hlength - 5))
  output_timing(
      .pixel_clock(output_clock),
    .reset(reset),
    .ext_sync(video_fsync),
    .timing_h_pos(output_timing_h),
    .timing_v_pos(/* open */),
    .pixel_x(/* open */),
    .pixel_y(output_pixel_y),
    .video_vsync(output_vsync),
    .video_hsync(output_hsync),
    .video_den(output_den),
    .video_line_start(output_line_start));
  csi_rx_line_buffer #(
      .line_width(video_h_visible),
    .pixels_per_clock(pixels_per_clock))
  even_linebuf(
      .write_clock(csi_byte_clock),
    .write_addr(linebuf_write_address),
    .write_data(pixel_data_in),
    .write_en(even_linebuf_wren),
    .read_clock(output_clock),
    .read_addr(linebuf_read_address),
    .read_q(even_linebuf_q));
  csi_rx_line_buffer #(
      .line_width(video_h_visible),
    .pixels_per_clock(pixels_per_clock))
  odd_linebuf(
      .write_clock(csi_byte_clock),
    .write_addr(linebuf_write_address),
    .write_data(pixel_data_in),
    .write_en(odd_linebuf_wren),
    .read_clock(output_clock),
    .read_addr(linebuf_read_address),
    .read_q(odd_linebuf_q));
  assign video_valid = 1'b1;
    //not yet implemented
endmodule

