module xorshift(
input wire clk,
input wire rst_n,
input wire kick_n,
output reg d_en_n,
output reg [3:0] data
);
reg [31:0] y = 32'h92d68ca2;
reg [3:0] state = 4'b0000;
  always @(posedge clk) begin
    if(rst_n == 1'b0) begin
      d_en_n <= 1'b1;
      state <= 4'b0000;
    end
    else begin
      case(state)
      4'b0000 : begin
        if(kick_n == 1'b0) begin
          y <= y ^ ({y[31 - 13:0],13'b0000000000000});
          state <= 4'b0001;
        end
      end
      4'b0001 : begin
        y <= y ^ ({17'b00000000000000000,y[31:17]});
        state <= 4'b0011;
      end
      4'b0011 : begin
        y <= y ^ ({y[31 - 5:0],5'b00000});
        state <= 4'b0010;
      end
      4'b0010 : begin
        state <= 4'b0110;
        d_en_n <= 1'b0;
        data <= y[3:0];
      end
      4'b0110 : begin
        state <= 4'b0111;
        data <= y[7:4];
      end
      4'b0111 : begin
        state <= 4'b0101;
        data <= y[11:8];
      end
      4'b0101 : begin
        state <= 4'b0100;
        data <= y[15:12];
      end
      4'b0100 : begin
        state <= 4'b1100;
        data <= y[19:16];
      end
      4'b1100 : begin
        state <= 4'b1101;
        data <= y[23:20];
      end
      4'b1101 : begin
        state <= 4'b1111;
        data <= y[27:24];
      end
      4'b1111 : begin
        state <= 4'b1110;
        data <= y[31:28];
      end
      4'b1110 : begin
        state <= 4'b1010;
        d_en_n <= 1'b1;
      end
      4'b1010 : begin
        state <= 4'b1000;
      end
      4'b1000 : begin
        state <= 4'b0000;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

module EPROC_IN2(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
input wire ENA,
input wire swap_inputbits,
input wire [1:0] ENCODING,
input wire [1:0] EDATA_IN,
output wire [9:0] DATA_OUT,
output wire DATA_RDY,
output wire busyOut
);
parameter do_generate=true;
parameter zeros10array = 1'b0;
reg [1:0] edata_in_s;
wire [9:0] DATA_OUT_direct; wire [9:0] DATA_OUT_8b10b_case; wire [9:0] DATA_OUT_HDLC_case; wire [9:0] DATA_OUT_s;
wire DATA_RDY_direct; wire DATA_RDY_8b10b_case; wire DATA_RDY_HDLC_case; wire DATA_RDY_sig;
wire RESTART_sig; wire rst_case00; wire rst_case01; wire rst_case10;  //-
  generate if (do_generate == true) begin: gen_enabled
      //
    always @(swap_inputbits, EDATA_IN) begin
      if(swap_inputbits == 1'b1) begin
        edata_in_s <= {EDATA_IN[0],EDATA_IN[1]};
      end
      else begin
        edata_in_s <= EDATA_IN;
      end
    end
    //
    assign RESTART_sig = rst | ( ~ENA);
    // comes from clk40 domain 
    //
    //-----------------------------------------------------------------------------------------
    // ENCODING case "00": direct data, no delimeter...
    //-----------------------------------------------------------------------------------------
    assign rst_case00 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b00)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_direct direct_data_case(
          .bitCLK(bitCLK),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case00),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_direct),
      .dataOUTrdy(DATA_RDY_direct));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "01": DEC8b10b
    //-----------------------------------------------------------------------------------------
    assign rst_case01 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b01)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_DEC8b10b dec8b10b_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case01),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_8b10b_case),
      .dataOUTrdy(DATA_RDY_8b10b_case),
      .busyOut(busyOut));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "10": HDLC
    //-----------------------------------------------------------------------------------------
    assign rst_case10 = ((RESTART_sig == 1'b0) && (ENCODING == 2'b10)) ? 1'b0 : 1'b1;
    //
    EPROC_IN2_HDLC decHDLC_case(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case10),
      .edataIN(edata_in_s),
      .dataOUT(DATA_OUT_HDLC_case),
      .dataOUTrdy(DATA_RDY_HDLC_case));
    //-----------------------------------------------------------------------------------------
    // output data/rdy according to the encoding settings
    //-----------------------------------------------------------------------------------------
    MUX4_Nbit #(
          .N(10))
    DATA_OUT_MUX4_10bit(
          .data0(DATA_OUT_direct),
      .data1(DATA_OUT_8b10b_case),
      .data2(DATA_OUT_HDLC_case),
      .data3(zeros10array),
      .sel(ENCODING),
      .data_out(DATA_OUT_s));
    MUX4 DATA_RDY_MUX4(
          .data0(DATA_RDY_direct),
      .data1(DATA_RDY_8b10b_case),
      .data2(DATA_RDY_HDLC_case),
      .data3(1'b0),
      .sel(ENCODING),
      .data_out(DATA_RDY_sig));
    assign DATA_RDY = DATA_RDY_sig;
    assign DATA_OUT = DATA_OUT_s;
        //------------------
  end
  endgenerate
  //
  //
  generate if (do_generate == false) begin: gen_disabled
      assign DATA_OUT = {10{1'b0}};
    assign DATA_RDY = 1'b0;
    assign busyOut = 1'b0;
