module MemController(
input wire clk,
input wire readMem,
input wire writeMem,
output reg regEn,
output reg wen,
output reg outen
);
//-----------------------------------------------------------------------------
parameter [2:0]
  ready = 0,
  read_in = 1,
  write_out = 2,
  write_outtwo = 3,
  write_in = 4,
  written = 5;
reg [2:0] state; reg [2:0] next_state;
  // architecture arch
  always @(posedge clk) begin
    state <= next_state;
  end
  always @(state, writeMem, readMem) begin
    case(state)
    ready : begin
      if(readMem == 1'b1) begin
        next_state <= read_in;
      end
      else if(writeMem == 1'b1) begin
        next_state <= write_in;
      end
      else begin
        next_state <= ready;
      end
    end
    read_in : begin
      next_state <= write_out;
    end
    write_in : begin
      next_state <= written;
    end
    write_out : begin
      next_state <= write_outtwo;
    end
    write_outtwo : begin
      next_state <= ready;
    end
    written : begin
      next_state <= ready;
    end
    endcase
  end
  always @(state) begin
    case(state)
    ready : begin
      regEn <= 1'b0;
      wen <= 1'b0;
      outen <= 1'b0;
    end
    read_in : begin
      regEn <= 1'b1;
      wen <= 1'b0;
      outen <= 1'b0;
    end
    write_in : begin
      regEn <= 1'b1;
      wen <= 1'b0;
      outen <= 1'b0;
    end
    write_out : begin
      regEn <= 1'b0;
      wen <= 1'b0;
      outen <= 1'b0;
    end
    write_outtwo : begin
      regEn <= 1'b0;
      wen <= 1'b0;
      outen <= 1'b1;
    end
    written : begin
      regEn <= 1'b0;
      wen <= 1'b1;
      outen <= 1'b0;
    end
    endcase
  end
//-----------------------------------------------------------------------------
endmodule

module ClockDivider(
input wire clk_in,
output wire clk_out
);
parameter [31:0] DEVIDER=2;
reg temp = 1'b0;
reg [31:0] counter = 0;
  always @(posedge clk_in) begin
    if((counter == DEVIDER)) begin
      counter <= 0;
      temp <=  ~(temp);
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign clk_out = temp;
endmodule

module procesador(
input wire Clk,
input wire Reset,
output wire [31:0] I_Addr,
