);
// Instruction memory
// Data memory
//----------------------
//----COMPONENTES-------
//----------------------
//----------------
//---SEÑALES------
//----------------
reg [31:0] PC_IN;
reg [31:0] PC_IN1;
reg [31:0] addResultIN;
reg [31:0] addResultOUT;
reg [31:0] MemMux1;
reg [31:0] MemMux2;  //-----ALU-----------------------------------------
reg [31:0] OpA;
reg [31:0] OpAPosible;
reg [31:0] OpB;
reg [31:0] mux1OpB;
reg [31:0] mux1OpBPosible;
reg [31:0] mux2OpB;
wire [5:0] AluControl;
reg [3:0] ALUctr;
wire Zero;
wire [31:0] AluResultIN;
wire [31:0] AluResultOUT;  //-------------------------------------------------
//------------CONTROL----------------------------
reg [5:0] Control;  //----EX------------
reg [3:0] EXctr;
reg [3:0] EXHAZARD;
reg RegDst;
reg [1:0] ALUOp;
reg AluSrc;  //-----M------------
reg [2:0] Mctr;
reg [2:0] MHAZARD;
reg [2:0] Mctr1;
wire [2:0] Mctr2;
reg PCSrc;  //----WB------------
reg [1:0] WEctr;
reg [1:0] WEHAZARD;
reg [1:0] WEctr1;
reg [1:0] WEctr2;
reg EscrReg;
reg MemToReg;  //-------------------------------------------------
reg [31:0] signo_extend;
reg [4:0] reg_lect1IF;
reg [4:0] reg_lect2IF;
reg [4:0] rdInstCarg;
reg [4:0] rdInstALU;
reg [4:0] reg_escr;
wire [4:0] reg_escrIN;
wire [31:0] dato_leido1;
wire [31:0] dato_leido2;
reg [31:0] dato_escr;
wire [4:0] RegEscribir1;
wire [4:0] RegEscribir2;
reg [4:0] mux_aux1;
reg [4:0] mux_aux2;  //-------FORWARDINGUNIT-----------
reg [4:0] ID_EX_RS;
reg [4:0] ID_EX_RT;
reg EX_MEM_ESCREG;
reg MEM_WB_ESCREG;
reg [4:0] EX_MEM_RD;
reg [4:0] MEM_WB_RD;
wire [1:0] AnticipaA;
wire [1:0] AnticipaB;
wire PC_Write;
wire IFID_Write;
reg IDEX_Memread;
wire MUX_sel;
reg [4:0] IDEX_Rt;
reg [4:0] IFID_Rs;
reg [4:0] IFID_Rt;
  //---------------
  //--PORT-MAPS----
  //---------------
  //BANCO REGISTROS--
  tabla_registros BANCO(
      .CLK(Clk),
    .Reset(Reset),
    .EscrReg(EscrReg),
    .reg_lec1(reg_lect1IF),
    .reg_lec2(reg_lect2IF),
    .reg_escr(reg_escr),
    .dato_escr(dato_escr),
    .dato_leido1(dato_leido1),
    .dato_leido2(dato_leido2));
  //ALU--
  ALU UAL(
      .A(OpA),
    .B(OpB),
    .control(ALUctr),
    .resultado(AluResultIN),
    .igual(Zero));
  ForwardingUnit UnitForward(
      .ID_EX_RS(ID_EX_RS),
    .ID_EX_RT(ID_EX_RT),
    .EX_MEM_ESCREG(EX_MEM_ESCREG),
    .MEM_WB_ESCREG(MEM_WB_ESCREG),
    .EX_MEM_RD(EX_MEM_RD),
    .MEM_WB_RD(MEM_WB_RD),
    .AnticipaA(AnticipaA),
    .AnticipaB(AnticipaB));
  HAZARD HazardUnit(
      .PC_Write(PC_Write),
    .IFID_Write(IFID_Write),
    .IDEX_Memread(IDEX_Memread),
    .MUX_sel(MUX_sel),
    .IDEX_Rt(IDEX_Rt),
    .IFID_Rs(IFID_Rs),
    .IFID_Rt(IFID_Rt));
  assign I_RdStb = 1'b1;
  assign I_WrStb = 1'b0;
  assign I_AddrStb = 1'b1;
  assign D_AddrStb = 1'b1;
  assign I_Addr = PC_IN;
  assign I_DataOut = 32'h00000000;
  //----------------------------
  //--CONTADOR DE PROGRAMA------
  //----------------------------
  always @(posedge Clk, posedge Reset) begin
    if(Reset == 1'b1) begin
      PC_IN <= 32'h00000000;
    end else begin
      if(PC_Write == 1'b1) begin
        if((PCSrc == 1'b1)) begin
          PC_IN <= addResultOUT;
        end
        else begin
          PC_IN <= PC_IN + 4;
        end
      end
    end
  end
  //---------------------
  //-PRIMER PIPE (IF)----
  //--------------------- 
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b1) || (PcSrc == 1'b1)) begin
      PC_IN1 <= 32'h00000000;
      Control <= 6'b111111;
      reg_lect1IF <= 5'b00000;
      reg_lect2IF <= 5'b00000;
      rdInstCarg <= 5'b00000;
      rdInstALU <= 5'b00000;
      signo_extend <= 32'h00000000;
      IFID_Rs <= 5'b00000;
      IFID_Rt <= 5'b00000;
    end else begin
      if((IFID_Write == 1'b1)) begin
        PC_IN1 <= PC_IN;
        Control <= I_DataIn[31:26];
        reg_lect1IF <= I_DataIn[25:21];
        reg_lect2IF <= I_DataIn[20:16];
        rdInstCarg <= I_DataIn[20:16];
        rdInstALU <= I_DataIn[15:11];
        if(I_DataIn[15] == 1'b1) begin
          signo_extend <= {16'hFFFF,I_DataIn[15:0]};
        end
        else begin
          signo_extend <= {16'h0000,I_DataIn[15:0]};
        end
      end
    end
  end
  assign IFID_Rs = reg_lect1IF;
  assign IFID_Rt = reg_lect2IF;
  assign IDEX_Rt = mux_aux1;
  assign IDEX_Memread = Mctr1[1];
  //---------------------
  //-SEGUNDO PIPE (EX)--
  //---------------------
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b1) || (PcSrc == 1'b1)) begin
      WEctr1 <= 2'b00;
      Mctr1 <= 3'b000;
      ALUOp <= 2'b00;
      ALUcontrol <= 6'b000000;
      OpAPosible <= 32'h00000000;
      mux1OpBPosible <= 32'h00000000;
      mux2OpB <= 32'h00000000;
      mux_aux1 <= 5'b00000;
      mux_aux2 <= 5'b00000;
      addResultIN <= 32'h00000000;
      AluSrc <= 1'b0;
      RegDst <= 1'b0;
      ID_EX_RS <= 5'b00000;
      ID_EX_RT <= 5'b00000;
      IDEX_Rt <= 5'b00000;
    end else begin
      if((PcSrc == 1'b1)) begin
        WEctr1 <= 2'b00;
        Mctr1 <= 3'b000;
        ALUOp <= 2'b00;
        ALUcontrol <= 6'b000000;
        OpAPosible <= 32'h00000000;
        mux1OpBPosible <= 32'h00000000;
        mux2OpB <= 32'h00000000;
        mux_aux1 <= 5'b00000;
        mux_aux2 <= 5'b00000;
        addResultIN <= 32'h00000000;
        AluSrc <= 1'b0;
        RegDst <= 1'b0;
        ID_EX_RS <= 5'b00000;
        ID_EX_RT <= 5'b00000;
        IDEX_Rt <= 5'b00000;
      end
      else begin
        WEctr1 <= WEctr;
        Mctr1 <= Mctr;
        ALUcontrol <= signo_extend[5:0];
        mux2OpB <= signo_extend;
        addResultIN <= {signo_extend[29:0],2'b00} + PC_IN1;
        OpAPosible <= dato_leido1;
        mux1OpBPosible <= dato_leido2;
        mux_aux1 <= rdInstCarg;
        mux_aux2 <= rdInstALU;
        RegDst <= EXctr[3];
        ALUOp <= EXctr[2:1];
        AluSrc <= EXctr[0];
        ID_EX_RS <= reg_lect1IF;
        ID_EX_RT <= reg_lect2IF;
      end
    end
  end
  //--------MULTIPLEXORES--------------
  always @(*) begin
    case(AluSrc)
      1'b0 : OpB <= mux1OpB;
      default : OpB <= mux2OpB;
    endcase
  end
  always @(*) begin
    case(RegDst)
      1'b0 : regEscribir1 <= mux_aux1;
      default : regEscribir1 <= mux_aux2;
    endcase
  end
  always @(*) begin
    case(MemToReg)
      1'b0 : dato_escr <= MemMux2;
      default : dato_escr <= MemMux1;
    endcase
  end
  //----------------------------------	
  //MULTIPLEXOR PARA ELEGIR LA ENTRADA A LA ALU DEL OPERANDO A
  always @(OpAPosible, AnticipaA, dato_escr, aluResultOUT) begin
    if((AnticipaA == 2'b00)) begin
      OpA <= OpAPosible;
    end
    else if((AnticipaA == 2'b01)) begin
      OpA <= dato_escr;
    end
    else if((AnticipaA == 2'b10)) begin
      OpA <= aluResultOUT;
      //when AnticipaA="10"
    end
  end
  //MULTIPLEXOR PARA ELEGIR LA ENTRADA POSIBLE DEL OPERANDO B
  always @(mux1OpB, AnticipaB, dato_escr, aluResultOUT) begin
    if((AnticipaB == 2'b00)) begin
      mux1OpB <= mux1OpBPosible;
    end
    else if((AnticipaB == 2'b01)) begin
      mux1OpB <= dato_escr;
    end
    else if((AnticipaB == 2'b10)) begin
      mux1OpB <= aluResultOUT;
    end
  end
  //---------------------
  //-TERCER PIPE (MEM)--
  //---------------------
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b1)) begin
      addResultOUT <= 32'h00000000;
      D_WrStb <= 1'b0;
      //memwrite
      D_RdStb <= 1'b0;
      //memread
      PCSrc <= 1'b0;
      D_DataOut <= 32'h00000000;
      aluResultOUT <= 32'h00000000;
      WEctr2 <= 2'b00;
      regEscribir2 <= 5'b00000;
      D_Addr <= 32'h00000000;
      EX_MEM_ESCREG <= 1'b0;
      IDEX_Memread <= 1'b0;
      EX_MEM_RD <= 5'b00000;
    end else begin
      if((PcSrc == 1'b1)) begin
        addResultOUT <= 32'h00000000;
        D_WrStb <= 1'b0;
        //memwrite
        D_RdStb <= 1'b0;
        //memread
        PCSrc <= 1'b0;
        D_DataOut <= 32'h00000000;
        aluResultOUT <= 32'h00000000;
        WEctr2 <= 2'b00;
        regEscribir2 <= 5'b00000;
        D_Addr <= 32'h00000000;
        EX_MEM_ESCREG <= 1'b0;
        IDEX_Memread <= 1'b0;
        EX_MEM_RD <= 5'b00000;
      end
      else begin
        WEctr2 <= WEctr1;
        addResultOUT <= addResultIN;
        D_WrStb <= Mctr1[0];
        //memwrite
        D_RdStb <= Mctr1[1];
        //memread
        PCSrc <= Mctr1[2] & Zero;
        EX_MEM_RD <= regEscribir1;
        D_Addr <= AluResultIN;
        aluResultOUT <= AluResultIN;
        D_DataOut <= mux1OpB;
        regEscribir2 <= regEscribir1;
        EX_MEM_ESCREG <= WEctr1[1];
      end
    end
  end
  //-----------------
  //--REGISTRO 4-----
  //-----------------
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b1) || (PcSrc == 1'b1)) begin
      MemMux1 <= 32'h00000000;
      MemMux2 <= 32'h00000000;
      reg_escr <= 5'b00000;
      MemToReg <= 1'b0;
      EscrReg <= 1'b0;
      MEM_WB_ESCREG <= 1'b0;
    end else begin
      MemMux1 <= D_DataIn;
      MemMux2 <= aluResultOUT;
      reg_escr <= regEscribir2;
      MemToReg <= WEctr2[0];
      EscrReg <= WEctr2[1];
      MEM_WB_ESCREG <= WEctr2[1];
      MEM_WB_RD <= regEscribir2;
    end
  end
  always @(ALUOp, ALUcontrol) begin
    case(ALUOp)
    2'b10 : begin
      //REG_A_REG
      case(ALUcontrol)
      6'b100000 : begin
        //ADD
        ALUctr <= 4'b0011;
      end
      6'b100010 : begin
        //SUB
        ALUctr <= 4'b1000;
      end
      6'b100100 : begin
        //AND
        ALUctr <= 4'b0000;
      end
      6'b100101 : begin
        //OR
        ALUctr <= 4'b0001;
      end
      6'b100110 : begin
        //XOR
        ALUctr <= 4'b0010;
      end
      6'b101010 : begin
        //SLT
        ALUctr <= 4'b1010;
      end
      default : begin
        ALUctr <= 4'b1111;
      end
      endcase
    end
    2'b00 : begin
      //LW ó SW
      ALUctr <= 4'b0011;
      //ADD PARA CONSEGUIR LA DIRECCION DE MEMORIA
    end
    2'b01 : begin
      //BEQ
      ALUctr <= 4'b0010;
      //XOR PARA VER SI RS Y RT SON IGUALES
    end
    2'b11 : begin
      //LIU
      ALUctr <= 4'b1001;
    end
    default : begin
      ALUctr <= 4'b1111;
    end
    endcase
  end
  always @(Control) begin
    case(Control)
    6'b000000 : begin
      //SPECIAL (R)
      EXHAZARD <= 4'b1100;
      MHAZARD <= 3'b000;
      WEHAZARD <= 2'b10;
    end
    6'b100011 : begin
      //LW
      EXHAZARD <= 4'b0001;
      MHAZARD <= 3'b010;
      WEHAZARD <= 2'b11;
    end
    6'b101011 : begin
      //SW
      EXHAZARD <= 4'b0001;
      MHAZARD <= 3'b001;
      WEHAZARD <= 2'b00;
    end
    6'b001111 : begin
      //LIU
      EXHAZARD <= 4'b0110;
      MHAZARD <= 3'b000;
      WEHAZARD <= 2'b10;
    end
    6'b000100 : begin
      //BE
      EXHAZARD <= 4'b0010;
      MHAZARD <= 3'b100;
      WEHAZARD <= 2'b00;
    end
    default : begin
      EXHAZARD <= 4'b0000;
      MHAZARD <= 3'b000;
      WEHAZARD <= 2'b00;
    end
    endcase
  end
  always @(MUX_Sel, WEHAZARD, MHAZARD, EXHAZARD) begin
    if(MUX_Sel == 1'b1) begin
      WEctr <= 2'b00;
      Mctr <= 3'b000;
      EXctr <= 4'b0000;
    end
    else if(MUX_Sel == 1'b0) begin
      WEctr <= WEHAZARD;
      Mctr <= MHAZARD;
      EXctr <= EXHAZARD;
    end
  end
endmodule

