module c_multiplexer(
input wire [(width * no_of_inputs) - 1:0] input,
input wire [select_size - 1:0] mux_select,
output reg [width - 1:0] output
);
parameter [31:0] width=4;
parameter [31:0] no_of_inputs=2;
parameter [31:0] select_size=1;
  always @(mux_select, input) begin : P1
    reg [31:0] control_val = 0;
    reg [31:0] base_val = 1;
    base_val = 1;
    control_val = 0;
    for (i=0; i <= select_size - 1; i = i + 1) begin
      if((mux_select[i] == 1'b1)) begin
        control_val = control_val + base_val;
      end
      base_val = base_val * 2;
    end
    output <= input[(control_val + 1) * width - 1:(control_val) * width];
  end
endmodule

