module debounce(
input wire clk_i,
input wire button_i,
output reg result_o
);
parameter [31:0] counter_size_g=10;
reg [1:0] flipflops_s;  // input flip flops
wire counter_set_s;  // sync reset to zero
reg [counter_size_g:0] counter_out_s = 1'b0;  // counter output
  assign counter_set_s = flipflops_s[0] ^ flipflops_s[1];
  // determine when to start/reset counter
  always @(posedge clk_i) begin
    flipflops_s[0] <= button_i;
    flipflops_s[1] <= flipflops_s[0];
    if(counter_set_s == 1'b1) begin
      // reset counter because input is changing
      counter_out_s <= {((counter_size_g)-(0)+1){1'b0}};
    end
    else if(counter_out_s[counter_size_g] == 1'b0) begin
      // stable input time is not yet met
      counter_out_s <= counter_out_s + 1;
    end
    else begin
      // stable input time is met
      result_o <= flipflops_s[1];
    end
  end
endmodule

