module AssignToASliceOfReg2b(
input wire clk,
input wire [0:0] data_in_addr,
input wire [7:0] data_in_data,
input wire [7:0] data_in_mask,
output wire data_in_rd,
input wire data_in_vld,
output wire [15:0] data_out,
input wire rst_n
);
reg [15:0] r = 16'h0000;
wire [15:0] r_next;
reg [3:0] r_next_11downto8;
reg [3:0] r_next_15downto12;
reg [3:0] r_next_3downto0;
reg [3:0] r_next_7downto4;
  assign data_in_rd = 1'b1;
  assign data_out = r;
  always @(posedge clk) begin
    if(rst_n == 1'b0) begin
      r <= 16'h0000;
    end
    else begin
      r <= r_next;
    end
  end
  assign r_next = {r_next_15downto12,r_next_11downto8,r_next_7downto4,r_next_3downto0};
  always @(data_in_addr, data_in_data, data_in_mask, data_in_vld, r) begin
    if(data_in_vld == 1'b1 && data_in_addr == 1'b1) begin
      if(data_in_mask == 8'hFF) begin
        r_next_11downto8 <= data_in_data[3:0];
        r_next_15downto12 <= data_in_data[7:4];
      end
      else if(data_in_mask == 8'h0F) begin
        r_next_15downto12 <= data_in_data[3:0];
        r_next_11downto8 <= r[11:8];
      end
      else begin
        r_next_11downto8 <= r[11:8];
        r_next_15downto12 <= r[15:12];
      end
    end
    else begin
      r_next_11downto8 <= r[11:8];
      r_next_15downto12 <= r[15:12];
    end
  end
  always @(data_in_addr, data_in_data, data_in_mask, data_in_vld, r) begin
    if(data_in_vld == 1'b1 && data_in_addr == 1'b0) begin
      if(data_in_mask == 8'hFF) begin
        r_next_3downto0 <= data_in_data[3:0];
        r_next_7downto4 <= data_in_data[7:4];
      end
      else if(data_in_mask == 8'h0F) begin
        r_next_7downto4 <= data_in_data[3:0];
        r_next_3downto0 <= r[3:0];
      end
      else begin
        r_next_3downto0 <= r[3:0];
        r_next_7downto4 <= r[7:4];
      end
    end
    else begin
      r_next_3downto0 <= r[3:0];
      r_next_7downto4 <= r[7:4];
    end
  end
endmodule

