input wire T2,
input wire CLR,
input wire RD,
input wire WR,
input wire [7:0] TX_DATA,
output wire TX_SEROUT,
input wire RX_SERIN,
output wire [7:0] RX_DATA,
output wire RX_READY,
output wire TX_BUSY
);
wire CE_16;
wire RX_FLAG;
reg RX_OLD_FLAG;
reg TX_FLAG;
wire TX_FLAGQ;
reg [7:0] LTX_DATA;
reg LRX_READY;
  assign RX_READY = LRX_READY;
  assign TX_BUSY = TX_FLAG ^ TX_FLAGQ;
  baudgen #(
      .bg_clock_freq(40000000),
    .bg_baud_rate(115200))
  baud(
      .CLK_I(CLK_I),
    .CLR(CLR),
    .CE_16(CE_16));
  uart urt(
      .CLK_I(CLK_I),
    .CLR(CLR),
    .CE_16(CE_16),
    .TX_DATA(LTX_DATA),
    .TX_FLAG(TX_FLAG),
    .TX_SEROUT(TX_SEROUT),
    .TX_FLAGQ(TX_FLAGQ),
    .RX_SERIN(RX_SERIN),
    .RX_DATA(RX_DATA),
    .RX_FLAG(RX_FLAG));
  always @(posedge CLK_I) begin
    if((T2 == 1'b1)) begin
      if((CLR == 1'b1)) begin
        TX_FLAG <= 1'b0;
        LTX_DATA <= 8'h33;
      end
      else begin
        if((RD == 1'b1)) begin
          // read Rx data
          LRX_READY <= 1'b0;
        end
        if((WR == 1'b1)) begin
          // write Tx data
          TX_FLAG <=  ~TX_FLAG;
          LTX_DATA <= TX_DATA;
        end
        if((RX_FLAG != RX_OLD_FLAG)) begin
          LRX_READY <= 1'b1;
        end
        RX_OLD_FLAG <= RX_FLAG;
      end
    end
  end
endmodule

