module eval_timer(
input wire Clk,
input wire Rst,
output wire Eval_timeout
);
//---------------------------------------------------------------------------
// Architecture section
//---------------------------------------------------------------------------
//---------------------------------------------------------------------------
// Constant Declarations
//---------------------------------------------------------------------------
parameter NUM_BITS = 8;  //---------------------------------------------------------------------------
// Signal Declarations
//---------------------------------------------------------------------------
wire [0:4] co;  // carry out  
wire [0:4] ceo;  // count enable out
wire [0:4] ceo_d1;  // registered count enable out 
wire [NUM_BITS - 1:0] zeros;  //---------------------------------------------------------------------------
// Component Declarations
//---------------------------------------------------------------------------
  // VHDL_RTL
  // set the load value to zero
  assign zeros = {((NUM_BITS - 1)-(0)+1){1'b0}};
  // Generate a 40-bit counter from 5 8-bit counters. Register the carry-out between counters
  // to avoid timing problems.
  genvar i;
  generate for (i=0; i <= 4; i = i + 1) begin: COUNTER_GEN
      // first 8-bit counter
    generate if (i == 0) begin: FIRST
          Counter #(
              .C_NUM_BITS(NUM_BITS))
      COUNT_0_I(
              .Clk(Clk),
        .Rst(Rst),
        .Load_in(zeros),
        .Count_Enable(1'b1),
        .Count_Load(1'b0),
        .Count_Down(1'b0),
        .Count_out(/* open */),
        .Carry_Out(co[0]));
      // register the carry out to create the count enable out 
      assign ceo[i] = co[i];
      FDR FDR_0_I(
              .Q(ceo_d1[i]),
        .C(Clk),
        .D(ceo[i]),
        .R(Rst));
    end
    endgenerate
    // all other eight bit counters and the carry out register
    generate if (i != 0) begin: ALL_OTHERS
          Counter #(
              .C_NUM_BITS(NUM_BITS))
      COUNT_I(
              .Clk(Clk),
        .Rst(Rst),
        .Load_in(zeros),
        .Count_Enable(ceo_d1[i - 1]),
        .Count_Load(1'b0),
        .Count_Down(1'b0),
        .Count_out(/* open */),
        .Carry_Out(co[i]));
      // register the carry out AND the count enable to create the count enable out      
      assign ceo[i] = co[i] & ceo_d1[i - 1];
      FDR FDR_0_I(
              .Q(ceo_d1[i]),
        .C(Clk),
        .D(ceo[i]),
        .R(Rst));
    end
    endgenerate
  end
  endgenerate
  // Using the final carry out as a CE, clock a '1' to assert and hold the eval_timeout signal.
  FDRE FDRE_I(
      .Q(eval_timeout),
    //[out]
    .C(Clk),
    //[in]
    .CE(ceo_d1[4]),
    //[in]
    .D(1'b1),
    //[in]
    .R(Rst));
endmodule

