module rdpfifo_top(
input wire Bus_rst,
input wire Bus_Clk,
input wire Bus_RdReq,
input wire Bus_WrReq,
input wire Bus2FIFO_RdCE1,
input wire Bus2FIFO_RdCE2,
input wire Bus2FIFO_RdCE3,
input wire Bus2FIFO_WrCE1,
input wire Bus2FIFO_WrCE2,
input wire Bus2FIFO_WrCE3,
input wire [0:C_IPIF_DBUS_WIDTH - 1] Bus_DBus,
input wire IP2RFIFO_WrReq,
input wire IP2RFIFO_WrMark,
input wire IP2RFIFO_WrRestore,
input wire IP2RFIFO_WrRelease,
input wire [0:C_FIFO_WIDTH - 1] IP2RFIFO_Data,
output wire RFIFO2IP_WrAck,
output wire RFIFO2IP_AlmostFull,
output wire RFIFO2IP_Full,
output wire [0:C_FIFO_DEPTH_LOG2X] RFIFO2IP_Vacancy,
output wire RFIFO2DMA_AlmostEmpty,
output wire RFIFO2DMA_Empty,
output wire [0:C_FIFO_DEPTH_LOG2X] RFIFO2DMA_Occupancy,
output wire FIFO2IRPT_DeadLock,
output wire [0:C_IPIF_DBUS_WIDTH - 1] FIFO2Bus_DBus,
output wire FIFO2Bus_WrAck,
output wire FIFO2Bus_RdAck,
output wire FIFO2Bus_Error,
output wire FIFO2Bus_Retry,
output wire FIFO2Bus_ToutSup
);
parameter C_MIR_ENABLE=true;
parameter [31:0] C_BLOCK_ID=255;
parameter [31:0] C_FIFO_DEPTH_LOG2X=9;
parameter [31:0] C_FIFO_WIDTH=32;
parameter C_INCLUDE_PACKET_MODE=true;
parameter C_INCLUDE_VACANCY=true;
parameter C_SUPPORT_BURST=true;
parameter [31:0] C_IPIF_DBUS_WIDTH=32;
parameter C_VIRTEX_II=true;
// Selection of target FPGA technology
// True = virtex ii family
// False = virtex family
// Inputs From the IPIF Bus
// Master Reset from the IPIF
// Master clock from the IPIF
// Inputs from the IP
// Outputs to the IP
// Outputs to the IPIF DMA/SG function
// Interrupt Output to IPIF Interrupt Register
// Outputs to the IPIF Bus
//-----------------------------------------------------------------------------
// COMPONENTS
//TYPES
// no types
// CONSTANTS
//--------------------------------------------------------------------------
// IMPORTANT!!!!!!!!!!!!!!!!!!!!!
// Set MODULE Versioning Information Here!!!
//
// The following three constants indicate the versioning read via the MIR
//--------------------------------------------------------------------------
parameter VERSION_MAJOR = 1;  // Major versioning the RPFIFO design
parameter VERSION_MINOR = 1;  // Minor Version of the RPFIFO design
parameter VERSION_REV = 1;  // Revision letter (0 = a, 1 = b, 2 = c, etc)
//--------------------------------------------------------------------------
// Set IPIF Block Protocol Type Here!!!!
//
//--------------------------------------------------------------------------
parameter PFIFO_INTFC_TYPE = 2;  // IPIF block protocol Type
// (Read Packet FIFO = 2, Write PFIFO = 3)
// General Use Constants
parameter LOGIC_LOW = 1'b0;
parameter LOGIC_HIGH = 1'b1;  //INTERNAL SIGNALS
// Dual Port interconnect
wire sig_mem_wrreq;
wire sig_mem_wr_enable;
wire [0:C_FIFO_WIDTH - 1] sig_mem_wr_data;
wire [0:C_FIFO_DEPTH_LOG2X - 1] sig_mem_wr_addr;
wire [0:C_FIFO_DEPTH_LOG2X - 1] sig_mem_rd_addr;
wire [0:C_FIFO_WIDTH - 1] sig_mem_rd_data;
wire sig_data_wrack;
wire sig_bramfifo_rdack;
wire sig_srlfifo_rdack;
wire sig_fifo_full;
wire sig_fifo_empty;
wire sig_fifo_almost_full;
wire sig_fifo_almost_empty;
wire [0:C_FIFO_DEPTH_LOG2X] sig_fifo_occupancy;
wire [0:C_FIFO_DEPTH_LOG2X] sig_fifo_vacancy;
wire sig_burst_rd_xfer;
wire sig_fifo_logic_reset;
wire sig_fifo_deadlock;
wire sig_bram_rdreq;
wire sig_srl_rdreq;
wire sig_mem_rd_enable;
wire [0:3] sig_bus_dbus_lsnib;  //-----------------------------------------------------------------------------
//----------- start processes -------------------------------------------------
  assign sig_bus_dbus_lsnib = Bus_DBus[C_IPIF_DBUS_WIDTH - 4:C_IPIF_DBUS_WIDTH - 1];
  // connect I/O signals to internals
  assign RFIFO2IP_WrAck = sig_data_wrack;
  assign RFIFO2IP_Full = sig_fifo_full;
  assign RFIFO2IP_AlmostFull = sig_fifo_almost_full;
  assign RFIFO2DMA_AlmostEmpty = sig_fifo_almost_empty;
  assign RFIFO2DMA_Empty = sig_fifo_empty;
  assign RFIFO2IP_Vacancy = sig_fifo_vacancy;
  assign RFIFO2DMA_Occupancy = sig_fifo_occupancy;
  // Some Dual Port signal assignments (vhdl wrapper)
  //sig_mem_wr_enable       <=  not(sig_fifo_full);
  assign sig_mem_wrreq = IP2RFIFO_WrReq;
  assign sig_mem_wr_data = IP2RFIFO_Data;
  ipif_control_rd #(
      .C_MIR_ENABLE(C_MIR_ENABLE),
    .C_BLOCK_ID(C_BLOCK_ID),
    .C_INTFC_TYPE(PFIFO_INTFC_TYPE),
    .C_VERSION_MAJOR(VERSION_MAJOR),
    .C_VERSION_MINOR(VERSION_MINOR),
    .C_VERSION_REV(VERSION_REV),
    .C_FIFO_WIDTH(C_FIFO_WIDTH),
    .C_DP_ADDRESS_WIDTH(C_FIFO_DEPTH_LOG2X),
    .C_SUPPORT_BURST(C_SUPPORT_BURST),
    .C_IPIF_DBUS_WIDTH(C_IPIF_DBUS_WIDTH))
  I_IPIF_INTERFACE_BLOCK(
      // Inputs From the IPIF Bus
    .Bus_rst(Bus_rst),
    .Bus_Clk(Bus_Clk),
    .Bus_RdReq(Bus_RdReq),
    .Bus_WrReq(Bus_WrReq),
    .Bus2FIFO_RdCE1(Bus2FIFO_RdCE1),
    .Bus2FIFO_RdCE2(Bus2FIFO_RdCE2),
    .Bus2FIFO_RdCE3(Bus2FIFO_RdCE3),
    .Bus2FIFO_WrCE1(Bus2FIFO_WrCE1),
    .Bus2FIFO_WrCE2(Bus2FIFO_WrCE2),
    .Bus2FIFO_WrCE3(Bus2FIFO_WrCE3),
    .Bus_DBus(sig_bus_dbus_lsnib),
    // Inputs from the FIFO Interface Logic
    .Fifo_rd_data(sig_mem_rd_data),
    .BRAMFifo_RdAck(sig_bramfifo_rdack),
    .SRLFifo_RdAck(sig_srlfifo_rdack),
    .Occupancy(sig_fifo_occupancy),
    .AlmostEmpty(sig_fifo_almost_empty),
    .Empty(sig_fifo_empty),
    .Deadlock(sig_fifo_deadlock),
    // Outputs to the FIFO
    .Fifo_rst(sig_fifo_logic_reset),
    .BRAMFifo_RdReq(sig_bram_rdreq),
    .SRLFifo_RdReq(sig_srl_rdreq),
    .Fifo_burst_rd_xfer(sig_burst_rd_xfer),
    // Outputs to the IPIF Bus
    .FIFO2IRPT_DeadLock(FIFO2IRPT_DeadLock),
    .FIFO2Bus_DBus(FIFO2Bus_DBus),
    .FIFO2Bus_WrAck(FIFO2Bus_WrAck),
    .FIFO2Bus_RdAck(FIFO2Bus_RdAck),
    .FIFO2Bus_Error(FIFO2Bus_Error),
    .FIFO2Bus_Retry(FIFO2Bus_Retry),
    .FIFO2Bus_ToutSup(FIFO2Bus_ToutSup));
  generate if ((C_FIFO_DEPTH_LOG2X > 4 || C_INCLUDE_PACKET_MODE == true)) begin: USE_BLOCK_RAM
      assign sig_srlfifo_rdack = 1'b0;
    // Connect the Dual Port Address Controller to the VHDL wrapper
    rdpfifo_dp_cntl #(
          .C_DP_ADDRESS_WIDTH(C_FIFO_DEPTH_LOG2X),
      .C_INCLUDE_PACKET_MODE(C_INCLUDE_PACKET_MODE),
      .C_INCLUDE_VACANCY(C_INCLUDE_VACANCY))
    I_DP_CONTROLLER(
          // Inputs
      .Bus_rst(sig_fifo_logic_reset),
      .Bus_clk(Bus_Clk),
      .Rdreq(sig_bram_rdreq),
      .Wrreq(sig_mem_wrreq),
      .Burst_rd_xfer(sig_burst_rd_xfer),
      .Mark(IP2RFIFO_WrMark),
      .Restore(IP2RFIFO_WrRestore),
      .Release(IP2RFIFO_WrRelease),
      // Outputs
      .WrAck(sig_data_wrack),
      .RdAck(sig_bramfifo_rdack),
      .Full(sig_fifo_full),
      .Empty(sig_fifo_empty),
      .Almost_Full(sig_fifo_almost_full),
      .Almost_Empty(sig_fifo_almost_empty),
      .DeadLock(sig_fifo_deadlock),
      .Occupancy(sig_fifo_occupancy),
      .Vacancy(sig_fifo_vacancy),
      .DP_core_wren(sig_mem_wr_enable),
      .Wr_Addr(sig_mem_wr_addr),
      .DP_core_rden(sig_mem_rd_enable),
      .Rd_Addr(sig_mem_rd_addr));
    // Dual Port Core connection
    pf_dpram_select #(
          .C_DP_DATA_WIDTH(C_FIFO_WIDTH),
      .C_DP_ADDRESS_WIDTH(C_FIFO_DEPTH_LOG2X),
      .C_VIRTEX_II(C_VIRTEX_II))
    I_DP_CORE(
          // Write Port signals
      .Wr_rst(sig_fifo_logic_reset),
      .Wr_Clk(Bus_Clk),
      .Wr_Enable(sig_mem_wr_enable),
      .Wr_Req(sig_mem_wrreq),
      .Wr_Address(sig_mem_wr_addr),
      .Wr_Data(sig_mem_wr_data),
      // Read Port Signals
      .Rd_rst(sig_fifo_logic_reset),
      .Rd_Clk(Bus_Clk),
      .Rd_Enable(sig_mem_rd_enable),
      .Rd_Address(sig_mem_rd_addr),
      .Rd_Data(sig_mem_rd_data));
  end
  endgenerate
  generate if ((C_FIFO_DEPTH_LOG2X <= 4 && C_INCLUDE_PACKET_MODE == False)) begin: USE_SRL_CORE
      assign sig_fifo_deadlock = 1'b0;
    assign sig_srlfifo_rdack = sig_srl_rdreq &  ~(sig_fifo_empty);
    assign sig_data_wrack = sig_mem_wrreq &  ~(sig_fifo_full);
    assign sig_bramfifo_rdack = 1'b0;
    srl16_fifo #(
          .C_FIFO_WIDTH(C_FIFO_WIDTH),
      .C_FIFO_DEPTH_LOG2X(C_FIFO_DEPTH_LOG2X),
      .C_INCLUDE_VACANCY(C_INCLUDE_VACANCY))
    I_SRL_MEM(
          .Bus_clk(Bus_Clk),
      .Bus_rst(sig_fifo_logic_reset),
      .Wr_Req(sig_mem_wrreq),
      .Wr_Data(sig_mem_wr_data),
      .Rd_Req(sig_srl_rdreq),
      .Rd_Data(sig_mem_rd_data),
      .Full(sig_fifo_full),
      .Almostfull(sig_fifo_almost_full),
      .Empty(sig_fifo_empty),
      .Almostempty(sig_fifo_almost_empty),
      .Occupancy(sig_fifo_occupancy),
      .Vacancy(sig_fifo_vacancy));
  end
  endgenerate
endmodule

