module audio_codec_model(
input wire rst_n,
input wire aud_data_in,
input wire aud_bclk_in,
input wire aud_lrclk_in,
output wire [data_width_g - 1:0] value_left_out,
output wire [data_width_g - 1:0] value_right_out
);
parameter [31:0] data_width_g=16;
// State definitions for internal codec.
parameter [1:0]
  wait_for_input = 0,
  read_left = 1,
  read_right = 2;
reg [1:0] present_state_r;
reg [31:0] bit_counter_r;  // Number of bits to count per sample.
reg [data_width_g - 1:0] input_buffer_r;  // Input buffer for incoming bits.
reg [data_width_g - 1:0] input_buffer_l_r;  // Input buffer for left channel.
reg [data_width_g - 1:0] input_buffer_r_r;  // Input buffer for right channel.
  //rtl
  // Assing output registers to outputs.
  assign value_left_out = input_buffer_l_r;
  assign value_right_out = input_buffer_r_r;
  always @(posedge aud_bclk_in, posedge rst_n) begin
    if((rst_n == 1'b0)) begin
      // Reset state and output registers.
      present_state_r <= wait_for_input;
      bit_counter_r <= data_width_g - 1;
      input_buffer_l_r <= {((data_width_g - 1)-(0)+1){1'b0}};
      input_buffer_r_r <= {((data_width_g - 1)-(0)+1){1'b0}};
    end else begin
      // Read input on bclk rising edge.
      case(present_state_r)
            // Handle init and other states.
      wait_for_input : begin
        // First input data, look for direction.
        input_buffer_r[bit_counter_r] <= aud_data_in;
        if((aud_lrclk_in == 1'b0)) begin
          present_state_r <= read_right;
        end
        else begin
          present_state_r <= read_left;
        end
        bit_counter_r <= bit_counter_r - 1;
      end
      read_right : begin
        // Read right channel data.
        if((bit_counter_r == 0)) begin
          // Reset counter and change channel if we have all data.
          input_buffer_r_r[bit_counter_r] <= aud_data_in;
          input_buffer_r_r[data_width_g - 1:1] <= input_buffer_r[data_width_g - 1:1];
          // Note: Is the above line ok? Same for the left channel.
          bit_counter_r <= data_width_g - 1;
          present_state_r <= read_left;
        end
        else begin
          input_buffer_r[bit_counter_r] <= aud_data_in;
          bit_counter_r <= bit_counter_r - 1;
        end
      end
      read_left : begin
        // Read left channel data.
        if((bit_counter_r == 0)) begin
          // Reset counter and change channel if we have all data.
          input_buffer_l_r[bit_counter_r] <= aud_data_in;
          input_buffer_l_r[data_width_g - 1:1] <= input_buffer_r[data_width_g - 1:1];
          bit_counter_r <= data_width_g - 1;
          present_state_r <= read_right;
        end
        else begin
          input_buffer_r[bit_counter_r] <= aud_data_in;
          bit_counter_r <= bit_counter_r - 1;
        end
      end
      endcase
    end
  end
endmodule

module registers(
input wire voted_data_bit,
input wire clk,
input wire reset,
input wire [2:0] status,
input wire [9:0] control_signals,
input wire [3:0] ECC_signal,
output reg [7:0] voted_data_out,
output reg [2:0] status_out,
output reg [3:0] ECC_out
);
reg [7:0] voted_data_reg;
reg [2:0] status_reg;
reg [3:0] ECC_reg;
  // Connect the registers to the outputs
  always @(voted_data_reg, status_reg, ECC_reg) begin
    voted_data_out <= voted_data_reg;
    status_out <= status_reg;
    ECC_out <= ECC_reg;
  end
  // Add registers for storage of data
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      voted_data_reg <= 8'b00000000;
      status_reg <= 3'b000;
      ECC_reg <= 4'b0000;
    end
    else begin
      if(control_signals[0] == 1'b1) begin
        voted_data_reg[0] <= voted_data_bit;
      end
      if(control_signals[1] == 1'b1) begin
        voted_data_reg[1] <= voted_data_bit;
      end
      if(control_signals[2] == 1'b1) begin
        voted_data_reg[2] <= voted_data_bit;
      end
      if(control_signals[3] == 1'b1) begin
        voted_data_reg[3] <= voted_data_bit;
      end
      if(control_signals[4] == 1'b1) begin
        voted_data_reg[4] <= voted_data_bit;
      end
      if(control_signals[5] == 1'b1) begin
        voted_data_reg[5] <= voted_data_bit;
      end
      if(control_signals[6] == 1'b1) begin
        voted_data_reg[6] <= voted_data_bit;
      end
      if(control_signals[7] == 1'b1) begin
        voted_data_reg[7] <= voted_data_bit;
      end
      if(control_signals[8] == 1'b1) begin
        status_reg <= status;
      end
      if(control_signals[9] == 1'b1) begin
        ECC_reg <= ECC_signal;
      end
    end
  end
endmodule

module ClockDiv(
input wire clk,
input wire reset,
output wire clk_2t,
output wire clk_4t,
output wire clk_16t
);
reg clk_2t_q = 1'b0;
reg div_4t = 1'b0;
reg clk_4t_q = 1'b0;
reg [3:0] div_16t = 4'b0000;
reg clk_16t_q = 1'b0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b0)) begin
      div_4t <= 1'b0;
    end else begin
      div_4t <=  ~div_4t;
    end
  end
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b0)) begin
      div_16t <= {4{1'b0}};
    end else begin
      div_16t <= div_16t + 1'b1;
    end
  end
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b0)) begin
      clk_2t_q <= 1'b0;
      clk_4t_q <= 1'b0;
      clk_16t_q <= 1'b0;
    end else begin
      clk_2t_q <=  ~clk_2t_q;
      if((div_4t == 1'b0)) begin
        clk_4t_q <=  ~clk_4t_q;
      end
      else begin
        clk_4t_q <= clk_4t_q;
      end
      if((div_16t == 4'b0000)) begin
        clk_16t_q <=  ~clk_16t_q;
      end
      else begin
        clk_16t_q <= clk_16t_q;
      end
    end
  end
  assign clk_2t = clk_2t_q;
  assign clk_4t = clk_4t_q;
  assign clk_16t = clk_16t_q;
endmodule

module PEnc4_2(
input wire [3:0] decodedIn,
output reg [1:0] encodedOut,
output reg validOut
);
  always @(decodedIn) begin
    if((decodedIn[3] == 1'b1)) begin
      encodedOut <= 2'b11;
      validOut <= 1'b1;
    end
    else if((decodedIn[2] == 1'b1)) begin
      encodedOut <= 2'b10;
      validOut <= 1'b1;
    end
    else if((decodedIn[1] == 1'b1)) begin
      encodedOut <= 2'b01;
      validOut <= 1'b1;
    end
    else if((decodedIn[0] == 1'b1)) begin
      encodedOut <= 2'b00;
      validOut <= 1'b1;
    end
    else begin
      encodedOut <= 2'b00;
      validOut <= 1'b0;
    end
  end
endmodule

