module unidade_controle_transmissao(
input wire liga,
input wire enviar,
input wire reset,
input wire clock,
input wire CTS,
output reg DTR,
output reg RTS,
output reg enable_transmissao,
output wire envioOk,
output reg [1:0] s_estado
);
// depuracao
parameter [1:0]
  inicial = 0,
  ligado = 1,
  transmissao = 2,
  espera = 3;
reg [1:0] estado;
  assign envioOk = CTS;
  always @(posedge clock, posedge estado, posedge reset, posedge liga, posedge enviar) begin
    if(reset == 1'b1) begin
      estado <= inicial;
    end else begin
      case(estado)
      inicial : begin
        if(liga == 1'b1) begin
          estado <= ligado;
        end
      end
      ligado : begin
        if(liga == 1'b1) begin
          if(enviar == 1'b1) begin
            estado <= espera;
          end
        end
        else begin
          estado <= inicial;
        end
      end
      espera : begin
        if(enviar == 1'b1) begin
          if(CTS == 1'b1) begin
            estado <= transmissao;
          end
        end
        else begin
          estado <= ligado;
        end
      end
      transmissao : begin
        if(enviar == 1'b0) begin
          estado <= ligado;
        end
      end
      endcase
    end
  end
  always @(estado) begin
    case(estado)
    inicial : begin
      s_estado <= 2'b00;
      DTR <= 1'b0;
      RTS <= 1'b0;
      enable_transmissao <= 1'b0;
    end
    ligado : begin
      s_estado <= 2'b01;
      DTR <= 1'b1;
      RTS <= 1'b0;
      enable_transmissao <= 1'b0;
    end
    espera : begin
      s_estado <= 2'b10;
      DTR <= 1'b1;
      RTS <= 1'b1;
      enable_transmissao <= 1'b0;
    end
    transmissao : begin
      s_estado <= 2'b11;
      DTR <= 1'b1;
      RTS <= 1'b1;
      enable_transmissao <= 1'b1;
    end
    endcase
  end
endmodule

module lbp_process(
input wire clk_proc,
input wire reset_n,
input wire [PIX_WIDTH - 1:0] in_data,
input wire in_fv,
input wire in_dv,
output wire [PIX_WIDTH - 1:0] out_data,
output wire out_fv,
output wire out_dv,
input wire enable_i,
input wire [15:0] widthimg_i,
input wire [7:0] theshold_i
);
parameter [31:0] LINE_WIDTH_MAX;
parameter [31:0] PIX_WIDTH;
//----------------------- in flow -----------------------
//---------------------- out flow -----------------------
//----------------------- params ------------------------
wire [PIX_WIDTH - 1:0] p00; wire [PIX_WIDTH - 1:0] p01; wire [PIX_WIDTH - 1:0] p02;
wire [PIX_WIDTH - 1:0] p10; wire [PIX_WIDTH - 1:0] p11; wire [PIX_WIDTH - 1:0] p12;
wire [PIX_WIDTH - 1:0] p20; wire [PIX_WIDTH - 1:0] p21; wire [PIX_WIDTH - 1:0] p22;
wire matrix_dv;
reg [PIX_WIDTH - 1:0] value_data;
reg value_dv;
  matrix_extractor #(
      .LINE_WIDTH_MAX(LINE_WIDTH_MAX),
    .PIX_WIDTH(PIX_WIDTH),
    .OUTVALUE_WIDTH(PIX_WIDTH))
  matrix_extractor_inst(
      .clk_proc(clk_proc),
    .reset_n(reset_n),
    .in_data(in_data),
    .in_fv(in_fv),
    .in_dv(in_dv),
    .p00(p00),
    .p01(p01),
    .p02(p02),
    .p10(p10),
    .p11(p11),
    .p12(p12),
    .p20(p20),
    .p21(p21),
    .p22(p22),
    .matrix_dv(matrix_dv),
    .value_data(value_data),
    .value_dv(value_dv),
    .out_data(out_data),
    .out_fv(out_fv),
    .out_dv(out_dv),
    .enable_i(enable_i),
    .widthimg_i(widthimg_i));
  always @(posedge clk_proc, posedge reset_n, posedge matrix_dv) begin
    if((reset_n == 1'b0)) begin
    end else begin
      value_dv <= 1'b0;
      if((matrix_dv == 1'b1)) begin
        if(((p11) > ((p00) + (theshold_i)))) begin
          value_data[0] <= 1'b1;
        end
        else begin
          value_data[0] <= 1'b0;
        end
        if(((p11) > ((p01) + (theshold_i)))) begin
          value_data[1] <= 1'b1;
        end
        else begin
          value_data[1] <= 1'b0;
        end
        if(((p11) > ((p02) + (theshold_i)))) begin
          value_data[2] <= 1'b1;
        end
        else begin
          value_data[2] <= 1'b0;
        end
        if(((p11) > ((p10) + (theshold_i)))) begin
          value_data[3] <= 1'b1;
        end
        else begin
          value_data[3] <= 1'b0;
        end
        if(((p11) > ((p12) + (theshold_i)))) begin
          value_data[4] <= 1'b1;
        end
        else begin
          value_data[4] <= 1'b0;
        end
        if(((p11) > ((p20) + (theshold_i)))) begin
          value_data[5] <= 1'b1;
        end
        else begin
          value_data[5] <= 1'b0;
        end
        if(((p11) > ((p21) + (theshold_i)))) begin
          value_data[6] <= 1'b1;
        end
        else begin
          value_data[6] <= 1'b0;
        end
        if(((p11) > ((p22) + (theshold_i)))) begin
          value_data[7] <= 1'b1;
        end
        else begin
          value_data[7] <= 1'b0;
        end
        //~ value_data<=p11;
        value_dv <= 1'b1;
      end
    end
  end
endmodule

module Ascon_StateUpdate_datapath(
input wire Clk,
input wire Reset,
input wire [3:0] RoundNr,
input wire [1:0] sel1,
input wire [1:0] sel2,
input wire [1:0] sel3,
input wire [1:0] sel4,
input wire [2:0] sel0,
input wire selout,
input wire [1:0] SelSbox,
input wire [2:0] SelDiff,
input wire Reg0En,
input wire Reg1En,
input wire Reg2En,
input wire Reg3En,
input wire Reg4En,
input wire RegOutEn,
input wire SboxEnable,
input wire ActivateGen,
input wire [3:0] GenSize,
input wire [127:0] IV,
input wire [127:0] Key,
input wire [127:0] DataIn,
output reg [127:0] DataOut
);
// Clock
// Reset (synchronous)
// Control signals
// biggest round is 12
// Data signals
// constants
parameter EXTRAIV = 64'h80800c0800000000;  // used in the initialization
parameter SEPCONSTANT = 64'h0000000000000001;
parameter ADCONSTANT = 64'h8000000000000000;  // Register signals
reg [63:0] SboxReg0In; reg [63:0] SboxReg1In; reg [63:0] SboxReg2In; reg [63:0] SboxReg3In; reg [63:0] SboxReg4In;
wire [63:0] SboxReg0Out; wire [63:0] SboxReg1Out; wire [63:0] SboxReg2Out; wire [63:0] SboxReg3Out; wire [63:0] SboxReg4Out;
wire [63:0] DiffReg0Out; wire [63:0] DiffReg1Out; wire [63:0] DiffReg2Out; wire [63:0] DiffReg3Out; wire [63:0] DiffReg4Out;
reg [127:0] RegOutIn; reg [127:0] RegOutOut;  // Internal signals on datapath
wire [15:0] Sbox0In; wire [15:0] Sbox1In; wire [15:0] Sbox2In; wire [15:0] Sbox3In; wire [15:0] Sbox4In;
wire [15:0] Sbox0Out; wire [15:0] Sbox1Out; wire [15:0] Sbox2Out; wire [15:0] Sbox3Out; wire [15:0] Sbox4Out;
reg [63:0] Diff1In; reg [63:0] Diff2In; reg [63:0] Diff3In; wire [63:0] DiffOut;
wire [63:0] XorReg01; reg [63:0] XorReg02; wire [63:0] XorReg11; reg [63:0] XorReg12;
reg [63:0] XorReg2; reg [63:0] XorReg31; reg [63:0] XorReg32; reg [63:0] XorReg4;
wire [127:0] OutSig0; reg [127:0] OutSig1;
  // declare and connect all sub entities
  Sbox_registers sboxregisters(
      Clk,
    Sbox0Out,
    Sbox1Out,
    Sbox2Out,
    Sbox3Out,
    Sbox4Out,
    Sbox0In,
    Sbox1In,
    Sbox2In,
    Sbox3In,
    Sbox4In,
    SboxReg0In,
    SboxReg1In,
    SboxReg2In,
    SboxReg3In,
    SboxReg4In,
    SboxReg0Out,
    SboxReg1Out,
    SboxReg2Out,
    SboxReg3Out,
    SboxReg4Out,
    SelSbox,
    SboxEnable,
    Reg0En,
    Reg1En,
    Reg2En,
    Reg3En,
    Reg4En);
  Sbox sbox(
      Sbox0In,
    Sbox1In,
    Sbox2In,
    Sbox3In,
    Sbox4In,
    RoundNr,
    Sbox0Out,
    Sbox1Out,
    Sbox2Out,
    Sbox3Out,
    Sbox4Out,
    SelSbox);
  FullDiffusionLayer difflayer(
      Diff1In,
    Diff2In,
    Diff3In,
    DiffOut);
  OutputGenerator outpgen(
      SboxReg0Out,
    SboxReg1Out,
    DataIn,
    GenSize,
    ActivateGen,
    XorReg01,
    XorReg11,
    OutSig0);
  // ActivateGen is a bit that indicates decryption or not
  //-------------------------------------------
  //---- Combinatorial logic for a round ------
  //-------------------------------------------
  always @(Diff1In, Diff2In, Diff3In, DiffOut, SboxReg0In, SboxReg1In, SboxReg2In, SboxReg3In, SboxReg4In, OutSig0, OutSig1, XorReg01, XorReg02, XorReg11, XorReg12, XorReg2, XorReg31, XorReg32, XorReg4, SboxReg0Out, SboxReg1Out, SboxReg2Out, SboxReg3Out, SboxReg4Out, Key, IV, RegOutIn, RegOutOut, sel0, sel1, sel2, sel3, sel4, selout) begin
    // Set correct inputs in registers
    if(sel0 == 3'b000) begin
      SboxReg0In <= DiffOut;
    end
    else if(sel0 == 3'b001) begin
      SboxReg0In <= EXTRAIV;
    end
    else if(sel0 == 3'b010) begin
      SboxReg0In <= XorReg01;
    end
    else if(sel0 == 3'b011) begin
      SboxReg0In <= XorReg02;
    end
    else begin
      SboxReg0In <= SboxReg0Out ^ ADCONSTANT;
    end
    if(sel1 == 2'b00) begin
      SboxReg1In <= DiffOut;
    end
    else if(sel1 == 2'b01) begin
      SboxReg1In <= Key[127:64];
    end
    else if(sel1 == 2'b10) begin
      SboxReg1In <= XorReg11;
    end
    else begin
      SboxReg1In <= XorReg12;
    end
    if(sel2 == 2'b00) begin
      SboxReg2In <= DiffOut;
    end
    else if(sel2 == 2'b01) begin
      SboxReg2In <= Key[63:0];
    end
    else begin
      SboxReg2In <= XorReg2;
    end
    if(sel3 == 2'b00) begin
      SboxReg3In <= DiffOut;
    end
    else if(sel3 == 2'b01) begin
      SboxReg3In <= IV[127:64];
    end
    else if(sel3 == 2'b10) begin
      SboxReg3In <= XorReg31;
    end
    else begin
      SboxReg3In <= XorReg32;
    end
    if(sel4 == 2'b00) begin
      SboxReg4In <= DiffOut;
    end
    else if(sel4 == 2'b01) begin
      SboxReg4In <= IV[63:0];
    end
    else if(sel4 == 2'b10) begin
      SboxReg4In <= XorReg4;
    end
    else begin
      SboxReg4In <= SboxReg4Out ^ SEPCONSTANT;
    end
    XorReg02 <= SboxReg0Out ^ Key[127:64];
    XorReg12 <= SboxReg1Out ^ Key[63:0];
    XorReg2 <= SboxReg2Out ^ Key[127:64];
    XorReg31 <= SboxReg3Out ^ Key[127:64];
    XorReg32 <= SboxReg3Out ^ Key[63:0];
    XorReg4 <= SboxReg4Out ^ Key[63:0];
    // Set output
    OutSig1[127:64] <= XorReg31;
    OutSig1[63:0] <= XorReg4;
    if(selout == 1'b0) begin
      RegOutIn <= OutSig0;
    end
    else begin
      RegOutIn <= OutSig1;
    end
    DataOut <= RegOutOut;
    if(SelDiff == 3'b000) begin
      Diff1In[63:64 - 19] <= SboxReg0Out[19 - 1:0];
      Diff1In[63 - 19:0] <= SboxReg0Out[63:19];
      Diff2In[63:64 - 28] <= SboxReg0Out[28 - 1:0];
      Diff2In[63 - 28:0] <= SboxReg0Out[63:28];
      Diff3In <= SboxReg0Out;
    end
    else if(SelDiff == 3'b001) begin
      Diff1In[63:64 - 61] <= SboxReg1Out[61 - 1:0];
      Diff1In[63 - 61:0] <= SboxReg1Out[63:61];
      Diff2In[63:64 - 39] <= SboxReg1Out[39 - 1:0];
      Diff2In[63 - 39:0] <= SboxReg1Out[63:39];
      Diff3In <= SboxReg1Out;
    end
    else if(SelDiff == 3'b010) begin
      Diff1In[63:64 - 1] <= SboxReg2Out[1 - 1:0];
      Diff1In[63 - 1:0] <= SboxReg2Out[63:1];
      Diff2In[63:64 - 6] <= SboxReg2Out[6 - 1:0];
      Diff2In[63 - 6:0] <= SboxReg2Out[63:6];
      Diff3In <= SboxReg2Out;
    end
    else if(SelDiff == 3'b011) begin
      Diff1In[63:64 - 10] <= SboxReg3Out[10 - 1:0];
      Diff1In[63 - 10:0] <= SboxReg3Out[63:10];
      Diff2In[63:64 - 17] <= SboxReg3Out[17 - 1:0];
      Diff2In[63 - 17:0] <= SboxReg3Out[63:17];
      Diff3In <= SboxReg3Out;
    end
    else begin
      Diff1In[63:64 - 7] <= SboxReg4Out[7 - 1:0];
      Diff1In[63 - 7:0] <= SboxReg4Out[63:7];
      Diff2In[63:64 - 41] <= SboxReg4Out[41 - 1:0];
      Diff2In[63 - 41:0] <= SboxReg4Out[63:41];
      Diff3In <= SboxReg4Out;
    end
  end
  //-------------------------------------------
  //---- The registers in the datapath --------
  //-------------------------------------------
  always @(posedge Clk, posedge Reset) begin
    if(Reset == 1'b1) begin
      // synchronous reset
      RegOutOut <= {128{1'b0}};
    end
    else begin
      if(RegOutEn == 1'b1) begin
        RegOutOut <= RegOutIn;
      end
    end
  end
endmodule

