module ElectronFpga_duo(
input wire clk_32M00,
input wire ps2_clk,
input wire ps2_data,
input wire ERST,
output wire [3:0] red,
output wire [3:0] green,
output wire [3:0] blue,
output wire vsync,
output wire hsync,
output wire audioL,
output wire audioR,
input wire casIn,
output wire casOut,
output wire LED1,
output wire LED2,
output wire SRAM_nOE,
output wire SRAM_nWE,
output wire SRAM_nCS,
output wire [20:0] SRAM_A,
inout wire [7:0] SRAM_D,
output wire ARDUINO_RESET,
input wire SW1,
output wire FLASH_CS,
output wire FLASH_SI,
output wire FLASH_CK,
input wire FLASH_SO,
input wire SDMISO,
output wire SDSS,
output wire SDCLK,
output wire SDMOSI,
input wire [1:0] DIP,
output wire [7:0] test,
input wire avr_RxD,
output wire avr_TxD
);
// Active low FLASH chip select
// Serial output to FLASH chip SI pin
// FLASH clock
// Serial input from FLASH chip SO pin
wire clock_16;
wire clock_24;
wire clock_32;
wire clock_33;
wire clock_40;
wire hard_reset_n;
reg powerup_reset_n;
reg [9:0] reset_counter;
wire [18:0] RAM_A;
wire [7:0] RAM_Din;
wire [7:0] RAM_Dout;
wire RAM_nWE;
wire RAM_nOE;
wire RAM_nCS;  //---------------------------------------------
// Bootstrap ROM Image from SPI FLASH into SRAM
//---------------------------------------------
// start address of user data in FLASH as obtained from bitmerge.py
// this is safely beyond the end of the bitstream
parameter user_address = 24'h060000;  // lenth of user data in FLASH = 256KB (16x 16K ROM) images
parameter user_length = 24'h040000;  // high when FLASH is being copied to SRAM, can be used by user as active high reset
wire bootstrap_busy;
  pll1 inst_pll1(
      // 32 MHz input clock
    .CLKIN_IN(clk_32M00),
    // the main system clock, and also the video clock in sRGB mode
    .CLK0_OUT(clock_16),
    // used as a 24.00MHz for the SAA5050 in Mode 7
    .CLK1_OUT(clock_24),
    // used as a output clock MIST scan doubler for the SAA5050 in Mode 7
    .CLK2_OUT(clock_32),
    // used as a video clock when the ULA is in 60Hz VGA Mode
    .CLK3_OUT(clock_40));
  dcm1 inst_dcm1(
      .CLKIN_IN(clk_32M00),
    // used as a video clock when the ULA is in 50Hz VGA Mode
    .CLKFX_OUT(clock_33));
  ElectronFpga_core #(
      .IncludeICEDebugger(true),
    .IncludeABRRegs(true),
    .IncludeJafaMode7(true))
  electron_core(
      .clk_16M00(clock_16),
    .clk_24M00(clock_24),
    .clk_32M00(clock_32),
    .clk_33M33(clock_33),
    .clk_40M00(clock_40),
    .hard_reset_n(hard_reset_n),
    .ps2_clk(ps2_clk),
    .ps2_data(ps2_data),
    .video_red(red),
    .video_green(green),
    .video_blue(blue),
    .video_vsync(vsync),
    .video_hsync(hsync),
    .audio_l(audioL),
    .audio_r(audioR),
    .ext_nOE(RAM_nOE),
    .ext_nWE(RAM_nWE),
    .ext_nCS(RAM_nCS),
    .ext_A(RAM_A),
    .ext_Dout(RAM_Dout),
    .ext_Din(RAM_Din),
    .SDMISO(SDMISO),
    .SDSS(SDSS),
    .SDCLK(SDCLK),
    .SDMOSI(SDMOSI),
    .caps_led(LED1),
    .motor_led(LED2),
    .cassette_in(casIn),
    .cassette_out(casOut),
    .vid_mode(DIP),
    .test(test),
    .avr_RxD(avr_RxD),
    .avr_TxD(avr_TxD),
    .cpu_addr(/* open */));
  //------------------------------------------------------
  // Power Up Reset Generation
  //------------------------------------------------------
  // Generate a reliable power up reset, as ERST on the Papilio doesn't do this
  always @(posedge clock_32) begin
    if((reset_counter[(9)] == 1'b0)) begin
      reset_counter <= reset_counter + 1;
    end
    powerup_reset_n <=  ~ERST & reset_counter[(9)];
  end
  // extend the version seen by the core to hold the 6502 reset during bootstrap
  assign hard_reset_n = powerup_reset_n &  ~bootstrap_busy;
  //------------------------------------------------------
  // Papilio Duo Misc
  //------------------------------------------------------
  // Follow convention for keeping Arduino reset
  assign ARDUINO_RESET = SW1;
  //------------------------------------------------------
  // BOOTSTRAP SPI FLASH to SRAM
  //------------------------------------------------------
  bootstrap #(
      .user_address(user_address),
    .user_length(user_length))
  inst_bootstrap(
      .clock(clock_16),
    .powerup_reset_n(powerup_reset_n),
    .bootstrap_busy(bootstrap_busy),
    .RAM_nOE(RAM_nOE),
    .RAM_nWE(RAM_nWE),
    .RAM_nCS(RAM_nCS),
    .RAM_A(RAM_A),
    .RAM_Din(RAM_Din),
    .RAM_Dout(RAM_Dout),
    .SRAM_nOE(SRAM_nOE),
    .SRAM_nWE(SRAM_nWE),
    .SRAM_nCS(SRAM_nCS),
    .SRAM_A(SRAM_A),
    .SRAM_D(SRAM_D),
    .FLASH_CS(FLASH_CS),
    .FLASH_SI(FLASH_SI),
    .FLASH_CK(FLASH_CK),
    .FLASH_SO(FLASH_SO));
endmodule

module Gatterschaltung(
