reg [6:0] ff_count;
  always @(posedge reset, posedge clk) begin
    if(reset == 1'b1) begin
      ff_count <= 7'b1000111 - delay;
    end else begin
      if(clkena == 1'b1) begin
        if(ff_count == 7'b1000111) begin
          // 71
          ff_count <= {7{1'b0}};
        end
        else begin
          ff_count <= ff_count + 1;
        end
      end
    end
  end
  assign stage = ff_count[1:0];
  //  0`3 ÅzÂ
  assign slot = ff_count[6:2];
    //  0`17 ÅzÂ
endmodule

