output wire wbs_ack,
input wire nes1_dat,
input wire nes2_dat,
output wire nes_lat,
output wire nes_clk,
output wire [7:0] nes1_data_out,
output wire [7:0] nes2_data_out
);
parameter [31:0] wb_size=16;
parameter [31:0] N=17;
//17 bit overflow 131k
// Syscon signals
// Wishbone signals
//nes data signals
reg read_ack;
reg write_ack;
wire [7:0] nes1_data_out_buf;
wire [7:0] nes2_data_out_buf;
  assign wbs_ack = read_ack | write_ack;
  //WBM-WRITE 
  always @(posedge gls_clk, posedge gls_reset) begin
    if(gls_reset == 1'b1) begin
      write_ack <= 1'b0;
      //sseg_edu_regs <= (others => (others => '0')) ;	--RESET REGISTERS HERE
    end else begin
      if(((wbs_strobe & wbs_write & wbs_cycle) == 1'b1)) begin
        //sseg_edu_regs(conv_integer(wbs_address(1 downto 0))) <= wbs_writedata; --WRITE TO REGISTERS HERE
        write_ack <= 1'b1;
      end
      else begin
        write_ack <= 1'b0;
      end
    end
  end
  //WBM-READ
  always @(posedge gls_clk, posedge gls_reset) begin
    if(gls_reset == 1'b1) begin
    end else begin
      wbs_readdata <= {nes2_data_out_buf,nes1_data_out_buf};
      //MASTER READ FROM REGISTERS HERE
      if((wbs_strobe == 1'b1 && wbs_write == 1'b0 && wbs_cycle == 1'b1)) begin
        read_ack <= 1'b1;
      end
      else begin
        read_ack <= 1'b0;
      end
    end
  end
  nes_ctl nes1(
      .clk(gls_clk),
    .reset(gls_reset),
    .nes_dat(nes1_dat),
    .nes_lat(nes_lat),
    .nes_clk(nes_clk),
    .nes_data_out(nes1_data_out_buf));
  nes_ctl nes2(
      .clk(gls_clk),
    .reset(gls_reset),
    .nes_dat(nes2_dat),
    .nes_lat(/* open */),
    .nes_clk(/* open */),
    .nes_data_out(nes2_data_out_buf));
  assign nes1_data_out = nes1_data_out_buf;
  assign nes2_data_out = nes2_data_out_buf;
endmodule

