module ALU(
input wire [4:0] alu_op,
input wire [31:0] a,
input wire [31:0] b,
output reg ovf,
output wire zero,
output wire [31:0] res
);
// inputs
// specifies alu operation to be performed (from CU in ID stage)
// operand 1
// operand 2
// outputs
// ovf of operation; to PSW
// zero when res is all 0s; to branch_circ
// result of the arit-logic operation on a and b
reg [31:0] res_i;  // ALU OPERATION
parameter ALUOP_SLL = 5'b00001;
parameter ALUOP_SRL = 5'b00010;
parameter ALUOP_SRA = 5'b00011;
parameter ALUOP_ADD = 5'b00100;
parameter ALUOP_ADDU = 5'b00101;
parameter ALUOP_SUB = 5'b00110;
parameter ALUOP_SUBU = 5'b00111;
parameter ALUOP_AND = 5'b01000;
parameter ALUOP_OR = 5'b01001;
parameter ALUOP_XOR = 5'b01010;
parameter ALUOP_SEQ = 5'b01011;
parameter ALUOP_SNE = 5'b01100;
parameter ALUOP_SLT = 5'b01101;
parameter ALUOP_SGT = 5'b01110;
parameter ALUOP_SLE = 5'b01111;
parameter ALUOP_SGE = 5'b10000;
parameter ALUOP_MOVS2I = 5'b00000;
parameter ALUOP_SLTU = 5'b10001;
parameter ALUOP_SGTU = 5'b10010;
parameter ALUOP_SGEU = 5'b10011;
  assign res = res_i;
  assign zero = res_i == 32'h00000000 ? 1'b1 : 1'b0;
  always @(alu_op, a, b) begin : P1
  // complete all the requested functions (20 in total, some are shared b/n instructions)
    reg [32:0] tmp;
    ovf <= 1'b0;
    case(alu_op)
    ALUOP_SLL : begin
      res_i <= (a) << (b[4:0]);
    end
    ALUOP_SRL : begin
      res_i <= (a) >> (b[4:0]);
    end
    ALUOP_SRA : begin
      // the shift_right func from numeric_std with a signed number as arg will do SRA
      res_i <= (a) >> (b[4:0]);
    end
    ALUOP_ADD : begin
      tmp = (a) + (b);
      res_i <= tmp[31:0];
      ovf <= ( ~a[31] &  ~b[31] & tmp[31]) | (a[31] & b[31] &  ~tmp[31]);
    end
    ALUOP_ADDU : begin
      tmp = (a) + (b);
      res_i <= tmp[31:0];
    end
    ALUOP_SUB : begin
      tmp = (a) - (b);
      res_i <= tmp[31:0];
      // "ovf = 1 when operands have different sign and result has different sign wrt first operand"
      if(((a[31] != b[31]) && (tmp[31] != a[31]))) begin
        ovf <= 1'b1;
      end
      else begin
        ovf <= 1'b0;
      end
    end
    ALUOP_SUBU : begin
      tmp = (a) - (b);
      res_i <= tmp[31:0];
    end
    ALUOP_AND : begin
      res_i <= a & b;
    end
    ALUOP_OR : begin
      res_i <= a | b;
    end
    ALUOP_XOR : begin
      res_i <= a ^ b;
    end
    ALUOP_SEQ : begin
      // if a = b then res = 1
      if(((a) == (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SNE : begin
      // if a /= b then res = 1
      if(((a) != (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SLT : begin
      // if a < b then res = 1
      if(((a) < (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SGT : begin
      // if a > b then res = 1
      if(((a) > (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SLE : begin
      // if a <= b then res = 1
      if(((a) <= (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SGE : begin
      // if a >= b then res = 1
      if(((a) >= (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_MOVS2I : begin
      res_i <= a;
    end
    ALUOP_SLTU : begin
      // if a < b then res = 1 (a, b unsigned)
      if(((a) < (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SGTU : begin
      // if a > b then res = 1 (a, b unsigned)
      if(((a) > (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    ALUOP_SGEU : begin
      // if a >= b then res = 1 (a, b unsigned)
      if(((a) >= (b))) begin
        res_i <= {28'h0000000,4'b0001};
      end
      else begin
        res_i <= 32'h00000000;
      end
    end
    default : begin
      res_i <= {32{1'b0}};
      // design decision, to avoid inferred latches during synthesis
    end
    endcase
  end
endmodule

module RAT_Basys3_wrapper(
