module RS232top(
input wire Reset,
input wire Clk,
input wire [7:0] Data_in,
input wire Valid_D,
output reg Ack_in,
output wire TX_RDY,
output wire TD,
input wire RD,
output wire [7:0] Data_out,
input wire Data_read,
output wire Full,
output wire Empty
);
// Low_level-active asynchronous reset
// System clock (20MHz), rising edge used
// Data to be sent
// Handshake signal
// from guest system, low when data is valid
// ACK for data received, low once data
// has been stored
// System ready to transmit
// RS232 Transmission line
// RS232 Reception line
// Received data
// Data read for guest system
// Full internal memory
// Empty internal memory
//----------------------------------------------------------------------
// Components for Transmitter Block
//----------------------------------------------------------------------
//----------------------------------------------------------------------
// Components for Receiver Block
//----------------------------------------------------------------------
//----------------------------------------------------------------------
// Internal Signals
//----------------------------------------------------------------------
reg [7:0] Data_FF;
reg StartTX;  // start signal for transmitter
reg LineRD_in;  // internal RX line
wire Valid_out;  // valid bit @ receiver
wire Code_out;  // bit @ receiver output
wire sinit;  // fifo reset
wire [7:0] Fifo_in;
wire Fifo_write;
wire TX_RDY_i;
  // RTL
  RS232_TX Transmitter(
      .Clk(Clk),
    .Reset(Reset),
    .Start(StartTX),
    .Data(Data_FF),
    .EOT(TX_RDY_i),
    .TX(TD));
  RS232_RX Receiver(
      .Clk(Clk),
    .Reset(Reset),
    .LineRD_in(LineRD_in),
    .Valid_out(Valid_out),
    .Code_out(Code_out),
    .Store_out(Fifo_write));
  ShiftRegister Shift(
      .Reset(Reset),
    .Clk(Clk),
    .Enable(Valid_Out),
    .D(Code_Out),
    .Q(Fifo_in));
  assign sinit =  ~reset;
  fifo Internal_memory(
      .clk(clk),
    .rst(sinit),
    .din(Fifo_in),
    .wr_en(Fifo_write),
    .rd_en(Data_read),
    .dout(Data_out),
    .full(Full),
    .empty(Empty));
  // purpose: Clocking process for input protocol
  always @(posedge Clk, posedge Reset) begin
    if(Reset == 1'b0) begin
      // asynchronous reset (active low)
      Data_FF <= {8{1'b0}};
      LineRD_in <= 1'b1;
      Ack_in <= 1'b1;
    end else begin
      // rising edge clock
      LineRD_in <= RD;
      if(Valid_D == 1'b0 && TX_RDY_i == 1'b1) begin
        Data_FF <= Data_in;
        Ack_in <= 1'b0;
        StartTX <= 1'b1;
      end
      else begin
        Ack_in <= 1'b1;
        StartTX <= 1'b0;
      end
    end
  end
  assign TX_RDY = TX_RDY_i;
endmodule

module vga_sync_reset(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
// The default values are for 640x480
parameter [31:0] H_SIZE=640;
parameter [31:0] H_FRONT_DELAY=16;
parameter [31:0] H_BACK_DELAY=48;
parameter [31:0] H_RETRACE_DELAY=96;
parameter [31:0] V_SIZE=480;
parameter [31:0] V_FRONT_DELAY=10;
parameter [31:0] V_BACK_DELAY=33;
parameter [31:0] V_RETRACE_DELAY=2;
// sync counters
reg [9:0] v_count_reg;
reg [9:0] h_count_reg;
  // registers
  always @(posedge clk) begin
    if(rst == 1'b0) begin
      v_count_reg <= {10{1'b0}};
      h_count_reg <= {10{1'b0}};
      vsync <= 1'b1;
      hsync <= 1'b1;
      active <= 1'b0;
    end
    else begin
      // Count the lines and rows      
      if(h_count_reg == (H_SIZE + H_FRONT_DELAY + H_BACK_DELAY + H_RETRACE_DELAY - 1)) begin
        h_count_reg <= {10{1'b0}};
        if(v_count_reg == (V_SIZE + V_FRONT_DELAY + V_BACK_DELAY + V_RETRACE_DELAY - 1)) begin
          v_count_reg <= {10{1'b0}};
        end
        else begin
          v_count_reg <= v_count_reg + 1;
        end
      end
      else begin
        h_count_reg <= h_count_reg + 1;
      end
      if(v_count_reg < V_SIZE && h_count_reg < H_SIZE) begin
        active <= 1'b1;
      end
      else begin
        active <= 1'b0;
      end
      if(h_count_reg > (H_SIZE + H_FRONT_DELAY) && h_count_reg <= (H_SIZE + H_FRONT_DELAY + H_RETRACE_DELAY)) begin
        hsync <= 1'b0;
      end
      else begin
        hsync <= 1'b1;
      end
      if(v_count_reg >= (V_SIZE + V_FRONT_DELAY) && v_count_reg < (V_SIZE + V_FRONT_DELAY + V_RETRACE_DELAY)) begin
        vsync <= 1'b0;
      end
      else begin
        vsync <= 1'b1;
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

