module counter(
input wire clk,
input wire btn,
output wire [7:0] seg,
output wire [3:0] an
);
reg [38:0] cnt;
wire [15:0] data;
parameter en = 4'b1111;
reg [16:0] base; reg [16:0] base_new; reg [16:0] hi; reg [16:0] hi_new; reg [16:0] sp;
reg [15:0] offset; reg [15:0] offset_new;
wire ref; wire vco;
wire [15:0] phase;
  driveseg u1(
      .data(data),
    .seg_c(seg),
    .seg_a(an),
    .en(en),
    .clk(clk),
    .rst(btn));
  phasedet u2(
      .ref(ref),
    .vco(vco),
    .mclk(clk),
    .rst(btn),
    .phase(phase));
  //data <= std_logic_vector(cnt(38 downto 23));
  //data <= std_logic_vector(phase);
  assign data = sp[15:0];
  always @(posedge clk, posedge btn) begin : P2
    reg old;
    if(btn == 1'b1) begin
      cnt <= {39{1'b0}};
      base <= {17{1'b0}};
      hi <= {17{1'b0}};
      offset <= {16{1'b0}};
      old = 1'b0;
    end else begin
      cnt <= cnt + 1'b1;
      base <= base_new;
      hi <= hi_new;
      if(old == 1'b0 && ref == 1'b1) begin
        offset <= offset_new;
      end
      old = ref;
    end
  end
  assign ref = base[14];
  assign vco = hi[14];
  always @(base, hi, offset, phase) begin : P1
    reg [16:0] base_next, hi_next;
    reg [15:0] offset_next;
    reg [16:0] setpoint;
    base_next = base + 1'b1;
    hi_next = hi + 1'b1;
    offset_next = offset;
    if(base == 16'hFFF0) begin
      base_next = {1{1'b0}};
    end
    offset_next = offset + phase;
    // Use 'offset' and not 'offset_next' to improve stability
    setpoint = phase[15:0] + offset[15:4] + 17'b01111111111000000;
    sp <= setpoint;
    if(hi == setpoint) begin
      hi_next = {1{1'b0}};
    end
    base_new <= base_next;
    hi_new <= hi_next;
    offset_new <= offset_next;
  end
endmodule

