module bshift(
input wire [G_W - 1:0] ii,
input wire [G_LOG2_W - 1:0] rtr,
output wire [G_W - 1:0] oo
);
parameter [31:0] G_W=16;
parameter [31:0] G_LOG2_W=4;
parameter [31:0] G_LEFT=1;
parameter [31:0] G_ROTATE=1;
parameter [31:0] G_SHIFT1=0;
//! Shift '1' instead of '0'. Applicable only for Shift operation.
parameter ZEROS = 1'b0;
parameter ONES = 1'b1;
wire [G_W - 1:0] itemp[0:G_LOG2_W];
  assign itemp[0] = ii;
  generate if (G_ROTATE == 1) begin: ROTATOR_GEN
      generate if (G_LEFT == 1) begin: LEFT_SHIFT_GEN
          genvar k;
      generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
              assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {itemp[k - 1][G_W - (2 ** (k - 1)) - 1:0],itemp[k - 1][G_W - 1:G_W - (2 ** (k - 1))]};
      end
      endgenerate
    end
    endgenerate
    generate if (G_LEFT == 0) begin: RIGHT_SHIFT_GEN
          genvar k;
      generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
              assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {itemp[k - 1][(2 ** (k - 1)) - 1:0],itemp[k - 1][G_W - 1:2 ** (k - 1)]};
      end
      endgenerate
    end
    endgenerate
  end
  endgenerate
  generate if (G_ROTATE == 0) begin: SHIFTER_GEN
      generate if (G_LEFT == 1) begin: LEFT_SHIFT_GEN
          generate if (G_SHIFT1 == 0) begin: SHIFT0_GEN
              genvar k;
        generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
                  assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {itemp[k - 1][G_W - (2 ** (k - 1)) - 1:0],ZEROS[G_W - 1:G_W - (2 ** (k - 1))]};
        end
        endgenerate
      end
      endgenerate
      generate if (G_SHIFT1 == 1) begin: SHIFT1_GEN
              genvar k;
        generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
                  assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {itemp[k - 1][G_W - (2 ** (k - 1)) - 1:0],ONES[G_W - 1:G_W - (2 ** (k - 1))]};
        end
        endgenerate
      end
      endgenerate
    end
    endgenerate
    generate if (G_LEFT == 0) begin: RIGHT_SHIFT_GEN
          generate if (G_SHIFT1 == 0) begin: SHIFT0_GEN
              genvar k;
        generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
                  assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {ZEROS[(2 ** (k - 1)) - 1:0],itemp[k - 1][G_W - 1:2 ** (k - 1)]};
        end
        endgenerate
      end
      endgenerate
      generate if (G_SHIFT1 == 1) begin: SHIFT1_GEN
              genvar k;
        generate for (k=1; k <= G_LOG2_W; k = k + 1) begin: barrel_gen
                  assign itemp[k] = (rtr[k - 1] == 1'b0) ? itemp[k - 1] : {ONES[(2 ** (k - 1)) - 1:0],itemp[k - 1][G_W - 1:2 ** (k - 1)]};
        end
        endgenerate
      end
      endgenerate
    end
    endgenerate
  end
  endgenerate
  assign oo = itemp[G_LOG2_W];
endmodule

