module ChannelBond(
input wire PixelClk,
input wire [9:0] pDataInRaw,
input wire pMeVld,
input wire [1:0] pOtherChVld,
input wire [1:0] pOtherChRdy,
output wire [9:0] pDataInBnd,
output wire pMeRdy
);
parameter kFIFO_Depth = 32;
reg [9:0] pFIFO[0:kFIFO_Depth - 1];
reg [9:0] pDataFIFO;
reg [31:0] pRdA; reg [31:0] pWrA;
reg pRdEn;
wire pAllVld; reg pAllVld_q; reg pMeRdy_int;
reg pBlnkBgnFlag; reg pTokenFlag; reg pTokenFlag_q; reg pAllVldBgnFlag;
  assign pAllVld = pMeVld & pOtherChVld[0] & pOtherChVld[1];
  assign pDataInBnd = pDataFIFO;
  // raw data with skew removed
  assign pMeRdy = pMeRdy_int;
  // data is de-skewed and valid
  // The process below should result in a dual-port distributed RAM with registered output
  always @(posedge PixelClk) begin
    if((pAllVld == 1'b1)) begin
      // begin writing in FIFO as soon as all the channels have valid data
      pFIFO[pWrA] <= pDataInRaw;
    end
    pDataFIFO <= pFIFO[pRdA];
    // register FIFO output
  end
  // FIFO address counters
  always @(posedge PixelClk) begin
    if((pAllVld == 1'b1)) begin
      pWrA <= pWrA + 1;
    end
    else begin
      // when invalid data, go back to the beginning
      pWrA <= 0;
    end
  end
  always @(posedge PixelClk) begin
    if((pAllVld == 1'b0)) begin
      pRdA <= 0;
    end
    else if((pRdEn == 1'b1)) begin
      pRdA <= pRdA + 1;
    end
  end
  always @(posedge PixelClk) begin
    pAllVld_q <= pAllVld;
    pAllVldBgnFlag <=  ~pAllVld_q & pAllVld;
    // this flag used below delays enabling read, thus making sure data is written first before being read
  end
  //-----------------------------------------------------------------------------
  // Channel bonding is done here:
  // 1 When all the channels have valid data (ie. alignment lock), FIFO is flow-through
  // 2 When marker is found on this channel, FIFO read is paused, thus holding data
  // 3 When all channels report the marker, FIFO read begins again, thus syncing markers  
  //-----------------------------------------------------------------------------
  always @(posedge PixelClk) begin
    if((pAllVld == 1'b0)) begin
      pRdEn <= 1'b0;
    end
    else if((pAllVldBgnFlag == 1'b1 || (pMeRdy_int == 1'b1 && pOtherChRdy == 2'b11))) begin
      pRdEn <= 1'b1;
    end
    else if((pBlnkBgnFlag == 1'b1 && !(pMeRdy_int == 1'b1 && pOtherChRdy == 2'b11))) begin
      pRdEn <= 1'b0;
    end
  end
  // Detect blanking period begin
  always @(posedge PixelClk) begin
    if((pRdEn == 1'b0 || pDataFIFO == kCtlTkn0 || pDataFIFO == kCtlTkn1 || pDataFIFO == kCtlTkn2 || pDataFIFO == kCtlTkn3)) begin
      pTokenFlag <= 1'b1;
      //token flag activates on invalid data, which avoids a BlnkBgn pulse if the valid signal goes up in the middle of a blanking period
    end
    else begin
      pTokenFlag <= 1'b0;
    end
    pTokenFlag_q <= pTokenFlag;
    pBlnkBgnFlag <=  ~pTokenFlag_q & pTokenFlag;
  end
  // Ready signal when marker is received
  always @(posedge PixelClk) begin
    if((pAllVld == 1'b0)) begin
      // if not all channels are valid, we are not ready either
      pMeRdy_int <= 1'b0;
    end
    else if((pBlnkBgnFlag == 1'b1)) begin
