module dp_lnadd(
input wire sysclk,
input wire reset,
input wire enable,
input wire [64:1] aaman,
input wire [11:1] aaexp,
input wire [64:1] bbman,
input wire [11:1] bbexp,
output wire [64:1] ccman,
output wire [11:1] ccexp
);
parameter [31:0] speed=1;
parameter [31:0] synthesize=1;
reg [64:1] aamanff; reg [64:1] bbmanff;
reg [11:1] aaexpff; reg [11:1] bbexpff;
reg [64:1] manleftff; reg [64:1] manrightff;
reg [64:1] aluleftff; reg [64:1] alurightff;
reg [13:1] expbaseff[3 + 2 * speed:1];
reg [5:1] shiftff;
wire [12:1] subexpone; wire [12:1] subexptwo;
wire switch;
wire [64:1] shiftleftnode; wire [64:1] shiftrightnode;
wire [64:1] alunode;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 64; k = k + 1) begin
        aamanff[k] <= 1'b0;
        bbmanff[k] <= 1'b0;
      end
      for (k=1; k <= 11; k = k + 1) begin
        aaexpff[k] <= 1'b0;
        bbexpff[k] <= 1'b0;
      end
      for (k=1; k <= 64; k = k + 1) begin
        manleftff[k] <= 1'b0;
        manrightff[k] <= 1'b0;
        aluleftff[k] <= 1'b0;
        alurightff[k] <= 1'b0;
      end
      for (k=1; k <= 11; k = k + 1) begin
        for (j=1; j <= 3 + speed; j = j + 1) begin
          expbaseff[j][k] <= 1'b0;
        end
      end
      shiftff <= 5'b00000;
    end else begin
      if((enable == 1'b1)) begin
        //*** LEVEL 1 ***
        aamanff <= aaman;
        bbmanff <= bbman;
        aaexpff <= aaexp;
        bbexpff <= bbexp;
        //*** LEVEL 2 ***
        for (k=1; k <= 64; k = k + 1) begin
          manleftff[k] <= (aamanff[k] &  ~(switch)) | (bbmanff[k] & switch);
          manrightff[k] <= (bbmanff[k] &  ~(switch)) | (aamanff[k] & switch);
        end
        for (k=1; k <= 11; k = k + 1) begin
          expbaseff[1][k] <= (aaexpff[k] &  ~(switch)) | (bbexpff[k] & switch);
        end
        for (k=2; k <= 3 + 2 * speed; k = k + 1) begin
          expbaseff[k][11:1] <= expbaseff[k - 1][11:1];
          // level 3 to 4/6
        end
        for (k=1; k <= 5; k = k + 1) begin
          shiftff[k] <= (subexpone[k] &  ~(switch)) | (subexptwo[k] & switch);
        end
        aluleftff <= shiftleftnode;
        alurightff <= shiftrightnode;
      end
    end
  end
  assign subexpone = ({1'b0,aaexpff}) - ({1'b0,bbexpff});
  assign subexptwo = ({1'b0,bbexpff}) - ({1'b0,aaexpff});
  assign switch = subexpone[12];
  generate if ((speed == 0)) begin: gsa
      dp_rsft64x5 shifter(
          .inbus(manrightff),
      .shift(shiftff),
      .outbus(shiftrightnode));
    assign shiftleftnode = manleftff;
  end
  endgenerate
  generate if ((speed == 1)) begin: gsb
      dp_rsft64x5pipe shifter(
          .sysclk(sysclk),
      .reset(reset),
      .enable(enable),
      .inbus(manrightff),
      .shift(shiftff),
      .outbus(shiftrightnode));
    fp_del #(
          .width(64),
      .pipes(1))
    sftdel(
          .sysclk(sysclk),
      .reset(reset),
      .enable(enable),
      .aa(manleftff),
      .cc(shiftleftnode));
  end
  endgenerate
  // level 3+speed in, level 4+2*speed out
  dp_fxadd #(
      .width(64),
    .pipes(speed + 1),
    .synthesize(synthesize))
  adder(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .aa(aluleftff),
    .bb(alurightff),
    .carryin(1'b0),
    .cc(alunode));
  //*** OUTPUTS ***
  assign ccman = alunode;
  assign ccexp = expbaseff[3 + 2 * speed][11:1];
endmodule

