module XOR_MIN_8b(
input wire [31:0] INPUT_1,
input wire [31:0] INPUT_2,
output reg [31:0] OUTPUT_1
);
  //-----------------------------------------------------------------------
  always @(INPUT_1, INPUT_2) begin : P1
    reg [7:0] rTemp1;
    reg [7:0] rTemp2;
    reg [7:0] rTemp3;
    reg [7:0] rTemp4;
    // ON TRAITE LE PREMIER MOT DE 8 BITS CONTENU DANS LES OPERANDES
    if(((INPUT_1[6:0]) < (INPUT_2[6:0]))) begin
      rTemp1[6:0] = INPUT_1[6:0];
    end
    else begin
      rTemp1[6:0] = INPUT_2[6:0];
    end
    rTemp1[7] = INPUT_1[7] ^ INPUT_2[7];
    // ON TRAITE LE SECOND MOT DE 8 BITS CONTENU DANS LES OPERANDES
    if(((INPUT_1[14:8]) < (INPUT_2[14:8]))) begin
      rTemp2[6:0] = INPUT_1[14:8];
    end
    else begin
      rTemp2[6:0] = INPUT_2[14:8];
    end
    rTemp2[7] = INPUT_1[15] ^ INPUT_2[15];
    // ON TRAITE LE TROISIEME MOT DE 8 BITS CONTENU DANS LES OPERANDES
    if(((INPUT_1[22:16]) < (INPUT_2[22:16]))) begin
      rTemp3[6:0] = INPUT_1[22:16];
    end
    else begin
      rTemp3[6:0] = INPUT_2[22:16];
    end
    rTemp3[7] = INPUT_1[23] ^ INPUT_2[23];
    // ON TRAITE LE QUATRIEME MOT DE 8 BITS CONTENU DANS LES OPERANDES
    if(((INPUT_1[30:24]) < (INPUT_2[30:24]))) begin
      rTemp4[6:0] = INPUT_1[30:24];
    end
    else begin
      rTemp4[6:0] = INPUT_2[30:24];
    end
    rTemp4[7] = INPUT_1[31] ^ INPUT_2[31];
    // ON REGROUPE LES 4 MOTS AFIN DE RECONSTITUER LE RESULTAT SUR 32 BITS
    OUTPUT_1 <= {rTemp4,rTemp3,rTemp2,rTemp1};
  end
    //-----------------------------------------------------------------------
endmodule

