  assign pc_mux = op_code_signal == 5'b10100 || op_code_signal == 5'b10101 || op_code_signal == 5'b10110 || op_code_signal == 5'b11000 || op_code_signal == 5'b11001 || op_code_signal == 5'b11010 || op_code_signal == 5'b01100 || op_code_signal == 5'b01101 ? 2'b01 : op_code_signal == 5'b11110 ? 2'b10 : op_code_signal == 5'b11111 ? 2'b11 : 2'b00;
