module ALU_ROM(
input wire [15:0] inst,
output reg [output_length - 1:0] ALU_ROM_Out
);
parameter [31:0] output_length=24;
// output length n
// input instruction
//
reg isShift = 1'b0;
reg [2:0] alu_opcode = 1'b0;
  always @(ALL) begin
    isShift <= inst[3];
    alu_opcode <= inst[2:0];
    // ALU operations
    if((isShift == 1'b0)) begin
      case(alu_opcode)
            // ADD (0)  -- refering to inst 3-0 bits
      3'b000 : begin
        ALU_ROM_Out <= {1'b0,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b11,1'b0,4'b1001,2'b00,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Control (bits 4-0), 5-bit
        // ADC (1)
      end
      3'b001 : begin
        ALU_ROM_Out <= {1'b0,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b11,1'b0,4'b1001,2'b01,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Stage Control 
        // SUB (2)
      end
      3'b010 : begin
        ALU_ROM_Out <= {1'b1,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b11,1'b0,4'b0110,2'b10,1'b0,1'b0,1'b0,2'b11,2'b01};
        // Decode Stage Control
        // SBC (3)
      end
      3'b011 : begin
        ALU_ROM_Out <= {1'b1,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b11,1'b0,4'b0110,2'b11,1'b0,1'b0,1'b0,2'b11,2'b01};
        // Decode Stage Control
        // AND (4)
      end
      3'b100 : begin
        ALU_ROM_Out <= {1'b0,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b1,4'b1110,2'b00,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Stage Control
        // OR (5)
      end
      3'b101 : begin
        ALU_ROM_Out <= {1'b0,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b1,4'b1011,2'b00,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Stage Control
        // XOR (6)
      end
      3'b110 : begin
        ALU_ROM_Out <= {1'b0,2'b11,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b1,4'b1001,2'b00,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Stage Control
        // NOT (7)
      end
      3'b111 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b1,4'b0000,2'b00,1'b0,1'b0,1'b0,2'b00,2'b01};
        // Decode Stage Control
        // ERROR
      end
      default : begin
        ALU_ROM_Out <= {((output_length - 1)-(0)+1){1'bX}};
      end
      endcase
      // Shift operations
    end
    else if((isShift == 1'b1)) begin
      case(alu_opcode)
            // SL (8)         
      3'b000 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b0,4'b1000,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // SRL (9)         
      end
      3'b001 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b0,4'b1001,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // SRA (10)  
      end
      3'b010 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b00,1'b0,4'b1010,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // RRA (14)   -- **** comment: they're weird  
      end
      3'b110 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b10,1'b0,4'b1110,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // RR  (13)   
      end
      3'b101 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b10,1'b0,4'b1101,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // RL (12)       
      end
      3'b100 : begin
        ALU_ROM_Out <= {1'b0,2'b10,1'b1,1'b0,1'b0,1'b0,1'b0,2'b10,1'b0,4'b1100,2'b00,1'b1,1'b0,1'b0,2'b00,2'b00};
        // Decode Stage
        // ERROR
      end
      default : begin
        ALU_ROM_Out <= {((output_length - 1)-(0)+1){1'bX}};
      end
      endcase
    end
  end
endmodule

module spike_filter(
input wire clock,
input wire pin_in,
output reg pin_out
);
parameter [31:0] g_stable_time=8;
reg pin_c;
reg [31:0] cnt = (g_stable_time - 1) / 2;
  always @(posedge clock) begin
    pin_c <= pin_in;
    if(pin_c == 1'b0) begin
      if(cnt == 0) begin
        pin_out <= 1'b0;
      end
      else begin
        cnt <= cnt - 1;
      end
    end
    else begin
      if(cnt == (g_stable_time - 1)) begin
        pin_out <= 1'b1;
      end
      else begin
        cnt <= cnt + 1;
      end
    end
  end
endmodule

module ALU(
input wire [7:0] alu_input_1,
input wire [7:0] alu_input_2,
output reg [7:0] alu_output,
input wire [7:0] alu_command,
inout reg busy,
input wire clk
);
// first ALU input ( 8 bit)
// second ALU input ( 8 bit)
// output signal of ALU ( 8 bit)
// command for ALU
// one bit signal that tells us if ALU is busy or not
// clock input
  always @(posedge clk) begin
    if(alu_command == 8'b00000001) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 + alu_input_2;
      // addition of input 
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000010) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 - alu_input_2;
      // substraction of input signals
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000011) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 & alu_input_2;
      // AND operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000100) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 | alu_input_2;
      // OR operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000101) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 ^ alu_input_2;
      // XOR operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000110) begin
      busy <= 1'b1;
      alu_output <=  ~alu_input_1;
      // NOT operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000111) begin
      busy <= 1'b1;
      alu_output <= (alu_input_1) >> 1;
      //shift right
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00001000) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 + alu_input_1;
      //shift left
      busy <= 1'b0;
    end
  end
endmodule

