module led_top(
input wire p_clk_50Mhz,
input wire [1:0] p_button,
output wire p_led_out
);
wire s_reset;
reg [15:0] s_clk_50Mhz_cnt;
reg s_clk_1Khz = 1'b0;
reg [15:0] s_clk_1Khz_cnt;
  // reset 신호 생성 
  // 
  assign s_reset =  ~p_button[0];
  // 분주 타이머 
  //
  always @(posedge s_reset, posedge p_clk_50Mhz) begin
    if(s_reset == 1'b1) begin
      s_clk_50Mhz_cnt <= {16{1'b0}};
    end
    else begin
      if(s_clk_50Mhz_cnt == (50000 - 1)) begin
        s_clk_1Khz <=  ~s_clk_1Khz;
        s_clk_50Mhz_cnt <= {16{1'b0}};
      end
      else begin
        s_clk_50Mhz_cnt <= s_clk_50Mhz_cnt + 1;
      end
    end
  end
  always @(posedge s_reset, posedge s_clk_1Khz) begin
    if(s_reset == 1'b1) begin
      s_clk_1Khz_cnt <= {16{1'b0}};
    end
    else begin
      s_clk_1Khz_cnt <= s_clk_1Khz_cnt + 1;
    end
  end
  assign p_led_out = s_clk_1Khz_cnt[7];
endmodule

