module rotKey(
input wire clk,
input wire rotA,
input wire rotB,
input wire rotPush,
output wire rotRightEvent,
output wire rotLeftEvent,
output wire rotPushEvent
);
parameter [31:0] CNT=5000;
// 30 ms at 50 MHz
wire rotA_d;
wire rotB_d;
wire rotA_rise;
wire rotB_rise;
  debounce #(
      .CNT(CNT))
  deb_rotA(
      .clk(clk),
    .input(rotA),
