reg [TAP2:1] reg = 1'b1;
  always @(posedge clk_i) begin
    if(rst_i == 1'b1) begin
      reg <= {((TAP2)-(1)+1){1'b1}};
    end
    else if(ce_i == 1'b1) begin
      reg <= {reg[TAP2 - 1:1],reg[TAP2] ^ reg[TAP1]};
    end
  end
  assign d_o = reg[1];
endmodule

module Blink(
input wire clk_i,
input wire rst_i,
output wire blink_o
);
parameter [31:0] FREQUENCY=25e6;
parameter [31:0] SECONDS=1;
parameter DIV = FREQUENCY * SECONDS - 1;
reg blink;
  always @(posedge clk_i) begin : P1
    reg [31:0] cnt = 0;
    if(rst_i == 1'b1) begin
      cnt = 0;
      blink <= 1'b0;
    end
    else begin
      if(cnt == DIV) begin
        cnt = 0;
        blink <=  ~(blink);
      end
      else begin
        cnt = cnt + 1;
      end
    end
  end
  assign blink_o = blink;
endmodule

