//-----------------------------------------------------------------------------
reg [31:0] crc; wire [31:0] nxtCrc;
  // ARCHITECTURE rtl
  assign nxtCrc[0] = crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[1] = crc[25] ^ crc[31] ^ iData[0] ^ iData[6] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[2] = crc[26] ^ iData[5] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[3] = crc[27] ^ iData[4] ^ crc[26] ^ iData[5] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6];
  assign nxtCrc[4] = crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[5] = crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[6] = crc[30] ^ iData[1] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[26] ^ iData[5] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6];
  assign nxtCrc[7] = crc[31] ^ iData[0] ^ crc[29] ^ iData[2] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5] ^ crc[24] ^ iData[7];
  assign nxtCrc[8] = crc[0] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[25] ^ iData[6] ^ crc[24] ^ iData[7];
  assign nxtCrc[9] = crc[1] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[26] ^ iData[5] ^ crc[25] ^ iData[6];
  assign nxtCrc[10] = crc[2] ^ crc[29] ^ iData[2] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5] ^ crc[24] ^ iData[7];
  assign nxtCrc[11] = crc[3] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[25] ^ iData[6] ^ crc[24] ^ iData[7];
  assign nxtCrc[12] = crc[4] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[26] ^ iData[5] ^ crc[25] ^ iData[6] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[13] = crc[5] ^ crc[30] ^ iData[1] ^ crc[29] ^ iData[2] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6];
  assign nxtCrc[14] = crc[6] ^ crc[31] ^ iData[0] ^ crc[30] ^ iData[1] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5];
  assign nxtCrc[15] = crc[7] ^ crc[31] ^ iData[0] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4];
  assign nxtCrc[16] = crc[8] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[24] ^ iData[7];
  assign nxtCrc[17] = crc[9] ^ crc[30] ^ iData[1] ^ crc[29] ^ iData[2] ^ crc[25] ^ iData[6];
  assign nxtCrc[18] = crc[10] ^ crc[31] ^ iData[0] ^ crc[30] ^ iData[1] ^ crc[26] ^ iData[5];
  assign nxtCrc[19] = crc[11] ^ crc[31] ^ iData[0] ^ crc[27] ^ iData[4];
  assign nxtCrc[20] = crc[12] ^ crc[28] ^ iData[3];
  assign nxtCrc[21] = crc[13] ^ crc[29] ^ iData[2];
  assign nxtCrc[22] = crc[14] ^ crc[24] ^ iData[7];
  assign nxtCrc[23] = crc[15] ^ crc[25] ^ iData[6] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[24] = crc[16] ^ crc[26] ^ iData[5] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6];
  assign nxtCrc[25] = crc[17] ^ crc[27] ^ iData[4] ^ crc[26] ^ iData[5];
  assign nxtCrc[26] = crc[18] ^ crc[28] ^ iData[3] ^ crc[27] ^ iData[4] ^ crc[24] ^ crc[30] ^ iData[1] ^ iData[7];
  assign nxtCrc[27] = crc[19] ^ crc[29] ^ iData[2] ^ crc[28] ^ iData[3] ^ crc[25] ^ crc[31] ^ iData[0] ^ iData[6];
  assign nxtCrc[28] = crc[20] ^ crc[30] ^ iData[1] ^ crc[29] ^ iData[2] ^ crc[26] ^ iData[5];
  assign nxtCrc[29] = crc[21] ^ crc[31] ^ iData[0] ^ crc[30] ^ iData[1] ^ crc[27] ^ iData[4];
  assign nxtCrc[30] = crc[22] ^ crc[31] ^ iData[0] ^ crc[28] ^ iData[3];
  assign nxtCrc[31] = crc[23] ^ crc[29] ^ iData[2];
  always @(posedge iClk, posedge iRst_n) begin
    if(iRst_n == 1'b0) begin
      crc <= {32{1'b0}};
    end else begin
      if(iInit == 1'b1) begin
        crc <= {32{1'b1}};
      end
      else if(iCalcEn == 1'b1) begin
        crc <= nxtCrc;
      end
    end
  end
  assign oCRC[31:24] =  ~({crc[24],crc[25],crc[26],crc[27],crc[28],crc[29],crc[30],crc[31]});
  assign oCRC[23:16] =  ~({crc[16],crc[17],crc[18],crc[19],crc[20],crc[21],crc[22],crc[23]});
  assign oCRC[15:8] =  ~({crc[8],crc[9],crc[10],crc[11],crc[12],crc[13],crc[14],crc[15]});
  assign oCRC[7:0] =  ~({crc[0],crc[1],crc[2],crc[3],crc[4],crc[5],crc[6],crc[7]});
  assign oCRCErr = crc != 32'hc704dd7b ? 1'b1 : 1'b0;
    // CRC not equal to magic number
endmodule

module Hex4Digs_2_SSeg(
input wire clock,
input wire inclk,
input wire sw0,
input wire [3:0] incr,
output reg [3:0] anodes,
output reg [7:0] cathodes
);
// Input clock
// Inc clock
// Switch to control clock
// Increment digits
// Anodes for display
// Cathodes for segments
reg clk;
parameter TC5Hz = 56;  // TC for 5 Hz clock
parameter TC1KHz = 15;  // TC for 1 KHz clock
wire clk5Hz = 1'b0;  // 5 Hz clock
wire clk1KHz = 1'b0;  // 1 KHz clock
reg [1:0] dsel = 2'b00;  // Display select
reg [3:0] hx0 = 4'b0000; reg [3:0] hx1 = 4'b0000; reg [3:0] hx2 = 4'b0000; reg [3:0] hx3 = 4'b0000;  // Hex digits
wire [7:0] sg0 = 8'b11111111; wire [7:0] sg1 = 8'b11111111; wire [7:0] sg2 = 8'b11111111; wire [7:0] sg3 = 8'b11111111;  // Segments
  // Get 1 KHz, 16 Hz, and 5 Hz clocks
  CDiv c5Hz(
      clock,
    TC5Hz,
    clk5Hz);
  CDiv c1KHz(
      clock,
    TC1KHz,
    clk1KHz);
  // Get 4 Hex digits and assign their segments
  Hex2SSeg dig0(
      hx0,
    sg0);
  Hex2SSeg dig1(
      hx1,
    sg1);
  Hex2SSeg dig2(
      hx2,
    sg2);
  Hex2SSeg dig3(
      hx3,
    sg3);
  always @(sw0, clk1KHz, clk5Hz) begin : P2
  // control clocks
    if((sw0 == 1'b0)) begin
      clk <= clk1KHz;
    end
    else begin
      clk <= clk5Hz;
    end
  end
  always @(posedge inclk) begin
    if((incr[0] == 1'b1)) begin
      hx0 <= hx0 + 1;
    end
    if((incr[1] == 1'b1)) begin
      hx1 <= hx1 + 1;
    end
    if((incr[2] == 1'b1)) begin
      hx2 <= hx2 + 1;
    end
    if((incr[3] == 1'b1)) begin
      hx3 <= hx3 + 1;
    end
  end
  //    cathodes <= sg0 when dsel = "00" else
  //                sg1 when dsel = "01" else
  //                sg2 when dsel = "10" else
  //                sg3;
  always @(posedge clk) begin : P1
  // choose output display with dsel
    case(dsel)
    2'b00 : begin
      cathodes <= sg3;
      anodes <= 4'b0111;
    end
    2'b01 : begin
      cathodes <= sg2;
      anodes <= 4'b1011;
    end
    2'b10 : begin
      cathodes <= sg1;
      anodes <= 4'b1101;
    end
    default : begin
      cathodes <= sg0;
      anodes <= 4'b1110;
    end
    endcase
    dsel <= dsel + 1;
  end
endmodule

