module STATE_PCRE_AT_MOST(
input wire CLK,
input wire RESET,
input wire INPUT,
input wire SYMBOL,
input wire WE,
output wire OUTPUT
);
parameter [31:0] M;
parameter [31:0] N;
// input data interface
// output data interface
// ----------------------------------------------------------------------------
//                     Architecture: full
// ----------------------------------------------------------------------------
wire local_reset;
reg [11:0] value;
wire at_most_in;
  assign local_reset = RESET |  ~SYMBOL;
  generate if ((M > 0)) begin: gen_exact_part_y
      STATE_PCRE_EXACT #(
          .M(M))
    exact_u(
          .CLK(CLK),
      .RESET(RESET),
      // input data interface
      .INPUT(INPUT),
      .SYMBOL(SYMBOL),
      .WE(WE),
      // output data interface
      .OUTPUT(at_most_in));
  end
  endgenerate
  generate if ((M == 0)) begin: gen_exact_part_n
      assign at_most_in = INPUT;
  end
  endgenerate
  always @(posedge RESET, posedge CLK) begin
    if((local_reset == 1'b1)) begin
      value <= {12{1'b0}};
    end
    else begin
      if((we == 1'b1)) begin
        if(((value > 0) || (at_most_in == 1'b1))) begin
          value <= value + 1;
        end
      end
    end
  end
  assign OUTPUT = (value > 0 && value <= (N - M)) ? 1'b1 : 1'b0;
endmodule

