module dynthreshold_process(
input wire clk_proc,
input wire reset_n,
input wire status_reg_enable_bit,
input wire [31:0] desired_ratio_reg,
input wire [31:0] border_research_type_reg,
input wire [IN_SIZE - 1:0] in_data,
input wire in_fv,
input wire in_dv,
output reg [OUT_SIZE - 1:0] out_data,
output reg out_fv,
output reg out_dv
);
parameter [31:0] CLK_PROC_FREQ;
parameter [31:0] IN_SIZE;
parameter [31:0] OUT_SIZE;
//-------------- dynamic parameters ports ---------------
//----------------------- in flow -----------------------
//---------------------- out flow -----------------------
reg enabled;  // Desired ratio of white pixels in percent
reg [31:0] current_desired_ratio;  // Ratio triggering the switch between a dichotomic research and an iterative one
reg [31:0] current_border_research_type;  //Threshold borders
wire [IN_SIZE - 1:0] lower_border_threshold = 1'b0;
wire [IN_SIZE - 1:0] upper_border_threshold = 1'b1;
  always @(posedge clk_proc, posedge reset_n) begin : P1
    reg [31:0] white_px_counter;
  //unsigned(31 downto 0);	
    reg [31:0] img_px_counter;
  //unsigned(31 downto 0);
    reg [31:0] current_ratio;
    reg [31:0] old_ratio;
    reg [IN_SIZE - 1:0] current_threshold;
    reg [IN_SIZE - 1:0] old_threshold;
    if((reset_n == 1'b0)) begin
      enabled <= 1'b0;
      out_data <= {((OUT_SIZE - 1)-(0)+1){1'b0}};
      out_dv <= 1'b0;
      out_fv <= 1'b0;
      current_threshold = {1{1'b0}};
    end else begin
      // Waiting for an image flow
      if((in_fv == 1'b0)) begin
        // Update params here, between two images processing
        // Updating threshold
        if((img_px_counter != 0 && enabled == 1'b1)) begin
          current_ratio = white_px_counter * 100 / img_px_counter;
          // Updating threshold with dichotomic search
          if(((( ( $signed((current_desired_ratio) - (current_ratio)) < 0 ) ? -$signed((current_desired_ratio) - (current_ratio)) : (current_desired_ratio) - (current_ratio) )) > current_border_research_type)) begin
            if((current_ratio > current_desired_ratio)) begin
              current_threshold = current_threshold + (upper_border_threshold - current_threshold) / 2;
            end
            else if(current_ratio < current_desired_ratio) begin
              current_threshold = lower_border_threshold + current_threshold / 2;
            end
          end
          else begin
            // To avoid a bouncing effect near the target, final updates are iteratives
            if((current_ratio > current_desired_ratio)) begin
              // Too many white pixels spotted, increasing threshold value
              if((current_threshold < upper_border_threshold)) begin
                current_threshold = current_threshold + 1;
              end
            end
            else if(current_ratio < current_desired_ratio) begin
              // Not enough white pixels, lowering threshold value
              if((current_threshold > lower_border_threshold)) begin
                current_threshold = current_threshold - 1;
              end
            end
          end
          old_ratio = current_ratio;
          old_threshold = current_threshold;
        end
        // Updating commanded ratio
        current_desired_ratio <= desired_ratio_reg;
        // Updating research type border
        current_border_research_type <= border_research_type_reg;
        // Reset pixel counter
        img_px_counter = 0;
        white_px_counter = 0;
        enabled <= status_reg_enable_bit;
      end
      if((enabled == 1'b1)) begin
        if((in_dv == 1'b1 && in_fv == 1'b1)) begin
          // Binarisation process
          if(((in_data) <= current_threshold)) begin
            out_data <= {((OUT_SIZE - 1)-(0)+1){1'b0}};
          end
          else begin
            out_data <= {((OUT_SIZE - 1)-(0)+1){1'b1}};
            white_px_counter = white_px_counter + 1;
          end
          img_px_counter = img_px_counter + 1;
        end
      end
      else begin
        out_data <= in_data;
      end
      out_dv <= in_dv;
      out_fv <= in_fv;
    end
  end
endmodule

