module DivisorFrecuencia(
input wire clk_in,
input wire rst,
output wire clk_out
);
parameter [31:0] FREQ_IN=100000000;
parameter [31:0] FREQ_OUT=1;
//Frecuencia que se desea obtener de SALIDA en Hz. Valor modificable.
//Señal de reloj de entrada
//Botón Reset
//Señal de reloj de salida
reg aux;
reg [31:0] contador;
reg [31:0] razon;
reg [31:0] cuenta;  //-Razón de Proporción = CLKdeEntrada/FrecuenciaDeseada 
//-Cuenta = (Razón/2) - 1
  always @(razon, rst, clk_in) begin : P2
  //Proceso que calcula el número de ciclos que se deben contar para obtener
  // frecuencia deseada.
    razon <= (FREQ_IN) / (FREQ_OUT);
    cuenta <= (razon / 2) - 1;
  end
  always @(posedge rst, posedge clk_in, posedge cuenta) begin : P1
  //Proceso divisor de frecuencia asíncrono.
    if((rst == 1'b1)) begin
      contador <= 0;
      aux <= 1'b0;
    end else begin
      if((contador == cuenta)) begin
        aux <=  ~(aux);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
      end
    end
  end
  assign clk_out = aux;
endmodule

