input wire clk
);
reg [5:0] counter = 1'b0;
  assign mem_addr = counter;
  always @(posedge masterReset, posedge clk) begin
    if((masterReset == 1'b1)) begin
      counter <= {6{1'b0}};
      window_val <= 2'b01;
    end else begin
      counter <= counter + 1'b1;
      window_val <= window_ctrl;
    end
  end
