module nbit_synchronizer(
input wire clk,
input wire reset,
input wire [N - 1:0] I,
output wire [N - 1:0] O
);
parameter [31:0] N;
reg [N - 1:0] dff1;
reg [N - 1:0] dff2;
  //Dual synchronization registers
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      dff1 <= {((N - 1)-(0)+1){1'b0}};
      dff2 <= {((N - 1)-(0)+1){1'b0}};
    end
    else begin
      dff1 <= I;
      dff2 <= dff1;
    end
  end
  //Synchronized output
  assign O = dff2;
endmodule

module clk_en_generator(
input wire reset,
input wire clk_input,
output reg clk_en
);
parameter [31:0] DIVIDER=10;
wire clk_divided;
reg clk_divided0;
  clock_divider #(
      .DIVIDER(DIVIDER))
  clk_divider_u(
      .reset(reset),
    .clk_input(clk_input),
    .clk_output(clk_divided));
  always @(posedge clk_input) begin
    clk_divided0 <= clk_divided0;
    clk_en <= 1'b0;
    if(clk_divided == 1'b1 && clk_divided0 == 1'b0) begin
      clk_en <= 1'b1;
    end
    if(reset == 1'b1) begin
      clk_en <= 1'b0;
    end
  end
endmodule

