module control(
input wire [5:0] op,
output reg ex_asel,
output reg ex_bsel,
output reg ex_ressel,
output reg [1:0] ex_regsel,
output reg [2:0] ex_aluop,
output reg ex_domult,
output reg ex_multop,
output reg ex_invin2,
output reg ex_valid_reg,
output reg ex_valid_res,
output reg ex_psw_enable,
output reg ex_put,
output reg m_write,
output reg m_read,
output reg m_valid_mem,
output reg m_valid_reg,
output reg wb_sel,
output reg wb_enable,
output reg id_bsel,
output reg id_beq,
output reg id_bne,
output reg illegal_op,
output reg trap,
output reg jump
);
// The op code
// (ra,psw)
// (rb,imm)
// (res,sign)
// (psw,pc,b,in)
// (nop,add,sub,or,and,xor,shz,shs)
// (off,on)
// (low,high)
// (off,on)
// Forwarding valid
// Forwarding valid
// PSW will be updated
// This is a PUT
// Write signal to the DM
// Read signal to the DM
// Forwarding valid
// Forwarding valid
// (mem,reg)
// (off,on)
// '0' if rd is used as r2
// '1' if the op is a branch
// '1' if the op is a branch n.eq.
// '1' when illegal op
  always @(op) begin
    case(op)
    6'b000000 : begin
      // ADD
      ex_asel <= 1'b0;
      // register
      ex_bsel <= 1'b0;
      // register
      ex_ressel <= 1'b0;
      // result
      ex_regsel <= 2'b10;
      // b register
      ex_aluop <= 3'b001;
      // add
      ex_domult <= 1'b0;
      // no mult
      ex_multop <= 1'b0;
      // low
      ex_invin2 <= 1'b0;
      // do not invert
      ex_valid_reg <= 1'b0;
      // reg is not valid
      ex_valid_res <= 1'b1;
      // res is valid
      ex_psw_enable <= 1'b0;
      // psw is not updated
      ex_put <= 1'b0;
      // this is not a put
      m_write <= 1'b0;
      // no write
      m_read <= 1'b0;
      // no read
      m_valid_mem <= 1'b1;
      // mem is valid
      m_valid_reg <= 1'b0;
      // reg is not valid
      trap <= 1'b0;
      // no trap
      jump <= 1'b0;
      // no jump
      wb_sel <= 1'b0;
      // memory
      wb_enable <= 1'b1;
      // enable
      id_bsel <= 1'b1;
      // use b
      id_beq <= 1'b0;
      // no branch
      id_bne <= 1'b0;
      // no branch
      illegal_op <= 1'b0;
      // legal op
    end
    6'b000001 : begin
      // ADDI
      ex_asel <= 1'b0;
      ex_bsel <= 1'b1;
      ex_ressel <= 1'b0;
      ex_regsel <= 2'b10;
      ex_aluop <= 3'b001;
      ex_domult <= 1'b0;
      ex_multop <= 1'b0;
      ex_invin2 <= 1'b0;
      ex_valid_reg <= 1'b0;
      ex_valid_res <= 1'b1;
      ex_psw_enable <= 1'b0;
      ex_put <= 1'b0;
      m_write <= 1'b0;
      m_read <= 1'b0;
      m_valid_mem <= 1'b1;
      m_valid_reg <= 1'b0;
      trap <= 1'b0;
      jump <= 1'b0;
      wb_sel <= 1'b0;
      wb_enable <= 1'b1;
      id_bsel <= 1'b1;
      id_beq <= 1'b0;
      id_bne <= 1'b0;
      illegal_op <= 1'b0;
    end
    6'b000010 : begin
      // ADDX
      ex_asel <= 1'b0;
      ex_bsel <= 1'b1;
      ex_ressel <= 1'b0;
      ex_regsel <= 2'b10;
      ex_aluop <= 3'b001;
      ex_domult <= 1'b0;
      ex_multop <= 1'b0;
      ex_invin2 <= 1'b0;
      ex_valid_reg <= 1'b0;
      ex_valid_res <= 1'b1;
      ex_psw_enable <= 1'b0;
      ex_put <= 1'b0;
      m_write <= 1'b0;
      m_read <= 1'b0;
      m_valid_mem <= 1'b1;
      m_valid_reg <= 1'b0;
      trap <= 1'b0;
      jump <= 1'b0;
      wb_sel <= 1'b0;
      wb_enable <= 1'b1;
      id_bsel <= 1'b1;
      id_beq <= 1'b0;
      id_bne <= 1'b0;
      illegal_op <= 1'b0;
    end
    6'b000011 : begin
      // ADDD
      ex_asel <= 1'b0;
      ex_bsel <= 1'b1;
      ex_ressel <= 1'b0;
      ex_regsel <= 2'b10;
      ex_aluop <= 3'b001;
      ex_domult <= 1'b0;
      ex_multop <= 1'b0;
      ex_invin2 <= 1'b0;
      ex_valid_reg <= 1'b0;
      ex_valid_res <= 1'b1;
      ex_psw_enable <= 1'b0;
      ex_put <= 1'b0;
      m_write <= 1'b0;
      m_read <= 1'b0;
      m_valid_mem <= 1'b1;
      m_valid_reg <= 1'b0;
      trap <= 1'b0;
      jump <= 1'b0;
      wb_sel <= 1'b0;
      wb_enable <= 1'b1;
      id_bsel <= 1'b1;
      id_beq <= 1'b0;
      id_bne <= 1'b0;
      illegal_op <= 1'b0;
    end
    6'b000100 : begin
      // ADDV
      ex_asel <= 1'b0;
      ex_bsel <= 1'b0;
      ex_ressel <= 1'b0;
      ex_regsel <= 2'b10;
      ex_aluop <= 3'b001;
      ex_domult <= 1'b0;
      ex_multop <= 1'b0;
      ex_invin2 <= 1'b0;
      ex_valid_reg <= 1'b1;
      ex_valid_res <= 1'b0;
      ex_psw_enable <= 1'b0;
      ex_put <= 1'b0;
      m_write <= 1'b0;
      m_read <= 1'b0;
      m_valid_mem <= 1'b1;
      m_valid_reg <= 1'b0;
      trap <= 1'b0;
      jump <= 1'b0;
      wb_sel <= 1'b0;
      wb_enable <= 1'b1;
      id_bsel <= 1'b1;
      id_beq <= 1'b0;
      id_bne <= 1'b0;
      illegal_op <= 1'b0;
    end
    6'b000101 : begin
      // ADDVI
      ex_asel <= 1'b0;
      ex_bsel <= 1'b1;
      ex_ressel <= 1'b0;
      ex_regsel <= 2'b10;
      ex_aluop <= 3'b001;
      ex_domult <= 1'b0;
      ex_multop <= 1'b0;
      ex_invin2 <= 1'b0;
      ex_valid_reg <= 1'b0;
      ex_valid_res <= 1'b1;
