module rat_wrapper(
input wire [7:0] switches,
input wire [2:0] buttons,
input wire rx,
output wire tx,
output wire hs,
output wire vs,
output wire [2:0] rout,
output wire [2:0] gout,
output wire [1:0] bout,
input wire clk,
input wire rst,
output wire [3:0] sel,
output wire [7:0] seg,
output wire [7:0] leds
);
// Declare RAT_CPU and I/O components ----------------------------------------
// Signals for connecting RAT_CPU to RAT_wrapper -----------------------------
wire [7:0] in_port_i;
wire [7:0] out_port_i;
wire [7:0] uart_in_i;
wire [7:0] uart_out_i;
wire [7:0] port_id_i;
wire io_oe_i;
wire int_i;
wire [10:0] wa_i;
wire [7:0] wd_i;
wire we_i;
wire [7:0] pixel_data_i;
  // Instantiate RAT_CPU --------------------------------------------------------
  rat_cpu rat_cpu1(
      .in_port(in_port_i),
    .out_port(out_port_i),
    .port_id(port_id_i),
    .rst(rst),
    .io_oe(io_oe_i),
    .int_in(int_i),
    .clk(clk));
  // Instantiate Inputs --------------------------------------------------------
  inputs inputs1(
      .input_port(in_port_i),
    .clk(clk),
    .buttons(buttons),
    .switches(switches),
    .uart_in(uart_in_i),
    .vga_in(pixel_data_i),
    .port_id(port_id_i));
  // Instantiate Outputs --------------------------------------------------------
  outputs outputs1(
      .leds(leds),
    .seg(seg),
    .sel(sel),
    .uart_out(uart_out_i),
    .vga_wa(wa_i),
    .vga_wd(wd_i),
    .vga_we(we_i),
    .port_id(port_id_i),
    .output_port(out_port_i),
    .io_oe(io_oe_i),
    .clk(clk));
  // Instantiate UART -----------------------------------------------------------
  uart_wrapper uart_wrapper1(
      .tx(tx),
    .rx(rx),
    .clk(clk),
    .rst(rst),
    .int(int_i),
    .data_in(uart_out_i),
    // data going OUT OF The board
    .data_out(uart_in_i));
  // data going INTO the board
  // Instantiate VGA ------------------------------------------------------------
  vgaDriverBuffer vga1(
      .clk(clk),
    .we(we_i),
    .wa(wa_i),
    .wd(wd_i),
    .rout(rout),
    .gout(gout),
    .bout(bout),
    .hs(hs),
    .vs(vs),
    .pixeldata(pixel_data_i));
endmodule

module snespad(
input wire clk_i,
input wire reset_i,
output wire pad_clk_o,
output wire pad_latch_o,
input wire [num_pads_g - 1:0] pad_data_i,
output wire [num_pads_g - 1:0] but_a_o,
output wire [num_pads_g - 1:0] but_b_o,
output wire [num_pads_g - 1:0] but_x_o,
output wire [num_pads_g - 1:0] but_y_o,
output wire [num_pads_g - 1:0] but_start_o,
output wire [num_pads_g - 1:0] but_sel_o,
output wire [num_pads_g - 1:0] but_tl_o,
output wire [num_pads_g - 1:0] but_tr_o,
output wire [num_pads_g - 1:0] but_up_o,
output wire [num_pads_g - 1:0] but_down_o,
output wire [num_pads_g - 1:0] but_left_o,
output wire [num_pads_g - 1:0] but_right_o
);
// number of pads connected to this core
parameter [31:0] num_pads_g=1;
parameter [31:0] reset_level_g=0;
parameter [31:0] button_level_g=0;
parameter [31:0] clocks_per_6us_g=6;
// System Interface -------------------------------------------------------
// Gamepad Interface ------------------------------------------------------
// Buttons Interface ------------------------------------------------------
wire clk_en_s;
wire shift_buttons_s;
wire save_buttons_s;
  snespad_ctrl #(
      .reset_level_g(reset_level_g),
    .clocks_per_6us_g(clocks_per_6us_g))
  ctrl_b(
      .clk_i(clk_i),
    .reset_i(reset_i),
    .clk_en_o(clk_en_s),
    .shift_buttons_o(shift_buttons_s),
    .save_buttons_o(save_buttons_s),
    .pad_clk_o(pad_clk_o),
    .pad_latch_o(pad_latch_o));
  genvar i;
  generate for (i=0; i <= num_pads_g - 1; i = i + 1) begin: pads
      snespad_pad #(
          .reset_level_g(reset_level_g),
      .button_level_g(button_level_g))
    pad_b(
          .clk_i(clk_i),
      .reset_i(reset_i),
      .clk_en_i(clk_en_s),
      .shift_buttons_i(shift_buttons_s),
      .save_buttons_i(save_buttons_s),
      .pad_data_i(pad_data_i[i]),
      .but_a_o(but_a_o[i]),
      .but_b_o(but_b_o[i]),
      .but_x_o(but_x_o[i]),
      .but_y_o(but_y_o[i]),
      .but_start_o(but_start_o[i]),
      .but_sel_o(but_sel_o[i]),
      .but_tl_o(but_tl_o[i]),
      .but_tr_o(but_tr_o[i]),
      .but_up_o(but_up_o[i]),
      .but_down_o(but_down_o[i]),
      .but_left_o(but_left_o[i]),
      .but_right_o(but_right_o[i]));
  end
  endgenerate
