module Processor(
input wire rst,
output wire [31:0] data_out,
input wire clk
);
wire [31:0] out_nPC = 1'b0;
wire [31:0] data_in = 1'b0;
wire [31:0] pc_out = 1'b0;
wire [31:0] im_out = 1'b0;
wire [31:0] seu_out = 1'b0;
wire [12:0] imm13_aux = 1'b0;  //en formato3 
//el inmmediato va del bit 0 al 12
wire [31:0] crs1_aux = 1'b0;
wire [31:0] crs2_aux = 1'b0;
wire [31:0] mux_out = 1'b0;
wire [5:0] cpu_out = 1'b0;
wire [31:0] alu_out = 1'b0;
wire cwp = 1'b0;
wire [5:0] nrs1 = 1'b0;
wire [5:0] nrs2 = 1'b0;
wire [5:0] nrd = 1'b0;
wire Ncwp = 1'b0;
wire carry = 1'b0;
wire [3:0] nzvc = 1'b0;
  PC Inst_PC(
      .rst(rst),
    .clk(clk),
    .DAT_in(out_nPC),
    .DAT_out(pc_out));
  PC Inst_nPC(
      .rst(rst),
    .clk(clk),
    .DAT_in(data_in),
    .DAT_out(out_nPC));
  Sumador Inst_Sumador(
      .operador1(32'b00000000000000000000000000000001),
    .operador2(pc_out),
    .resultado(data_in));
  IM Inst_IM(
      .rst(rst),
    .addr(pc_out),
    .data(im_out));
  Mod5Seu Inst_SEU(
      .imm13(im_out[12:0]),
    .SEUimm32(seu_out));
  MUX Inst_MUX(
      .Crs2(crs2_aux),
    .SEUimm13(seu_out),
    .i(im_out[13]),
    .Oper2(mux_out));
  windows_manager_arch Inst_WM(
      .rs1(im_out[18:14]),
    .rs2(im_out[4:0]),
    .rd(im_out[29:25]),
    .op(im_out[31:30]),
    .op3(im_out[24:19]),
    .CWP(cwp),
    .nrs1(nrs1),
    .nrs2(nrs2),
    .nrd(nrd),
    .Ncwp(Ncwp));
  PSR Inst_PSR(
      .NZVC(nzvc),
    .rst(rst),
    .clk(clk),
    .Ncwp(Ncwp),
    .Carry(carry),
    .cwp(cwp));
  PSR_modifier Inst_PSR_mod(
      .AluResult(alu_out),
    .OP1(crs1_aux[31]),
    .OP2(mux_out[31]),
    .AluOp(cpu_out),
    .NZVC(nzvc));
  RF Inst_RF(
      .rst(rst),
    .rs1(nrs1),
    .rs2(nrs2),
    .rd(nrd),
    .dwr(alu_out),
    .ORs1(crs1_aux),
    .ORs2(crs2_aux));
  ALU Inst_ALU(
      .Oper1(crs1_aux),
    .Oper2(mux_out),
    .ALUOP(cpu_out),
    .carry(carry),
    .Salida(alu_out));
  CU Inst_CU(
      .op(im_out[31:30]),
    .op3(im_out[24:19]),
    .aluop(cpu_out));
  assign data_out = alu_out;
endmodule

module control7seg(
input wire clk_1KHz,
input wire rst,
input wire [15:0] data_in,
output reg [6:0] data_out,
output reg [3:0] sel
);
// =================================================================================
//           ARCHITECTURE
// =================================================================================
// Tipos propios:
parameter [1:0]
  s0 = 0,
  s1 = 1,
  s2 = 2,
  s3 = 3;
  //---------------------------------------------------------------------------
// Declaracion de senales
//---------------------------------------------------------------------------
reg [1:0] current_state; reg [1:0] next_state;  // Estados actual y siguiente.
wire [3:0] disp0;
wire [3:0] disp1;
wire [3:0] disp2;
wire [3:0] disp3;
reg [3:0] dispBin_aux;  //---------------------------------------------------------------------------
// Componentes
//---------------------------------------------------------------------------
  //---------------------------------------------------------------------------
  // Conexion de senales
  //---------------------------------------------------------------------------
  assign disp0 = data_in[3:0];
  // disp0 es el de mas a la derecha
  assign disp1 = data_in[7:4];
  assign disp2 = data_in[11:8];
  assign disp3 = data_in[15:12];
  //---------------------------------------------------------------------------
  // Instancia de componentes
  //---------------------------------------------------------------------------
  //-------------------------------------------------
  // Proceso de calculo del estado siguiente
  //-------------------------------------------------
  always @(current_state) begin
    case(current_state)
    s0 : begin
      next_state <= s1;
    end
    s1 : begin
      next_state <= s2;
    end
    s2 : begin
      next_state <= s3;
    end
    default : begin
      next_state <= s0;
    end
    endcase
  end
  //-------------------------------------------------
  // Proceso de asignación de valores a las salidas
  //-------------------------------------------------
  always @(current_state, disp0, disp1, disp2, disp3) begin
    case(current_state)
    s0 : begin
      dispBin_aux <= disp0;
      sel <= 4'b1110;
    end
    s1 : begin
      dispBin_aux <= disp1;
      sel <= 4'b1101;
    end
    s2 : begin
      dispBin_aux <= disp2;
      sel <= 4'b1011;
    end
    s3 : begin
      dispBin_aux <= disp3;
      sel <= 4'b0111;
    end
    default : begin
      dispBin_aux <= {4{1'b0}};
      sel <= 4'b1111;
    end
    endcase
  end
  //-------------------------------------------------
  // Proceso de actualizacion del estado
  //-------------------------------------------------
  always @(posedge clk_1KHz, posedge rst) begin
    if(rst == 1'b1) begin
      current_state <= s0;
    end else begin
      current_state <= next_state;
    end
  end
  //-------------------------------------------------
  // Conversion binario - 7seg
  //-------------------------------------------------
  always @(dispBin_aux) begin
    case(dispBin_aux)
    4'b0000 : begin
      //0
      data_out <= 7'b1000000;
    end
    4'b0001 : begin
      //1
      data_out <= 7'b1111001;
    end
    4'b0010 : begin
      //2
      data_out <= 7'b0100100;
    end
    4'b0011 : begin
      //3
      data_out <= 7'b0110000;
    end
    4'b0100 : begin
      //4
      data_out <= 7'b0011001;
    end
    4'b0101 : begin
      //5
      data_out <= 7'b0010010;
    end
    4'b0110 : begin
      //6
      data_out <= 7'b0000010;
    end
    4'b0111 : begin
      //7
      data_out <= 7'b1111000;
    end
    4'b1000 : begin
      //8
      data_out <= 7'b0000000;
    end
    4'b1001 : begin
      //9
      data_out <= 7'b0010000;
    end
    4'b1010 : begin
      //A
      data_out <= 7'b0001000;
    end
    4'b1011 : begin
      //B
      data_out <= 7'b0000011;
    end
    4'b1100 : begin
      //C
      data_out <= 7'b1000110;
    end
    4'b1101 : begin
      //D
      data_out <= 7'b0100001;
    end
    4'b1110 : begin
      //E
      data_out <= 7'b0000110;
    end
    4'b1111 : begin
      //F
      data_out <= 7'b0001110;
    end
    default : begin
      //apagado
      data_out <= 7'b1111111;
    end
    endcase
  end
endmodule

