module blockPHfinding(
input wire clk_i,
input wire reset_i,
input wire framing_i,
output reg block_o
);
parameter [2:0]
  waiting = 0,
  tick1 = 1,
  tick2 = 2,
  tick3 = 3,
  tick4 = 4;
reg [2:0] s_state;
  always @(posedge clk_i, posedge reset_i) begin
      // process p_serin
    if((reset_i == 1'b1)) begin
      // asynchronous reset 
      block_o <= 1'b0;
      s_state <= waiting;
    end else begin
      // rising clock edge
      case(s_state)
            //-----------------------------------------------------------------------
      tick1 : begin
        block_o <= 1'b1;
        s_state <= tick2;
        //-----------------------------------------------------------------------
      end
      tick2 : begin
        block_o <= 1'b1;
        s_state <= tick3;
        //-----------------------------------------------------------------------
      end
      tick3 : begin
        block_o <= 1'b1;
        s_state <= tick4;
        //-----------------------------------------------------------------------
      end
      tick4 : begin
        block_o <= 1'b1;
        s_state <= waiting;
        //-----------------------------------------------------------------------
        //-----------------------------------------------------------------------
      end
      default : begin
        if(framing_i == 1'b1) begin
          s_state <= tick1;
        end
        else begin
          block_o <= 1'b0;
          s_state <= waiting;
        end
      end
      endcase
    end
  end
endmodule

