module idea_com_inner(
input wire Clk,
input wire Reset,
input wire RxD,
output wire TxD,
output reg [7:0] LEDs
);
// The UART for the communication with the PC:
//component idea_hw 
//    Port ( CLK : in STD_LOGIC;
//			  START : in  STD_LOGIC;
//           READY : out  STD_LOGIC;			  
//           KEY : in  STD_LOGIC_VECTOR (127 downto 0);
//           X1 : in  STD_LOGIC_VECTOR (15 downto 0);
//           X2 : in  STD_LOGIC_VECTOR (15 downto 0);
//           X3 : in  STD_LOGIC_VECTOR (15 downto 0);
//           X4 : in  STD_LOGIC_VECTOR (15 downto 0);
//           Y1 : out  STD_LOGIC_VECTOR (15 downto 0);
//           Y2 : out  STD_LOGIC_VECTOR (15 downto 0);
//           Y3 : out  STD_LOGIC_VECTOR (15 downto 0);
//           Y4 : out  STD_LOGIC_VECTOR (15 downto 0));
//end component;
// All used signals for the top level are defined here:
reg read = 1'b1;
reg write = 1'b1;
wire rxrdy = 1'b1; wire txrdy = 1'b1;
wire parity_error = 1'b0; wire framing_error = 1'b0; wire overrun = 1'b0;
wire [7:0] data = 8'b00000000;
reg [7:0] txdata = 8'b00000000;
reg start_idea = 1'b0; wire ready_idea = 1'b0;
reg [15:0] x1 = 16'b0000000000000000; reg [15:0] x2 = 16'b0000000000000000; reg [15:0] x3 = 16'b0000000000000000; reg [15:0] x4 = 16'b0000000000000000;
wire [15:0] y1 = 16'b0000000000000000; wire [15:0] y2 = 16'b0000000000000000; wire [15:0] y3 = 16'b0000000000000000; wire [15:0] y4 = 16'b0000000000000000;
reg [127:0] key = 128'h00000000000000000000000000000000;
parameter [3:0]
  IDLE = 0,
  WAIT_FOR_DATA = 1,
  RECEIVED_BYTE = 2,
  READ_BYTE = 3,
  WAIT_FOR_RXRDY_0 = 4,
  WAIT_FOR_IDEA_TO_DEACTIVATE_READY = 5,
  WAIT_FOR_IDEA_TO_COMPLETE = 6,
  WRITE_BYTE = 7,
  WRITE_BYTE_NOW = 8,
  WRITE_BYTE_ACK = 9,
  WAIT_FOR_TXRDY_1 = 10,
  LOOPBACK_MODE = 11;
reg [3:0] state = IDLE;
reg [4:0] byte_cntr = 5'b00000;
reg loopback_select = 1'b0;
wire [15:0] z1 = 16'b0000000000000000; wire [15:0] z2 = 16'b0000000000000000; wire [15:0] z3 = 16'b0000000000000000; wire [15:0] z4 = 16'b0000000000000000;
  // The UART module
  uart uart1(
      Clk,
    Reset,
    read,
    write,
    data,
    txdata,
    RxD,
    TxD,
    rxrdy,
    txrdy,
    parity_error,
    framing_error,
    overrun);
  // The encryption algorithm
  //	idea1:   idea_hw port map( clk, start_idea, ready_idea, key, x1, x2, x3, x4, y1, y2, y3, y4);
  idea_single uut(
      .KEY(key),
    .clk_in(Clk),
    .ready_out(ready_idea),
    .start_in(start_idea),
    .X1(x1),
    .X2(x2),
    .X3(x3),
    .X4(x4),
    .Y1(y1),
    .Y2(y2),
    .Y3(y3),
    .Y4(y4));
  // mux for loopback mode
  multiplexer mux1(
      .A(y1),
    .B(x1),
    .S(loopback_select),
    .O(z1));
  multiplexer mux2(
      .A(y2),
    .B(x2),
    .S(loopback_select),
    .O(z2));
  multiplexer mux3(
      .A(y3),
    .B(X3),
    .S(loopback_select),
    .O(z3));
  multiplexer mux4(
      .A(y4),
    .B(X4),
    .S(loopback_select),
    .O(z4));
  // The state machine for the communication:
  always @(posedge Clk) begin
    if((Reset == 1'b1)) begin
      state <= IDLE;
      byte_cntr <= 5'b00000;
      read <= 1'b1;
      write <= 1'b1;
      LEDs <= 8'b00000000;
      //LEDs <= "00000000"; hier ändern in original
    end
    else begin
      if((state == IDLE)) begin
        // Initial state
        state <= WAIT_FOR_DATA;
        byte_cntr <= 5'b00000;
      end
      else if((state == WAIT_FOR_DATA)) begin
        write <= 1'b1;
        // Waiting for incoming data.
        if((rxrdy == 1'b1)) begin
          // There is a byte at the receiver!
          state <= RECEIVED_BYTE;
        end
      end
      else if((state == RECEIVED_BYTE)) begin
        // The UART signalizes, that there
        // is a new byte to be read!
        read <= 1'b0;
        state <= READ_BYTE;
      end
      else if((state == READ_BYTE)) begin
        // Read the byte and set the
        // right input registers of the
        // IDEA block.
        LEDs[7] <= 1'b1;
        LEDs[0] <= framing_error;
        LEDs[1] <= parity_error;
        LEDs[2] <= overrun;
        byte_cntr <= byte_cntr + 5'b00001;
        if((byte_cntr == 5'b00000)) begin
          x1[7:0] <= data;
        end
        else if((byte_cntr == 5'b00001)) begin
          x1[15:8] <= data;
        end
        else if((byte_cntr == 5'b00010)) begin
          x2[7:0] <= data;
        end
        else if((byte_cntr == 5'b00011)) begin
          x2[15:8] <= data;
        end
        else if((byte_cntr == 5'b00100)) begin
          x3[7:0] <= data;
        end
        else if((byte_cntr == 5'b00101)) begin
          x3[15:8] <= data;
        end
        else if((byte_cntr == 5'b00110)) begin
          x4[7:0] <= data;
        end
        else if((byte_cntr == 5'b00111)) begin
          x4[15:8] <= data;
        end
        else if((byte_cntr == 5'b01000)) begin
          key[7:0] <= data;
        end
        else if((byte_cntr == 5'b01001)) begin
          key[15:8] <= data;
        end
        else if((byte_cntr == 5'b01010)) begin
          key[23:16] <= data;
        end
        else if((byte_cntr == 5'b01011)) begin
          key[31:24] <= data;
        end
        else if((byte_cntr == 5'b01100)) begin
          key[39:32] <= data;
        end
        else if((byte_cntr == 5'b01101)) begin
          key[47:40] <= data;
        end
        else if((byte_cntr == 5'b01110)) begin
          key[55:48] <= data;
        end
        else if((byte_cntr == 5'b01111)) begin
          key[63:56] <= data;
        end
        else if((byte_cntr == 5'b10000)) begin
          key[71:64] <= data;
        end
        else if((byte_cntr == 5'b10001)) begin
          key[79:72] <= data;
        end
        else if((byte_cntr == 5'b10010)) begin
          key[87:80] <= data;
        end
        else if((byte_cntr == 5'b10011)) begin
          key[95:88] <= data;
        end
        else if((byte_cntr == 5'b10100)) begin
          key[103:96] <= data;
        end
        else if((byte_cntr == 5'b10101)) begin
          key[111:104] <= data;
        end
        else if((byte_cntr == 5'b10110)) begin
          key[119:112] <= data;
        end
        else if((byte_cntr == 5'b10111)) begin
          key[127:120] <= data;
        end
        read <= 1'b1;
        state <= WAIT_FOR_RXRDY_0;
      end
      else if((state == WAIT_FOR_RXRDY_0)) begin
        // Wait until the UART has acknowledged
        LEDs[7] <= 1'b0;
        // that the data has been read.
        if((rxrdy == 1'b0)) begin
          if((byte_cntr == 5'b11000)) begin
            // add loopback mode
            if((key == 128'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF)) begin
              state <= LOOPBACK_MODE;
              loopback_select <= 1'b1;
            end
            else begin
              start_idea <= 1'b1;
              state <= WAIT_FOR_IDEA_TO_DEACTIVATE_READY;
              loopback_select <= 1'b0;
            end
            // added newly: 20130405
            //							read <= '1';
          end
          else begin
            state <= WAIT_FOR_DATA;
          end
        end
      end
      else if((state == LOOPBACK_MODE)) begin
        byte_cntr <= 5'b00000;
        state <= WRITE_BYTE;
      end
      else if((state == WAIT_FOR_IDEA_TO_DEACTIVATE_READY)) begin
        if((ready_idea == 1'b0)) begin
          state <= WAIT_FOR_IDEA_TO_COMPLETE;
        end
      end
      else if((state == WAIT_FOR_IDEA_TO_COMPLETE)) begin
        // The IDEA algorithm has computed its results now.
        byte_cntr <= 5'b00000;
        start_idea <= 1'b0;
        if((ready_idea == 1'b1)) begin
          LEDs[1] <= 1'b1;
          state <= WRITE_BYTE;
        end
      end
      else if((state == WRITE_BYTE)) begin
        // Write back the computed data set
        byte_cntr <= byte_cntr + 5'b00001;
        if((byte_cntr == 5'b00000)) begin
          txdata <= z1[7:0];
        end
        else if((byte_cntr == 1)) begin
          txdata <= z1[15:8];
        end
        else if((byte_cntr == 2)) begin
          txdata <= z2[7:0];
        end
        else if((byte_cntr == 3)) begin
          txdata <= z2[15:8];
        end
        else if((byte_cntr == 4)) begin
          txdata <= z3[7:0];
        end
        else if((byte_cntr == 5)) begin
          txdata <= z3[15:8];
        end
        else if((byte_cntr == 6)) begin
          txdata <= z4[7:0];
        end
        else if((byte_cntr == 7)) begin
          txdata <= z4[15:8];
        end
        state <= WRITE_BYTE_NOW;
      end
      else if((state == WRITE_BYTE_NOW)) begin
        write <= 1'b0;
        state <= WRITE_BYTE_ACK;
      end
      else if((state == WRITE_BYTE_ACK)) begin
        write <= 1'b1;
        if((txrdy == 1'b0)) begin
          state <= WAIT_FOR_TXRDY_1;
        end
      end
      else if((state == WAIT_FOR_TXRDY_1)) begin
        if((txrdy == 1'b1)) begin
          txdata <= 8'b00000000;
          if((byte_cntr == 5'b01000)) begin
            state <= WAIT_FOR_DATA;
            byte_cntr <= 5'b00000;
            LEDs[3] <= 1'b1;
          end
          else begin
            state <= WRITE_BYTE;
          end
        end
      end
    end
  end
endmodule

module vme_dma_du(
input wire rst,
