input wire [6:2] adr_o,
input wire [31:0] mstr_dat_i,
input wire [7:4] dma_act_bd,
output wire [31:2] dma_dest_adr,
output wire [31:2] dma_sour_adr,
output wire [2:0] dma_sour_device,
output wire [2:0] dma_dest_device,
output wire [4:0] dma_vme_am,
output wire blk_sgl,
output wire inc_sour,
output wire inc_dest,
output wire [15:0] dma_size,
output wire clr_dma_act_bd,
input wire set_dma_err,
input wire clr_dma_en,
output wire dma_en,
output wire dma_null,
input wire en_mstr_dat_i_reg
);
// irq for cpu; asserted when done or error (if enabled)
// if set, dma_slv has access and vica verse
// if set, write from slave side will be done
// if set, write from master side will be done
// slave signals
// wb_master singals
// vme_dma_au
// active bd number
// active bd destination adress
// active bd source adress
// selects the source device
// selects the destination device
// type of dma transmission
// indicates if DMA transfer should be done as block or single accesses
// indicates if source adress should be incremented
// indicates if destination adress should be incremented
// size of data package
// clears dma_act_bd if dma_mstr has done without error or
// when dma_err will be cleared
// dma_mstr
// sets dma error bit if vme error
// clears dma en bit if dma_mstr has done
// starts dma_mstr, if 0 => clears dma_act_bd counter
// indicates the last bd   
// enable for data in
wire [7:0] dma_sta_int;
reg [31:0] act_bd_conf_int;
wire [31:0] int_data;
wire [6:2] int_adr;
wire dma_err;
wire dma_irq;
wire dma_ien;
wire dma_en_int;
wire write_flag_mstr;
reg [31:0] mstr_dat_i_reg;
reg [31:0] dma_dest_adr_int;
reg [31:0] dma_sour_adr_int;
reg [15:0] dma_size_reg;
  assign clr_dma_act_bd = (clr_dma_en == 1'b1 && set_dma_err == 1'b0) || dma_sta[9] == 1'b1 ? 1'b1 : 1'b0;
  assign dma_en = dma_sta[0];
  assign irq_o = dma_sta[2];
  assign dma_dest_adr = dma_dest_adr_int[31:2];
  assign dma_sour_adr = dma_sour_adr_int[31:2];
  assign dma_size = dma_size_reg;
  assign dma_sour_device = act_bd_conf_int[18:16];
  assign dma_dest_device = act_bd_conf_int[14:12];
  assign dma_vme_am = act_bd_conf_int[8:4];
  assign blk_sgl = act_bd_conf_int[7:4] == 4'b0001 || act_bd_conf_int[7:4] == 4'b0101 ? 1'b1 : act_bd_conf_int[7:4] == 4'b1100 ? 1'b0 : act_bd_conf_int[7:4] == 4'b1110 ? 1'b0 : act_bd_conf_int[3];
  assign inc_sour = act_bd_conf_int[2];
  assign inc_dest = act_bd_conf_int[1];
  assign dma_null = act_bd_conf_int[0];
  assign int_data = mstr_dat_i_reg;
  assign int_adr = adr_o;
  assign write_flag_mstr = mstr_ack == 1'b1 ? 1'b1 : 1'b0;
  assign slv_dat_o = {32{1'b0}};
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      mstr_dat_i_reg <= {32{1'b0}};
    end else begin
      if(en_mstr_dat_i_reg == 1'b1) begin
        mstr_dat_i_reg <= mstr_dat_i;
      end
    end
  end
  // dma_dest_adr_int 0x48
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      dma_dest_adr_int <= {32{1'b0}};
    end else begin
      if((write_flag_mstr == 1'b1 && int_adr[3:2] == 2'b00)) begin
        dma_dest_adr_int[31:0] <= int_data[31:0];
      end
    end
  end
  // dma_sour_adr_int 0x4c
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      dma_sour_adr_int <= {32{1'b0}};
    end else begin
      if((write_flag_mstr == 1'b1 && int_adr[3:2] == 2'b01)) begin
        dma_sour_adr_int[31:0] <= int_data[31:0];
      end
    end
  end
  // dma_size 0x50   
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      dma_size_reg <= {16{1'b0}};
    end else begin
      if((write_flag_mstr == 1'b1 && int_adr[3:2] == 2'b10)) begin
        dma_size_reg[15:0] <= int_data[15:0];
      end
    end
  end
  // act_bd_conf_int 0x54
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      act_bd_conf_int <= {32{1'b0}};
    end else begin
      if((write_flag_mstr == 1'b1 && int_adr[3:2] == 2'b11)) begin
        act_bd_conf_int[31:0] <= int_data[31:0];
      end
    end
  end
endmodule

