module rx_cap_reg(
input wire clk,
input wire rst,
input wire [31:0] cap_reg,
input wire [31:0] cap_din,
input wire rx_block_start,
input wire ch_data,
input wire ud_a_en,
input wire ud_b_en,
input wire cs_a_en,
input wire cs_b_en,
output wire [31:0] cap_dout,
output reg cap_evt
);
// clock
// reset
//cap_ctrl_wr: in std_logic; -- control register write	
//cap_ctrl_rd: in std_logic; -- control register read
//cap_data_rd: in std_logic;          -- data register read
// write data
// start of block signal
// channel status/user data
// user data ch. A enable
// user data ch. B enable
// channel status ch. A enable
// channel status ch. B enable
// read data
// capture event (interrupt)
wire [31:0] cap_ctrl_bits; wire [31:0] cap_ctrl_dout;
reg [31:0] cap_reg_1; reg [31:0] cap_new;
reg [31:0] bitlen; reg [31:0] cap_len;
reg [31:0] bitpos; reg [31:0] cur_pos;
wire chid; wire cdata; reg compared;
wire [3:0] d_enable;
  // Data bus or'ing
  assign cap_dout = cap_reg_1;
  // when cap_data_rd = '1' else cap_ctrl_dout;
  assign chid = cap_reg[6];
  assign cdata = cap_reg[7];
  // capture data register
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      cap_reg_1 <= {32{1'b0}};
      //
      cap_new <= {32{1'b0}};
      cur_pos <= 0;
      cap_len <= 0;
      cap_evt <= 1'b0;
      compared <= 1'b0;
      bitpos <= 0;
      bitlen <= 0;
    end else begin
      bitlen <= cap_reg[5:0];
      bitpos <= cap_reg[15:8];
      if(bitlen > 0) begin
        // bitlen = 0 disables the capture function
        // bit counter, 0 to 191
        if(rx_block_start == 1'b1) begin
          cur_pos <= 0;
          cap_len <= 0;
          cap_new <= {32{1'b0}};
          compared <= 1'b0;
        end
        else if(cs_b_en == 1'b1) begin
          // ch. status #2 comes last, count then
          cur_pos <= cur_pos + 1;
        end
        // capture bits
        if(cur_pos >= bitpos && cap_len < bitlen) begin
          case(d_enable)
          4'b0001 : begin
            // user data channel A
            if(cdata == 1'b0 && chid == 1'b0) begin
              cap_new[cap_len] <= ch_data;
              cap_len <= cap_len + 1;
            end
          end
          4'b0010 : begin
            // user data channel B
            if(cdata == 1'b0 && chid == 1'b1) begin
              cap_new[cap_len] <= ch_data;
              cap_len <= cap_len + 1;
            end
          end
          4'b0100 : begin
            // channel status ch. A
            if(cdata == 1'b1 && chid == 1'b0) begin
              cap_new[cap_len] <= ch_data;
              cap_len <= cap_len + 1;
            end
          end
          4'b1000 : begin
            // channel status ch. B
            if(cdata == 1'b1 && chid == 1'b1) begin
              cap_new[cap_len] <= ch_data;
              cap_len <= cap_len + 1;
            end
          end
          default : begin
          end
          endcase
        end
        // if all bits captured, check with previous data
        if(cap_len == bitlen && compared == 1'b0) begin
          compared <= 1'b1;
          // event generated if captured bits differ
          if(cap_reg_1 != cap_new) begin
            cap_evt <= 1'b1;
          end
          cap_reg_1 <= cap_new;
        end
        else begin
          cap_evt <= 1'b0;
        end
      end
    end
  end
  assign d_enable[0] = ud_a_en;
  assign d_enable[1] = ud_b_en;
  assign d_enable[2] = cs_a_en;
  assign d_enable[3] = cs_b_en;
endmodule

