module FlagBlock(
input wire clock,
input wire reset,
input wire ALUc,
input wire ALUz,
input wire Cen,
input wire Zen,
input wire ALUop,
input wire ALUcout,
input wire ALUzout,
output wire ALUvalid,
output wire [1:0] FR
);
// clock signal
// reset signal
// conditional carry flag change
// conditional zero flag change
// enable carry flag change
// enable zero flag change
// unconditional ALU operation
// the carry out from ALU
// the zero out from ALU
// whether the ALU output is valid or not
// Flag register
reg carry; reg zero;
  // behave
  assign ALUvalid = (carry & ALUc) | (zero & ALUz) | (ALUop);
  assign FR[0] = carry;
  assign FR[1] = zero;
  always @(posedge clock, posedge reset) begin
    if((reset == 1'b1)) begin
      carry <= 1'b0;
      // reset the register
      zero <= 1'b0;
    end
    else begin
      if((Cen == 1'b1)) begin
        carry <= ALUcout;
        // Update the carry register
      end
      if((Zen == 1'b1)) begin
        zero <= ALUzout;
        // Update the zero register
      end
    end
  end
endmodule

