module Controller_25AA02E48(
input wire CLK,
input wire [3:0] CLKDivH,
input wire [3:0] CLKDivL,
input wire ReadID,
output wire [47:0] ID,
output wire SCLK,
output wire CS,
output wire MOSI,
input wire MISO
);
//Signal BusyRegister : STD_LOGIC :='0';
//Signal DataRegister : STD_LOGIC_VECTOR (11 downto 0) :=(others=>'0');
//signal AddressRegister : STD_LOGIC_VECTOR (4 downto 0) :=(others=>'0');
reg [6:0] TransferRegister = 1'b0;  // Data and Address to be transfered. Only 15 bit because MSB is applied immidately at WE='1'
reg [7:0] ReadRegister = 8'hEE;
reg SCLKRegister = 1'b0; reg MOSIRegister = 1'b0;  // DAC draws less current if pins are low -> when idle pull low.
reg CSRegister = 1'b0;  // Chip select high when idle, low for initial read cycle
reg [3:0] ClockDivCounter = 0; reg [3:0] Final_counter = 0;  // How many CLK-Cycles has already been waited (update SCLK, when counter reached value set in interface), second: counter to release CS
reg [4:0] BitCounter = 0;  // How many bits have been transfered?
reg NCRESCLK;  // Next Clockcycle has Rising Edge on SCLK
reg NCFESCLK;  // Next Clockcycle has Falling Edge on SCLK
parameter [3:0]
  waiting = 0,
  write_instruction_byte = 1,
  write_address = 2,
  read1 = 3,
  read2 = 4,
  read3 = 5,
  read4 = 6,
  read5 = 7,
  read6 = 8,
  final_wait_to_CS = 9;
reg [3:0] cont_state = write_instruction_byte;
reg [7:0] ByteToSend = 8'h03;
reg [47:0] ReceivedID = 48'hDEADDEADBEEF;
reg WE = 1'b1;
reg BusyRegister = 1'b0;
  assign SCLK = SCLKRegister;
  assign MOSI = MOSIRegister;
  assign CS = CSRegister;
  //Busy<=BusyRegister;
  assign ID = ReceivedID;
  always @(posedge CLK) begin
    if(BusyRegister == 1'b0) begin
      // reset case
      ClockDivCounter <= 0;
      SCLKRegister <= 1'b0;
    end
    else begin
      ClockDivCounter <= ClockDivCounter + 1;
      if(SCLKRegister == 1'b1) begin
        if(CLKDivH == (ClockDivCounter)) begin
          SCLKRegister <= 1'b0;
          ClockDivCounter <= 0;
        end
      end
      else begin
        if(CLKDivL == (ClockDivCounter)) begin
          SCLKRegister <= 1'b1;
          ClockDivCounter <= 0;
        end
      end
    end
  end
  always @(CLKDivL, ClockDivCounter, SCLKRegister) begin
    if(CLKDivL == (ClockDivCounter) && SCLKRegister == 1'b0) begin
      NCRESCLK <= 1'b1;
    end
    else begin
      NCRESCLK <= 1'b0;
    end
  end
  always @(CLKDivH, ClockDivCounter, SCLKRegister) begin
    if(CLKDivH == (ClockDivCounter) && SCLKRegister == 1'b1) begin
      NCFESCLK <= 1'b1;
    end
    else begin
      NCFESCLK <= 1'b0;
    end
  end
  always @(posedge CLK) begin
    if(BusyRegister == 1'b0) begin
      if(WE == 1'b1) begin
        TransferRegister <= ByteToSend[6:0];
        BusyRegister <= 1'b1;
        //CSRegister<='0';
        MOSIRegister <= ByteToSend[7];
      end
    end
    else begin
      if(NCFESCLK == 1'b1) begin
        // on falling edge, bits are transfered-> increase number of transferred bits
        BitCounter <= BitCounter + 1;
        TransferRegister[6:1] <= TransferRegister[5:0];
        MOSIRegister <= TransferRegister[6];
        ReadRegister[7:1] <= ReadRegister[6:0];
        ReadRegister[0] <= MISO;
      end
      if(NCRESCLK == 1'b1) begin
        // on rising edge, change data (should work best because t_setup = t_hold = 2,5 ns)
      end
      if(BitCounter == (7) && NCFESCLK == 1'b1) begin
        // when 16 bits have been transfered, wait until clock to cipselect time is fullfilled (min 10 ns, 
        //CSRegister<='1';
        BusyRegister <= 1'b0;
        BitCounter <= 0;
      end
    end
  end
  always @(posedge CLK) begin
    case(cont_state)
    waiting : begin
      WE <= 1'b0;
      CSRegister <= 1'b1;
      if(ReadID == 1'b1) begin
        CSRegister <= 1'b0;
        cont_state <= write_instruction_byte;
        ByteToSend <= 8'h03;
        WE <= 1'b1;
      end
    end
    write_instruction_byte : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= write_address;
        ByteToSend <= 8'hFA;
        WE <= 1'b1;
      end
    end
    write_address : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read1;
        ByteToSend <= 8'h00;
        WE <= 1'b1;
      end
    end
    read1 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read2;
        ByteToSend <= 8'h00;
        WE <= 1'b1;
        ReceivedID[47:40] <= ReadRegister;
      end
    end
    read2 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read3;
        //ByteToSend <= X"00";
        ReceivedID[39:32] <= ReadRegister;
        WE <= 1'b1;
      end
    end
    read3 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read4;
        //ByteToSend <= X"00";
        ReceivedID[31:24] <= ReadRegister;
        WE <= 1'b1;
      end
    end
    read4 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read5;
        //ByteToSend <= X"00";
        ReceivedID[23:16] <= ReadRegister;
        WE <= 1'b1;
      end
    end
    read5 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= read6;
        //ByteToSend <= X"00";
        ReceivedID[15:8] <= ReadRegister;
        WE <= 1'b1;
      end
    end
    read6 : begin
      WE <= 1'b0;
      if(BusyRegister == 1'b0 && WE == 1'b0) begin
        cont_state <= final_wait_to_CS;
        //ByteToSend <= X"00";
        ReceivedID[7:0] <= ReadRegister;
        Final_counter <= 0;
      end
    end
    final_wait_to_CS : begin
      Final_counter <= Final_counter + 1;
      if(CLKDivL == (Final_counter)) begin
        cont_state <= waiting;
      end
    end
    default : begin
    end
    endcase
  end
endmodule

