module cpu2periph(
input wire clk_cpu,
input wire reset,
input wire cpu_write,
input wire [3:0] cpu_data,
input wire buffok,
output reg setbuff,
output reg [7:0] pcbuff,
output reg cpu_ready,
output wire debug
);
//established : in  STD_LOGIC;
reg [7:0] buff;
parameter [2:0]
  WAIT4EMPTYBUFF = 0,
  WAIT4MSB = 1,
  RXMSB = 2,
  WAIT4LSB = 3,
  RXLSB = 4;
reg [2:0] CurrState;
reg dbg;
  always @(posedge clk_cpu, posedge reset) begin
    if(reset == 1'b1) begin
      CurrState <= WAIT4EMPTYBUFF;
      buff <= {8{1'b0}};
      pcbuff <= {8{1'b0}};
      cpu_ready <= 1'b0;
      dbg <= 1'b0;
    end else begin
      case(CurrState)
      WAIT4EMPTYBUFF : begin
        //wait until the BUFFOK flag is cleared, which hopefully happens fast enough, and connection is established
        setbuff <= 1'b0;
        if(buffok == 1'b0) begin
          //and established = '1' then
          CurrState <= WAIT4MSB;
        end
      end
      WAIT4MSB : begin
        //wait for CPU to request a write
        if(cpu_write == 1'b1) begin
          cpu_ready <= 1'b1;
          CurrState <= RXMSB;
        end
      end
      RXMSB : begin
        //meh, quite a useless state
        //	CurrState <= STOPMSB;
        //when STOPMSB =>	--set ready low, and while cpu_write is still high, copy its data to the buffer
        //	cpu_ready <= '0';
        if(cpu_write == 1'b1) begin
          buff[7:4] <= cpu_data;
        end
        else begin
          cpu_ready <= 1'b0;
          CurrState <= WAIT4LSB;
        end
      end
      WAIT4LSB : begin
        //wait for CPU to request a write
        if(cpu_write == 1'b1) begin
          cpu_ready <= 1'b1;
          CurrState <= RXLSB;
        end
      end
      RXLSB : begin
        //meh, quite a useless state
        //	CurrState <= STOPLSB;
        //when STOPLSB =>	--set ready low, and while cpu_write is still high, copy its data to the buffer
        //	cpu_ready <= '0';
        if(cpu_write == 1'b1) begin
          buff[3:0] <= cpu_data;
        end
        else begin
          //Our data is ready, put it into the PCBUFF and set the BUFFOK flag
          cpu_ready <= 1'b0;
          pcbuff <= buff;
          setbuff <= 1'b1;
          CurrState <= WAIT4EMPTYBUFF;
        end
        dbg <=  ~dbg;
      end
      endcase
    end
  end
  assign debug = dbg;
endmodule

