module slib_edge_detect(
input wire CLK,
input wire RST,
input wire D,
output wire RE,
output wire FE
);
// Clock
// Reset
// Signal input
// Rising edge detected
// Falling edge detected
reg iDd;  // D register
  // Store D
  always @(posedge RST, posedge CLK) begin
    if((RST == 1'b1)) begin
      iDd <= 1'b0;
    end else begin
      iDd <= D;
    end
  end
  // Output ports
  assign RE = iDd == 1'b0 && D == 1'b1 ? 1'b1 : 1'b0;
  assign FE = iDd == 1'b1 && D == 1'b0 ? 1'b1 : 1'b0;
endmodule

