module register_file(
input wire Wren,
input wire rst,
input wire [5:0] rs1,
input wire [5:0] rs2,
input wire [5:0] rd,
input wire [31:0] data,
output reg [31:0] crs1,
output reg [31:0] crs2,
output reg [31:0] crd
);
reg [31:0] reg[0:39] = 32'h00000000;
  always @(rst, rs1, rs2, rd, data) begin
    if((rst == 1'b0)) begin
      crs1 <= reg[rs1];
      crs2 <= reg[rs2];
      crd <= reg[rd];
      if((rd != 5'b00000 && Wren == 1'b1)) begin
        reg[rd] <= data;
      end
    end
    else if((rst == 1'b1)) begin
      crs1 <= 32'h00000000;
      crs2 <= 32'h00000000;
      reg <= {32{32'h00000000}};
    end
  end
endmodule

