module c_comparator(
input wire [width - 1:0] input1,
input wire [width - 1:0] input2,
output reg [2:0] output
);
parameter [31:0] width=16;
  always @(input1, input2) begin : P1
    reg [2:0] result;
    result = 3'b000;
    if((input1 == input2)) begin
      result[0] = 1'b1;
    end
    else if((input1 > input2)) begin
      result[1] = 1'b1;
    end
    else if((input1 < input2)) begin
      result[2] = 1'b1;
    end
    output <= result;
  end
endmodule

