input wire RstxRBI,
input wire [1:0] SelectxDI,
input wire [C_AXIS_TDATA_WIDTH - 1:0] Data0xDI,
input wire [C_AXIS_TDATA_WIDTH - 1:0] Data1xDI,
input wire [C_AXIS_TDATA_WIDTH - 1:0] Data2xDI,
input wire [C_AXIS_TDATA_WIDTH - 1:0] Data3xDI,
input wire Valid0xSI,
input wire Valid1xSI,
input wire Valid2xSI,
input wire Valid3xSI,
output reg Ready0xSO,
output reg Ready1xSO,
output reg Ready2xSO,
output reg Ready3xSO,
output reg [C_AXIS_TDATA_WIDTH - 1:0] DataxDO,
output reg ValidxSO,
input wire ReadyxSI
);
parameter [31:0] C_AXIS_TDATA_WIDTH=32;
parameter [31:0] C_AXIS_NUM_SI_SLOTS=2;
  always @(Data0xDI, Data1xDI, Data2xDI, Data3xDI, Valid0xSI, Valid1xSI, Valid2xSI, Valid3xSI, ReadyxSI, SelectxDI) begin
    case(SelectxDI)
    2'b00 : begin
      DataxDO <= Data0xDI;
      ValidxSO <= Valid0xSI;
      Ready0xSO <= ReadyxSI;
    end
    2'b01 : begin
      DataxDO <= Data1xDI;
      ValidxSO <= Valid1xSI;
      Ready1xSO <= ReadyxSI;
    end
    2'b10 : begin
      DataxDO <= Data2xDI;
      ValidxSO <= Valid2xSI;
      Ready2xSO <= ReadyxSI;
    end
    2'b11 : begin
      DataxDO <= Data3xDI;
      ValidxSO <= Valid3xSI;
      Ready3xSO <= ReadyxSI;
    end
    default : begin
      DataxDO <= Data0xDI;
      ValidxSO <= Valid0xSI;
      Ready0xSO <= ReadyxSI;
    end
    endcase
  end
endmodule

module ov7670_vga(
