input wire [7:0] data,
output reg [15:0] rgb
);
  always @(posedge pclk) begin : P1
    reg cycle = 1'b0;
    if(cycle == 1'b0) begin
      rgb[15:8] <= data;
      cycle = 1'b1;
    end
    else begin
      rgb[7:0] <= data;
      cycle = 1'b0;
    end
  end
endmodule

