module pwm(
input wire clk,
input wire [N - 1:0] value,
output reg output
);
parameter [31:0] N=4;
reg [N - 1:0] accumulator;
wire [N - 1:0] accum_next;
wire pwm_next;
  always @(negedge clk) begin
    accumulator <= accum_next;
    output <= pwm_next;
  end
  assign accum_next = accumulator + 1'b1;
  assign pwm_next = (accumulator < value) ? 1'b1 : 1'b0;
endmodule

module counter(
