input wire reset,
output wire [3:0] Q
);
parameter [31:0] Nbits=4;
parameter [31:0] Nmax=9;
reg [3:0] cpt;
wire enable;
  assign Q = cpt;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      cpt <= {4{1'b0}};
    end
    else if(enable == 1'b1) begin
      cpt <= cpt + 1;
    end
  end
endmodule

