module VGA640x480(
input wire reset,
input wire clk_0,
output wire clk50,
output reg hs,
output reg vs,
output reg [2:0] r,
output reg [2:0] g,
output reg [2:0] b,
output reg [9:0] req_x,
output reg [9:0] req_y,
input wire [2:0] res_r,
input wire [2:0] res_g,
input wire [2:0] res_b
);
//100m时钟输入
//50m时钟输出
//行同步、场同步信号
// 向渲染模块询问坐标
// 渲染模块输出的颜色
reg [2:0] r1; reg [2:0] g1; reg [2:0] b1;
reg hs1; reg vs1;
reg [9:0] vector_x; reg [9:0] vector_y;  //x 坐标
reg clk; reg clk_1;
  assign clk50 = clk_1;
  //-------------------------------------------------------------------
  always @(posedge clk_0) begin : P10
  //对100m输入信号二分频
    clk_1 <=  ~clk_1;
  end
  always @(posedge clk_1) begin : P9
  //对50m输入信号二分频
    clk <=  ~clk;
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P8
  //行区间像素数（含消隐区）
    if((reset == 1'b0)) begin
      vector_x <= {10{1'b0}};
    end else begin
      if((vector_x == 799)) begin
        vector_x <= {10{1'b0}};
      end
      else begin
        vector_x <= vector_x + 1;
      end
    end
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P7
  //场区间行数（含消隐区）
    if((reset == 1'b0)) begin
      vector_y <= {10{1'b0}};
    end else begin
      if((vector_x == 799)) begin
        if((vector_y == 524)) begin
          vector_y <= {10{1'b0}};
        end
        else begin
          vector_y <= vector_y + 1;
        end
      end
    end
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P6
  //行同步信号产生（同步宽度96，前沿16）
    if((reset == 1'b0)) begin
      hs1 <= 1'b1;
    end else begin
      if((vector_x >= 656 && vector_x < 752)) begin
        hs1 <= 1'b0;
      end
      else begin
        hs1 <= 1'b1;
      end
    end
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P5
  //场同步信号产生（同步宽度2，前沿10）
    if((reset == 1'b0)) begin
      vs1 <= 1'b1;
    end else begin
      if((vector_y >= 490 && vector_y < 492)) begin
        vs1 <= 1'b0;
      end
      else begin
        vs1 <= 1'b1;
      end
    end
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P4
  //行同步信号输出
    if((reset == 1'b0)) begin
      hs <= 1'b0;
    end else begin
      hs <= hs1;
    end
  end
  //-------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin : P3
  //场同步信号输出
    if((reset == 1'b0)) begin
      vs <= 1'b0;
    end else begin
      vs <= vs1;
    end
  end
  //-------------------------------------------------------------------
  always @(posedge reset, posedge clk, posedge vector_x, posedge vector_y) begin : P2
  // xy坐标定位控制
    if((reset == 1'b0)) begin
      r1 <= 3'b000;
      g1 <= 3'b000;
      b1 <= 3'b000;
    end else begin
      if((vector_x < 640 && vector_y < 480)) begin
        req_x <= vector_x;
        req_y <= vector_y;
        r1 <= res_r;
        g1 <= res_g;
        b1 <= res_b;
      end
      else begin
        r1 <= 3'b000;
        g1 <= 3'b000;
        b1 <= 3'b000;
      end
    end
  end
  //-------------------------------------------------------------------
  always @(hs1, vs1, r1, g1, b1) begin : P1
  //色彩输出
    if((hs1 == 1'b1 && vs1 == 1'b1)) begin
      r <= r1;
      g <= g1;
      b <= b1;
    end
    else begin
      r <= {3{1'b0}};
      g <= {3{1'b0}};
      b <= {3{1'b0}};
    end
  end
endmodule

module n(
input wire clk,
input wire reset,
input wire [7:0] entrada,
output reg [3:0] anode,
output wire [6:0] display_out
);
// TYPES:
parameter [1:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3;
  // SIGNALS:
reg [1:0] STATE; reg [1:0] NEXT_STATE;
wire [7:0] binary_to_bcd_conversor_IN_DATA;
wire [9:0] binary_to_bcd_conversor_OUT_DATA;
reg [3:0] seg7_IN_DATA;
wire [6:0] seg7_OUT_DATA;
  binToBCD binary_to_bcd(
      .binary(8'b00000001),
    .bcd(binary_to_bcd_conversor_OUT_DATA));
  bcdTo7SEG bcd_to_7seg(
      .clk(clk),
    .bcd(seg7_IN_DATA),
    .segmented(seg7_OUT_DATA));
  always @(STATE, binary_to_bcd_conversor_OUT_DATA) begin
    case(STATE)
    S0 : begin
      anode <= 4'b1110;
      seg7_IN_DATA <= binary_to_bcd_conversor_OUT_DATA[3:0];
      NEXT_STATE <= S1;
    end
    S1 : begin
      anode <= 4'b1101;
      seg7_IN_DATA <= binary_to_bcd_conversor_OUT_DATA[7:4];
      NEXT_STATE <= S2;
    end
    S2 : begin
      anode <= 4'b1011;
      seg7_IN_DATA <= {2'b00,binary_to_bcd_conversor_OUT_DATA[9:8]};
      NEXT_STATE <= S3;
    end
    S3 : begin
      anode <= 4'b0111;
      seg7_IN_DATA <= 4'b0000;
      NEXT_STATE <= S0;
    end
    default : begin
      anode <= 4'b1110;
      seg7_IN_DATA <= 4'b0010;
      NEXT_STATE <= S0;
    end
    endcase
  end
  assign display_out = seg7_OUT_DATA;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      STATE <= S0;
    end else begin
      STATE <= NEXT_STATE;
    end
  end
endmodule

