module fx2fpga(
input wire reset,
input wire ifclk,
input wire flagA,
input wire flagB,
input wire int0,
input wire int1,
input wire pa3,
input wire pa7,
input wire clkout,
input wire [7:0] pd,
output wire dummy,
input wire [7:0] fd,
input wire gotData,
output wire sloe,
output wire slrd,
output wire slwr,
output wire [1:0] fifoAddr,
output wire pktEnd,
output reg [7:0] sseg,
output reg [3:0] anode,
input wire [2:0] sw,
output wire [7:0] led_out
);
parameter [31:0] COUNTER_WIDTH=18;
// Unused connections must be configured as inputs
// PA0
// PA1
// PA3
// PA7
// Dummy output, not connected to FX2
// Data & control from the FX2
// FLAGC
// Control to the FX2
// PA2
// PA4 & PA5
// PA6
// Onboard peripherals
reg [COUNTER_WIDTH - 1:0] counter; wire [COUNTER_WIDTH - 1:0] counter_next;
reg [3:0] hex;
reg [15:0] checksum; wire [15:0] checksum_next;
reg [7:0] led; wire [7:0] led_next;
  always @(posedge ifclk, posedge reset) begin
    if((reset == 1'b1)) begin
      counter <= {((COUNTER_WIDTH - 1)-(0)+1){1'b0}};
      checksum <= {16{1'b0}};
      led <= {8{1'b0}};
    end else begin
      counter <= counter_next;
      checksum <= checksum_next;
      led <= led_next;
    end
  end
  // binary counter
  assign counter_next = counter + 1;
  // Tri-stating doesn't seem to work...set them all as inputs
  assign dummy = flagA & flagB & int0 & int1 & pa3 & pa7 & clkout & pd[0] & pd[1] & pd[1] & pd[2] & pd[3] & pd[4] & pd[5] & pd[6] & pd[7];
  assign led_out = led;
  assign fifoAddr = sw[2] == 1'b1 ? sw[1:0] : {2{1'bZ}};
  assign sloe = sw[2] == 1'b1 ? 1'b0 : 1'bZ;
  assign slrd = sw[2] == 1'b1 ? 1'b0 : 1'bZ;
  assign slwr = sw[2] == 1'b1 ? 1'b1 : 1'bZ;
  assign pktEnd = sw[2] == 1'b1 ? 1'b1 : 1'bZ;
  assign checksum_next = gotData == 1'b1 ? checksum + (fd) : checksum;
  assign led_next = gotData == 1'b1 ? fd : led;
  // process to choose which 7-seg display to light
  always @(counter[17:16], checksum) begin
    case(counter[17:16])
    2'b00 : begin
      anode <= 4'b1110;
      hex <= checksum[3:0];
      sseg[7] <= 1'b1;
    end
    2'b01 : begin
      anode <= 4'b1101;
      hex <= checksum[7:4];
      sseg[7] <= 1'b1;
    end
    2'b10 : begin
      anode <= 4'b1011;
      hex <= checksum[11:8];
      sseg[7] <= 1'b1;
    end
    default : begin
      anode <= 4'b0111;
      hex <= checksum[15:12];
      sseg[7] <= 1'b1;
    end
    endcase
  end
  // combinatorial logic to display the correct pattern based
  // on the output of the selector process above.
  always @(*) begin
    case(hex)
      4'b0000 : sseg[6:0] <= 7'b0000001;
      4'b0001 : sseg[6:0] <= 7'b1001111;
      4'b0010 : sseg[6:0] <= 7'b0010010;
      4'b0011 : sseg[6:0] <= 7'b0000110;
      4'b0100 : sseg[6:0] <= 7'b1001100;
      4'b0101 : sseg[6:0] <= 7'b0100100;
      4'b0110 : sseg[6:0] <= 7'b0100000;
      4'b0111 : sseg[6:0] <= 7'b0001111;
      4'b1000 : sseg[6:0] <= 7'b0000000;
      4'b1001 : sseg[6:0] <= 7'b0000100;
      4'b1010 : sseg[6:0] <= 7'b0001000;
  // a
      4'b1011 : sseg[6:0] <= 7'b1100000;
  // b
      4'b1100 : sseg[6:0] <= 7'b0110001;
  // c
      4'b1101 : sseg[6:0] <= 7'b1000010;
  // d
      4'b1110 : sseg[6:0] <= 7'b0110000;
  // e
      default : sseg[6:0] <= 7'b0111000;
    endcase
  end
    // f
endmodule

