module alu(
input wire [3:0] n,
input wire [3:0] m,
input wire [1:0] opcode,
output wire [3:0] d,
output wire cout
);
wire [3:0] m_inverted;
wire [3:0] nand_result;
wire [3:0] nor_result;
wire [3:0] adder_result;
wire adder_carry_out;
wire operation_type;
wire sub;
  // Make sense from control bits
  assign operation_type = opcode[1];
  // Are we doing logical or arithmetic operation?
  assign sub = opcode[0];
  // Are we doing addition/NAND or subtraction/NOR?
  // Here we calculate inverted bits for subtraction if necessary
  assign m_inverted[0] =  ~m[0];
  assign m_inverted[1] =  ~m[1];
  assign m_inverted[2] =  ~m[2];
  assign m_inverted[3] =  ~m[3];
  // Addition
  carry_ripple_adder adder_instance(
      .a(n),
    .b(m_inverted),
    .ci(1'b1),
    .s(adder_result),
    .co(adder_carry_out));
  // Logical NAND operation
  assign nand_result[0] =  ~m[0] & n[0];
  assign nand_result[1] =  ~m[1] & n[1];
  assign nand_result[2] =  ~m[2] & n[2];
  assign nand_result[3] =  ~m[3] & n[3];
  // Logical NOR operation
  assign nor_result[0] =  ~m[0] | n[0];
  assign nor_result[1] =  ~m[1] | n[1];
  assign nor_result[2] =  ~m[2] | n[2];
  assign nor_result[3] =  ~m[3] | n[3];
  // Select output based on which operation was requested
  assign d = opcode == 2'b10 ? nand_result : opcode == 2'b11 ? nor_result : adder_result;
  // Carry out bit
  assign cout = operation_type == 1'b0 ? adder_carry_out ^ sub : 1'b0;
endmodule

