module ascon_shift_register(
input wire ClkxCI,
input wire RstxRBI,
input wire ShiftEnablexSI,
input wire ShiftRegINxDI,
output wire [DATA_WIDTH - 1:0] ShiftRegOUTxDO
);
parameter [63:0] RESET_VALUE=64'h0000000000000000;
parameter [31:0] DATA_WIDTH=64;
reg [DATA_WIDTH - 1:0] DataxDP;
  // architecture structural
  assign ShiftRegOUTxDO = DataxDP;
  // purpose: Left shift each cycle
  // type   : sequential
  // inputs : ClkxCI, RstxRBI
  // outputs: DataOUTxDO
  always @(posedge ClkxCI, posedge RstxRBI) begin
      // process shift_p
    if(RstxRBI == 1'b0) begin
      // asynchronous reset (active low)
      DataxDP <= RESET_VALUE;
    end else begin
      // rising clock edge
      if(ShiftEnablexSI == 1'b1) begin
        DataxDP <= {DataxDP[DATA_WIDTH - 2:0],ShiftRegINxDI};
        // shift left
      end
    end
  end
endmodule

module system(
input wire rst,
input wire clk,
input wire btn0,
input wire rxd,
output wire txd,
output wire evn1,
output wire evn2,
output wire led0,
output wire led1
);
// system reset, high active
// system clock, 50 MHz, rising edge active
// push button, low active
// receiver signal
// transmitter signal
// event1, interrupt, high active
// event2, RETURNI, high active
// led, low active
// led, low active
parameter RSTDEF = 1'b1;  // high active
wire reset;  // high active
wire sbtn0;
wire srxd;
reg [8:0] enable;
wire [1:0] led;
wire en0;
wire en1;
wire [9:0] address;
wire [17:0] instruction;
wire [7:0] port_id;
wire write_strobe;  // high active
wire [7:0] out_port;
wire read_strobe;  // high active
reg [7:0] in_port;
wire interrupt;  // high active
wire interrupt_ack;  // high active
reg [10:0] addra;
wire [7:0] dout1;
wire wea;
wire [7:0] dout2;
wire [10:0] addrb;
wire [7:0] dib;
wire [7:0] dob;
wire enb;
wire web;
  // -----------------------------------------------------------------------------
  assign evn1 = interrupt;
  assign evn2 = instruction[17:14] == 4'b1110 ? 1'b1 : 1'b0;
  // Resetgenarator und Synchronisation des Resetsignals mit dem System
  FDSx2 sync_rst(
      .D(1'b0),
    .Q(reset),
    .S(rst),
    .C(clk));
  // -----------------------------------------------------------------------------
  // Synchronisation des Eingangssignals RXD mit dem System
  FDSx2 sync_rxd(
      .D(rxd),
    .Q(srxd),
    .S(reset),
    .C(clk));
  // -----------------------------------------------------------------------------
  // Synchronisation des Eingangssignals BTN0 mit dem System
  FDSx2 sync_btn0(
      .D(btn0),
    .Q(sbtn0),
    .S(reset),
    .C(clk));
  // -----------------------------------------------------------------------------
  assign en1 = enable[1] & write_strobe;
  // Flipflop fuer das serielle Datenausgangssignal TXD
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  txd_ff(
      .D(out_port[0]),
    .Q(txd),
    .CE(en1),
    .S(reset),
    .C(clk));
  assign en0 = enable[0] & write_strobe;
  // Flipflop fuer das Steuerungssignals der LED0
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  led0_ff(
      .D(out_port[0]),
    .Q(led[0]),
    .CE(en0),
    .S(reset),
    .C(clk));
  // Flipflop fuer das Steuerungssignals der LED1
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  led1_ff(
      .D(out_port[1]),
    .Q(led[1]),
    .CE(en0),
    .S(reset),
    .C(clk));
  assign led0 = led[0];
  assign led1 = led[1];
  // -----------------------------------------------------------------------------
  // Timer
  timer #(
      .RSTDEF(RSTDEF))
  t1(
      .rst(reset),
    .clk(clk),
    .irq(interrupt),
    .iack(interrupt_ack));
  // -----------------------------------------------------------------------------
  // Dekoder
  always @(*) begin
    case(port_id[3:0])
      4'b0000 : enable <= 9'b000000001;
  // LED0, LED1
      4'b0001 : enable <= 9'b000000010;
  // transmitter bit
      4'b0010 : enable <= 9'b000000100;
  // a7..a0 ram address
      4'b0011 : enable <= 9'b000001000;
  // a10..a8 ram address
      4'b0100 : enable <= 9'b000010000;
  // ram data
      4'b1000 : enable <= 9'b000100000;
  // control register
      4'b1001 : enable <= 9'b000100000;
  // p7..p0 pointer
      4'b1010 : enable <= 9'b000100000;
  // p10..p8 pointer
      4'b1011 : enable <= 9'b000100000;
  // length
      default : enable <= 9'b000000000;
    endcase
  end
  always @(*) begin
    case(port_id[3:0])
      4'b0000 : in_port <= {5'b00000,sbtn0,led};
  // button & leds
      4'b0001 : in_port <= {7'b0000000,srxd};
  // receiver bit
      4'b0010 : in_port <= addra[7:0];
  // a7..a0 ram adress
      4'b0011 : in_port <= {5'b00000,addra[10:8]};
  // a10..a8 ram address
      4'b0100 : in_port <= dout1;
  // ram data
      default : in_port <= dout2;
    endcase
  end
  // interface to asic
  // -----------------------------------------------------------------------------
  kcpsm3 cpu(
      .reset(reset),
    .clk(clk),
    .address(address),
    .instruction(instruction),
    .port_id(port_id),
    .write_strobe(write_strobe),
    .out_port(out_port),
    .read_strobe(read_strobe),
    .in_port(in_port),
    .interrupt(interrupt),
    .interrupt_ack(interrupt_ack));
  // -----------------------------------------------------------------------------
  // programm memory
  programm rom(
      .clk(clk),
    .address(address),
    .instruction(instruction));
  // -----------------------------------------------------------------------------
  // address register
  always @(posedge rst, posedge clk) begin
    if(rst == RSTDEF) begin
      addra <= {11{1'b0}};
    end else begin
      if(enable[2] == 1'b1 && write_strobe == 1'b1) begin
        addra[7:0] <= out_port;
      end
      if(enable[3] == 1'b1 && write_strobe == 1'b1) begin
        addra[10:8] <= out_port[2:0];
      end
    end
  end
  assign wea = enable[4] & write_strobe;
  // data memory
  RAMB16_S9_S9 ram(
      // interface to PicoBlaze
    .DOA(dout1),
    // Port A 8-bit Data Output
    .DOPA(/* open */),
    // Port A 1-bit Parity Output
    .ADDRA(addra),
    // Port A 11-bit Address Input
    .CLKA(clk),
    // Port A Clock
    .DIA(out_port),
    // Port A 8-bit Data Input
    .DIPA(1'b0),
    // Port A 1-bit parity Input
    .ENA(1'b1),
    // Port A RAM Enable Input
    .SSRA(reset),
    // Port A Synchronous Set/Reset Input
    .WEA(wea),
    // Port A Write Enable Input
    // interface to co-processor
    .DOB(DOB),
    // Port B 8-bit Data Output
    .DOPB(/* open */),
    // Port B 1-bit Parity Output
    .ADDRB(ADDRB),
    // Port B 11-bit Address Input
    .CLKB(CLK),
    // Port B Clock
    .DIB(DIB),
    // Port B 8-bit Data Input
    .DIPB(1'b0),
    // Port-B 1-bit parity Input
    .ENB(ENB),
    // Port B RAM Enable Input      
    .SSRB(reset),
    // Port B Synchronous Set/Reset Input
    .WEB(WEB));
  // -----------------------------------------------------------------------------
  insertsort #(
      .RSTDEF(RSTDEF))
  asic(
      .rst(rst),
    .clk(clk),
    // interface to PicoBlaze
    .rsel(port_id),
    .din(out_port),
    .dout(dout2),
    .ena(enable[5]),
    .wre(write_strobe),
    // interface to RAM block through port B
    .WEB(WEB),
    .ENB(ENB),
    .ADDRB(ADDRB),
    .DIB(DOB),
    .DOB(DIB));
endmodule

module FlashIO(
input wire [22:1] addr,
input wire [15:0] datain,
output reg [15:0] dataout,
input wire clk,
input wire reset,
output wire flash_byte,
output wire flash_vpen,
output wire flash_ce,
output reg flash_oe,
output reg flash_we,
output wire flash_rp,
output reg [22:1] flash_addr,
inout reg [15:0] flash_data,
input wire ctl_read,
input wire ctl_write,
input wire ctl_erase
);
// ×ÖÄ£Ê½ÏÂÎª22-1£¬×Ö½ÚÄ£Ê½Îª22-0
// hard port connecting flash chip
// signal to vhdl entity
parameter [4:0]
  waiting = 0,
  write1 = 1,
  write2 = 2,
  write3 = 3,
  write4 = 4,
  write5 = 5,
  read1 = 6,
  read2 = 7,
  read3 = 8,
  read4 = 9,
  sr1 = 10,
  sr2 = 11,
  sr3 = 12,
  sr4 = 13,
  sr5 = 14,
  erase1 = 15,
  erase2 = 16,
  erase3 = 17,
  erase4 = 18,
  erase5 = 19,
  erase6 = 20,
  done = 21;
reg [4:0] state = waiting;
reg [4:0] next_state = waiting;
reg ctl_read_last; reg ctl_write_last; reg ctl_erase_last;
  // always set 1 for ×ÖÄ£Ê½
  assign flash_byte = 1'b1;
  // write protect, always 1
  assign flash_vpen = 1'b1;
  // ce is enable, 0 is selected, 1 is not.
  assign flash_ce = 1'b0;
  // 0 is reset, 1 is work, always 1
  assign flash_rp = 1'b1;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b0)) begin
      dataout <= {16{1'b0}};
      flash_oe <= 1'b1;
      flash_we <= 1'b1;
      state <= waiting;
      next_state <= waiting;
      ctl_read_last <= ctl_read;
      ctl_write_last <= ctl_write;
      ctl_erase_last <= ctl_erase;
      flash_data <= {16{1'bZ}};
    end else begin
      case(state)
            // wait(initial)
      waiting : begin
        // store last so you can change the value
        // to triggle the action when necessary
        if((ctl_read != ctl_read_last)) begin
          flash_we <= 1'b0;
          state <= read1;
          ctl_read_last <= ctl_read;
        end
        else if((ctl_write != ctl_write_last)) begin
          flash_we <= 1'b0;
          state <= write1;
          ctl_write_last <= ctl_write;
        end
        else if((ctl_erase != ctl_erase_last)) begin
          flash_we <= 1'b0;
          dataout[0] <= 1'b0;
          state <= erase1;
          ctl_erase_last <= ctl_erase;
        end
        // write
      end
      write1 : begin
        flash_data <= 16'h0040;
        state <= write2;
      end
      write2 : begin
        flash_we <= 1'b1;
        state <= write3;
      end
      write3 : begin
        flash_we <= 1'b0;
        state <= write4;
      end
      write4 : begin
        flash_addr <= addr;
        flash_data <= datain;
        state <= write5;
      end
      write5 : begin
        flash_we <= 1'b1;
        state <= sr1;
        next_state <= done;
        // small loop CM in write
        // write 6 is sr1
      end
      sr1 : begin
        flash_we <= 1'b0;
        flash_data <= 16'h0070;
        state <= sr2;
      end
      sr2 : begin
        flash_we <= 1'b1;
        state <= sr3;
      end
      sr3 : begin
        flash_data <= {16{1'bZ}};
        state <= sr4;
      end
      sr4 : begin
        flash_oe <= 1'b0;
        state <= sr5;
      end
      sr5 : begin
        flash_oe <= 1'b1;
        if(flash_data[7] == 1'b0) begin
          state <= sr1;
        end
        else begin
          state <= next_state;
        end
        // read
      end
      read1 : begin
        flash_data <= 16'h00FF;
        state <= read2;
      end
      read2 : begin
        flash_we <= 1'b1;
        state <= read3;
      end
      read3 : begin
        flash_oe <= 1'b0;
        flash_addr <= addr;
        flash_data <= {16{1'bZ}};
        state <= read4;
      end
      read4 : begin
        dataout <= flash_data;
        state <= done;
        // erase
      end
      erase1 : begin
        flash_data <= 16'h0020;
        state <= erase2;
      end
      erase2 : begin
        flash_we <= 1'b1;
        state <= erase3;
      end
      erase3 : begin
        flash_we <= 1'b0;
        state <= erase4;
      end
      erase4 : begin
        flash_data <= 16'h00D0;
        flash_addr <= addr;
        state <= erase5;
      end
      erase5 : begin
        flash_we <= 1'b1;
        next_state <= erase6;
        state <= sr1;
        // jump to sr1
        // return back from sr5
      end
      erase6 : begin
        state <= done;
        dataout[0] <= 1'b1;
      end
      default : begin
        flash_oe <= 1'b1;
        flash_we <= 1'b1;
        flash_data <= {16{1'bZ}};
        state <= waiting;
      end
      endcase
    end
  end
endmodule

