module grade(
input wire rst,
input wire clk,
input wire [163:0] a,
output reg done,
output wire [7:0] c
);
//--------------------------------------------------------------------------------------------------
//--------------------------------------------------------------------------------------------------
reg [7:0] counter;  // keeps the track of the grade 
reg [163:0] a_int;  // register and shifter for the input a
wire [163:0] a_shift;  //--------------------------------------------------------------------------------------------------
parameter [0:0]
  END_STATE = 0,
  E0 = 1;
  // the finite stte machine
reg State;  //--------------------------------------------------------------------------------------------------
  //--------------------------------------------------------------------------------------------------	
  assign c = counter;
  // Output
  assign a_shift = {a_int[162:0],1'b0};
  // shift to lefts of the internal register for the input
  //-------------------------------------------------------------------------------------------------- 
  // Finite state machine for computing the grade of the input polynomial
  //--------------------------------------------------------------------------------------------------
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      // synchronous resert signal, the input needs to be valid at the moment
      a_int <= a;
      counter <= 8'b10100011;
      // NUM_BITS , in this case it is 163
      Done <= 1'b0;
      State <= E0;
    end
    else begin
      case(State)
            //----------------------------------------------------------------------------
      E0 : begin
        // The operation concludes when it founds the most significant bit of the input
        if(a_int[163] == 1'b1 || counter == 8'b00000000) begin
          done <= 1'b1;
          State <= END_STATE;
        end
        else begin
          counter <= counter - 1;
          a_int <= a_shift;
          // Check out if the next bit of the input is '1'
        end
        //----------------------------------------------------------------------------
      end
      END_STATE : begin
        // Do nothing, just wait the reset signal again
        State <= END_STATE;
        //----------------------------------------------------------------------------
      end
      default : begin
      end
      endcase
    end
  end
endmodule

