module RegisterFile(
input wire clk,
input wire rst,
input wire [BitWidth - 1:0] Data_in_mem,
input wire [BitWidth - 1:0] Data_in_CU,
input wire [BitWidth - 1:0] Data_in_ACC,
input wire [1:0] Data_in_sel,
input wire [7:0] Register_in_sel,
input wire [2:0] Register_out_sel,
output reg [BitWidth - 1:0] Data_out
);
parameter [31:0] BitWidth;
reg [BitWidth - 1:0] R0_in = 1'b0; reg [BitWidth - 1:0] R0_out = 1'b0;
reg [BitWidth - 1:0] R1_in = 1'b0; reg [BitWidth - 1:0] R1_out = 1'b0;
reg [BitWidth - 1:0] R2_in = 1'b0; reg [BitWidth - 1:0] R2_out = 1'b0;
reg [BitWidth - 1:0] R3_in = 1'b0; reg [BitWidth - 1:0] R3_out = 1'b0;
reg [BitWidth - 1:0] R4_in = 1'b0; reg [BitWidth - 1:0] R4_out = 1'b0;
reg [BitWidth - 1:0] R5_in = 1'b0; reg [BitWidth - 1:0] R5_out = 1'b0;
reg [BitWidth - 1:0] R6_in = 1'b0; reg [BitWidth - 1:0] R6_out = 1'b0;
reg [BitWidth - 1:0] R7_in = 1'b0; reg [BitWidth - 1:0] R7_out = 1'b0;
reg [BitWidth - 1:0] Data_in = 1'b0;
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      R0_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R1_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R2_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R3_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R4_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R5_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R6_out <= {((BitWidth - 1)-(0)+1){1'b0}};
      R7_out <= {((BitWidth - 1)-(0)+1){1'b0}};
    end else begin
      R0_out <= R0_in;
      R1_out <= R1_in;
      R2_out <= R2_in;
      R3_out <= R3_in;
      R4_out <= R4_in;
      R5_out <= R5_in;
      R6_out <= R6_in;
      R7_out <= R7_in;
    end
  end
  always @(Data_in_mem, Data_in_CU, Data_in_ACC, Data_in_sel) begin
    case(Data_in_sel)
    2'b01 : begin
      Data_in <= Data_in_CU;
    end
    2'b10 : begin
      Data_in <= Data_in_ACC;
    end
    2'b11 : begin
      Data_in <= Data_in_mem;
    end
    default : begin
      Data_in <= {((BitWidth - 1)-(0)+1){1'b0}};
    end
    endcase
  end
  always @(Data_in, Register_in_sel, R7_out, R6_out, R5_out, R4_out, R3_out, R2_out, R1_out, R0_out) begin
    if(Register_in_sel[0] == 1'b0) begin
      R0_in <= R0_out;
    end
    else begin
      R0_in <= Data_in;
    end
    if(Register_in_sel[1] == 1'b0) begin
      R1_in <= R1_out;
    end
    else begin
      R1_in <= Data_in;
    end
    if(Register_in_sel[2] == 1'b0) begin
      R2_in <= R2_out;
    end
    else begin
      R2_in <= Data_in;
    end
    if(Register_in_sel[3] == 1'b0) begin
      R3_in <= R3_out;
    end
    else begin
      R3_in <= Data_in;
    end
    if(Register_in_sel[4] == 1'b0) begin
      R4_in <= R4_out;
    end
    else begin
      R4_in <= Data_in;
    end
    if(Register_in_sel[5] == 1'b0) begin
      R5_in <= R5_out;
    end
    else begin
      R5_in <= Data_in;
    end
    if(Register_in_sel[6] == 1'b0) begin
      R6_in <= R6_out;
    end
    else begin
      R6_in <= Data_in;
    end
    if(Register_in_sel[7] == 1'b0) begin
      R7_in <= R7_out;
    end
    else begin
      R7_in <= Data_in;
    end
  end
  always @(Register_out_sel, R7_out, R6_out, R5_out, R4_out, R3_out, R2_out, R1_out, R0_out) begin
    case(Register_out_sel)
    3'b000 : begin
      Data_out <= R0_out;
    end
    3'b001 : begin
      Data_out <= R1_out;
    end
    3'b010 : begin
      Data_out <= R2_out;
    end
    3'b011 : begin
      Data_out <= R3_out;
    end
    3'b100 : begin
      Data_out <= R4_out;
    end
    3'b101 : begin
      Data_out <= R5_out;
    end
    3'b110 : begin
      Data_out <= R6_out;
    end
    3'b111 : begin
      Data_out <= R7_out;
    end
    default : begin
      Data_out <= {((BitWidth - 1)-(0)+1){1'b0}};
    end
    endcase
  end
endmodule

module fsm(
input wire clk,
input wire [3:0] cpt,
input wire travaux,
output reg reset_cpt,
output reg [7:0] Led
);
reg [7:0] Led_i;
parameter [2:0]
  RV = 0,
  RO = 1,
  VR = 2,
  ORE = 3,
  ORANGE_ON = 4,
  ORANGE_OFF = 5;
reg [2:0] state; reg [2:0] next_state;
reg reset_cpt_i;
  always @(state, cpt) begin
    // init des tous les signaux inter..
    Led_i <= 8'b11111111;
    reset_cpt_i <= 1'b0;
    case(state)
    RV : begin
      Led_i <= 8'b10000001;
    end
    RO : begin
      Led_i <= 8'b10000010;
      reset_cpt_i <= 1'b1;
    end
    VR : begin
      Led_i <= 8'b00100100;
    end
    ORE : begin
      Led_i <= 8'b01000001;
    end
    ORANGE_ON : begin
      Led_i <= 8'b01000010;
    end
    ORANGE_OFF : begin
      Led_i <= 8'b00000000;
    end
    default : begin
      Led_i <= 8'b10100101;
    end
    endcase
  end
  always @(posedge clk) begin
    // changement d etat
    state <= next_state;
    // mise a jour des ports de sortie
    Led <= Led_i;
    reset_cpt <= reset_cpt_i;
  end
  always @(state, cpt) begin
    next_state <= state;
    case(state)
    RV : begin
      if(travaux == 1'b1) begin
        next_state <= ORANGE_ON;
      end
      else begin
        next_state <= RO;
      end
    end
    RO : begin
      next_state <= VR;
    end
    VR : begin
      if(cpt == 4'b0110) begin
        next_state <= ORE;
      end
      else begin
        next_state <= VR;
      end
    end
    ORE : begin
      next_state <= RV;
    end
    ORANGE_ON : begin
      if(travaux == 1'b0) begin
        next_state <= RO;
      end
      else begin
        next_state <= ORANGE_OFF;
      end
    end
    ORANGE_OFF : begin
      next_state <= ORANGE_ON;
    end
    default : begin
      next_state <= RV;
    end
    endcase
  end
endmodule

module EventReg(
input wire reset,
input wire clk,
input wire strobe,
input wire [15:0] data_in,
output wire [15:0] data_out,
input wire isLocal,
input wire in_buf_ready,
input wire out_buf_ready,
input wire clr,
input wire trg,
input wire att,
input wire atl,
input wire spa,
input wire cwrc,
input wire cwrd,
input wire srq,
input wire ppr,
input wire stb_received,
input wire REN,
input wire ATN,
input wire IFC
);
//------------------ gpib device ---------------------
// device is local controlled
// input buffer ready
// output buffer ready
// clear device (DC)
// trigger device (DT)
// addressed to talk(L or LE)
// addressed to listen (T or TE)
// seriall poll active
//------------------ gpib controller ---------------------
// controller write commands
// controller write data
// service requested
// parallel poll ready
// stb received
wire i_clr;
wire i_trg;
wire i_srq;
wire clr_app;
wire trg_app;
wire srq_app;
reg t_clr_in; wire t_clr_out;
reg t_trg_in; wire t_trg_out;
reg t_srq_in; wire t_srq_out;
  assign data_out[0] = isLocal;
  assign data_out[1] = in_buf_ready;
  assign data_out[2] = out_buf_ready;
  assign data_out[3] = i_clr;
  assign data_out[4] = i_trg;
  assign data_out[5] = att;
  assign data_out[6] = atl;
  assign data_out[7] = spa;
  assign data_out[8] = cwrc;
  assign data_out[9] = cwrd;
  assign data_out[10] = i_srq;
  assign data_out[11] = ppr;
  assign data_out[12] = stb_received;
  assign data_out[13] = REN;
  assign data_out[14] = ATN;
  assign data_out[15] = IFC;
  always @(posedge reset, posedge strobe) begin
    if(reset == 1'b1) begin
      t_clr_in <= 1'b0;
      t_trg_in <= 1'b0;
      t_srq_in <= 1'b0;
    end else begin
      if(data_in[3] == 1'b0) begin
        t_clr_in <=  ~t_clr_out;
      end
      else if(data_in[4] == 1'b0) begin
        t_trg_in <=  ~t_trg_out;
      end
      else if(data_in[10] == 1'b0) begin
        t_srq_in <=  ~t_srq_out;
      end
    end
  end
  EventMem EVM1(
      .reset(reset),
    .occured(clr),
    .approved(clr_app),
    .output(i_clr));
  SinglePulseGenerator #(
      .WIDTH(1))
  SPG1(
      .reset(reset),
    .clk(clk),
    .t_in(t_clr_in),
    .t_out(t_clr_out),
    .pulse(clr_app));
  EventMem EVM2(
      .reset(reset),
    .occured(trg),
    .approved(trg_app),
    .output(i_trg));
  SinglePulseGenerator #(
      .WIDTH(1))
  SPG2(
      .reset(reset),
    .clk(clk),
    .t_in(t_trg_in),
    .t_out(t_trg_out),
    .pulse(trg_app));
  EventMem EVM3(
      .reset(reset),
    .occured(srq),
    .approved(srq_app),
    .output(i_srq));
  SinglePulseGenerator #(
      .WIDTH(1))
  SPG3(
      .reset(reset),
    .clk(clk),
    .t_in(t_srq_in),
    .t_out(t_srq_out),
    .pulse(srq_app));
endmodule

