module Arith_Unit(
input wire [7:0] A,
input wire [7:0] B,
input wire [2:0] OP,
output wire [3:0] CCR,
output wire [7:0] RESULT
);
wire [8:0] a1 = 1'b0; wire [8:0] b1 = 1'b0;
reg [8:0] arith = 1'b0;
  // Give extra bit to accound for carry,overflow,negative
  assign a1 = {1'b0,A};
  assign b1 = {1'b0,B};
  always @(*) begin
    case(OP)
      3'b000 : arith <= a1 + b1;
  // ADD
      3'b001 : arith <= a1 - b1;
  // SUB
      3'b101 : arith <= a1 + b1;
  // ADDI
      default : arith <= a1 + b1;
    endcase
  end
  assign CCR[3] = arith[7];
  // Negative
  assign CCR[2] = arith[7:0] == 16'h0000 ? 1'b1 : 1'b0;
  // Zero
  assign CCR[1] = arith[8] ^ arith[7];
  // Overflow
  assign CCR[0] = arith[8];
  //Carry
  assign RESULT = arith[7:0];
endmodule

