module montgomery_mult(
input wire clk,
input wire reset,
input wire valid_in,
input wire [15:0] a,
input wire [15:0] b,
input wire [15:0] n,
input wire [15:0] s_prev,
input wire [15:0] n_c,
output reg [15:0] s,
output reg valid_out
);
// es le valid out TODO : cambiar nombre
reg [15:0] b_reg[0:7]; reg [15:0] next_b_reg[0:7];
wire valid_mid[0:7]; wire fifo_reqs[0:7]; reg fifo_reqs_reg[0:7]; reg next_fifo_reqs_reg[0:7]; reg stops[0:7];
wire [15:0] a_out_mid[0:7]; wire [15:0] n_out_mid[0:7]; wire [15:0] s_out_mid[0:7];  //std_logic_vector(15 downto 0);
//Señales a la fifo
reg wr_en; reg rd_en; wire empty;
wire [15:0] fifo_out;
wire [48:0] fifo_out_feedback; reg [48:0] fifo_in_feedback;
reg read_fifo_feedback; wire empty_feedback;  //Señales de entrada al primer PE
reg [15:0] a_in; reg [15:0] s_in; reg [15:0] n_in;
reg f_valid; wire busy_pe;  //salida c_step del primer PE para ir contando y saber cuando sacar el valor correcto.
wire c_step; reg reg_c_step;  //contador para saber cuando coño acabamos :)
reg [7:0] count; reg [7:0] next_count;  //señal para escribir el loopback en la fifo de entrada de feedback
reg wr_fifofeed;
parameter [1:0]
  rst_fifos = 0,
  wait_start = 1,
  process_data = 2,
  dump_feed = 3;
reg [1:0] state; reg [1:0] next_state;
reg reg_busy;
reg reset_fifos;
reg [15:0] count_feedback; reg [15:0] next_count_feedback;
  //Fifo para almacenar b
  fifo_512_bram fifo_b(
      .clk(clk),
    .rst(reset_fifos),
    .din(b),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .dout(fifo_out),
    .empty(empty));
  //Fifo para el feedback al primer PE
  fifo_256_feedback fifo_feed(
      .clk(clk),
    .rst(reset_fifos),
    .din(fifo_in_feedback),
    .wr_en(wr_fifofeed),
    .rd_en(read_fifo_feedback),
    .dout(fifo_out_feedback),
    .empty(empty_feedback));
  //Primer PE
  montgomery_step et_first(
      .clk(clk),
    .reset(reset),
    .valid_in(f_valid),
    .a(a_in),
    .b(b_reg[0]),
    .n(n_in),
    .s_prev(s_in),
    .n_c(n_c),
    .s(s_out_mid[0]),
    .valid_out(valid_mid[0]),
    .busy(busy_pe),
    .b_req(fifo_reqs[0]),
    .a_out(a_out_mid[0]),
    .n_out(n_out_mid[0]),
    .c_step(c_step),
    .stop(stops[0]));
  //Ultimo PE
  montgomery_step et_last(
      .clk(clk),
    .reset(reset),
    .valid_in(valid_mid[6]),
    .a(a_out_mid[6]),
    .b(b_reg[7]),
    .n(n_out_mid[6]),
    .s_prev(s_out_mid[6]),
    .n_c(n_c),
    .s(s_out_mid[7]),
    .valid_out(valid_mid[7]),
    .b_req(fifo_reqs[7]),
    .a_out(a_out_mid[7]),
    .n_out(n_out_mid[7]),
    .stop(stops[7]));
  genvar i;
  generate for (i=1; i <= 6; i = i + 1) begin: g1
      montgomery_step et_i(
          .clk(clk),
      .reset(reset),
      .valid_in(valid_mid[i - 1]),
      .a(a_out_mid[i - 1]),
      .b(b_reg[i]),
      .n(n_out_mid[i - 1]),
      .s_prev(s_out_mid[i - 1]),
      .n_c(n_c),
      .s(s_out_mid[i]),
      .valid_out(valid_mid[i]),
      .b_req(fifo_reqs[i]),
      .a_out(a_out_mid[i]),
      .n_out(n_out_mid[i]),
      .stop(stops[i]));
  end
  endgenerate
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      state <= wait_start;
      count_feedback <= {16{1'b0}};
      reg_busy <= 1'b0;
      for (i=0; i <= 7; i = i + 1) begin
        b_reg[i] <= {1{1'b0}};
        fifo_reqs_reg[i] <= 1'b0;
        count <= {8{1'b0}};
        reg_c_step <= 1'b0;
      end
    end
    else begin
      state <= next_state;
      reg_busy <= busy_pe;
      count_feedback <= next_count_feedback;
      for (i=0; i <= 7; i = i + 1) begin
        b_reg[i] <= next_b_reg[i];
        fifo_reqs_reg[i] <= next_fifo_reqs_reg[i];
        count <= next_count;
        reg_c_step <= c_step;
      end
    end
  end
  //Proceso combinacional que controla las lecturas a la fifo
  always @(fifo_reqs_reg, fifo_out, b, fifo_reqs, b_reg, state, empty) begin
    for (i=0; i <= 7; i = i + 1) begin
      next_b_reg[i] <= b_reg[i];
      next_fifo_reqs_reg[i] <= fifo_reqs[i];
    end
    if((state == wait_start)) begin
      next_b_reg[0] <= b;
      next_fifo_reqs_reg[0] <= 1'b0;
      //anulamos la peticion de b
      for (i=1; i <= 7; i = i + 1) begin
        next_b_reg[i] <= {1{1'b0}};
        next_fifo_reqs_reg[i] <= 1'b0;
      end
    end
    else begin
      for (i=0; i <= 7; i = i + 1) begin
        if((fifo_reqs_reg[i] == 1'b1 && empty == 1'b0)) begin
          next_b_reg[i] <= fifo_out;
        end
      end
    end
  end
  //Proceso combinacional fsm principal
  always @(valid_in, b, state, fifo_reqs, a_out_mid, n_out_mid, s_out_mid, valid_mid, a, s_prev, n, busy_pe, empty_feedback, fifo_out_feedback, count, reg_c_step, reset, reg_busy, count_feedback) begin
    //las peticiones a la fifo son las or de los modulos
    rd_en <= fifo_reqs[0] | fifo_reqs[1] | fifo_reqs[2] | fifo_reqs[3] | fifo_reqs[4] | fifo_reqs[5] | fifo_reqs[6] | fifo_reqs[7];
    next_state <= state;
    wr_en <= 1'b0;
    fifo_in_feedback <= {a_out_mid[7],n_out_mid[7],s_out_mid[7],valid_mid[7]};
    read_fifo_feedback <= 1'b0;
    wr_fifofeed <= 1'b0;
    //Controlamos el primer PE
    a_in <= a;
    s_in <= s_prev;
    n_in <= n;
    f_valid <= valid_in;
    reset_fifos <= reset;
    //ponemos las salidas
    s <= {16{1'b0}};
    valid_out <= 1'b0;
    //Incrementamos el contador solo cuando el primer PE termina su cuenta
    next_count <= count;
    next_count_feedback <= count_feedback;
    //El contador solo se incrementa una vez por ciclo de la pipeline, así me evito que cada PE lo incremente
    if((reg_c_step == 1'b1)) begin
      next_count <= count + 8;
    end
    //durante el ciclo de la pipeline que sea considerado el ultimo, sacamos los datos
    if((count == 8'h20)) begin
      s <= s_out_mid[0];
      valid_out <= valid_mid[0];
    end
    for (i=0; i <= 7; i = i + 1) begin
      stops[i] <= 1'b0;
    end
    case(state)
        //Esperamos a que tengamos un input y vamos cargando las b's
    wait_start : begin
      //reset_fifos   <= '1';
      if((valid_in == 1'b1)) begin
        reset_fifos <= 1'b0;
        //next_b_reg(0) <= b;
        next_state <= process_data;
        //wr_en <= '1';
      end
    end
    process_data : begin
      wr_fifofeed <= valid_mid[7];
      if((valid_in == 1'b1)) begin
        wr_en <= 1'b1;
      end
      //Miramos si hay que volver a meter datos a la b
      if((empty_feedback == 1'b0 && reg_busy == 1'b0)) begin
        read_fifo_feedback <= 1'b1;
        next_state <= dump_feed;
        next_count_feedback <= 16'h0000;
      end
      //Si ya hemos sobrepasado el limite paramos y volvemos a la espera
      if((count > 8'h23)) begin
        next_state <= wait_start;
        //y
        for (i=0; i <= 7; i = i + 1) begin
          stops[i] <= 1'b1;
        end
        next_count <= {8{1'b0}};
      end
      //Vacia la fifo de feedback
    end
    dump_feed : begin
      if((empty_feedback == 1'b0)) begin
        next_count_feedback <= count_feedback + 1;
      end
      wr_fifofeed <= valid_mid[7];
      read_fifo_feedback <= 1'b1;
      a_in <= fifo_out_feedback[48:33];
      n_in <= fifo_out_feedback[32:17];
      s_in <= fifo_out_feedback[16:1];
      f_valid <= fifo_out_feedback[0];
      if((empty_feedback == 1'b1)) begin
        next_state <= process_data;
      end
      if((count_feedback == 8'h22)) begin
        read_fifo_feedback <= 1'b0;
        next_state <= process_data;
      end
    end
    rst_fifos : begin
      next_state <= wait_start;
      reset_fifos <= 1'b1;
    end
    endcase
  end
endmodule

module SerialReceiver(
input wire clk,
input wire rx,
output reg [7:0] data
);
parameter [1:0]
  idle = 0,
  receiving = 1,
  stopbit = 2;
reg [1:0] state = idle;
reg [7:0] temp_data;
reg [31:0] bit_pos = 0;
  always @(posedge clk) begin
    // serial receive
    // XgbvrbgÅcounter_matchªXV
    if(((state == idle) && rx == 1'b0)) begin
      bit_pos <= 0;
      state <= receiving;
    end
    else if((state == receiving)) begin
      temp_data <= {rx,temp_data[7:1]};
      bit_pos <= bit_pos + 1;
      if((bit_pos == 7)) begin
        state <= stopbit;
      end
    end
    else if((state == stopbit)) begin
      if((rx == 1'b1)) begin
        data <= temp_data;
        state <= idle;
      end
