module SpaceWireCODECIPTimer(
input wire clock,
input wire reset,
input wire timer6p4usReset,
input wire timer12p8usStart,
output wire after6p4us,
output wire after12p8us
);
parameter [31:0] gTimer6p4usValue=640;
parameter [31:0] gTimer12p8usValue=1280;
reg iTimerState12p8us;
reg [9:0] iTimerCount6p4us;
reg [10:0] iTimerCount12p8us;
reg iAfter6p4us;
reg iAfter12p8us;
  assign after6p4us = iAfter6p4us;
  assign after12p8us = iAfter12p8us;
  //--------------------------------------------------------------------
  // ECSS-E-ST-50-12C  8.4.7 Timer.
  // The timer provides the After 6.4 us and After 12.8 us timeouts used 
  // in link initialization.
  //--------------------------------------------------------------------
  //--------------------------------------------------------------------
  // After 6.4us.
  //--------------------------------------------------------------------
  always @(posedge clock, posedge reset, posedge timer6p4usReset) begin
    if((reset == 1'b1 || timer6p4usReset == 1'b1)) begin
      iTimerCount6p4us <= {10{1'b0}};
      iAfter6p4us <= 1'b0;
    end else begin
      if((iTimerCount6p4us < gTimer6p4usValue)) begin
        iTimerCount6p4us <= iTimerCount6p4us + 1;
        iAfter6p4us <= 1'b0;
      end
      else begin
        iTimerCount6p4us <= {10{1'b0}};
        iAfter6p4us <= 1'b1;
      end
    end
  end
  //--------------------------------------------------------------------
  // After 12.8us.
  //--------------------------------------------------------------------
  always @(posedge clock, posedge reset, posedge timer12p8usStart, posedge timer6p4usReset) begin
    if((reset == 1'b1 || timer6p4usReset == 1'b1)) begin
      iTimerState12p8us <= 1'b0;
      iTimerCount12p8us <= {11{1'b0}};
      iAfter12p8us <= 1'b0;
    end else begin
      if((iTimerState12p8us == 1'b0)) begin
        iAfter12p8us <= 1'b0;
        if((timer12p8usStart == 1'b1)) begin
          iTimerState12p8us <= 1'b1;
        end
      end
      else begin
        if((iTimerCount12p8us < gTimer12p8usValue)) begin
          iTimerCount12p8us <= iTimerCount12p8us + 1;
          iAfter12p8us <= 1'b0;
        end
        else begin
          iTimerCount12p8us <= {11{1'b0}};
          iTimerState12p8us <= 1'b0;
          iAfter12p8us <= 1'b1;
        end
      end
    end
  end
endmodule

module data_split(
input wire pclk,
input wire reset,
input wire vsync,
input wire [7:0] din,
output wire [15:0] stream1_o,
output wire [15:0] stream2_o,
output wire [15:0] stream3_o,
output wire [15:0] stream4_o,
output wire vsync_pcie_o
);
parameter [3:0]
  IDLE = 0,
  S1MSB = 1,
  S1LSB = 2,
  S2MSB = 3,
  S2LSB = 4,
  S3MSB = 5,
  S3LSB = 6,
  S4MSB = 7,
  S4LSB = 8,
  LATCHDATA = 9,
  WAITLOW = 10;
  //state machine definition
reg [3:0] split_state; reg [3:0] split_state_next;
reg [15:0] stream1; reg [15:0] stream1_next;
reg [15:0] stream2; reg [15:0] stream2_next;
reg [15:0] stream3; reg [15:0] stream3_next;
reg [15:0] stream4; reg [15:0] stream4_next;
reg [15:0] stream1_masked;
reg [15:0] stream2_masked;
reg [15:0] stream3_masked;
reg [15:0] stream4_masked;
reg vsync_pcie;
  //signal mapping 
  assign vsync_pcie_o = vsync_pcie;
  assign stream1_o = stream1_masked;
  assign stream2_o = stream2_masked;
  assign stream3_o = stream3_masked;
  assign stream4_o = stream4_masked;
  //vsync triggers the data spliting process
  always @(posedge reset, posedge split_state, posedge pclk, posedge stream1, posedge stream2, posedge stream3, posedge stream4, posedge stream1_masked, posedge stream2_masked, posedge stream3_masked, posedge stream3_masked) begin
    if((reset == 1'b1)) begin
      split_state <= IDLE;
      stream1 <= {16{1'b0}};
      stream2 <= {16{1'b0}};
      stream3 <= {16{1'b0}};
      stream4 <= {16{1'b0}};
      stream1_masked <= {16{1'b0}};
      stream2_masked <= {16{1'b0}};
      stream3_masked <= {16{1'b0}};
      stream4_masked <= {16{1'b0}};
      vsync_pcie <= 1'b0;
    end else begin
      split_state <= split_state_next;
      stream1 <= stream1_next;
      stream2 <= stream2_next;
      stream3 <= stream3_next;
      stream4 <= stream4_next;
      if(split_state == WAITLOW) begin
        vsync_pcie <= 1'b1;
      end
      else begin
        vsync_pcie <= 1'b0;
      end
      if(split_state == LATCHDATA) begin
        stream1_masked <= stream1;
        stream2_masked <= stream2;
        stream3_masked <= stream3;
        stream4_masked <= stream4;
      end
      else begin
        stream1_masked <= stream1_masked;
        stream2_masked <= stream2_masked;
        stream3_masked <= stream3_masked;
        stream4_masked <= stream4_masked;
      end
    end
  end
  //next process
  always @(reset, split_state, vsync, pclk, stream1, stream2, stream3, stream4, din) begin
    case(split_state)
    IDLE : begin
      if((vsync == 1'b1)) begin
        split_state_next <= S1MSB;
        stream1_next[15:8] <= din;
        stream1_next[7:0] <= stream1[7:0];
      end
      else begin
        split_state_next <= IDLE;
        stream1_next <= stream1;
      end
      //2,3,4 unchanged
      stream2_next <= stream2;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    S1MSB : begin
      stream1_next[15:8] <= stream1[15:8];
      stream1_next[7:0] <= din;
      split_state_next <= S1LSB;
      //2,3,4 unchanged
      stream2_next <= stream2;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    S1LSB : begin
      split_state_next <= S2MSB;
      //2 MSB
      stream2_next[15:8] <= din;
      stream2_next[7:0] <= stream2[7:0];
      //1,3,4 unchanged
      stream1_next <= stream1;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    S2MSB : begin
      split_state_next <= S2LSB;
      //2 LSB
      stream2_next[15:8] <= stream2[15:8];
      stream2_next[7:0] <= din;
      //1,3,4 unchanged
      stream1_next <= stream1;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    S2LSB : begin
      split_state_next <= S3MSB;
      //3 MSB
      stream3_next[15:8] <= din;
      stream3_next[7:0] <= stream3[7:0];
      //1,2,4 unchanged
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream4_next <= stream4;
    end
    S3MSB : begin
      split_state_next <= S3LSB;
      //3 LSB
      stream3_next[15:8] <= stream3[15:8];
      stream3_next[7:0] <= din;
      //1,2,4 unchanged
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream4_next <= stream4;
    end
    S3LSB : begin
      split_state_next <= S4MSB;
      //4 MSB
      stream4_next[15:8] <= din;
      stream4_next[7:0] <= stream4[7:0];
      //1,2,3 unchanged
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream3_next <= stream3;
    end
    S4MSB : begin
      split_state_next <= S4LSB;
      //4 LSB
      stream4_next[15:8] <= stream4[15:8];
      stream4_next[7:0] <= din;
      //1,2,3 unchanged
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream3_next <= stream3;
    end
    S4LSB : begin
      split_state_next <= LATCHDATA;
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    LATCHDATA : begin
      stream1_next <= stream1;
      split_state_next <= WAITLOW;
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    WAITLOW : begin
      if((vsync == 1'b0)) begin
        split_state_next <= IDLE;
      end
      else begin
        split_state_next <= WAITLOW;
      end
      stream1_next <= stream1;
      stream2_next <= stream2;
      stream3_next <= stream3;
      stream4_next <= stream4;
    end
    endcase
  end
endmodule

module PRBS_ANY(
input wire CHK_MODE,
input wire RST,
input wire CLK,
input wire [NBITS - 1:0] DATA_IN,
input wire EN,
output reg [NBITS - 1:0] DATA_OUT
);
//CHK_MODE: boolean := false; 
parameter INV_PATTERN=false;
parameter [31:0] POLY_LENGHT=7;
parameter [31:0] POLY_TAP=6;
parameter [31:0] NBITS=4;
// sync reset active high
// system clock
// inject error/data to be checked
// enable/pause pattern generation
// generated prbs pattern/errors found
reg [1:POLY_LENGHT] prbs[NBITS:0] = 1'b1;
wire [NBITS - 1:0] data_in_i;
wire [NBITS - 1:0] prbs_xor_a;
wire [NBITS - 1:0] prbs_xor_b;
wire [NBITS:1] prbs_msb;
  assign data_in_i = INV_PATTERN == false ? DATA_IN :  ~DATA_IN;
  genvar I;
  generate for (I=0; I <= NBITS - 1; I = I + 1) begin: g1
      assign prbs_xor_a[I] = prbs[I][POLY_TAP] ^ prbs[I][POLY_LENGHT];
    assign prbs_xor_b[I] = prbs_xor_a[I] ^ data_in_i[I];
    assign prbs_msb[I + 1] = CHK_MODE == 1'b0 ? prbs_xor_a[I] : data_in_i[I];
    assign prbs[I + 1] = {prbs_msb[I + 1],prbs[I][1:POLY_LENGHT - 1]};
  end
  endgenerate
  always @(posedge CLK) begin
    if(RST == 1'b1) begin
      prbs[0] <= {1{1'b1}};
      DATA_OUT <= {((NBITS - 1)-(0)+1){1'b1}};
    end
    else if(EN == 1'b1) begin
      DATA_OUT <= prbs_xor_b;
      prbs[0] <= prbs[NBITS];
    end
  end
endmodule

module X_Axis_Subsystem(
input wire clk_50,
input wire reset,
output wire motor_ctrl_signal,
input wire feedback_clk
);
// 50MHZ_clock
// 
// 
//architecture of the circuit.
wire [1:0] phase_correction;  // signals for PLL
wire pll_configupdate_sig; wire pll_areset_sig; wire pll_scandataout_sig; wire pll_scandone_sig; wire pll_scanclk_sig; wire pll_scandata_sig; wire pll_scanclkena_sig;
wire reconfig_busy;
  //"begin" statement for architecture.
  PFD detect(
      .correction(phase_correction),
    .ref_clk(1'b1),
    .feedback_clk(feedback_clk));
  PLL PLL_inst(
      .areset(pll_areset_sig),
