    .scandataout(pll_scandataout_sig),
    .scandone(pll_scandone_sig));
  PLL_RECONFIG PLL_RECONFIG_inst(
      .clock(clk_50),
    .counter_param(3'b000),
    .counter_type(4'b0000),
    .data_in(9'b000000000),
    .pll_scandataout(pll_scandataout_sig),
    // pll_scandataout port must be connected to  the  scandataout port of the PLL.
    .reconfig(1'b0),
    .reset(reset),
    .write_param(1'b0),
    // write data_in to param defined by counter_type and counter_param
    .busy(reconfig_busy),
    .pll_areset(pll_areset_sig),
    // The  pll_areset port must be connected to the areset port of the ALTPLL 
    .pll_configupdate(pll_configupdate_sig),
    // NOT REQUIRED HOW IS THIS DIFFERENT THAN WRITE_PARAM? When asserted, the  pll_configupdate port loads selected data to PLL configuration latches. 
    .pll_scanclk(pll_scanclk_sig),
    // Drives the  scanclk port on the PLL to be reconfigured.
    .pll_scanclkena(pll_scanclkena_sig),
    // This acts as a clock enable for the  scanclk port on the PLL to be reconfigured.
    .pll_scandata(pll_scandata_sig),
    // Drives the  scandata port on the PLL to be reconfigured.
    .pll_scandone(1'b0),
    .read_param(1'b0));
endmodule

