module gpio_switcher(
inout reg [15:0] gpio,
input wire [15:0] gp_ctrl,
output reg [15:0] gp_in,
input wire [15:0] gp_out
);
  always @(gpio, gp_ctrl, gp_out) begin
    for (i=0; i <= 15; i = i + 1) begin
      // read / in
      if(gp_ctrl[i] == 1'b0) begin
        gpio[i] <= 1'bZ;
        gp_in[i] <= gpio[i];
        // write / out				
      end
      else begin
        gpio[i] <= gp_out[i];
        gp_in[i] <= 1'b0;
      end
    end
  end
endmodule

module BUSREG(
input wire iCLK,
input wire oCLK,
input wire CLR,
input wire LOAD,
input wire OE,
input wire [width - 1:0] I,
output reg [width - 1:0] O,
output reg bus_ack
);
parameter [31:0] width=16;
reg [width - 1:0] DATA = 16'hffff;
  always @(posedge iCLK, posedge CLR) begin
    if((CLR == 1'b1)) begin
      DATA <= 16'hffff;
    end else begin
      if((LOAD == 1'b1)) begin
        DATA <= I;
      end
    end
  end
  always @(posedge oCLK, posedge CLR) begin
    if((CLR == 1'b1)) begin
      O <= {((width - 1)-(0)+1){1'bZ}};
      bus_ack <= 1'b0;
    end else begin
      if((oe == 1'b1)) begin
        O <= DATA;
        bus_ack <= 1'b1;
      end
      else begin
        O <= {((width - 1)-(0)+1){1'bZ}};
        bus_ack <= 1'b0;
      end
    end
  end
endmodule

