module adder(
input wire clk,
input wire reset,
input wire [width - 1:0] a,
input wire [width - 1:0] b,
output reg [width:0] c
);
parameter [31:0] width=1;
  // rtl
  // purpose: Add the values
  // type   : sequential
  // inputs : clk, reset, a, b
  // outputs: c
  always @(posedge clk, posedge reset) begin
      // process add
    if(reset == 1'b1) begin
      // asynchronous reset (active high)
      c <= {((width)-(0)+1){1'b0}};
    end else begin
      // rising clock edge
      c <= ({1'b0,a}) + ({1'b0,b});
    end
  end
endmodule

