  always @(posedge clk_caph, posedge rst_n_i) begin : P1
    reg [31:0] datacpt = 0;
    if((rst_n_i == 1'b0)) begin
      frame_valid_s <= 1'b0;
      data_valid_s <= 1'b0;
      data_s <= {((SIZE - 1)-(0)+1){1'b0}};
      datacpt = 0;
      linecpt <= 0;
    end else begin
      data_valid_s <= 1'b0;
      if((data_i[TOKEN_SIZE - 1:TOKEN_SIZE - 2] == CaphHeader[Data])) begin
        data_s <= data_i[7:0];
        data_valid_s <= 1'b1;
        frame_valid_s <= 1'b1;
        datacpt = datacpt + 1;
        if((datacpt == (imwidth_i))) begin
          datacpt = 0;
          linecpt <= linecpt + 1;
        end
      end
      if((linecpt == (imheight_i))) begin
        frame_valid_s <= 1'b0;
        data_valid_s <= 1'b0;
        datacpt = 0;
        linecpt <= 0;
      end
    end
  end
  assign fifo_unpile =  ~(fifo_empty);
  assign data_valid_o = data_valid_s;
  assign frame_valid_o = frame_valid_s;
  assign data_o = data_s;
