input wire ENABLE,
input wire INIT,
output wire BIT_OUT
);
reg [4:0] shift_reg;
reg [4:0] shift_next;
  // register
  always @(posedge clk, posedge reset_n) begin
    if((reset_n == 1'b0)) begin
      shift_reg <= 5'b01010;
    end else begin
      shift_reg <= shift_next;
    end
  end
  // next state
  always @(shift_reg, enable, init) begin
    shift_next <= shift_reg;
    if((enable == 1'b1)) begin
      shift_next <= {( ~(shift_reg[2] ^ shift_reg[0])) &  ~(init),shift_reg[4:1]};
    end
  end
  // output
  assign bit_out =  ~(shift_reg[0]);
