module ALU(
input wire [0:data_width - 1] in_1,
input wire [0:data_width - 1] in_2,
output reg [0:data_width - 1] outp,
input wire [0:2] sel
);
parameter [31:0] data_width=16;
reg [0:data_width - 1] add_out = 1'b0; wire [0:data_width - 1] sub_out = 1'b0; wire [0:data_width - 1] mul_out = 1'b0; wire [0:data_width - 1] div_out = 1'b0; reg [0:data_width - 1] not_out = 1'b0; reg [0:data_width - 1] and_out = 1'b0; reg [0:data_width - 1] xor_out = 1'b0; reg [0:data_width - 1] or_out = 1'b0;
  always @(in_1, in_2) begin
    add_out <= (in_1) + (in_2);
    // after 2 ns;
    //sub_out <= std_logic_vector(to_integer(unsigned(in_1)) - to_integer(unsigned(in_2)));-- after 2 ns;
    //mul_out <= std_logic_vector(to_integer(unsigned(in_1)) * to_integer(unsigned(in_2)));-- after 3 ns;
    //div_out <= std_logic_vector(to_integer(unsigned(in_1)) / to_integer(unsigned(in_2)));-- after 3 ns;
    or_out <= in_1 | in_2;
    // after 1 ns;
    and_out <= in_1 & in_2;
    // after 1 ns;
    not_out <=  ~in_1;
    // after 1 ns;
    xor_out <= in_1 ^ in_2;
    // after 1 ns;
  end
  always @(sel, add_out, sub_out, mul_out, div_out, or_out, and_out, not_out, xor_out) begin
    if((sel == 3'b000)) begin
      outp <= add_out;
    end
    else if((sel == 3'b001)) begin
      outp <= sub_out;
    end
    else if((sel == 3'b010)) begin
      outp <= mul_out;
    end
    else if((sel == 3'b011)) begin
      outp <= div_out;
    end
    else if((sel == 3'b100)) begin
      outp <= not_out;
    end
    else if((sel == 3'b101)) begin
      outp <= and_out;
    end
    else if((sel == 3'b110)) begin
      outp <= xor_out;
    end
    else if((sel == 3'b111)) begin
      outp <= or_out;
    end
    else begin
      outp <= {((data_width - 1)-(0)+1){1'b0}};
    end
  end
endmodule

