module bcd_g(
input wire [31:0] entrada_int,
output reg [3:0] decenas_millones,
output reg [3:0] millones,
output reg [3:0] centenas_mill,
output reg [3:0] decenas_mill,
output reg [3:0] millares,
output reg [3:0] centenas,
output reg [3:0] decenas,
output reg [3:0] unidades
);
  always @(entrada_int) begin : P1
    reg [71:0] shift;
    shift = {1{1'b0}};
    shift[34:3] = entrada_int;
    for (i=0; i <= 28; i = i + 1) begin
      if(shift[35:32] > 4) begin
        shift[35:32] = shift[35:32] + 3;
      end
      if(shift[39:36] > 4) begin
        shift[39:36] = shift[39:36] + 3;
      end
      if(shift[43:40] > 4) begin
        shift[43:40] = shift[43:40] + 3;
      end
      if(shift[47:44] > 4) begin
        shift[47:44] = shift[47:44] + 3;
      end
      if(shift[51:48] > 4) begin
        shift[51:48] = shift[51:48] + 3;
      end
      if(shift[55:52] > 4) begin
        shift[55:52] = shift[55:52] + 3;
      end
      if(shift[59:56] > 4) begin
        shift[59:56] = shift[59:56] + 3;
      end
      if(shift[63:60] > 4) begin
        shift[63:60] = shift[63:60] + 3;
      end
      shift[71:1] = shift[70:0];
    end
    decenas_millones <= shift[63:60];
    millones <= shift[59:56];
    centenas_mill <= shift[55:52];
    decenas_mill <= shift[51:48];
    millares <= shift[47:44];
    centenas <= shift[43:40];
    decenas <= shift[39:36];
    unidades <= shift[35:32];
  end
endmodule

module alu(
