        wrtrigval[1] <= 1'b1;
      end
      8'hC6 : begin
        wrtrigcfg[1] <= 1'b1;
      end
      8'hC8 : begin
        wrtrigmask[2] <= 1'b1;
      end
      8'hC9 : begin
        wrtrigval[2] <= 1'b1;
      end
      8'hCA : begin
        wrtrigcfg[2] <= 1'b1;
      end
      8'hCC : begin
        wrtrigmask[3] <= 1'b1;
      end
      8'hCD : begin
        wrtrigval[3] <= 1'b1;
      end
      8'hCE : begin
        wrtrigcfg[3] <= 1'b1;
      end
      default : begin
      end
      endcase
    end
    exeReg <= exe;
  end
