module top_nto1_pll_diff_rx_and_tx(
input wire reset,
input wire clkin_p,
input wire clkin_n,
input wire [5:0] datain_p,
input wire [5:0] datain_n,
output wire clkout_p,
output wire clkout_n,
output wire [5:0] dataout_p,
output wire [5:0] dataout_n
);
// reset (active high)
// lvds clock input
// lvds data inputs
// lvds clock output
// lvds data outputs
// Parameters for serdes factor and number of IO pins
parameter S = 7;  // Set the serdes factor to be 4
parameter D = 6;  // Set the number of inputs and outputs to be 6
parameter DS = (D * S) - 1;  // Used for bus widths = serdes factor * number of inputs - 1
wire [6:0] clk_iserdes_data;
wire rx_bufg_x1;
wire [DS:0] rxd;
wire [6:0] capture;
wire [3:0] counter;
wire bitslip;
wire rst;
wire rx_serdesstrobe;
wire rx_bufpll_clk_xn;
wire rx_bufpll_lckd;
wire not_bufpll_lckd;
wire [0:0] temp1p;
wire [0:0] temp1n;
reg [DS:0] txd;
parameter TX_CLK_GEN = 7'b1100001;  // Transmit a constant to make a clock
  assign rst = reset;
  // active high reset pin
  // Clock Input, Generate ioclocks via PLL
  serdes_1_to_n_clk_pll_s8_diff #(
      .CLKIN_PERIOD(6.700),
    .PLLD(1),
    .PLLX(S),
    .S(S),
    .BS(TRUE))
  clkin(
      .clkin_p(clkin_p),
    .clkin_n(clkin_n),
    .rxioclk(rx_bufpll_clk_xn),
    .pattern1(7'b1100001),
    // default values for 7:1 video applications
    .pattern2(7'b1100011),
    .rx_serdesstrobe(rx_serdesstrobe),
    .rx_bufg_pll_x1(rx_bufg_x1),
    .bitslip(bitslip),
    .reset(rst),
    .datain(clk_iserdes_data),
    .rx_pll_lckd(/* open */),
    // PLL locked - only used if a 2nd BUFPLL is required
    .rx_pllout_xs(/* open */),
    // Multiplied PLL clock - only used if a 2nd BUFPLL is required
    .rx_bufpll_lckd(rx_bufpll_lckd));
  // Data Inputs
  assign not_bufpll_lckd =  ~rx_bufpll_lckd;
  serdes_1_to_n_data_s8_diff #(
      .S(S),
    .D(D))
  datain(
      .use_phase_detector(1'b1),
    .datain_p(datain_p),
    .datain_n(datain_n),
    .rxioclk(rx_bufpll_clk_xn),
    .rxserdesstrobe(rx_serdesstrobe),
    .gclk(rx_bufg_x1),
    .bitslip(bitslip),
    .reset(not_bufpll_lckd),
    .debug_in(2'b00),
    .data_out(rxd),
    .debug(/* open */));
  always @(posedge rx_bufg_x1) begin
    txd <= rxd;
  end
  // Transmitter Logic - Instantiate serialiser to generate forwarded clock
  serdes_n_to_1_s8_diff #(
      .S(S),
    .D(1))
  clkout(
      .dataout_p(temp1p),
    .dataout_n(temp1n),
    .txioclk(rx_bufpll_clk_xn),
    .txserdesstrobe(rx_serdesstrobe),
    .gclk(rx_bufg_x1),
    .reset(rst),
    .datain(TX_CLK_GEN));
  // Transmit a constant to make the clock
  assign clkout_p = temp1p[0];
  assign clkout_n = temp1n[0];
  // Instantiate Outputs and output serialisers for output data lines
  serdes_n_to_1_s8_diff #(
      .S(S),
    .D(D))
  dataout(
      .dataout_p(dataout_p),
    .dataout_n(dataout_n),
    .txioclk(rx_bufpll_clk_xn),
    .txserdesstrobe(rx_serdesstrobe),
    .gclk(rx_bufg_x1),
    .reset(rst),
    .datain(txd));
endmodule

