  rd_fifo(
      .clk_wr(clk_memfb90_n),
    .rst_wr(rst_memfb270),
    .put(rf_put),
    .din(rf_din),
    .full(/* open */),
    // can't stall
    .clk_rd(clk_tb),
    .rst_rd(rst_tb),
    .got(mem_rstb),
    .valid(mem_rstb),
    .dout(mem_rdata));
  memtest_fsm #(
      .A_BITS(24),
    .D_BITS(32))
  fsm(
      .clk(clk_tb),
    .rst(rst_tb),
    .mem_rdy(mem_rdy),
    .mem_rstb(mem_rstb),
    .mem_rdata(mem_rdata),
    .mem_req(mem_req),
    .mem_write(mem_write),
    .mem_addr(mem_addr),
    .mem_wdata(mem_wdata),
    .status(fsm_status));
  // Signal mem_ctrl ready only if both FIFOs are not full.
  assign mem_rdy =  ~(cf_full | wf_full);
  // Word aligned access to memory.
  // Parallel "put" to both FIFOs.
  assign cf_put = mem_req & mem_rdy;
  assign wf_put = mem_req & mem_write & mem_rdy;
  assign cf_din = {mem_write,mem_addr,1'b0};
  assign wf_din = mem_wdata;
  //---------------------------------------------------------------------------
  // Outputs
  //---------------------------------------------------------------------------
  assign led[7] = locked;
  assign led[6:3] = {4{1'b0}};
  assign led[2:0] = fsm_status;
endmodule

module drp_arbiter(
input wire reset,
input wire clk,
input wire jtaglocked,
output reg bgrant_A,
output reg bgrant_B,
input wire bbusy_A,
input wire bbusy_B,
input wire [7:0] daddr_A,
input wire den_A,
input wire [15:0] di_A,
input wire dwe_A,
output wire [15:0] do_A,
output wire drdy_A,
input wire [7:0] daddr_B,
input wire den_B,
input wire [15:0] di_B,
input wire dwe_B,
output wire [15:0] do_B,
output wire drdy_B,
output wire [7:0] daddr_C,
output wire den_C,
output wire [15:0] di_C,
output wire dwe_C,
input wire [15:0] do_C,
input wire drdy_C
);
// input clock
// input clock
// input clock
// bus grant
// bus grant
// bus busy
// bus busy
parameter [2:0]
  NOGRANT = 0,
  GRANT_A = 1,
  GRANT_A_WAIT = 2,
  GRANT_B = 3,
  GRANT_B_WAIT = 4;
reg [2:0] state;
reg [7:0] daddr_C_reg;
reg [15:0] di_C_reg;
reg den_C_reg;
reg dwe_C_reg;
reg [7:0] daddr_reg;
reg [15:0] di_reg;
reg den_reg;
reg dwe_reg;
reg [15:0] do_A_reg;
reg drdy_A_reg;
reg [15:0] do_B_reg;
reg drdy_B_reg;
reg overlap_A;
reg overlap_B;
  assign daddr_C = daddr_C_reg;
  assign di_C = di_C_reg;
  assign den_C = den_C_reg;
  assign dwe_C = dwe_C_reg;
  assign do_B = do_B_reg;
  assign drdy_B = drdy_B_reg;
  assign drdy_A = drdy_A_reg;
  assign do_A = do_A_reg;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      state <= NOGRANT;
      daddr_C_reg <= 8'h00;
      di_C_reg <= 16'h0000;
      dwe_C_reg <= 1'b0;
      den_C_reg <= 1'b0;
      daddr_reg <= 8'h00;
      di_reg <= 16'h0000;
      dwe_reg <= 1'b0;
      den_reg <= 1'b0;
      drdy_A_reg <= 1'b0;
      do_A_reg <= 16'h0000;
      drdy_B_reg <= 1'b0;
      do_B_reg <= 16'h0000;
      overlap_A <= 1'b0;
      overlap_B <= 1'b0;
      bgrant_A <= 1'b0;
      bgrant_B <= 1'b0;
    end else begin
      case(state)
      NOGRANT : begin
        if(jtaglocked == 1'b0) begin
          if(bbusy_A == 1'b0 && bbusy_B == 1'b0) begin
            if(overlap_B == 1'b1) begin
              daddr_C_reg <= daddr_reg;
              di_C_reg <= di_reg;
              dwe_C_reg <= dwe_reg;
              den_C_reg <= den_reg;
              overlap_B <= 1'b0;
              bgrant_A <= 1'b0;
              bgrant_B <= 1'b1;
              state <= GRANT_B;
            end
            else if(overlap_A == 1'b1) begin
              daddr_C_reg <= daddr_reg;
              di_C_reg <= di_reg;
              dwe_C_reg <= dwe_reg;
              den_C_reg <= den_reg;
              overlap_A <= 1'b0;
              bgrant_A <= 1'b1;
              bgrant_B <= 1'b0;
              state <= GRANT_A;
            end
            else begin
              if(den_A == 1'b1 && den_B == 1'b0) begin
                daddr_C_reg <= daddr_A;
                di_C_reg <= di_A;
                dwe_C_reg <= dwe_A;
                den_C_reg <= den_A;
                overlap_A <= 1'b0;
                overlap_B <= 1'b0;
                bgrant_A <= 1'b1;
                bgrant_B <= 1'b0;
                state <= GRANT_A;
              end
              if(den_A == 1'b0 && den_B == 1'b1) begin
                daddr_C_reg <= daddr_B;
                di_C_reg <= di_B;
                dwe_C_reg <= dwe_B;
                den_C_reg <= den_B;
                overlap_A <= 1'b0;
                overlap_B <= 1'b0;
                bgrant_A <= 1'b0;
                bgrant_B <= 1'b1;
                state <= GRANT_B;
              end
              if(den_A == 1'b1 && den_B == 1'b1) begin
                daddr_C_reg <= daddr_A;
                di_C_reg <= di_A;
                dwe_C_reg <= dwe_A;
                den_C_reg <= den_A;
                daddr_reg <= daddr_B;
                di_reg <= di_B;
                dwe_reg <= dwe_B;
                den_reg <= den_B;
                overlap_A <= 1'b0;
                overlap_B <= 1'b1;
                bgrant_A <= 1'b1;
                bgrant_B <= 1'b0;
                state <= GRANT_A;
              end
              if(den_A == 1'b0 && den_B == 1'b0) begin
                daddr_C_reg <= 8'h00;
                di_C_reg <= 16'h0000;
                dwe_C_reg <= 1'b0;
                den_C_reg <= 1'b0;
                bgrant_A <= 1'b0;
                bgrant_B <= 1'b0;
              end
            end
          end
          else if(bbusy_A == 1'b1 && bbusy_B == 1'b0) begin
            if(den_A == 1'b1) begin
              daddr_C_reg <= daddr_A;
              di_C_reg <= di_A;
              dwe_C_reg <= dwe_A;
              den_C_reg <= den_A;
              state <= GRANT_A;
              bgrant_A <= 1'b1;
            end
            if(den_B == 1'b1) begin
              daddr_reg <= daddr_B;
              di_reg <= di_B;
              dwe_reg <= dwe_B;
              den_reg <= den_B;
              overlap_B <= 1'b1;
            end
          end
          else if(bbusy_A == 1'b0 && bbusy_B == 1'b1) begin
            if(den_B == 1'b1) begin
              daddr_C_reg <= daddr_B;
              di_C_reg <= di_B;
              dwe_C_reg <= dwe_B;
              den_C_reg <= den_B;
              state <= GRANT_B;
              bgrant_B <= 1'b1;
            end
            if(den_A == 1'b1) begin
              daddr_reg <= daddr_A;
              di_reg <= di_A;
              dwe_reg <= dwe_A;
              den_reg <= den_A;
              overlap_A <= 1'b1;
            end
          end
        end
        drdy_A_reg <= 1'b0;
        do_A_reg <= 16'h0000;
        drdy_B_reg <= 1'b0;
        do_B_reg <= 16'h0000;
      end
      GRANT_A : begin
        if(drdy_C == 1'b1) begin
          //if (den_B = '1' or req_A_B = '1' or overlap_B = '1') and busy_in /= '1'  then
          // if  bbusy_A /= '1' and (den_B = '1'  or overlap_B = '1')  then
          if(bbusy_A != 1'b1 && overlap_B == 1'b1) begin
            daddr_C_reg <= daddr_reg;
            di_C_reg <= di_reg;
            dwe_C_reg <= dwe_reg;
            den_C_reg <= den_reg;
            overlap_B <= 1'b0;
            bgrant_A <= 1'b0;
            bgrant_B <= 1'b1;
            state <= GRANT_B;
          end
          else if(bbusy_A != 1'b1 && den_B == 1'b1) begin
            daddr_C_reg <= daddr_B;
            di_C_reg <= di_B;
            dwe_C_reg <= dwe_B;
            den_C_reg <= den_B;
            overlap_B <= 1'b0;
            bgrant_A <= 1'b0;
            bgrant_B <= 1'b1;
            state <= GRANT_B;
          end
          else begin
            state <= NOGRANT;
          end
          do_A_reg <= do_C;
        end
        else begin
          daddr_C_reg <= daddr_A;
          di_C_reg <= di_A;
          dwe_C_reg <= dwe_A;
          den_C_reg <= den_A;
        end
        if(den_B == 1'b1) begin
          daddr_reg <= daddr_B;
          di_reg <= di_B;
          dwe_reg <= dwe_B;
          den_reg <= den_B;
          overlap_B <= 1'b1;
        end
        drdy_A_reg <= drdy_C;
        drdy_B_reg <= 1'b0;
      end
      GRANT_B : begin
        if(drdy_C == 1'b1) begin
          //if (den_A = '1' or overlap_A = '1') and busy_in /= '1'   then
          if(bbusy_B != 1'b1 && overlap_A == 1'b1) begin
            daddr_C_reg <= daddr_reg;
            di_C_reg <= di_reg;
            dwe_C_reg <= dwe_reg;
            den_C_reg <= den_reg;
            overlap_A <= 1'b0;
            bgrant_A <= 1'b1;
            bgrant_B <= 1'b0;
            state <= GRANT_A;
          end
          else if(bbusy_B != 1'b1 && den_A == 1'b1) begin
            daddr_C_reg <= daddr_A;
            di_C_reg <= di_A;
            dwe_C_reg <= dwe_A;
            den_C_reg <= den_A;
            overlap_A <= 1'b0;
            bgrant_A <= 1'b1;
            bgrant_B <= 1'b0;
            state <= GRANT_A;
          end
          else begin
            state <= NOGRANT;
          end
          do_B_reg <= do_C;
        end
        else begin
          daddr_C_reg <= daddr_B;
          di_C_reg <= di_B;
          dwe_C_reg <= dwe_B;
          den_C_reg <= den_B;
        end
        if(den_A == 1'b1) begin
          daddr_reg <= daddr_A;
          di_reg <= di_A;
          dwe_reg <= dwe_A;
          den_reg <= den_A;
          overlap_A <= 1'b1;
        end
        drdy_B_reg <= drdy_C;
        drdy_A_reg <= 1'b0;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

