module fifoWrite(
input wire iClk,
input wire iRst,
input wire iWrite,
input wire [gAddrWidth:0] iRdPointer,
output wire oFull,
output wire oEmpty,
output wire [gAddrWidth:0] oPointer,
output wire [gAddrWidth - 1:0] oAddress,
output wire [gAddrWidth - 1:0] oUsedWord
);
parameter [31:0] gAddrWidth=4;
reg [gAddrWidth:0] w_ptr_reg;
wire [gAddrWidth:0] w_ptr_next;
wire [gAddrWidth:0] gray1;
wire [gAddrWidth:0] bin;
wire [gAddrWidth:0] bin1;
wire [gAddrWidth - 1:0] waddr_all;
wire waddr_msb;
wire raddr_msb;
wire full_flag;
wire empty_flag;
wire [gAddrWidth:0] w_elements_wr;
wire [gAddrWidth:0] w_elements_rd;
wire [gAddrWidth:0] w_elements_diff;
reg [gAddrWidth - 1:0] w_elements_reg;
wire [gAddrWidth - 1:0] w_elements_next;
  //! Clock process for registers.
  always @(posedge iClk, posedge iRst) begin
    if(iRst == cActivated) begin
      w_ptr_reg <= {((gAddrWidth)-(0)+1){cInactivated}};
      w_elements_reg <= {((gAddrWidth - 1)-(0)+1){cInactivated}};
    end else begin
      w_ptr_reg <= w_ptr_next;
      w_elements_reg <= w_elements_next;
    end
  end
  // (gAddrWidth+1)-bit Gray counter
  assign bin = w_ptr_reg ^ ({cInactivated,bin[gAddrWidth:1]});
  assign bin1 = (bin) + 1;
  assign gray1 = bin1 ^ ({cInactivated,bin1[gAddrWidth:1]});
  // update write pointer
  assign w_ptr_next = iWrite == cActivated && full_flag == cInactivated ? gray1 : w_ptr_reg;
  // gAddrWidth-bit Gray counter
  assign waddr_msb = w_ptr_reg[gAddrWidth] ^ w_ptr_reg[gAddrWidth - 1];
  assign waddr_all = {waddr_msb,w_ptr_reg[gAddrWidth - 2:0]};
  assign raddr_msb = iRdPointer[gAddrWidth] ^ iRdPointer[gAddrWidth - 1];
  // check for FIFO write empty
  assign empty_flag = iRdPointer[gAddrWidth] == w_ptr_reg[gAddrWidth] && iRdPointer[gAddrWidth - 2:0] == w_ptr_reg[gAddrWidth - 2:0] && raddr_msb == waddr_msb ? cActivated : cInactivated;
  // check for FIFO write full
  assign full_flag = iRdPointer[gAddrWidth] != w_ptr_reg[gAddrWidth] && iRdPointer[gAddrWidth - 2:0] == w_ptr_reg[gAddrWidth - 2:0] && raddr_msb == waddr_msb ? cActivated : cInactivated;
  // convert gray value to bin and obtain difference
  assign w_elements_wr = bin;
  assign w_elements_rd = iRdPointer ^ ({cInactivated,w_elements_rd[gAddrWidth:1]});
  assign w_elements_diff = (w_elements_wr) - (w_elements_rd);
  assign w_elements_next = w_elements_diff[gAddrWidth - 1:0];
  // output
  assign oAddress = waddr_all;
  assign oPointer = w_ptr_reg;
  assign oUsedWord = w_elements_reg;
  assign oEmpty = empty_flag;
  assign oFull = full_flag;
endmodule

