module hcc_castdtoy(
input wire sysclk,
input wire reset,
input wire enable,
input wire [64:1] aa,
output wire [67 + 10 * target:1] cc,
output wire ccsat,
output wire cczip
);
parameter [31:0] target=0;
parameter [31:0] roundconvert=0;
parameter [31:0] outputpipe=0;
parameter [31:0] doublespeed=1;
parameter [31:0] synthesize=1;
wire [53 + 11 * target:1] zerovec;
reg [64:1] aaff;
wire satnode; wire zipnode;
reg satff; reg zipff;
wire [13:1] expnode;
wire [54 + 10 * target:1] fracnode;
reg [67 + 10 * target:1] ccff;
wire [64:1] mantissanode;
reg [13:1] exponentff[2:1];
reg [2:1] satdelff; reg [2:1] zipdelff;
  // ieee754: sign (64), 8 exponent (63:53), 52 mantissa (52:1)
  // x format: (signx5,!sign,mantissa XOR sign, sign(xx.xx)), exponent(13:1)
  // multiplier, divider : (SIGN)('1')(52:1), exponent(13:1)
  // (multiplier & divider use unsigned numbers, sign packed with input)
  generate if ((roundconvert == 1)) begin: gza
      genvar k;
    generate for (k=1; k <= 53 + 11 * target; k = k + 1) begin: gzb
          assign zerovec[k] = 1'b0;
    end
    endgenerate
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 64; k = k + 1) begin
        aaff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        aaff <= aa;
      end
    end
  end
  // if exponent = 1023 => saturate, if 0 => 0
  assign satnode = aaff[63] & aaff[62] & aaff[61] & aaff[60] & aaff[59] & aaff[58] & aaff[57] & aaff[56] & aaff[55] & aaff[54] & aaff[53];
  assign zipnode =  ~(aaff[63] | aaff[62] | aaff[61] | aaff[60] | aaff[59] | aaff[58] | aaff[57] | aaff[56] | aaff[55] | aaff[54] | aaff[53]);
  genvar k;
  generate for (k=1; k <= 11; k = k + 1) begin: gexpa
      assign expnode[k] = (aaff[k + 52] | satnode) &  ~(zipnode);
  end
  endgenerate
  assign expnode[12] = satnode;
  assign expnode[13] = 1'b0;
  //**************************************
  //*** direct to multipier or divider ***
  //**************************************
  generate if ((target == 0)) begin: gmda
      // already in "01"&mantissa format used by multiplier and divider
    //fracnode <= aaff(64) & '1' & aaff(52 DOWNTO 1);
    // 13/07/09
    assign fracnode[54] = aaff[64];
    assign fracnode[53] =  ~(zipnode);
    assign fracnode[52:1] = aaff[52:1];
    generate if ((outputpipe == 0)) begin: gmdb
          assign cc = {fracnode,expnode};
      assign ccsat = satnode;
      assign cczip = zipnode;
    end
    endgenerate
    generate if ((outputpipe == 1)) begin: gmdc
          always @(posedge sysclk, posedge reset) begin
        if((reset == 1'b1)) begin
          for (k=1; k <= 67; k = k + 1) begin
            ccff[k] <= 1'b0;
          end
          satff <= 1'b0;
          zipff <= 1'b0;
        end else begin
          if((enable == 1'b1)) begin
            ccff <= {fracnode,expnode};
            satff <= satnode;
            zipff <= zipnode;
          end
        end
      end
      assign cc = ccff;
      assign ccsat = satff;
      assign cczip = zipff;
    end
    endgenerate
  end
  endgenerate
  //***********************
  //*** internal format ***
  //***********************
  generate if ((target == 1)) begin: gxa
      assign fracnode[64] = aaff[64];
    assign fracnode[63] = aaff[64];
    assign fracnode[62] = aaff[64];
    assign fracnode[61] = aaff[64];
    assign fracnode[60] = aaff[64];
    //fracnode(59) <= NOT(aaff(64));  -- '1' XOR sign
    // 13/07/09
    assign fracnode[59] = aaff[64] ^  ~(zipnode);
    genvar k;
    generate for (k=1; k <= 52; k = k + 1) begin: gfa
          assign fracnode[k + 6] = aaff[k] ^ aaff[64];
    end
    endgenerate
    genvar k;
    generate for (k=1; k <= 6; k = k + 1) begin: gfb
          assign fracnode[k] = aaff[64];
            // '0' XOR sign
    end
    endgenerate
    //*** OUTPUT STAGE(S) ***
    generate if ((roundconvert == 0 && outputpipe == 0)) begin: gsa
          assign cc = {fracnode,expnode};
      assign ccsat = satnode;
      assign cczip = zipnode;
    end
    endgenerate
    generate if ((outputpipe == 1 && ((roundconvert == 0) || (roundconvert == 1 && doublespeed == 0)))) begin: gsb
          generate if ((roundconvert == 0)) begin: gsc
              assign mantissanode = fracnode;
      end
      endgenerate
      generate if ((roundconvert == 1)) begin: gsd
              assign mantissanode = fracnode + ({zerovec[63:1],aaff[64]});
      end
      endgenerate
      always @(posedge sysclk, posedge reset) begin
        if((reset == 1'b1)) begin
          for (k=1; k <= 77; k = k + 1) begin
            ccff[k] <= 1'b0;
          end
          satff <= 1'b0;
          zipff <= 1'b0;
        end else begin
          if((enable == 1'b1)) begin
            ccff <= {mantissanode,expnode};
            satff <= satnode;
            zipff <= zipnode;
          end
        end
      end
      assign cc = ccff;
      assign ccsat = satff;
      assign cczip = zipff;
    end
    endgenerate
    generate if ((roundconvert == 1 && doublespeed == 1)) begin: gse
          generate if ((synthesize == 0)) begin: gsf
              hcc_addpipeb #(
                  .width(64),
          .pipes(2))
        addone(
                  .sysclk(sysclk),
          .reset(reset),
          .enable(enable),
          .aa(fracnode),
          .bb(zerovec[64:1]),
          .carryin(aaff[64]),
          .cc(mantissanode));
      end
      endgenerate
      generate if ((synthesize == 1)) begin: grb
              hcc_addpipes #(
                  .width(64),
          .pipes(2))
        addtwo(
                  .sysclk(sysclk),
          .reset(reset),
          .enable(enable),
          .aa(fracnode),
          .bb(zerovec[64:1]),
          .carryin(aaff[64]),
          .cc(mantissanode));
      end
      endgenerate
      always @(posedge sysclk, posedge reset) begin
        if((reset == 1'b1)) begin
          for (k=1; k <= 13; k = k + 1) begin
            exponentff[1][k] <= 1'b0;
            exponentff[2][k] <= 1'b0;
          end
          satdelff <= 2'b00;
          zipdelff <= 2'b00;
        end else begin
          if((enable == 1'b1)) begin
            exponentff[1][13:1] <= expnode;
            exponentff[2][13:1] <= exponentff[1][13:1];
            satdelff[1] <= satnode;
            satdelff[2] <= satdelff[1];
            zipdelff[1] <= zipnode;
            zipdelff[2] <= zipdelff[1];
          end
        end
      end
      assign cc = {mantissanode,exponentff[2][13:1]};
      assign ccsat = satdelff[2];
      assign cczip = zipdelff[2];
    end
    endgenerate
  end
  endgenerate
endmodule

