module standard_fifo_poll(
input wire readrequest,
input wire CLK,
input wire [31:0] fifo_data,
output reg fifo_read,
input wire fifo_valid,
input wire reset,
output reg [31:0] fifo_value
);
reg fifo_read_was_invalid;
reg [31:0] buffered_value;
reg [3:0] pollstage;
  always @(posedge CLK) begin
    // only in pollstage 0001 and if we need to get a new fifo value, we set fifo_read to 1, otherwise always 0
    fifo_read <= 1'b0;
    if((reset == 1'b1)) begin
      pollstage <= 4'b0000;
    end
    else begin
      case(pollstage)
            // idle state, initiate fifo_read if requested
      4'b0001 : begin
        if((readrequest == 1'b1 || fifo_read_was_invalid == 1'b1)) begin
          fifo_read <= 1'b1;
          pollstage <= 4'b0010;
        end
        // waitstate
      end
      4'b0010 : begin
        pollstage <= 4'b0100;
        // evaluate, if the read was valid
        // if so, put the read value into the output buffer
        // otherwise set the output buffer to zero
        // the fifo_read_was_invalid flag will cause the system to re-read the fifo
      end
      4'b0100 : begin
        pollstage <= 4'b1000;
        if((fifo_valid == 1'b1)) begin
          buffered_value <= fifo_data;
          fifo_read_was_invalid <= 1'b0;
        end
        else begin
          buffered_value <= {32{1'b0}};
          fifo_read_was_invalid <= 1'b1;
        end
        // buffered value contains the current fifo value (or empty if no value could be read)
        //	we only overwrite the readout register, if there is no active read
      end
      4'b1000 : begin
        if((readrequest == 1'b0)) begin
          fifo_value <= buffered_value;
          pollstage <= 4'b0001;
        end
      end
      default : begin
        pollstage <= 4'b0001;
        fifo_value <= {32{1'b0}};
        fifo_read_was_invalid <= 1'b1;
      end
      endcase
    end
  end
endmodule

module MusicBoxClocking(
input wire CLOCK_50,
input wire RESET_RI,
output wire ClkSystem_CO,
output wire ClkPWM_CO,
output wire ResetSystem_SO,
output wire ResetPWM_SO,
output reg FreqInt_SO,
output reg KeyInt_SO
);
parameter KEYFREQDIV = 9;  // divides the frequency wave to the
// key-speed wave
wire Clk5M_C = 1'b0;
wire Clk64M_C = 1'b0;
wire Clk128k_C = 1'b0;
wire ResetSystem_S = 1'b0;
wire ResetPWM_S = 1'b0;
wire PLLLocked_S = 1'b0;
wire FreqWave_SN = 1'b0; reg FreqWave_SP = 1'b0;
wire FreqEdgeDet_S;
reg [KEYFREQDIV - 1:0] ClkDivider_D = 1'b0;
wire KeyWave_SN = 1'b0; reg KeyWave_SP = 1'b0;
wire KeyEdgeDet_S = 1'b0;
  // architecture RTL
  // clock generator PLL from 50MHz input clock
  ClocksPLL ClocksPLL_i(
      .areset(RESET_RI),
    .inclk0(CLOCK_50),
    .c0(Clk5M_C),
    .c1(Clk64M_C),
    .c2(Clk128k_C),
    .locked(PLLLocked_S));
  // clock outputs
  assign ClkSystem_CO = Clk5M_C;
  assign ClkPWM_CO = Clk64M_C;
  // reset synchronizer for System Clock
  ResetSync ResetSync_Sys_i(
      .Clk_CI(Clk5M_C),
    .ClkStable_RI(PLLLocked_S),
    .OtherReset_RI(RESET_RI),
    .SyncReset_SO(ResetSystem_S));
  assign ResetSystem_SO = ResetSystem_S;
  // reset sync for pwm clock
  ResetSync ResetSync_pwm_i(
      .Clk_CI(Clk64M_C),
    .ClkStable_RI(PLLLocked_S),
    .OtherReset_RI(RESET_RI),
    .SyncReset_SO(ResetPWM_S));
  assign ResetPWM_SO = ResetPWM_S;
  //---------------------------------------------------------------------------
  // Generation of Interrupts
  //---------------------------------------------------------------------------
  // frequency wave generator
  CrossClockDomain CrossClockDomain_Freq_i(
      .Clk_CI(Clk5M_C),
    .AsyncIn_SI(Clk128k_C),
    .SyncOut_SO(FreqWave_SN));
  always @(posedge Clk128k_C) begin
      // process clk_divider
    // rising clock edge
    ClkDivider_D <= ClkDivider_D + 1;
  end
  CrossClockDomain CrossClockDomain_Key_i(
      .Clk_CI(Clk5M_C),
    .AsyncIn_SI(ClkDivider_D[KEYFREQDIV - 1]),
    .SyncOut_SO(KeyWave_SN));
  // edge detector flipflops
  always @(posedge Clk5M_C) begin
      // process freq_edge_det
    // rising clock edge
    if(ResetSystem_S == 1'b1) begin
      // synchronous reset (active high)
      FreqWave_SP <= 1'b0;
      FreqInt_SO <= 1'b0;
      KeyWave_SP <= 1'b0;
      KeyInt_SO <= 1'b0;
    end
    else begin
      FreqWave_SP <= FreqWave_SN;
      FreqInt_SO <= FreqWave_SN &  ~(FreqWave_SP);
      KeyWave_SP <= KeyWave_SN;
      KeyInt_SO <= KeyWave_SN &  ~(KeyWave_SP);
    end
  end
endmodule

module dflipflop(
