module spi_ctrl(
input wire clk,
input wire rst,
input wire en,
input wire [7:0] sdata,
output wire sdout,
output wire oled_sclk,
output wire fin
);
// System clok (100MHz)
// Global synchronous reset
// Block enable pin
// Byte to be sent
// Serial data out
// OLED serial clock
// Finish flag for block
parameter [1:0]
  Idle = 0,
  Send = 1,
  Done = 2;
reg [1:0] current_state = Idle;  // Signal for state machine
reg [7:0] shift_register;  // Shift register to shift out sdata saved when en was set
reg [3:0] shift_counter;  // Keeps track how many bits were sent
wire clk_divided = 1'b1;  // Used as oled_sclk
reg [4:0] counter = 1'b0;  // Count clocks to be used to divide clk
reg temp_sdata = 1'b1;  // Tied to sdout
reg falling = 1'b0;  // Signal indicating that the clk has just fell
  assign clk_divided =  ~counter[4];
  // oled_sclk = clk / 32
  assign oled_sclk = clk_divided;
  assign sdout = temp_sdata;
  assign fin = current_state == Done ? 1'b1 : 1'b0;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      // Synchronous rst
      current_state <= Idle;
    end
    else begin
      case(current_state)
      Idle : begin
        // Wait for en to go high
        if(en == 1'b1) begin
          current_state <= Send;
        end
      end
      Send : begin
        // Start sending bits, transition out when all bits are sent and oled_sclk is high
        if(shift_counter == 4'b1000 && falling == 1'b0) begin
          current_state <= Done;
        end
      end
      Done : begin
        // Finish SPI transimission wait for en to go low
        if(en == 1'b0) begin
          current_state <= Idle;
        end
      end
      default : begin
        current_state <= Idle;
      end
      endcase
    end
  end
  always @(posedge clk) begin
    if(current_state == Send) begin
      // Start clock counter when in send state
      counter <= counter + 1;
    end
    else begin
      // Reset clock counter when not in send state
      counter <= {5{1'b0}};
    end
  end
  always @(posedge clk) begin : P1
  // Sends SPI data formatted oled_sclk active low with sdout changing on the falling edge
    if(current_state == Idle) begin
      shift_counter <= {4{1'b0}};
      shift_register <= sdata;
      // Keeps placing sdata into shift_register so that when state goes to send it has the latest sdata
      temp_sdata <= 1'b1;
    end
    else if(current_state == Send) begin
      if(clk_divided == 1'b0 && falling == 1'b0) begin
        // If on the falling edge of clk_divided
        falling <= 1'b1;
        // Indicate that it is passed the falling edge
        temp_sdata <= shift_register[7];
        // Send out the MSB
        shift_register <= {shift_register[6:0],1'b0};
        // Shift through sdata
        shift_counter <= shift_counter + 1;
        // Keep track of what bit it is on
      end
      else if(clk_divided == 1'b1) begin
        // On oled_sclk high reset the falling flag
        falling <= 1'b0;
      end
    end
  end
endmodule

module mux2to1bit(
input wire input0,
input wire input1,
output reg output,
input wire sel
);
  // mux2to1
  always @(input0, input1, sel) begin : P1
    reg sel_var;
    sel_var = sel;
    case(sel_var)
    1'b0 : begin
      output <= input0;
    end
    1'b1 : begin
      output <= input1;
    end
    default : begin
      output <= 1'bZ;
    end
    endcase
  end
endmodule

module lcd_controller(
input wire clk,
input wire reset_n,
input wire lcd_enable,
input wire [9:0] lcd_bus,
output reg busy,
output reg rw,
output reg rs,
output reg e,
output reg [7:0] lcd_data
);
//system clock
//active low reinitializes lcd
//latches data into lcd controller
//data and control signals
//lcd controller busy/idle feedback
//read/write, setup/data, and enable for lcd
//data signals for lcd
parameter [1:0]
  power_up = 0,
  initialize = 1,
  ready = 2,
  send = 3;
reg [1:0] state;
parameter freq = 50;  //system clock frequency in MHz
  always @(posedge clk) begin : P1
    reg [31:0] clk_count = 0;
  //event counter for timing
    case(state)
        //wait 50 ms to ensure Vdd has risen and required LCD wait is met
    power_up : begin
      busy <= 1'b1;
      if((clk_count < (50000 * freq))) begin
        //wait 50 ms
        clk_count = clk_count + 1;
        state <= power_up;
      end
      else begin
        //power-up complete
        clk_count = 0;
        rs <= 1'b0;
        rw <= 1'b0;
        lcd_data <= 8'b00110000;
        state <= initialize;
      end
      //cycle through initialization sequence  
    end
    initialize : begin
      busy <= 1'b1;
      clk_count = clk_count + 1;
      if((clk_count < (10 * freq))) begin
        //function set
        lcd_data <= 8'b00111100;
        //2-line mode, display on
        //lcd_data <= "00110100";    --1-line mode, display on
        //lcd_data <= "00110000";    --1-line mdoe, display off
        //lcd_data <= "00111000";    --2-line mode, display off
        e <= 1'b1;
        state <= initialize;
      end
      else if((clk_count < (60 * freq))) begin
        //wait 50 us
        lcd_data <= 8'b00000000;
        e <= 1'b0;
        state <= initialize;
      end
      else if((clk_count < (70 * freq))) begin
        //display on/off control
        lcd_data <= 8'b00001100;
        //display on, cursor off, blink off
        //lcd_data <= "00001101";    --display on, cursor off, blink on
        //lcd_data <= "00001110";    --display on, cursor on, blink off
        //lcd_data <= "00001111";    --display on, cursor on, blink on
        //lcd_data <= "00001000";    --display off, cursor off, blink off
        //lcd_data <= "00001001";    --display off, cursor off, blink on
        //lcd_data <= "00001010";    --display off, cursor on, blink off
        //lcd_data <= "00001011";    --display off, cursor on, blink on            
        e <= 1'b1;
        state <= initialize;
      end
      else if((clk_count < (120 * freq))) begin
        //wait 50 us
        lcd_data <= 8'b00000000;
        e <= 1'b0;
        state <= initialize;
      end
      else if((clk_count < (130 * freq))) begin
        //display clear
        lcd_data <= 8'b00000001;
        e <= 1'b1;
        state <= initialize;
      end
      else if((clk_count < (2130 * freq))) begin
        //wait 2 ms
        lcd_data <= 8'b00000000;
        e <= 1'b0;
        state <= initialize;
      end
      else if((clk_count < (2140 * freq))) begin
        //entry mode set
        lcd_data <= 8'b00000110;
        //increment mode, entire shift off
        //lcd_data <= "00000111";    --increment mode, entire shift on
        //lcd_data <= "00000100";    --decrement mode, entire shift off
        //lcd_data <= "00000101";    --decrement mode, entire shift on
        e <= 1'b1;
        state <= initialize;
      end
      else if((clk_count < (2200 * freq))) begin
        //wait 60 us
        lcd_data <= 8'b00000000;
        e <= 1'b0;
        state <= initialize;
      end
      else begin
        //initialization complete
        clk_count = 0;
        busy <= 1'b0;
        state <= ready;
      end
      //wait for the enable signal and then latch in the instruction
    end
    ready : begin
      if((lcd_enable == 1'b1)) begin
        busy <= 1'b1;
        rs <= lcd_bus[9];
        rw <= lcd_bus[8];
        lcd_data <= lcd_bus[7:0];
        clk_count = 0;
        state <= send;
      end
      else begin
        busy <= 1'b0;
        rs <= 1'b0;
        rw <= 1'b0;
        lcd_data <= 8'b00000000;
        clk_count = 0;
        state <= ready;
      end
      //send instruction to lcd        
    end
    send : begin
      busy <= 1'b1;
      if((clk_count < (50 * freq))) begin
        //do not exit for 50us
        busy <= 1'b1;
        if((clk_count < freq)) begin
          //negative enable
          e <= 1'b0;
        end
        else if((clk_count < (14 * freq))) begin
          //positive enable half-cycle
          e <= 1'b1;
        end
        else if((clk_count < (27 * freq))) begin
          //negative enable half-cycle
          e <= 1'b0;
        end
        clk_count = clk_count + 1;
        state <= send;
      end
      else begin
        clk_count = 0;
        state <= ready;
      end
    end
    endcase
    //reset
    if((reset_n == 1'b0)) begin
      state <= power_up;
    end
  end
endmodule
